INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('1', '11.10.11.10.', '52', '206');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('1', '1', '1', 'FRA tutti i doni del Tuo amore, o Dio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('1', '1', '2', 'Non v\'è qui in terra né v\'è in ciel maggior');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('1', '1', '3', 'Del sangue che, morendo sulla croce,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('1', '1', '4', 'Per noi versato ha il nostro Redentor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('1', '2', '1', 'La fede pur che tutti a Lui ci lega');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('1', '2', '2', 'A noi largisce la Tua santa man;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('1', '2', '3', 'S\'ella non fosse, quel divino dono');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('1', '2', '4', 'A noi sarebbe stato offerto invan.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('1', '3', '1', 'Ognor di più Ti loderemo, o Dio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('1', '3', '2', 'Perché la grazia Tua tutto ci dà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('1', '3', '3', 'Il Salvator divino ed il potere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('1', '3', '4', 'Che al nostro cuore desirar lo fa.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('2', '8.7.8.7.4.7.', '50', '97');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('2', '1', '1', 'PADRE, pria che il mondo fosse');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('2', '1', '2', 'Tu ci conoscevi già;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('2', '1', '3', 'A Gesù il Tuo amor ci addusse');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('2', '1', '4', 'Con sua dolce potestà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('2', '1', '5', 'Ora siamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('2', '1', '6', 'Figli per l\'eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('2', '2', '1', 'Dell\'amor che ci largisci');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('2', '2', '2', 'Le ricchezze noi godiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('2', '2', '3', 'Ed in esso riposando');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('2', '2', '4', 'La Tua pace conosciam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('2', '2', '5', 'Dio e Padre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('2', '2', '6', 'D\'un sol cuore T\'adoriam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('3', '11.10.11.10.', '52', '52');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('3', '1', '1', 'O DIO, Tu Capo d\'ogni cosa sei,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('3', '1', '2', 'Ricchezze e gloria vengon sol da Te;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('3', '1', '3', 'Nel Tuo divino amore tutto reggi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('3', '1', '4', 'In libertà i Tuoi figli son per fé.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('3', '2', '1', 'Nelle Tue mani son potenza e forza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('3', '2', '2', 'E per lo Spirto forti pur noi siam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('3', '2', '3', 'Ed ora, o Dio, così da Te sorretti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('3', '2', '4', 'Il Nome Tuo glorioso qui lodiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('3', '3', '1', 'Eccelso Nome! Qual divina calma');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('3', '3', '2', 'Inonda il cuore mentre noi cantiam!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('3', '3', '3', 'O Dio- Padre, Figlio e Spirto Santo-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('3', '3', '4', 'La nostra adorazione a Te rechiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('4', '11.10.11.10. Dattilico.', '17', '128');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('4', '1', '1', 'E\' TUO l\'amore che insieme ci chiama');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('4', '1', '2', 'E dal deserto radunaci a Te;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('4', '1', '3', 'Presto in eterno a Te lodi offriremo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('4', '1', '4', 'Ma già, Signor, T\'adoriam or per fé.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('4', '2', '1', 'Già pria lo Spirito Santo ha parlato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('4', '2', '2', 'All\'alme nostre sovente di Te;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('4', '2', '3', 'Ora un tesoro d\'amor T\'apportiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('4', '2', '4', 'E Te l\'offriam prosternati ai Tuoi piè.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('4', '3', '1', 'Per noi soffristi indicibili pene,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('4', '3', '2', 'Per noi la vita Tu desti, Signor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('4', '3', '3', 'In armonia con l\'omaggio del cielo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('4', '3', '4', 'Ora dei Tuoi sal un canto dal cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('4', '4', '1', 'Sovra ogni nome il Tuo Nome risplende:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('4', '4', '2', 'Nostro Signore Gesù, T\'adoriam!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('4', '4', '3', 'Noi T\'attendiam, Tua beltà contemplando,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('4', '4', '4', 'Ed al prezioso Tuo amor rispondiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('5', '10.10.4.10.10.4.', '18', '157');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '1', '1', 'PADRE di gloria, a Te la voce alziam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '1', '2', 'E nel fulgor del Tuo divin favor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '1', '3', 'Noi Ti lodiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '1', '4', 'In Te la gloria d\'un eterno pian,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '1', '5', 'La gloria d\'un divino amor sovran');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '1', '6', 'Noi contempliam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '2', '1', 'Tu eri, Padre - dolce è ricordar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '2', '2', 'Pria che vi fosse in terra chi il Tuo cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '2', '3', 'Potesse amar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '2', '4', 'Noi Ti lodiam poiché il Tuo sommo amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '2', '5', 'Ci volle, figli con il Tuo Figliol,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '2', '6', 'A Te portar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '3', '1', 'Egli discese l\'opra ad effettuar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '3', '2', 'Per crude pene qui la via calcò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '3', '3', 'Senza esitar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '3', '4', 'Possiamo noi dinanzi al pian divin');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '3', '5', 'D\'eterno amor, di grazia senza fin,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '3', '6', 'Non adorar?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '4', '1', 'Noi T\'adoriamo mentre contempliam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '4', '2', 'O Padre, il frutto che per Te acquistò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '4', '3', 'Quel pian d\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('5', '4', '4', 'A Te mirïadi rispondon già');
