INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('6', '2', '2', 'Che l\'Uomo divino mostrò:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('6', '2', '3', 'Così la Sua vita preziosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('6', '2', '4', 'Possiam contemplare quaggiù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('6', '3', '1', 'Gesù - questo Nome ci parla');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('6', '3', '2', 'Di pene sofferte in amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('6', '3', '3', 'E la simpatia ci dice');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('6', '3', '4', 'Del ciel, quando siam nel dolor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('6', '4', '1', 'Ei che non conobbe peccato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('6', '4', '2', 'Fu fatto peccato per noi:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('6', '4', '3', 'Tu desti Te stesso per vincer');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('6', '4', '4', 'L\'amor, la fiducia dei Tuoi.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('6', '5', '1', 'Pensando al Tuo Nome, si eleva');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('6', '5', '2', 'Dal cuor nostro l\'adorazion:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('6', '5', '3', 'Gesù, Capo su diecimila,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('6', '5', '4', 'Il Tuo grande amor ci salvò!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('7', '6.7.6.7.8.6.7.6.7.8.', '140', '88');
