INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('7', '1', '2', 'Insiem le nostre voci,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('7', '1', '3', 'Al mondo proclamiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('7', '1', '4', 'Che siam appien felici');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('7', '1', '5', 'Poiché la nostra casa è il ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('7', '1', '6', 'Il nostro Capo è là,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('7', '1', '7', 'Di gloria coronato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('7', '1', '8', 'E noi che qui attendiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('7', '1', '9', 'Il regno Suo beato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('7', '1', '10', 'Gridiam: Vieni, Signor Gesù!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('8', '6.6.6.5.6.6.6.5.', '43', '146');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('8', '1', '1', 'O DIO, confessiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('8', '1', '2', 'Tua gloria e grandezza;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('8', '1', '3', 'Da Te è ogni cosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('8', '1', '4', 'In terra ed in ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('8', '1', '5', 'Qual vasta pienezza!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('8', '1', '6', 'Qual gloria sublime!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('8', '1', '7', 'O Dio, T\'adoriamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('8', '1', '8', 'Amen, sì. Amen!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('9', '11.11.11.11.(a)', '191', '55');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('9', '1', '1', 'AL possente Nome di Gesù, gloria!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('9', '1', '2', 'Or dinanzi a Lui prostrati noi cadiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('9', '1', '3', 'Con un sol accento cantiam Sua lode');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('9', '1', '4', 'E Signor di tutti noi Lo coroniam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('9', '2', '1', 'Riscattati dalla razza d\'Adamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('9', '2', '2', 'Dall\'error redenti, il Signor lodiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('9', '2', '3', 'Che con la Sua grazia ora ci salva');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('9', '2', '4', 'E Signor di tutti noi Lo coroniam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('9', '3', '1', 'Proclamiamo il solo Nome ch\'è dato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('9', '3', '2', 'Sotto i cieli, il Nome che invocar possiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('9', '3', '3', 'Che dalle celesti schiere è adorato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('9', '3', '4', 'E Signor di tutti noi Lo coroniam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('9', '4', '1', 'Presto, nella gloria, coi riscattati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('9', '4', '2', 'In felice schiera ai Suoi piè cadrem:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('9', '4', '3', 'Canterem l\'eterno, beato canto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('9', '4', '4', 'E Signor di tutti Lo coronerem.');
