INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('10', '1', '3', 'Nella Tua pace mantenuti, in Cristo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('10', '1', '4', 'Finché nel Tuo riposo alfine entriam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('11', '10.10.10.9.10.9.', '171', '93');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '1', '1', 'LA Parola incarnata Tu sei,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '1', '2', 'L\'Unigenito Figlio del Padre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '1', '3', 'Dio svelato, veduto ed udito,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '1', '4', 'Tu l\'Oggetto di lode del ciel:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '1', '5', 'Degno sei d\'ogni omaggio, Signore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '1', '6', 'Esaltato, di Dio l\'Agnel!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '2', '1', 'In Te, espressa in maniera perfetta,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '2', '2', 'La Persona del Padre risplende;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '2', '3', 'In Te sta di Deità la pienezza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '2', '4', 'In eterno, Signor, sei divin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '2', '5', 'E con Te nel cospetto del Padre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '2', '6', 'La Sua grazia esaltiam senza fin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '3', '1', 'Nell\'amare Te stesso, in cui posa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '3', '2', 'Ineffabil del Padre l\'amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '3', '3', 'A Lui là son attratti i cuor nostri');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '3', '4', 'E con Te benedetti noi siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '3', '5', 'Il Suo Nome, Signor, dichiarasti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '3', '6', 'Al Suo amore con Te parte abbiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '4', '1', 'Di quel vasto, beato universo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '4', '2', 'Tu se\' il Centro ed il Sole, Signore;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '4', '3', 'Tu rïempi, Figliolo di Dio -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '4', '4', 'Questo il tema di lodi riman -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '4', '5', 'Quella sfera ove Dio, conosciuto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('11', '4', '6', 'Nel Suo proprio riposo, Si tien.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('12', '7.7.7.6.7.7.7.6.', '142', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '1', '1', 'CANTIAMO senza posa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '1', '2', 'Del nostro Salvatore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '1', '3', 'La grazia e il sommo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '1', '4', 'Che tutto ci donò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '1', '5', 'In ciel or Egli è entrato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '1', '6', 'E là con Lui sediamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '1', '7', 'Là senza vel vediamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '1', '8', 'Il volto del Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '2', '1', 'Là tutto è pura luce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '2', '2', 'Che inonda il nostro cuore:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '2', '3', 'Del cielo nel fulgore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '2', '4', 'La gloria contempliam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '2', '5', 'E mentre siam qui in terra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '2', '6', 'Con Lui noi camminiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '2', '7', 'Il Suo sostegno abbiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '2', '8', 'E in Lui noi dimoriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '3', '1', 'E mentre il giornaliero');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '3', '2', 'Servizio qui compiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '3', '3', 'Pur fra le lotte abbiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '3', '4', 'La pace ch\'Egli dà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '3', '5', 'Lassù la via conduce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '3', '6', 'Là dov\'è gloria e vita');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '3', '7', 'E abbiamo l\'infinita');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '3', '8', 'Delizia del Suo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '4', '1', 'Infine trasformati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '4', '2', 'A Sua somiglianza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '4', '3', 'Potrem con esultanza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '4', '4', 'Migliori lodi alzar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '4', '5', 'Per sempre col Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '4', '6', 'Simìli a Lui saremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '4', '7', 'E Lo contempleremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('12', '4', '8', 'Nella magion lassù.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('13', '9.8.9.8.9.8.9.8. Dattilico.', '125', '140');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '1', '1', 'IL Padre mandò il Figliolo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '1', '2', 'Un mondo perduto a salvar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '1', '3', 'Ma l\'uom peccatore la croce,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '1', '4', 'La tomba, al Signor volle dar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '1', '5', 'La coppa dell\'ira Egli bevve,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '1', '6', 'Divin Sostituto per l\'uom;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '1', '7', 'Sua vita lasciò, e nell\'obbrobrio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '1', '8', 'Estrem della tomba Egli entrò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '2', '1', 'La terra, alla morte del Figlio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '2', '2', 'Diletto di Dio, tremò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '2', '3', 'La tenebra avvolse il Suo duolo -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '2', '4', 'Compiuta è l\'opera or.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '2', '5', 'Sul volto Suo splende la gioia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '2', '6', 'Ei vive per non morir più:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '2', '7', 'L\'angoscia indicibil passata,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '2', '8', 'Vivente, trionfa Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '3', '1', 'La via recente e vivente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '3', '2', 'Aperta ora sta verso il ciel;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '3', '3', 'Di là, dove il sangue è veduto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '3', '4', 'Il dono di Dio ci vien.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '3', '5', 'Il fiume d\'immensa Sua grazia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '3', '6', 'Che santa giustizia formò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '3', '7', 'Or scorre nell\'arido luogo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '3', '8', 'Là dove moriva il Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '4', '1', 'Ben presto il Signore ritorna,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '4', '2', 'Il Conquistator regnerà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '4', '3', 'L\'Agnello che un dì fu immolato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '4', '4', 'Ognun confessare dovrà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '4', '5', 'E\' degno Gesù di ricever');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '4', '6', 'La gloria e l\'omaggio già or,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '4', '7', 'E\' degno che ognuno s\'inchini');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('13', '4', '8', 'Credendo nel solo Signor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('14', '8.7.8.7.', '24', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '1', '1', 'MILLE e mille voci in coro');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '1', '2', 'Or magnifican l\'Agnel;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '1', '3', 'Mille e mille lor rispondon');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '1', '4', 'Del Suo Nome empiendo il ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '2', '1', 'Sorge il coro: Gloria e lode');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '2', '2', 'All\'Agnel che ucciso fu!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '2', '3', 'E rispondono i redenti:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '2', '4', 'Gloria a Te, Signor Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '3', '1', 'Quale incenso grato al Padre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '3', '2', 'Al Suo trono sale ognor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '3', '3', 'Questa lode; ognun si prostra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '3', '4', 'Adorando il Redentor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '4', '1', 'Vuole il Padre che si renda');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '4', '2', 'Gloria egual al Suo Figliol,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '4', '3', 'Mentre il Figlio Lui rivela');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '4', '4', 'E glorifica Lui sol.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '5', '1', 'E lo Spirto intanto guida');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '5', '2', 'Vaste schiere su nel ciel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '5', '3', 'Che ora adorano l\'Eterno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '5', '4', 'Rivelato nell\'Agnel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '6', '1', 'Gode ormai tutt\'il creato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '6', '2', 'Il riposo Suo divin');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '6', '3', 'Ed ha, in luogo del dolore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '6', '4', 'Gioia e pace senza fin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '7', '1', 'Sempre più s\'eleva il canto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '7', '2', 'Di Sua lode il cielo è pien');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '7', '3', 'E noi pure, giubilanti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('14', '7', '4', 'Rispondiam: Amen, Amen.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('15', '11.10.11.10.', '52', '155');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('15', '1', '1', 'E\' L\'amor Tuo, Signore, sovra il trono');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('15', '1', '2', 'Lo stesso, come sulla croce fu:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('15', '1', '3', 'In umiltà la vita desti in dono,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('15', '1', '4', 'Ora per noi vivente sei lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('15', '2', '1', 'Là Ti vediam, l\'Agnello un dì immolato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('15', '2', '2', 'Tua morte fu l\'eterno nostro ben;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('15', '2', '3', 'Ti contempliam di gloria coronato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('15', '2', '4', 'Senz\'ombra alcuna al fronte Tuo seren.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('15', '3', '1', 'L\'oscurità sul Golgota incontrasti:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('15', '3', '2', 'Or è radioso il volto Tuo, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('15', '3', '3', 'A Dio sia lode! E questo ognor ci basti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('15', '3', '4', 'Che "Tu rimani", santo Salvator!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('15', '4', '1', 'Sì, "Tu rimani"! Terra e mare e cielo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('15', '4', '2', 'Più non saranno, ma Tu resti ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('15', '4', '3', 'Inalterabil dura, e senza velo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('15', '4', '4', 'Negl\'incalzantisi anni il Tuo splendor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('16', '8.6.8.6.8.6.8.6.', '126', '174');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('16', '1', '1', 'O BENEDETTO Vincitor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('16', '1', '2', 'Sopra il poter del mal,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('16', '1', '3', 'Noi qui Ti salutiam, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('16', '1', '4', 'In santa maestà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('16', '1', '5', 'Ora nel mezzo a noi Tu stai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('16', '1', '6', 'In tutto il Tuo splendor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('16', '1', '7', 'A Te in adorazion chiniam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('16', '1', '8', 'Con gioia il nostro cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('16', '2', '1', 'Della divina gloria Tu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('16', '2', '2', 'Signore, sei il fulgor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('16', '2', '3', 'Di Sua sostanza l\'espression!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('16', '2', '4', 'Così adorato or');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('16', '2', '5', 'Sei da color che il frutto son');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('16', '2', '6', 'Di quell\'amor divin:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('16', '2', '7', 'Supremo sei, Tue glorie ognor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('16', '2', '8', 'Risplendon senza fin!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('17', '9.8.9.8.9.8.9.8. Giambico.', '137', '109');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('17', '1', '1', 'LA grazia di Gesù il Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('17', '1', '2', 'Del Padre l\'infinito amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('17', '1', '3', 'E dello Spirito il favore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('17', '1', '4', 'Dimorin su di noi ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('17', '1', '5', 'Possiamo noi cosi l\'unione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('17', '1', '6', 'Coi santi e col Signor serbar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('17', '1', '7', 'Gustando, in dolce comunione,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('17', '1', '8', 'Gioie che il mondo non può dar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('18', '11.10.11.10.10.10.', '180', '45');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('18', '1', '1', 'O BENEDETTO Spirito divino,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('18', '1', '2', 'Non visto, in grazia conosciuto Tu;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('18', '1', '3', 'Consolatore nostro e Guida, infino');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('18', '1', '4', 'A quando il Salvator vedrem lassù;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('18', '1', '5', 'L\'amore Suo, che noi per Te gustiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('18', '1', '6', 'I nostri spirti ha messo in libertà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('18', '2', '1', 'Noi c\'inchiniamo al Tuo voler sovrano');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('18', '2', '2', 'Che i nostri cuor poteva soggiogar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('18', '2', '3', 'Ché nella nuova nascita provammo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('18', '2', '4', 'Quella potenza ch\'è nelle Tue man.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('18', '2', '5', 'Per Te zampilla in vita quel poter');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('18', '2', '6', 'Ed in risposta muove i nostri cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('18', '3', '1', 'Ed or a noi, O Spirto benedetto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('18', '3', '2', 'Tu sveli le profondità d\'amor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('18', '3', '3', 'Cose che occhio mai non vide, orecchio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('18', '3', '4', 'Mai non udì, per noi Dio preparò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('18', '3', '5', 'A Te in risposta lieti noi cantiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('18', '3', '6', 'Con esultanza lode Ti rendiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('19', '7.6.7.6.7.6.7.6.', '34', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '1', '1', 'SIGNORE, con Te sempre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '1', '2', 'Simìli a Te sarem,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '1', '3', 'Per sempre a Te vicini');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '1', '4', 'Quando ritornerai.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '1', '5', 'Finito il nostro viaggio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '1', '6', 'Il volto Tuo vedrem,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '1', '7', 'Vivrem nella Tua grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '1', '8', 'Quando ritornerai.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '2', '1', 'I tratti del Tuo volto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '2', '2', 'Disfatto un dì, in amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '2', '3', 'Contemplerem con gioia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '2', '4', 'Quando ritornerai.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '2', '5', 'Cessato ogni dolore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '2', '6', 'Per sempre i nostri cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '2', '7', 'T\'adoreran, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '2', '8', 'Quando ritornerai.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '3', '1', 'Sul trono Tuo seduti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '3', '2', 'Tuoi ci confesserai:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '3', '3', 'Là tutti ci vedranno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '3', '4', 'Quando ritornerai.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '3', '5', 'E ancor più della gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '3', '6', 'Apprezzerem, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '3', '7', 'Tua dolce vicinanza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('19', '3', '8', 'Quando ritornerai.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('20', '4.8.4.8.8.', '28', '53');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '1', '1', 'O DIO, Tu sol');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '1', '2', 'Dimori in luce senza par');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '1', '3', 'Che ad occhio uman');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '1', '4', 'Non è concesso di scrutar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '1', '5', 'La nostra parte è d\'adorar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '2', '1', 'La Tua Deità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '2', '2', 'Noi contemplare non possiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '2', '3', 'Tant\'è al di là');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '2', '4', 'Di quanto noi capir possiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '2', '5', 'Pur le Tue glorie noi vediam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '3', '1', 'Sul trono in ciel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '3', '2', 'Per fede noi Gesù vediam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '3', '3', 'In maestà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '3', '4', 'Divina e umana, ed esultiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '3', '5', 'Con tutto il cielo Lui lodiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '4', '1', 'Il pian che Tu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '4', '2', 'Formasti dall\'eternità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '4', '3', 'Ei rivelò:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '4', '4', 'Perfetto nell\'umanità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('20', '4', '5', 'E pur eterno in Deità.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('21', '8.6.8.8.6.', '134', '3');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '1', '1', 'SANTO, divin Consolator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '1', '2', 'A Te sia pieno onor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '1', '3', 'Di Deità la gloria è');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '1', '4', 'Tua propria sfera, e pur Tu se\'');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '1', '5', 'Qui in umil minister.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '2', '1', 'Dolce, paziente è il Tuo amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '2', '2', 'Che a Cristo lega i cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '2', '3', 'Di santa gioia li empi Tu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '2', '4', 'Ed il lodare Lui lassù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '2', '5', 'E\' loro occupazion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '3', '1', 'Il Tuo servizio compi or');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '3', '2', 'Pel Padre e pel Figliol;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '3', '3', 'La Loro gloria procacciar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '3', '4', 'E\' Tuo piacere, e assicurar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '3', '5', 'Di Dio l\'intero pian.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '4', '1', 'Te che sei Dio or adoriam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '4', '2', 'A Te noi c\'inchiniam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '4', '3', 'Benedizione, lode e onor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '4', '4', 'Alla Persona Tua ognor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('21', '4', '5', 'Con gioia noi rendiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('22', '7.6.7.6.7.6.7.6.', '34', '72');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('22', '1', '1', 'QUANT\' è meravigliosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('22', '1', '2', 'Di Dio la bontà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('22', '1', '3', 'D\'ogni peccato e colpa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('22', '1', '4', 'Ei liberato m\'ha.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('22', '1', '5', 'Del Salvator nel sangue');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('22', '1', '6', 'Netto il mio cuore or è:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('22', '1', '7', 'Non v\'è una nube in cielo-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('22', '1', '8', 'Non una macchia in me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('22', '2', '1', 'Cristo morì! Son puro:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('22', '2', '2', 'Non una macchia è in me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('22', '2', '3', 'Grande è l\'amor di Dio!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('22', '2', '4', 'Non una nube è in ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('22', '2', '5', 'Trionfa sul peccato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('22', '2', '6', 'Lo Spirto per la fé:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('22', '2', '7', 'Non v\' è una nube in cielo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('22', '2', '8', 'Non una macchia in me.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('23', '10.10.10.9.(a)', '168', '100');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('23', '1', '1', 'COM\'è buono l\'Iddio Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('23', '1', '2', 'L\'immutabile Amico fedele!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('23', '1', '3', 'Di Lui, pari alla forza, l\'amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('23', '1', '4', 'Né misura né fine non ha.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('23', '2', '1', 'Per lo Spirto di Cristo volgiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('23', '2', '2', 'Ver\' la casa per noi preparata;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('23', '2', '3', 'Lui per quello che avvenne lodiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('23', '2', '4', 'Pure in Lui pel futuro fidiam!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('24', '8.8.8.8.', '30', '193');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('24', '1', '1', 'IL nome sia di Vincitor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('24', '1', '2', 'A Lui che solo combattè;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('24', '1', '3', 'Nel vincer nostro, onor non v\'è:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('24', '1', '4', 'Siam trionfanti nel Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('24', '2', '1', 'In debolezza, in disonor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('24', '2', '2', 'Ei la corona conquistò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('24', '2', '3', 'Tutti i nemici umiliò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('24', '2', '4', 'Mediante Sua umiliazion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('24', '3', '1', 'Spezzò di Satana il poter,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('24', '3', '2', 'La morte, nel morir, piegò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('24', '3', '3', 'Fatto peccato, annullò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('24', '3', '4', 'Ei del peccato il triste imper.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('24', '4', '1', 'Lodate l\'immolato Agnel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('24', '4', '2', 'Che la vittoria conseguì,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('24', '4', '3', 'Ei che viveva, che morì,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('24', '4', '4', 'Che vive nella gloria in ciel.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('25', '10.11.10.11.', '172', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '1', '1', 'PADRE, il Tuo Nome benedir vogliam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '1', '2', 'Come fanciulli ammaestrati in grazia;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '1', '3', 'A Te in giustizia i nostri cuor leviam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '1', '4', 'Ed esultiam dinanzi a la Tua faccia.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '2', '1', 'Dolce è la confidenza che Tu dài,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '2', '2', 'Benché al di sopra d\'ogni nostra lode;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '2', '3', 'A Te veniamo là dove Tu stai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '2', '4', 'E in quella luce il nostro cuore gode.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '3', '1', 'Là nel proponimento del Tuo cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '3', '2', 'Il nostro posto già è preparato:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '3', '3', 'Tuoi figli siam con Quei che nel Suo amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '3', '4', 'Tutte le nostre pene ha sopportato.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '4', '1', 'In Lui, finora assente, noi posiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '4', '2', 'Finché nel mondo ancora camminiamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '4', '3', 'Con speme, Lui che ci trasporterà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '4', '4', 'Oltre il poter di morte, qui attendiamo.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '5', '1', 'O Padre Santo, tienici quaggiù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '5', '2', 'Nel Nome Tuo d\'amore benedetto-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '5', '3', 'Fa\' che, attendendo il gaudio di lassù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('25', '5', '4', 'Senza timor viviam al Tuo cospetto.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('26', '11.10.11.10.', '52', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '1', '1', 'L\'AMORE Tuo, Padre, è nostra parte,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '1', '2', 'Qual figli, a Cristo simili, noi siam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '1', '3', 'Con Te: chi mai può dire un tale amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '1', '4', 'Cosi perfetto, libero, sovran?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '2', '1', 'Tu Padre Suo, nostro pur per grazia;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '2', '2', 'La stessa Sua delizia noi gustiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '2', '3', 'Nello splendor del volto Tuo gioiosi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '2', '4', 'Del ciel nell\'infinita luce stiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '3', '1', 'Un\'immutabil gloria empie il luogo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '3', '2', 'Dove Gesù dimora, là nel ciel;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '3', '3', 'Pure maggiore gioia pregustiamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '3', '4', 'Con Lui, per sempre presso Lui, sarem!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '4', '1', 'I secoli a venir diran le immense');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '4', '2', 'Ricchezze di Tua grazia per color');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '4', '3', 'Che in Tua presenza condivideranno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '4', '4', 'Di figli un posto col Tuo Figlio ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '5', '1', 'Padre, il Tuo amor, sorgente d\'ogni cosa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '5', '2', 'Più dolce ancor dei doni che ci dà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '5', '3', 'Sovra di noi or brilla, e come sempre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '5', '4', 'Vive Gesù, per sempre durerà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '6', '1', 'Sì, noi gioiamo in Te, poiché l\'eterna');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '6', '2', 'Nostra porzion è l\'amor Tuo divin:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '6', '3', 'Simili al Tuo Figliol, con Lui nel cielo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('26', '6', '4', 'Nella beatitudin senza fin.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('27', '14.14.14.14.', '85', '85');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('27', '1', '1', 'O DIO, la Tua grandezza, lieti in cuor, riconosciam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('27', '1', '2', 'E la Tua gloria e Tua potenza uniti celebriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('27', '1', '3', 'Tu sei l\'Onnipotente, le Tue vie son un mister');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('27', '1', '4', 'Ed è la Tua sapienza al di là d\'ogni pensier.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('27', '2', '1', 'Se pure imperi cadon e nazioni non son più,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('27', '2', '2', 'Con noi Tu sei e tutto con amor dirigi Tu:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('27', '2', '3', 'Tu ci sostieni mentre proseguiamo nel cammin,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('27', '2', '4', 'Con rinnovate forze giungeremo noi al fin.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('28', '10.9.10.9.10.9.10.9.', '177', '89');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '1', '1', 'SALVE, Cristo una volta reietto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '1', '2', 'Le Tue lodi amiamo cantar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '1', '3', 'Tu soffristi, Signor, per salvarci');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '1', '4', 'Ed a Dio ci volesti portar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '1', '5', 'Su di Te nostre pene prendesti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '1', '6', 'Fosti l\'umile Uom dei dolor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '1', '7', 'Or, godendo il favore divino,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '1', '8', 'Vita abbiam nel Tuo Nome, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '2', '1', 'Gesù, salve! Sul trono nel cielo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '2', '2', 'Coronato in divina maestà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '2', '3', 'Te per fé contemplando, T\'offriamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '2', '4', 'Un tributo che fine non ha.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '2', '5', 'Or paziente Tu attendi quell\'ora,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '2', '6', 'Quando in gloria i Tuoi santi saran');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '2', '7', 'E, con Te nell\'eterne dimore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '2', '8', 'La Tua gioia, Signore, godran.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '3', '1', 'Presto, in ciel, l\'uno all\'altro la storia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '3', '2', 'Di Tua grazia, Signor, narrerem,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '3', '3', 'E l\'amor che a morir Ti condusse,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '3', '4', 'Adorandoti, celebrerem;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '3', '5', 'Nella contemplazion di Tua gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '3', '6', 'In eterno potrem dimorar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '3', '7', 'E cantar quell\'amore che in terra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('28', '3', '8', 'Pienamente nessun può lodar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('29', '8.7.8.7.8.7.8.7.', '25', '53');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '1', '1', 'SIGNOR nostro, nostro tutto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '1', '2', 'A Te accanto ci stringiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '1', '3', 'Quando tutto cade, un posto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '1', '4', 'Sotto l\'ale Tue troviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '1', '5', 'T\'invochiamo, confidando');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '1', '6', 'Nel Tuo Nome, Salvator:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '1', '7', 'Ieri, oggi, come sempre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '1', '8', 'Tu lo Stesso sei, Signor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '2', '1', 'Scorre il tempo, i nostri giorni');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '2', '2', 'Incalzanti e brevi son;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '2', '3', 'Mille anni, al Tuo cospetto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '2', '4', 'Sono come un giorno sol.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '2', '5', 'Ma Tua maestà non muta,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '2', '6', 'Il Tuo Nome è eccelso ognor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '2', '7', 'Attraverso il tempo eterno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '2', '8', 'Tu lo Stesso sei, Signor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '3', '1', 'Sei dei mondi Creatore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '3', '2', 'E del firmamento Tu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '3', '3', 'Ma lor glorie tog1ierai-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '3', '4', 'Non saran trovati più.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '3', '5', 'Pure gli anni Tuoi rimangon,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '3', '6', 'Non ha fine mai il Tuo onor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '3', '7', 'La potenza Tua acclamiamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('29', '3', '8', 'Tu lo Stesso sei, Signor!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('30', '9.8.9.8. Dattilico.', '112', '81');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('30', '1', '1', 'SIGNORE, dai Tuoi radunati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('30', '1', '2', 'Attendi un ricordo d\'amor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('30', '1', '3', 'Nel pan che rompiamo ci parli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('30', '1', '4', 'Del corpo Tuo datoci allor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('30', '2', '1', 'Tu il Vaso piacevole a Dio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('30', '2', '2', 'Nel Suo servizio ogni dì');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('30', '2', '3', 'Soffristi per tutto il cammino:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('30', '2', '4', 'In Te il Suo voler si compì.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('30', '3', '1', 'Il calice, la comunione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('30', '3', '2', 'Del Tuo sangue, insieme beviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('30', '3', '3', 'A Te che sei Figlio di Dio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('30', '3', '4', 'Uniti l\'amore diciam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('31', '12.11.12.11.', '33', '125');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('31', '1', '1', 'SOL breve ci resta un momento d\'attesa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('31', '1', '2', 'Ben presto il Signore dal ciel scenderà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('31', '1', '3', 'Vegliam dunque intenti in preghiera e digiuno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('31', '1', '4', 'Ché, ben lo sappiamo, Ei non tarderà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('31', '2', '1', 'Con voce d\'arcangel, di Dio con la tromba,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('31', '2', '2', 'Verrà nelle nubi a rapirci lassù;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('31', '2', '3', 'Colui che attendiamo con santo desìo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('31', '2', '4', 'Verrà fra non molto, Ei stesso Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('31', '3', '1', 'Sappiamo che i santi, già in Cristo dormienti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('31', '3', '2', 'Risorti, il Signore con Sé porterà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('31', '3', '3', 'E noi che saremo quaggiù sulla terra,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('31', '3', '4', 'Uniti con loro, nel ciel rapirà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('31', '4', '1', 'Deh! vieni, si vieni, glorioso Signore!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('31', '4', '2', 'Accogli i Tuoi santi a gioire con Te:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('31', '4', '3', 'Allora nel cielo godrem pienamente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('31', '4', '4', 'Le gioie che nostre son già per la fé.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('32', '7.6.7.6.', '41', '204');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('32', '1', '1', 'O BENEDETTO e santo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('32', '1', '2', 'Divin Consolator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('32', '1', '3', 'Il nostro cuor Ti rende');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('32', '1', '4', 'Adorazione e onor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('32', '2', '1', 'Deh! fa\' che la Tua voce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('32', '2', '2', 'Con umiltà ascoltiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('32', '2', '3', 'E che da Te sorretti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('32', '2', '4', 'Più non Ti rattristiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('32', '3', '1', 'Ci dona grazia e forza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('32', '3', '2', 'A fin che camminiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('32', '3', '3', 'Con Te, per luce e guida,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('32', '3', '4', 'Finché quaggiù restiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('32', '4', '1', 'O Santo che dal cielo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('32', '4', '2', 'Venisti ausilio a dar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('32', '4', '3', 'A Te le nostre lodi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('32', '4', '4', 'Amiamo tributar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('33', '13.13.14.14.', '201', '53');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('33', '1', '1', 'VIENI, Signor Gesù, o Principe di Pace,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('33', '1', '2', 'Radice di David e sua Progenie sei;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('33', '1', '3', 'Uomo dal Padre scelto, Fedele e Verace,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('33', '1', '4', '"Vieni!" lo Spirto dice, la sposa dice: "Vieni!"');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('33', '2', '1', 'A Te che sei lassù, di sopra d\'ogni cosa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('33', '2', '2', 'Or dal deserto sal d\'amor l\'ansiosa voce:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('33', '2', '3', 'Dove quaggiù moristi T\'attende la Tua sposa-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('33', '2', '4', '"Vieni!" lo Spirto dice, la sposa dice: "Vieni!"');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('33', '3', '1', 'L\'oscurità quaggiù è in parte già passata:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('33', '3', '2', 'O Stella del Mattin, risplendi nel cuor nostro,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('33', '3', '3', 'Chiamando la Tua sposa per esser al Tuo lato!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('33', '3', '4', '"Vieni!" lo Spirto dice, la sposa dice: "Vieni!"');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('34', '8.8.8.8.8.8.', '26', '51');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('34', '1', '1', 'IL Salvator, Gesù, chi è?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('34', '1', '2', 'L\'Iddio possente, fatto Uom!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('34', '1', '3', 'Or è per noi il Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('34', '1', '4', 'Portare a Dio gli erranti vuol.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('34', '1', '5', 'Sul legno il sangue Suo versò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('34', '1', '6', 'E d\'ogni mal ci liberò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('34', '2', '1', 'Nel mondo pace non avrai:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('34', '2', '2', 'Oh, cessa il vano tuo lottar!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('34', '2', '3', 'Nel Salvator la troverai,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('34', '2', '4', 'Avrai riposo nel Suo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('34', '2', '5', 'Il Salvator, Gesù, chi è?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('34', '2', '6', 'Colui che Si donò per me!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('35', '11.10.11.10.', '52', '58');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('35', '1', '1', 'O DIO d\'amore, come i Tuoi pensieri');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('35', '1', '2', 'Senza misura a noi svelati son!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('35', '1', '3', 'La lor preziosità nessun può dire,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('35', '1', '4', 'La lor pienezza niun conoscer può.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('35', '2', '1', 'Noi Ti benediciamo per la luce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('35', '2', '2', 'In cui volesti rivelarti a noi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('35', '2', '3', 'Ed il favor di Tua benevolenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('35', '2', '4', 'Per quei che suggellasti come Tuoi.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('35', '3', '1', 'Tu fonte sei di bene, e in Te gioiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('35', '3', '2', 'La Tua splendente gloria noi vediam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('35', '3', '3', 'Ora, mediante di Gesù la morte,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('35', '3', '4', 'Riconciliati siam, e Ti lodiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('35', '4', '1', 'Dai nostri cuor, di santa gioia pieni,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('35', '4', '2', 'Sgorga la lode che ora T\'apportiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('35', '4', '3', 'A Te, o Padre, Figlio e Spirto Santo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('35', '4', '4', 'L\'adorazione e il culto noi rendiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('36', '8.8.8.7.8.8.8.7.', '153', '106');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '1', '1', 'SALVE all\'Unto del Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '1', '2', 'Di David Figliol divino!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '1', '3', 'Viene, il tempo è già vicino,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '1', '4', 'Il Suo regno a cominciar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '1', '5', 'Viene a sollevar l\'oppresso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '1', '6', 'Il prigione a liberare,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '1', '7', 'Il delitto a sgomberare,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '1', '8', 'E con grazia a governar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '2', '1', 'Ei che, con le mani alzate,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '2', '2', 'Da una nuvola fu ascoso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '2', '3', 'Tornerà dal ciel, glorioso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '2', '4', 'Colmo di benedizion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '2', '5', 'Tutti quelli che L\'attendon');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '2', '6', 'Il Suo volto alfin vedranno;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '2', '7', 'Sodisfatti allor saranno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '2', '8', 'E Lui sempre loderan.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '3', '1', 'Scende come pioggia dolce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '3', '2', 'Sovra suolo inaridito,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '3', '3', 'Ed il Suo cammin fiorito');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '3', '4', 'E\' di gioia, speme, amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '3', '5', 'I sovrani della terra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '3', '6', 'Lodi danno a Lui sincere,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '3', '7', 'E con lor nazioni intere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('36', '3', '8', 'Servon lieti al Salvator.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('37', '11.11.11.11.(b)', '192', '110');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('37', '1', '1', '"IN Cristo Gesù" - quale nuova creazion');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('37', '1', '2', 'Nel Figlio di Dio la grazia troviam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('37', '1', '3', 'I cuori ripieni di santa emozion');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('37', '1', '4', 'La lode che non avrà fine cantiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('37', '2', '1', 'Le cose invisibili, eterne del ciel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('37', '2', '2', 'La vista dell\'anima posson colmar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('37', '2', '3', 'In scene superne che là, senza vel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('37', '2', '4', 'Risplendon in gloria per l\'eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('37', '3', '1', 'In questo glorioso reame, di già');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('37', '3', '2', 'Mediante lo Spirto gioire possiam-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('37', '3', '3', 'Oh parte beata, che non finirà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('37', '3', '4', 'A Te riverenti, o Dio, ci prostriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('37', '4', '1', 'E\' "nuova ogni cosa", per sempre passâr');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('37', '4', '2', 'Le cose d\'un tempo; lo sguardo leviam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('37', '4', '3', 'In alto, alla casa con ansia a guardar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('37', '4', '4', 'Il giorno di Dio spuntare vediam!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('38', '9.8.9.8. Giambico.', '161', '120');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '1', '1', 'DIO, inscrutabil, infinito,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '1', '2', 'Di sopra della creazion,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '1', '3', 'Dimori in luce inaccessibil');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '1', '4', 'Di là da ogni relazion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '2', '1', 'Quando consideri le cose');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '2', '2', 'Che in ciel e sulla terra son,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '2', '3', 'Sta scritto, O Dio, che Tu T\'abbassi-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '2', '4', 'Oh, grazia senza paragon!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '3', '1', 'Chi mai a Te consiglio diede,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '3', '2', 'Chi mai conobbe il Tuo pensier?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '3', '3', 'A niuno rendi conto mai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '3', '4', 'Di ciò che in proprio T\'appartien.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '4', '1', 'Pur di Tua maestà la gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '4', '2', 'Trova l\'eguale nel Tuo amor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '4', '3', 'La morte di Gesù dimostra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '4', '4', 'I sentimenti del Tuo cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '5', '1', 'Sei or in Cristo rivelato:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '5', '2', 'Oh, gloria dell\'incarnazion!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '5', '3', 'Ne sia l\'imperituro frutto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('38', '5', '4', 'L\'universal adorazion!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('39', '10.10.10.10.', '21', '11');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('39', '1', '1', 'SIGNOR Gesù, in Te ci rallegriam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('39', '1', '2', 'Poiché Tu sei venuto a noi vicin;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('39', '1', '3', 'Nella Tua gloria Ti presenti ai Tuoi:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('39', '1', '4', 'Con rispondenti cuori T\'adoriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('39', '2', '1', 'La volontà di Dio amasti Tu:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('39', '2', '2', 'Venisti per compirla come Uom,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('39', '2', '3', 'La vita deponesti Tu quaggiù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('39', '2', '4', 'Per prenderla di nuovo, in potestà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('39', '3', '1', 'Ed or, Signor, sei là, l\'inizio Tu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('39', '3', '2', 'Di ciò che pel piacer di Dio sarà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('39', '3', '3', 'E noi con Te, qual Tuoi, Signor Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('39', '3', '4', 'In benedetta vicinanza siam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('40', '11.10.11.10.10.10.', '180', '97');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '1', '1', '"A ME guardate!" grida il Salvatore:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '1', '2', 'Sopra la croce, ecco, il Santo muor-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '1', '3', 'In sacrificio, Ei Vittima, Si diede,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '1', '4', 'L\'Agnel di Dio, possente Salvator!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '1', '5', 'Di Dio l\'amore appieno visto fu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '1', '6', 'Quando i peccati espiò Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '2', '1', 'Ora solenne! Ora senza eguale-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '2', '2', 'In solitaria forza, là il Figliol');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '2', '3', 'Unico di Dio Padre, fatto Uomo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '2', '4', 'Pei peccatori spira - oh, qual vision!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '2', '5', 'Signor di gloria, Ei crocifisso fu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '2', '6', 'Signor di vita, Ei morì quaggiù!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '3', '1', 'Di morte degni, o Dio, noi eravamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '3', '2', 'Nostra era tal vendetta, ma portò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '3', '3', 'L\'Agnello Tuo le nostre colpe in croce,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '3', '4', 'Nostro Garante, il peso ne accettò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '3', '5', 'Con Lui noi siamo morti, con Gesù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '3', '6', 'Quand\'Egli crocifisso per noi fu.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '4', '1', 'Con Lui vivificati con divina');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '4', '2', 'Vita, con Lui risuscitati, i Suoi-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '4', '3', 'E tutti i Suoi son Tuoi- là delle glorie');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '4', '4', 'Del loro Capo brilleran con Lui.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '4', '5', 'Noi, che di morte sol degni eravam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('40', '4', '6', 'Ravvicinati nel Suo sangue siam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('41', '8.5.8.5.8.5.8.5.', '37', '169');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('41', '1', '1', 'RAMMENTANDOTI, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('41', '1', '2', 'A Te il cuor leviam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('41', '1', '3', 'Ed il Nome Tuo adorando');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('41', '1', '4', 'Grati un canto alziam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('41', '1', '5', 'Il Tuo amor a Te ci addusse,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('41', '1', '6', 'Libertà ci diè:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('41', '1', '7', 'D\'un sol cuor e d\'una voce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('41', '1', '8', 'Lodi offriamo a Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('41', '2', '1', 'Tua fu l\'onta del Calvario,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('41', '2', '2', 'Tua la pena fu:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('41', '2', '3', 'Là per noi eterno gaudio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('41', '2', '4', 'Meritasti Tu.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('41', '2', '5', 'Del travaglio Tuo il frutto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('41', '2', '6', 'Vedi Tu, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('41', '2', '7', 'Nella lode che dei Tuoi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('41', '2', '8', 'Sale d\'ogni cuor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('42', '8.7.8.7.8.7.8.7.', '25', '213');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('42', '1', '1', 'OH, pensier meraviglioso!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('42', '1', '2', 'Signor nostro, T\'appartien');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('42', '1', '3', 'Un oggetto che allo stato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('42', '1', '4', 'Tuo d\'umanità convien!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('42', '1', '5', 'Un corrispondente aiuto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('42', '1', '6', 'Che il Tuo Dio formò, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('42', '1', '7', 'A Te simil ed unito-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('42', '1', '8', 'Oh qual gran mister d\'amor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('42', '2', '1', 'Mosso dalle Tue profonde');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('42', '2', '2', 'Affezioni, il nostro cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('42', '2', '3', 'O Signor Gesù, risponde');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('42', '2', '4', 'Con veraci accenti or.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('42', '2', '5', 'Presto al posto Tuo di Capo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('42', '2', '6', 'Parte avrem accanto a Te,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('42', '2', '7', 'Ma possiam, in santa unione,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('42', '2', '8', 'Ora nostra parte aver.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('43', '14.14.14.14.', '85', '83');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('43', '1', '1', 'GESU\', Signore nostro, lietamente T\'adoriam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('43', '1', '2', 'Con gioia ed esultanza Te Signor riconosciam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('43', '1', '3', 'Beati in Tua presenza, ci prostriam dinanzi a Te:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('43', '1', '4', 'Tu di seder sul trono, Salvatore, degno se\'!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('43', '2', '1', 'Oh, come trionfasti, e trionfasti in gloria Tu!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('43', '2', '2', 'La morte fu sconfitta, sua potenza non è più.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('43', '2', '3', 'La glorïosa storia non possiam tacer, Signor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('43', '2', '4', 'Tu sulla morte e sul sepolcro fosti Vincitor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('43', '3', '1', '"Signor, che cos\'è l\'uomo?" noi sclamiam dal nostro cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('43', '3', '2', 'Gesù, l\'Agnel che fu immolato, coronato or!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('43', '3', '3', 'Gioiosi, noi vogliamo le Tue lodi proclamar -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('43', '3', '4', 'La morte hai dominato e vinto nel risuscitar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('43', '3', '5', '"Signor, che cos\'è l\'uomo?" Con profonda adorazion,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('43', '3', '6', 'Gesù, divin Signore, Capo della creazion,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('43', '3', '7', 'La lode inesauribil eleviam dinanzi a Te:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('43', '3', '8', 'Supremo ad ogni cosa, Capo della chiesa se\'!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('44', '11.10.11.6.', '187', '9');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '1', '1', 'SIGNORE Gesù Cristo, che in Tua grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '1', '2', 'Prendesti il posto un dì dei peccator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '1', '3', 'Di Dio la gloria sul Tuo volto or splende!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '1', '4', 'Io vengo a Te, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '2', '1', 'Là dove Tu, Figliol di Dio, Ti tieni,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '2', '2', 'In quel fulgor di gloria che ad ognor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '2', '3', 'Con l\'opra Tua perfetta meritasti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '2', '4', 'Io vengo a Te, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '3', '1', 'Là per conoscer Te nell\'amor Tuo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '3', '2', 'Che nella morte fu provato allor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '3', '3', '(Nelle superne altezze ora siedi!)');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '3', '4', 'Io vengo a Te, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '4', '1', 'Così qual sei in somma gloria, centro');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '4', '2', 'Delle celesti corti di splendor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '4', '3', 'Degno d\'onor, di forza e di potenza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '4', '4', 'Io vengo a Te, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '5', '1', 'Da me distolgo, o mio Signor, lo sguardo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '5', '2', 'Per imparar di Dio la grazia e amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '5', '3', 'In Te, che il miserabil non respingi-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('44', '5', '4', 'Io vengo a Te, Signor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('45', '12.11.12.11.', '33', '76');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('45', '1', '1', 'O DIO nostro Padre, con gioia vogliamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('45', '1', '2', 'Le lodi del santo Tuo Nome cantar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('45', '1', '3', 'L\'amor Tuo perfetto ricaccia il timore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('45', '1', '4', 'E può di Tua pace i cuor nostri colmar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('45', '2', '1', 'L\'immenso valor del Tuo Figlio apportiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('45', '2', '2', 'Sua lode con cuori adoranti cantiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('45', '2', '3', 'Fu Lui, Gesù, il Cristo, che in grazia discese');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('45', '2', '4', 'Al fin che il prezioso Tuo amor conosciam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('45', '3', '1', 'Con cuori ricolmi Te, fonte sovrana');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('45', '3', '2', 'D\'eterno gioire, o Padre, lodiam-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('45', '3', '3', 'Portati or a Te, dal Tuo Spirto condotti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('45', '3', '4', 'Mediante Gesù, nostro Capo, adoriam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('46', '9.8.9.8. Giambico.', '161', '115');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '1', '1', 'GESU\', il glorioso Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '1', '2', 'Tema è del canto eterno in ciel;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '1', '3', 'Egli perdono e pace t\'offre:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '1', '4', 'Non vuoi a Lui appartener?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '2', '1', 'Nel mondo dove morte regna,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '2', '2', 'E\' il cuor tuo oppresso dal dolor?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '2', '3', 'Ei ti comprende, e vuol che a Lui');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '2', '4', 'Tu venga - in Lui v\'è vita e amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '3', '1', 'Ei vuol stornarti dal peccato-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '3', '2', 'Gioia nei suoi piacer non v\'è-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '3', '3', 'E darti vuol tesori occulti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '3', '4', 'Grazia che abbonda verso te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '4', '1', 'Prima che il cuore tuo battesse,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '4', '2', 'Prima che fosse il mondo ancor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '4', '3', 'L\'amor divin per l\'uom dispose');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '4', '4', 'Felicità nello splendor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '5', '1', 'Se i tuoi peccati ti condannan,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '5', '2', 'Lo stato tuo più grave è ancor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '5', '3', 'Gesù moriva per salvarti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '5', '4', 'Tutti i peccati Ei portò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '6', '1', 'Or quale Uomo vive in cielo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '6', '2', 'Di Dio alla destra, in ogni onor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '6', '3', 'E vuol salvarti e benedirti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('46', '6', '4', 'A te Sua mano è tesa ancor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('47', '10.9.10.9.', '114', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '1', '1', 'TU parlasti, Signor! Fu Tua voce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '1', '2', 'Che i cuor nostri attirò presso Te;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '1', '3', 'Che ci addusse alla scelta migliore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '1', '4', 'Ove liberi grazia ci fe\'.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '2', '1', 'Tu vuoi pur che, in costante letizia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '2', '2', 'Per la fede quaggiù camminiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '2', '3', 'Noi udimmo Tua voce, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '2', '4', 'E il dolor del Tuo amore sappiam-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '3', '1', 'Conosciam la Tua gloria: il deserto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '3', '2', 'A noi pace giammai non può dar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '3', '3', 'Nel sentier ci affrettiamo, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '3', '4', 'Il Tuo santo riposo a gustar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '4', '1', 'Nostra gioia perenne, o Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '4', '2', 'E\' riposta lassù presso Te,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '4', '3', 'Per quel giorno in cui noi Ti vedremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '4', '4', 'E conflitto mai più non avrem.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '5', '1', 'In Te noto è l\'amore divino');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '5', '2', 'E le glorie del Padre vedrem');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '5', '3', 'Presto appieno con occhi rapiti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '5', '4', 'E qual gioia e corona Te avrem.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '6', '1', 'Presto noi Ti vedrem qual Tu sei:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '6', '2', 'Oh speranza beata! Lassù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '6', '3', 'Alla casa del Padre, al riposo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '6', '4', 'Nostra parte, ci chiamerai Tu!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '7', '1', 'O riposo ineffabil, divino,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '7', '2', 'Il riposo di Dio nel ciel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '7', '3', 'Dove Te, nostra gioia ed amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('47', '7', '4', 'In eterno brillare vedrem!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('48', '5.5.4.5.5.4.', '40', '47');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('48', '1', '1', 'OH! infinito');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('48', '1', '2', 'Eterno Dio!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('48', '1', '3', 'Noi ci prostriam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('48', '1', '4', 'La Tua grandezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('48', '1', '5', 'Riconosciamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('48', '1', '6', 'E Ti lodiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('48', '2', '1', 'Il Tuo Diletto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('48', '2', '2', 'Conobbe appieno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('48', '2', '3', 'Il Tuo cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('48', '2', '4', 'Te ha rivelato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('48', '2', '5', 'E dichiarato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('48', '2', '6', 'Qui in amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('48', '3', '1', 'Te contemplando,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('48', '3', '2', 'Noi riverenti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('48', '3', '3', 'In Te gioiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('48', '3', '4', 'In Cristo accetti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('48', '3', '5', 'Ora e in eterno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('48', '3', '6', 'Noi T\'adoriam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('49', '11.10.11.10.', '52', '25');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('49', '1', '1', 'PADRE di gloria, grati T\'adoriamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('49', '1', '2', 'Di lode Tua grandezza è al di là;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('49', '1', '3', 'Noi Ti benediciam - lo Spirto in noi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('49', '1', '4', 'Potenza a tal celeste canto dà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('49', '2', '1', 'Pensiamo all\'Uomo nella Tua presenza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('49', '2', '2', 'Capo esaltato, assiso in ciel, lassù-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('49', '2', '3', 'Risuscitato per la Tua potenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('49', '2', '4', 'Quando coi morti annoverato fu.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('49', '3', '1', 'Pensiamo a quella gloria che ci elesse:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('49', '3', '2', 'Ne sei la Fonte, Padre Santo, Tu;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('49', '3', '3', 'La gloria dell\'amor che ci redense');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('49', '3', '4', 'Nell\'Uomo della scelta Tua, Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('49', '4', '1', 'Come predestinati all\'adozione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('49', '4', '2', 'La gloria della grazia noi lodiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('49', '4', '3', 'E, conoscendo in Cristo il nostro posto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('49', '4', '4', 'Chinati in Tua presenza, T\'adoriam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('50', '10.9.8.9.', '178', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('50', '1', '1', 'DELL\' Albero della Vita gustiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('50', '1', '2', 'Noi la dolcezza in Te, Signor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('50', '1', '3', 'A quel paese cui tendiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('50', '1', '4', 'S\'accorda perfettamente ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('50', '2', '1', 'Di vita celeste cibo, in amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('50', '2', '2', 'Proposto in piani d\'eternità;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('50', '2', '3', 'Di vita i frutti, freschi ognor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('50', '2', '4', 'Quell\'Albero benedetto dà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('50', '3', '1', 'E\' un unico frutto, eguale ad ognor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('50', '3', '2', 'Che Tu ci offri tuttor, benché');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('50', '3', '3', 'Sì vario e ricco di valor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('50', '3', '4', 'E tutto provien, Signor, da Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('50', '4', '1', 'Sì, frutti che l\'alma nostra gustò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('50', '4', '2', 'Già per lo Spirito, mentre qui');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('50', '4', '3', 'Andiamo nel deserto ancor-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('50', '4', '4', 'Son frutti d\'amor che non ha fin.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('51', '8.8.8.7.', '151', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '1', '1', 'QUANDO penso a Te, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '1', '2', 'Al Tuo amor per me infinito');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '1', '3', 'Il mio cuore a Te è rapito');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '1', '4', 'Al pensier di Tua bontà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '2', '1', 'Pur se guardo in me, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '2', '2', 'Quanto debol è il cuor mio!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '2', '3', 'Vacillante è il mio desìo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '2', '4', 'Più di quello d\'un bambin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '3', '1', 'Ma il Tuo amore mai non muta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '3', '2', 'E richiama a Te il mio cuore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '3', '3', 'Per goder del suo fulgore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '3', '4', 'Nella pace senza fin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '4', '1', 'Deh, Tu donami costanza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '4', '2', 'Per restare al Tuo cospetto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '4', '3', 'E trovare il mio diletto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '4', '4', 'Sempre in Te, Signor Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '5', '1', 'Sì ch\'io possa maggiormente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '5', '2', 'Te conoscer ogni giorno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '5', '3', 'Attendendo il Tuo ritorno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '5', '4', 'Con amore e fedeltà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '6', '1', 'E se pur, per la mia colpa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '6', '2', 'Una nube i raggi oscura,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '6', '3', 'Pure è cosa ben sicura');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '6', '4', 'Che il Tuo sol la sperderà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '7', '1', 'Oh, mantieni l\'alma mia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '7', '2', 'Dimorante in Te, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '7', '3', 'Sì che i frutti del Tuo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '7', '4', 'In me possano brillar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '8', '1', 'E ch\' io cresca giornalmente,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '8', '2', 'Benché in piccola misura,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '8', '3', 'Nella santa Tua natura');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('51', '8', '4', 'Finché Teco in ciel sarò.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('52', '10.9.10.9.10.9.10.9.', '177', '177');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '1', '1', 'PADRE Santo, a Te noi cantiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '1', '2', 'Nella luce divina lassù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '1', '3', 'Nei reami del santo consiglio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '1', '4', 'Ove brilla il fulgor di Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '1', '5', 'Benedetti nei luoghi celesti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '1', '6', 'Te con cuori adoranti lodiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '1', '7', 'Frutto siam del proposito eterno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '1', '8', 'Dove in gioia riposo gustiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '2', '1', 'Ti lodiam, nostro Padre glorioso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '2', '2', 'Di Tua grazia gli oggetti noi siam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '2', '3', 'Or dinanzi al Tuo volto, esultanti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '2', '4', 'Pel piacer del Tuo cuor ci teniam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '2', '5', 'Noi Tuoi figli, alla gloria proposti-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '2', '6', 'Conosciuti dall\'eternità -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '2', '7', 'Siam con Cristo, il Diletto, che sempre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '2', '8', 'Il Tuo Oggetto supremo sarà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '3', '1', 'Padre Santo, Tu solo potevi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '3', '2', 'Nel Tuo unico, amato Figliol,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '3', '3', 'Benedirci cosi col Tuo Spirto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '3', '4', 'Ed averci Tuoi figli ad ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '3', '5', 'Sì, ben presto, nel dì senza fine,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '3', '6', 'Noi in gloria con Cristo sarem;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '3', '7', 'Nell\'immagine Sua benedetta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('52', '3', '8', 'Brillerem in eterno, Amen!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('53', '10.9.l0.9.10.9.10.9.', '177', '65');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '1', '1', 'OR la buona novella che Dio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '1', '2', 'Nel Suo Cristo rivela cantiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '1', '3', 'La Sua santa Persona lodiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '1', '4', 'E per l\'opra compiuta L\'amiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '1', '5', 'Egli è Dio, benedetto in eterno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '1', '6', 'E per sempre lo Stesso sarà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '1', '7', 'Ma pur venne quaggiù per salvarci,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '1', '8', 'Discendendo nell\'umanità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '2', '1', 'Per compire quest\'opra da solo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '2', '2', 'Sulla croce Se stesso Egli diè');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '2', '3', 'Ed il peso portò dei peccati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '2', '4', 'Che gravava su voi e su me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '2', '5', 'Or asceso, alla destra di Dio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '2', '6', 'Trionfante nel ciel Lo vediam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '2', '7', 'Sodisfatta è di Dio la giustizia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '2', '8', 'Ed in Lui pur accetti noi siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '3', '1', 'In Gesù trova il Padre diletto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '3', '2', 'Ed in quei che il Suo sangue acquistò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '3', '3', 'E lo Spirto ai nostri occhi presenta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '3', '4', 'Il vivente e glorioso Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '3', '5', 'Dal peccato e dal mondo salvati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '3', '6', 'Già al presente nel Cristo noi siam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '3', '7', 'Nella separazion camminando');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('53', '3', '8', 'Mentre il nostro Signor attendiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('54', '7.6.7.6.', '41', '109');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '1', '1', 'E\' DOLCE pel fedele');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '1', '2', 'Il Nome del Signor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '1', '3', 'Dilegua le sue pene');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '1', '4', 'E caccia il suo timor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '2', '1', 'Consola il cuore afflitto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '2', '2', 'Dà pace nel dolor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '2', '3', 'All\'affamato è pane,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '2', '4', 'Riposo al vïator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '3', '1', 'O Nome tanto amato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '3', '2', 'Sicuro asil divin,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '3', '3', 'Tesoro sempre pieno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '3', '4', 'Di grazia senza fin!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '4', '1', 'Gesù, Amico, Sposo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '4', '2', 'Profeta, Re, Pastor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '4', '3', 'O Vita nostra e Guida,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '4', '4', 'A Te diam lode ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '5', '1', 'E\' debol nostra lode');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '5', '2', 'E freddo il nostro cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '5', '3', 'Ma in cielo degnamente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '5', '4', 'Ti loderem, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '6', '1', 'Or mentre T\'attendiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '6', '2', 'La grazia Tua annunciar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '6', '3', 'Fa\' che possiam, fedeli,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('54', '6', '4', 'E il Nome Tuo onorar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('55', '8.8.8.7.8.8.8.7.', '153', '172');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '1', '1', 'NOI poniam le nostre vie,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '1', '2', 'Ciò che affligge il nostro cuore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '1', '3', 'Nell\'ognor fedeli cure');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '1', '4', 'Di Colui che regge il ciel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '1', '5', 'Che alle nubi il corso impone');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '1', '6', 'Ed al vento il suo cammino:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '1', '7', 'Al Suo popol pellegrino');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '1', '8', 'Il sentiero traccerà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '2', '1', 'Fedeltà e grazia eterne!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '2', '2', 'Tu conosci, O Padre, ognora,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '2', '3', 'Per la Tua creatura');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '2', '4', 'Quel che il bene produrrà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '2', '5', 'Sì, Tu porti in esistenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '2', '6', 'Quel ch\'è grato al Tuo cospetto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '2', '7', 'E le cose che hai eletto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '2', '8', 'Tua potenza adempirà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '3', '1', 'Noi lasciamo a Te disporre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '3', '2', 'Ogni cosa in nostro bene:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '3', '3', 'Presto la benedizione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '3', '4', 'Dal dolore sgorgherà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '3', '5', 'Nel prezioso Tuo consiglio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '3', '6', 'Nel sovrano Tuo diritto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '3', '7', 'Ogni cosa che ci ha afflitto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '3', '8', 'La Tua man trasformerà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '4', '1', 'Il Tuo popol Tu conduci,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '4', '2', 'Lo sostieni in ogni ora;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '4', '3', 'Noi fidiamo nella cura');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '4', '4', 'Benedetta del Tuo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '4', '5', 'Se la notte e la tempesta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '4', '6', 'Attraversa nostra via,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '4', '7', 'Nostro Dio, Tua signoria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('55', '4', '8', 'Tutto in bene condurrà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('56', '9.8.9.8.9.8.9.8. Dattilico.', '125', '146');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '1', '1', 'SIGNOR, com\'è dolce il cammino,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '1', '2', 'Benché siam erranti qui ancor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '1', '3', 'Ché già il nostro spirito gode');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '1', '4', 'Del Padre il divino favor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '1', '5', 'Per fede riposo troviamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '1', '6', 'Là dove seduto sei Tu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '1', '7', 'E al cielo guardare possiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '1', '8', 'Poiché il nostro Capo è lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '2', '1', 'In spirto lassù già noi siamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '2', '2', 'E presto, felici, sarem');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '2', '3', 'In anime e corpi perfetti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '2', '4', 'E glorificati, con Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '2', '5', 'Del Padre l\'amor ci sostiene');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '2', '6', 'Durante il penoso cammin;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '2', '7', 'Del Padre la casa anelata');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '2', '8', 'E\' pronta per quel lieto fin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '3', '1', 'Il Consolator ci assicura');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '3', '2', 'L\'amor Tuo divino, quaggiù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '3', '3', 'Ei stesso è l\'Arra preziosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '3', '4', 'Di fulgida gloria lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '3', '5', 'Ed ora il piacere di Dio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '3', '6', 'Sostegno e rinfresco ci dà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '3', '7', 'Finché sulla fronte dei santi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '3', '8', 'Il nuovo Tuo Nome sarà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '4', '1', 'Signor, la Tua gloria attendiamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '4', '2', 'La sola dimora per noi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '4', '3', 'E\' in cielo, là dove a Tua gioia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '4', '4', 'Avranno con Te parte i Tuoi.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '4', '5', 'Per noi non v\'è qui luogo caro');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '4', '6', 'Se Tu non vi sei, o Signor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '4', '7', 'In Te e con Te sta, per grazia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('56', '4', '8', 'La nostra porzione ad ognor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('57', '8.7.8.7.7.7.7.6.', '145', '53');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('57', '1', '1', 'LA\' nella gloria fulgida');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('57', '1', '2', 'Dal cielo coronato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('57', '1', '3', 'Stai tra le schiere angeliche');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('57', '1', '4', 'Potente ed adorato.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('57', '1', '5', 'Qual grano in terra ascoso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('57', '1', '6', 'Tu sol non rimanesti:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('57', '1', '7', 'Risorto ci facesti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('57', '1', '8', 'Compagni Tuoi, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('57', '2', '1', 'Ed or con santo giubilo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('57', '2', '2', 'Il Nome Tuo glorioso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('57', '2', '3', 'I nostri cuori lodano,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('57', '2', '4', 'Signore, Capo e Sposo!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('57', '2', '5', 'Ed or attendi il giorno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('57', '2', '6', 'Che resa alfin perfetta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('57', '2', '7', 'La sposa Tua diletta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('57', '2', '8', 'Al fianco Tuo sarà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('58', '11.10.11.10.', '52', '97');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('58', '1', '1', 'SIGNOR, siam Tuoi! Col sangue Tuo comprati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('58', '1', '2', 'Noi ch\'eravamo schiavi e peccator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('58', '1', '3', 'Da Te redenti, siam a Dio portati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('58', '1', '4', 'E pur lo Spirto hai dato ai nostri cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('58', '2', '1', 'Signore, siamo Tuoi, T\'apparteniamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('58', '2', '2', 'E sempre a Te vogliamo appartener.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('58', '2', '3', 'Nei nostri cuori regna e fa\' che siamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('58', '2', '4', 'Ognor soggetti al Tuo divin voler.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('58', '3', '1', 'Fa\' che a ciascun di noi i vivi rai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('58', '3', '2', 'Della Tua luce splendan già nel cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('58', '3', '3', 'E affretta il dì che manifesterai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('58', '3', '4', 'Davanti al mondo che siam Tuoi, Signor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('59', '7.6.7.6.', '41', '145');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '1', '1', 'IL cuor di Dio è amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '1', '2', 'E amor ti vuole offrir:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '1', '3', 'Per affrancarti, Cristo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '1', '4', 'Il Figlio Suo, morì.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '2', '1', 'Lontan non è il tuo Dio:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '2', '2', 'In grazia attende or');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '2', '3', 'Al fianco tuo, per darti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '2', '4', 'La Sua benedizion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '3', '1', 'Gesù portò il giudizio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '3', '2', 'Dei tuoi peccati allor-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '3', '3', 'Or nulla t\'impedisce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '3', '4', 'D\'entrar nel Suo favor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '4', '1', 'Lo Spirto Santo è dato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '4', '2', 'E il cuor ti riempirà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '4', '3', 'Sorgente è d\'ogni grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '4', '4', 'Che a tutto supplirà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '5', '1', 'Da tal benedizione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '5', '2', 'Lontano vuoi restar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '5', '3', 'Ed all\'amor del Padre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '5', '4', 'Per sempre rinunciar?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '6', '1', 'Di Dio la dimora');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '6', '2', 'Per te aperta sta,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '6', '3', 'Del Padre là godrai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('59', '6', '4', 'L\'amor a eternità.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('60', '8.8.8.7.8.8.8.7.', '153', '58');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('60', '1', '1', 'NOSTRO Padre, Ti lodiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('60', '1', '2', 'Fonte di benedizione;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('60', '1', '3', 'In pienezza dì fulgore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('60', '1', '4', 'Il Figliol Ti rivelò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('60', '1', '5', 'Noi gioiamo in Tua presenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('60', '1', '6', 'E in amore T\'adoriamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('60', '1', '7', 'Or che a Te dinanzi siamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('60', '1', '8', 'In splendente santità.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('61', '14.14.14.14.', '85', '60');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('61', '1', '1', 'O DIO, suprem "IO SONO", riverenti T\'adoriam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('61', '1', '2', 'Ché il Tuo mirabil dono ha posto l\'uom in libertà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('61', '1', '3', 'Di redenzione l\'opra ogni colpa cancellò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('61', '1', '4', 'E un popolo di prìncipi per Dio assicurò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('61', '2', '1', 'Ai Tuoi consigli pria che i mondi fosser noi guardiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('61', '2', '2', 'E i grandi Tuoi pensieri nel formare l\'uom vediam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('61', '2', '3', 'Tu ci affrancasti, nella Tua sovrana volontà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('61', '2', '4', 'Per introdurre vita e gioia e piena libertà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('61', '3', '1', 'Non rimarranno lacrime a turbar la gioia allor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('61', '3', '2', 'Di pura beatitudin della nuova creazion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('61', '3', '3', 'Pel Tuo servizio santo sarà tolto ogni dolor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('61', '3', '4', 'L\'amore Tuo provato pienamente, o Dio d\'amor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('61', '4', '1', 'Oh, qual eccelsa nota di risposta sgorgherà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('61', '4', '2', 'Là dov\'è Tua dimora, per l\'intera eternità!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('61', '4', '3', 'La gran distesa della sfera che creò il Tuo amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('61', '4', '4', 'Gioisce, conoscendo, O Dio, che sei vicino ognor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('62', '7.7.7.6.7.7.7.6.', '142', '17');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('62', '1', '1', 'O DIO dell\'universo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('62', '1', '2', 'Oh, quale assicurasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('62', '1', '3', 'Sfera d\'amore e lode');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('62', '1', '4', 'Di là d\'ogni pensier!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('62', '1', '5', 'Nei giorni senza fine,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('62', '1', '6', 'Cristo e la chiesa sono');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('62', '1', '7', 'Risposta pel Tuo piano');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('62', '1', '8', 'E in questo è il Tuo piacer.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('62', '2', '1', 'Ti diamo culto e lode');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('62', '2', '2', 'Per quel che sei, o Dio;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('62', '2', '3', 'L\'amor Tuo, la Tua grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('62', '2', '4', 'Ricolman ogni cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('62', '2', '5', 'A Te nell\'assemblea,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('62', '2', '6', 'O benedetto Dio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('62', '2', '7', 'Eterna gloria sia -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('62', '2', '8', 'Tua santa parte ognor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('63', '11.11.6.11.11.6.', '195', '46');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('63', '1', '1', 'DIO nostro e Padre, Ti benediciamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('63', '1', '2', 'Il Nome Tuo esaltiam, e con letizia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('63', '1', '3', 'La lode T\'esprimiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('63', '1', '4', 'Che sei "maggior di tutti" noi sappiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('63', '1', '5', 'Ma questa relazion di grazia pone');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('63', '1', '6', 'Nostr\'alma in libertà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('63', '2', '1', 'I Tuoi eletti, benedetti in Cristo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('63', '2', '2', 'Son, nei celesti luoghi, nel riposo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('63', '2', '3', 'Del Tuo paterno amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('63', '2', '4', 'O Padre, come il nostro cuor s\'espande');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('63', '2', '5', 'Verso Te stesso, mentre in Lui, accetti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('63', '2', '6', 'Qual figli Tuoi, noi stiam!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('64', '9.8.9.8. Giambico.', '161', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '1', '1', 'SCENE gloriose e benedette');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '1', '2', 'Dove il peccato non può entrar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '1', '3', 'Che i nostri spirti già distolgon');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '1', '4', 'Da questa terra dove erriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '2', '1', 'Potrem chiamar la nostra casa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '2', '2', 'La casa di Dio Padre, là?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '2', '3', 'Il Suo riposo, potrem dire');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '2', '4', 'Riposo nostro, in libertà?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '3', '1', 'Sì! Nella luce immacolata');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '3', '2', 'Immacolati noi vivrem;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '3', '3', 'I nostri cuori sodisfatti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '3', '4', 'Di Dio il riposo gusterem.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '4', '1', 'In Sua presenza l\'alma nostra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '4', '2', 'Gioia e riposo troverà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '4', '3', 'Allor che, senza mutamento,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '4', '4', 'Il giorno eterno scorrerà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '5', '1', 'A Gesù simili in quel luogo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '5', '2', 'Di luce e di supremo amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '5', '3', 'A Lui, un dì Uom di dolori,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '5', '4', 'Del cielo tema eterno or.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '6', '1', 'L\'amor suprem e benedetto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '6', '2', 'Che il cuor più debol può gustar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '6', '3', 'Di ciò che presto avrem in cielo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('64', '6', '4', 'A noi la luce già vuol dar!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('65', '10.9.10.9.', '114', '7');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '1', '1', 'MENTRE i Tuoi si radunan, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '1', '2', 'D\'aver Te quale Capo gioiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '1', '3', 'Glorïoso Signor, le Tue cure');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '1', '4', 'Per la Tua assemblea sappiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '2', '1', 'Se nel mondo Tu sei rigettato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '2', '2', 'Rinnegata la Tua autorità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '2', '3', 'Noi vogliamo i Tuoi santi interessi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '2', '4', 'Custodir, poi che a noi sei Sovran.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '3', '1', 'Mentre insieme bramiamo curare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '3', '2', 'Ciò ch\'è Tuo, il Tuo aiuto ci da\'!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '3', '3', 'Fa\' che siam quali servi fedeli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '3', '4', 'Sottomessi alla Tua volontà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '4', '1', 'Con franchezza vorremmo affrontare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '4', '2', 'Ciò che Satana può insinuar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '4', '3', 'La saggezza e virtù necessarie');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '4', '4', 'Noi vorremmo da Te solo trar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '5', '1', 'Nella Tua assemblea confidi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '5', '2', 'Ché fedele al Tuo Nome ella è,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '5', '3', 'Testimone verace e splendente,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '5', '4', 'Senza macchia, appartata per Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '6', '1', 'Presto il suon della tromba udiremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '6', '2', 'Che ci chiama la terra a lasciar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '6', '3', 'Questo vaso, da Te acquistato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('65', '6', '4', 'Pronto allora, potrai Tu mostrar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('66', '8.8.8.7.8.8.8.7.', '153', '134');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '1', '1', 'DIO di grazia, il Tuo piacere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '1', '2', 'Nel Tuo Cristo è conosciuto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '1', '3', 'E ci parla dell\'immensa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '1', '4', 'Tua benedizion pei Tuoi.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '1', '5', 'Egli in Tua presenza è entrato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '1', '6', 'Quale Uomo è visto in cielo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '1', '7', 'Il Tuo pian è in Lui mostrato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '1', '8', 'La Tua gloria ha centro in Lui.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '2', '1', 'Pure, qual raggiante amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '2', '2', 'Nel Suo volto brilla ognora!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '2', '3', 'Quale luce si diffonde');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '2', '4', 'Da quel luogo di splendor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '2', '5', 'Ed amore e luce esprimon');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '2', '6', 'Quel che Tu, o Padre, sei,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '2', '7', 'Mentre in grazia nostra parte');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '2', '8', 'Col Tuo Figlio conosciam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '3', '1', 'O sorgente di delizie,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '3', '2', 'Fonte di benedizione!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '3', '3', 'Oh, s\'uniscan tutti i santi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '3', '4', 'Il Tuo Nome a confessar!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '3', '5', 'Ogni cuor la lode esprime');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '3', '6', 'E a Te sal di lodi il coro;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '3', '7', 'Ogni voce è al canto unita');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('66', '3', '8', 'Echeggiando: "Dio è amor".');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('67', '8.8.8.8.8.8.8.8.(a)', '157', '5');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '1', '1', 'DIO e Padre, Ti lodiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '1', '2', 'Lieti siamo al Tuo cospetto;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '1', '3', 'Oltre morte, parte abbiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '1', '4', 'Con il Figlio Tuo diletto.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '1', '5', 'Or risorto, vive in cielo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '1', '6', 'Come Uomo trionfante,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '1', '7', 'Nella luce senza velo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '1', '8', 'Nell\'amore, a Te dinante.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '2', '1', 'Ei nel quale il cuore Tuo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '2', '2', 'Ha riposo pien trovato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '2', '3', 'Ora Dio e Padre Suo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '2', '4', 'E pur nostro T\'ha chiamato.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '2', '5', 'Egli i Suoi a Te conduce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '2', '6', 'Per godere il Tuo favore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '2', '7', 'Del Tuo volto, Dio, la luce,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '2', '8', 'Padre, del Tuo cuor l\'amore.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '3', '1', 'Oh, letizia ben sicura,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '3', '2', 'Pace che non può mutare!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '3', '3', 'Fin che pel Tuo Figlio dura');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '3', '4', 'Quell \'amor, dovrà durare,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '3', '5', 'Padre, pei fratelli Suoi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '3', '6', 'Or con Lui sì associati:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '3', '7', 'Oh, felici i figli Tuoi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('67', '3', '8', 'Come il Tuo Diletto amati!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('68', '10.10.10.10.10.9.', '166', '53');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('68', '1', '1', 'O SIGNOR, che lasciasti la gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('68', '1', '2', 'Tua nel cielo, quaggiù per venire,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('68', '1', '3', 'Chi può mai degnamente lodare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('68', '1', '4', 'Quell\'amor che Ti spinse a morire?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('68', '1', '5', 'Noi, comprati, per sempre Tuoi siamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('68', '1', '6', 'E qui uniti Ti benediciam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('68', '2', '1', 'Ma risorto, Tu, il Primo, dai morti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('68', '2', '2', 'Trionfante nel ciel sei entrato:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('68', '2', '3', 'Glorïoso, se\' il Capo vivente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('68', '2', '4', 'Degno d\'essere sempre adorato.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('68', '2', '5', 'Nel Tuo volto la gloria risplende');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('68', '2', '6', 'E l\'amore divin noi vediam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('69', '11.10.11.10. Dattilico.', '17', '73');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('69', '1', '1', 'O BENEDETTO Signore vivente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('69', '1', '2', 'I nostri cuori, deh, impegna con Te:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('69', '1', '3', 'Vibra la corda che già or risponde');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('69', '1', '4', 'In libertà che l\'amore ci diè.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('69', '2', '1', 'Ravvicinati al Tuo cuore che ama.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('69', '2', '2', 'Presso di Te, al Tuo fianco restar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('69', '2', '3', 'A Te guardando là dove dimori');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('69', '2', '4', 'E nel Tuo amore per sempre posar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('69', '3', '1', 'Per camminare da Te sostenuti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('69', '3', '2', 'Quaggiù le sante Tue vie imparar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('69', '3', '3', 'Per Te crescendo a Tua santa statura,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('69', '3', '4', 'A Te le lodi in eterno donar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('69', '4', '1', 'Sia questo in terra l\'intero piacere,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('69', '4', '2', 'Tu sei l\'oggetto prezioso dei cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('69', '4', '3', 'Pronti alla méta che insieme bramiamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('69', '4', '4', 'H Tuo incontro nell\'aria, Signor.');
