INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('70', '2', '2', '"V\'è posto ancor!"');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('70', '2', '3', 'Amore immenso, senza par -');
