INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('70', '2', '8', '"V\'è posto ancor!"');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('70', '3', '1', 'Vieni, ché tutto è pronto già:');
