INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('71', '11.10.11.10.11.10.11.10.', '183', '111');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '1', '1', 'UDITE il canto che solenne sale!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '1', '2', 'Dolce s\'eleva della lode il cor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '1', '3', 'Dal luogo dove, nel cantare un inno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '1', '4', 'Dei Suoi la voce guida il Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '1', '5', 'La notte del rigettamento Suo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '1', '6', 'Avvolge tutto in cupa oscurità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '1', '7', 'Mentre il Figliol dell\'uomo solo avanza:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '1', '8', 'Fino alla croce, morte e tomba va!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '2', '1', 'Udite il canto che armonioso sale!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '2', '2', 'Soave sgorga della lode il cor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '2', '3', 'Tutta l\'angoscia Sua noi ricordiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '2', '4', 'E uniti alziam la voce al Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '2', '5', 'Tutta la nostra colpa Egli, il diletto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '2', '6', 'Figlio di Dio, su di Sé portò-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '2', '7', 'Mentre le onde, i flutti si versavan');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '2', '8', 'Sul capo Suo, "E\' compiuto" Egli gridò!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '3', '1', 'Udite il canto che gioioso sale!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '3', '2', 'Lieto s\'innalza della lode il cor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '3', '3', 'Noi T\'acclamiamo come il Vincitore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '3', '4', 'Mentre la voce a Te leviam, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '3', '5', 'Tu, rifiutato qui dall\'uomo, siedi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '3', '6', 'Di Dio sul trono, coronato, or;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '3', '7', 'Sì, amen! Tu, Signore, ne sei degno!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '3', '8', 'Sclamiamo insieme con gioioso cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '4', '1', 'Udite il canto che possente sale!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '4', '2', 'Alto risuona della lode il cor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '4', '3', 'Presto la terra e il ciel T\'adoreranno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '4', '4', 'Tutti alzeran la voce a Te, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '4', '5', 'Tu ci hai amati, sì, d\'ogni peccato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '4', '6', 'Con il Tuo sangue ci lavasti Tu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '4', '7', 'Ed ora alziam a Te il felice canto:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('71', '4', '8', 'Degno è l\'Agnello che immolato fu!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('72', '11.10.11.6.', '187', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('72', '1', '1', 'IL nostro Dio, che abbiam ben conosciuto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('72', '1', '2', 'Nell\'infinito amore di Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('72', '1', '3', 'Riposo trova i Suoi nel benedire');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('72', '1', '4', 'Dinanzi a Sé lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('72', '2', '1', 'Il nostro Dio è il centro, e Sua presenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('72', '2', '2', 'Rïempie quella sfera dove son');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('72', '2', '3', 'Dei Suoi l\'immense schiere a Lui d\'intomo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('72', '2', '4', 'In santa adorazion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('72', '3', '1', 'Suprema gloria è là, che tutto inonda');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('72', '3', '2', 'E - privilegio più prezioso ancor -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('72', '3', '3', 'A quell\'amor avranno parte insieme');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('72', '3', '4', 'Quei che chiamò l\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('72', '4', '1', 'Oh, simili a Gesù! Suprema grazia!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('72', '4', '2', 'Simili a Lui dinanzi a Te sarem');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('72', '4', '3', 'E lo splendor di gloria faccia a faccia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('72', '4', '4', 'Là senza vel vedrem.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('73', '11.11.6.11.11.6.', '195', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('73', '1', '1', 'PADRE, Tu ami! Un tal divin favore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('73', '1', '2', 'Favore senza nubi, può posare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('73', '1', '3', 'Appien su noi quaggiù;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('73', '1', '4', 'Brilla il Tuo volto su noi, come sempre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('73', '1', '5', 'Brilla sul Tuo Figliol, la cui splendente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('73', '1', '6', 'Imagin porterem.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('74', '8.8.8.8.', '30', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '1', '1', 'RIPOSO sei dei santi tu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '1', '2', 'Di Dio Gerusalemme, ognor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '1', '3', 'Chi dei palazzi tuoi d\'amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '1', '4', 'La strada d\'or calcò lassù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '2', '1', 'A noi la gioia tua per dir?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '2', '2', 'Oh, luoghi franchi d\'ogni mal,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '2', '3', 'Dove Dio stesso dimorar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '2', '4', 'Si degna ed ogni cuor riempir!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '3', '1', 'Chi a noi la gioia può narrar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '3', '2', 'Dei santi là, che uniti son');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '3', '3', 'In dolce, eterna occupazion');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '3', '4', 'A cui bramiam partecipar?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '4', '1', 'E quel riposo, in sicurtà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '4', '2', 'Non turba nube né dolor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '4', '3', 'V\'è lode eterna in ogni cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '4', '4', 'E amor perenne regnerà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '5', '1', 'La forza dello Spirto già');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '5', '2', 'A noi la porta aprì del ciel:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '5', '3', 'In quel favore senza vel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '5', '4', 'E senza duol ci fece entrar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '6', '1', 'Sarem là sol per adorar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '6', '2', 'Ove nostr\'alme forza avran');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '6', '3', 'E vita e gioia, che non san');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '6', '4', 'La vista e il senso misurar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '7', '1', 'Dio e l\'Agnello ne saran');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '7', '2', 'La luce e il tempio, e nel fulgor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '7', '3', 'Le riscattate schiere ognor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('74', '7', '4', 'Parte al mister svelato avran!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('75', '11.10.11.10.11.10.', '182', '209');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('75', '1', '1', 'GESU\' , Signore nostro, noi cantiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('75', '1', '2', 'Tua fama incomparabil, Tuo valor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('75', '1', '3', 'Di lode i sacrifici T\'apportiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('75', '1', '4', 'Benedicendo il Nome Tuo, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('75', '1', '5', 'E cuori e voci ad onorarti uniamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('75', '1', '6', 'Ché di Tue glorie è colmo il nostro cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('75', '2', '1', 'E pur maggiore lode in Sion T\'attende:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('75', '2', '2', 'Tu sei il suo Signore ed il suo Re;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('75', '2', '3', 'La creazione, in libertà e riposo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('75', '2', '4', 'Con gioia renderà tributo a Te:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('75', '2', '5', 'Confesserà ogni lingua Te Signore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('75', '2', '6', 'E a Te s\'inchineranno terra e ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('75', '3', '1', 'Più dolce ancor- i santi Tuoi saranno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('75', '3', '2', 'La più preziosa gioia pel Tuo cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('75', '3', '3', 'Essi, che nel lodarti troveranno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('75', '3', '4', 'La lor eterna parte là, Signor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('75', '3', '5', 'Con Te lassù, la gloria Tua vedranno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('75', '3', '6', 'Dove sovrano domina l\'amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('76', '8.7.8.7.', '24', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '1', '1', 'ALMA, sorgi, Dio ti chiama,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '1', '2', 'Niuno più t\'impedirà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '1', '3', 'La Sua mano, ti protegge');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '1', '4', 'Che ti diede libertà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '2', '1', 'Se per l\'arido deserto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '2', '2', 'Deve la tua via passar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '2', '3', 'Ricche fonti di freschezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '2', '4', 'Il tuo Dio ti vuol donar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '3', '1', 'Con te va divina luce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '3', '2', 'Che circonda il tuo cammin');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '3', '3', 'D\'ogni bene e che ti guida');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '3', '4', 'Ad un giorno senza fin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '4', '1', 'Non più il duro pan d\'Egitto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '4', '2', 'Prezzo della schiavitù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '4', '3', 'E\' tuo cibo, ma dei forti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '4', '4', 'Ora il pane godi tu.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '5', '1', 'Ai piaceri dell\'Egitto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '5', '2', 'Rinunciasti? Dio ti vuol');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '5', '3', 'Sodisfar delle ricchezze');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '5', '4', 'Che derivan da Lui sol.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '6', '1', 'Ei t\'insegna nel deserto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '6', '2', 'A conoscere il Suo amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '6', '3', 'Sua pazienza, grazia, forza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '6', '4', 'E ti dà divin ristor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '7', '1', 'Mentre viaggi ver\' la méta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '7', '2', 'Pur le prove produrran');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '7', '3', 'Piena grazia e ricchi doni');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '7', '4', 'Che dal ciel discenderan.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '8', '1', 'Benché lunga sia la via');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '8', '2', 'Forza non ti mancherà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '8', '3', 'Vesti fresche e facil passo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '8', '4', 'Segni son ch\' Ei con te va.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '9', '1', 'Quando a Canaan, la méta,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '9', '2', 'Finalmente giungerai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '9', '3', 'E con inni di trionfo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '9', '4', 'In Sionne tu verrai,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '10', '1', 'Quei che allora incontrerai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '10', '2', 'A te ignoto non sarà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '10', '3', 'Con un ben provato amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('76', '10', '4', 'Il tuo Dio t\'accoglierà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('77', '8.7.8.7.8.7.8.7.', '25', '9998');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('77', '1', '1', 'I TUOI passi nel deserto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('77', '1', '2', 'O Signore, amiam tracciar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('77', '1', '3', 'Ed il fiume del Tuo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('77', '1', '4', 'Riverenti contemplar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('77', '1', '5', 'Fino a Betleem scendesti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('77', '1', '6', 'La Tua mano ognun sanò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('77', '1', '7', 'Ed a vincer l\'onde e i venti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('77', '1', '8', 'La parola Tua bastò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('77', '2', '1', 'Alla croce ed all\'avello');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('77', '2', '2', 'Ti condusse quell\'amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('77', '2', '3', 'E dal cielo ove Tu sei');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('77', '2', '4', 'Or quel fiume scorre ancor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('77', '2', '5', 'Quell\'amor illimitato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('77', '2', '6', 'Noi, commossi, contempliam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('77', '2', '7', 'In risposta, riverenti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('77', '2', '8', 'O Signore, T\'adoriam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('78', '8.8.8.7.8.8.8.7.', '153', '66');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '1', '1', 'PADRE nostro, Dio d\'amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '1', '2', 'Ogni lode a Te rendiamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '1', '3', 'Nel sovrano Tuo favore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '1', '4', 'Ogni nostro ben vediam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '1', '5', 'Là scorgiamo la sorgente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '1', '6', 'Donde scorre l\'acqua viva');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '1', '7', 'Che qual fiume glorïoso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '1', '8', 'Reca gioia ovunque va.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '2', '1', 'Tu per Tuoi ci conoscesti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '2', '2', 'Nell\'eternità passata,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '2', '3', 'Tuoi eletti ci facesti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '2', '4', 'Ci guardasti con amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '2', '5', 'Poi, chiamandoci per guzia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '2', '6', 'Attirasti l\'alma nostra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '2', '7', 'Dalle tenebre del mondo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '2', '8', 'A godere il Tuo favor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '3', '1', 'Ed ancora ci conduci');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '3', '2', 'In virtù di Tua parola');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '3', '3', 'Che santifica e consola');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '3', '4', 'I diletti Tuoi quaggiù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '3', '5', 'Sì che in grazia noi cresciamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '3', '6', 'Ogni giorno più vicini,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '3', '7', 'Finché insieme dimoriamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('78', '3', '8', 'Al cospetto Tuo lassù.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('79', '9.8.9.8. Giambico.', '161', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '1', '1', 'DIO e l\'Agnello - oh, prezïosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '1', '2', 'Divina fonte, nota al cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '1', '3', 'Di gioia e amor che niun può dire,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '1', '4', 'Che m\'appartengon ad ognor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '2', '1', 'Anima mia, l\'Agnel dimora');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '2', '2', 'Dove riposo Dio godrà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '2', '3', 'E quei che son con Lui beati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '2', '4', 'L\'amor divino inonderà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '3', '1', 'Là del nascosto pan di Cristo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '3', '2', 'Che qui soffrì, nutrito ognor -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '3', '3', 'Di Dio tesoro benedetto -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '3', '4', 'Avrò diletto nel Suo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '4', '1', 'Chiamato col segreto nome');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '4', '2', 'D\'una delizia ascosa pien,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '4', '3', 'Sulla pietruzza bianca impresso -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '4', '4', 'Risposta al disonor terren!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '5', '1', 'Con Te, mia Guida e Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '5', '2', 'Camminerò nel Tuo fulgor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '5', '3', 'Sarà più bianca la mia veste');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '5', '4', 'Nella celeste luce allor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '6', '1', 'Là nel cammino senza macchia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '6', '2', 'Che la Sua mano preparò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '6', '3', 'Porrò il mio piede, mentre il giorno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '6', '4', 'Sopra il riposo brilla ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '7', '1', 'Ma chi dirà l\'intensa gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '7', '2', 'Di luce viva là nel ciel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '7', '3', 'Ove Dio spiega il Suo splendore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '7', '4', 'E stan le glorie dell\'Agnel?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '8', '1', 'Là, giammai stanchi, i nostri occhi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '8', '2', 'Sopra di Lui si poseran,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '8', '3', 'E nella lode senza fine');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('79', '8', '4', 'I nostri cuori esulteran.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('80', '10.10.10.9.10.10.10.9.', '170', '191');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '1', '1', 'TI lodiamo, Signore di gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '1', '2', 'Costituito di tutto l\'Erede,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '1', '3', 'Tua grandezza vediam nella storia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '1', '4', 'Ammirabile di creazion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '1', '5', 'Della gloria di Dio lo splendore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '1', '6', 'In Te, il Figlio, è veduto, e Tu sei');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '1', '7', 'Della Sua sostanza espressione:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '1', '8', 'T\'acclamiamo supremo, Signor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '2', '1', 'Non è frutto di mente d\'umani');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '2', '2', 'Dell\'umanità Tua il Nome:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '2', '3', 'Tu erediti un Nome nei piani');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '2', '4', 'Glorïosi d\'amore divin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '2', '5', 'Più eccellente degli angeli in cielo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '2', '6', 'Il Figliolo Tu sei, o Signore.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '2', '7', 'A Te diamo l\'onor, Emmanuele!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '2', '8', 'La Parola incarnata sei Tu.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '3', '1', 'E\' il Tuo trono, O Dio, in eterno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '3', '2', 'Del Tuo regno lo scettro è giustizia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '3', '3', 'Creator benedetto, la terra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '3', '4', 'Ed i ciel opra son di Tue man.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '3', '5', 'Pur la terra ed i ciel periranno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '3', '6', 'Ma Tu sempre rimani, e Tua fama');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '3', '7', 'Non vien meno nel volger degli anni:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('80', '3', '8', 'Tu rïempi ogni cosa ad ognor!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('81', '9.8.9.8. Dattilico.', '112', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '1', '1', 'SIGNOR, la Tua gloria vediamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '1', '2', 'Ma non con lo sguardo mortal:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '1', '3', 'La gloria sul trono del Padre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '1', '4', 'Giammai l\'occhio uman scorgerà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '2', '1', 'Di là-or che Tu sei salito,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '2', '2', 'Compiuta la redenzïon -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '2', '3', 'Lo Spirito reca Tua gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '2', '4', 'A quei che T\'attendon, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '3', '1', 'Non può l\'occhio umano vedere,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '3', '2', 'L\'orecchio dell\'uom non può udir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '3', '3', 'Niun cuore quaggiù può comprender');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '3', '4', 'Né ciò che sarà concepir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '4', '1', 'Ma Dio ha donato il Suo Spirto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '4', '2', 'Che svela i tesor che lassù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '4', '3', 'Ei stesso approntò per coloro');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '4', '4', 'Che in grazia suggella quaggiù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '5', '1', 'Il gran Precursor nostro è in gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '5', '2', 'Pur non Si vergogna di noi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '5', '3', 'E qual Primogenito vuole');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '5', '4', 'Che abbiam parte a tutto con Lui.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '6', '1', 'La gioia di nuova creazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '6', '2', 'Già splende nell\'oscurità:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '6', '3', 'Quel mondo di benedizione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('81', '6', '4', 'La casa dei santi sarà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('82', '10.9.10.9.10.9.10.9.', '177', '178');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('82', '1', '1', 'AL Tuo amor rispondendo, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('82', '1', '2', 'Il Tuo Nome prezioso adoriam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('82', '1', '3', 'Nessun altro è più degno di lode,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('82', '1', '4', 'Nessun altro signor conosciam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('82', '1', '5', 'Per compire il divino volere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('82', '1', '6', 'Tu lasciasti la gloria del ciel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('82', '1', '7', 'Adempisti di Dio la giustizia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('82', '1', '8', 'O Signor, il Verace e Fedel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('82', '2', '1', 'Come in terra, Signor, raccogliesti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('82', '2', '2', 'I discepoli intorno ai Tuoi piè');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('82', '2', '3', 'Per udir le parole di grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('82', '2', '4', 'Procedenti soltanto da Te,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('82', '2', '5', 'Così adesso al Tuo Nome prezioso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('82', '2', '6', 'Radunati noi siamo, Signor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('82', '2', '7', 'Il Tuo amore profondo, infinito,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('82', '2', '8', 'A Te attira risposta dal cuor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('83', '10.10.10.10.', '21', '80');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '1', '1', 'OH, l\'infinita gioia d\'abitar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '1', '2', 'O Padre, nella casa Tua nel ciel!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '1', '3', 'Cristo è riflesso in ogni cosa là');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '1', '4', 'Ed il Tuo amore brilla senza vel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '2', '1', 'Tutti i pensier divini del Tuo pian');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '2', '2', 'Pel Tuo piacere là compiuti son;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '2', '3', 'Risplende in gloria quel che visto fu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '2', '4', 'Brillar in Cristo qui in umiliazion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '3', '1', 'Pur, forte dello Spirto nel poter,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '3', '2', 'Può ciascun occhio su di Lui guardar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '3', '3', 'Ogni impression di Lui che riceviam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '3', '4', 'Gioiosa, fresca lode fa levar!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '4', '1', 'Ed ogni cerchio unito intorno a Te');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '4', '2', 'Di Cristo qualche raggio può mostrar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '4', '3', 'E per la Tua delizia, il Tuo piacer');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '4', '4', 'Per tutta eternità potrà brillar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '5', '1', 'Supremo sovra tutto, là il Tuo amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '5', '2', 'Per sempre il suo riposo troverà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '5', '3', 'Mentre ogni cuore, di letizia pien,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('83', '5', '4', 'Di quell\'amore eterno gusterà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('84', '12.11.12.11.', '33', '200');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('84', '1', '1', 'SIGNORE Gesù, lietamente esprimiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('84', '1', '2', 'Il senso profondo di Tua degnità;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('84', '1', '3', 'Tu sei il Risorto, il Santo e Verace:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('84', '1', '4', 'Le lodi che a Te sondovute rendiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('84', '2', '1', 'Ancora una volta ci dài di gustare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('84', '2', '2', 'Di Tua presenza la gioia e il calor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('84', '2', '3', 'All\'ombra Tua, in pace, felici posiamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('84', '2', '4', 'E\' dolce il Tuo frutto per chi sa il Tuo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('84', '3', '1', 'Sì, Tu fosti solo, finché quale grano');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('84', '3', '2', 'Prezioso moristi: risorto or Tu se\';');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('84', '3', '3', 'Di là dalla morte, miriadi di santi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('84', '3', '4', 'La gloria Tua son, "tutti d\'uno" con Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('84', '4', '1', 'Or Tu Ti compiaci di prendere posto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('84', '4', '2', 'Fra i Tuoi, che già gustan Tua grazia, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('84', '4', '3', 'I Tuoi Ti conoscon così qual Tu sei');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('84', '4', '4', 'Del ciel nella gloria, dimora d\'amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('85', '8.8.11.8.', '46', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '1', '1', 'V\'E\' riposo allo stanco in Te,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '1', '2', 'Nel Tuo amore, o Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '1', '3', 'Nella grazia che salvi in Te ci fe\'');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '1', '4', 'E che chiama gli erranti ancor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '2', '1', 'V\'è riposo nel dolce amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '2', '2', 'Che ha tracciato il sentier quaggiù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '2', '3', 'Attraverso l\'intero terren dolor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '2', '4', 'E che un posto ci diè lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '3', '1', 'Della grazia la calma appar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '3', '2', 'Che dai regni vien di lassù:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '3', '3', 'Qual riposo al pensier che potrem mirar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '3', '4', 'La Tua faccia, Signor Gesù!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '4', '1', 'Pur nel duolo riposo v\'è,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '4', '2', 'Nel membrare che il Tuo dolor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '4', '3', 'Una prova sì grande, Signore, diè');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '4', '4', 'Del Tuo santo, immenso amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '5', '1', 'V\'è riposo nel Tuo cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '5', '2', 'D Che il dominio d\'amor svelò:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '5', '3', 'Delle colpe che furono nostre allor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '5', '4', 'Il dolore per noi portò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '6', '1', 'Il riposo nel giogo abbiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '6', '2', 'Della sola Tua volontà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '6', '3', 'Nei Tuoi passi e Tuoi detti noi apprendiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '6', '4', 'Qual pazienza in Te, Gesù, v\'ha.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '6', '5', 'Ora dove passasti Tu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '6', '6', 'E\' il cammin che dobbìam seguir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '6', '7', 'E al riposo che duolo non turba più');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('85', '6', '8', 'Coi Tuoi passi vogliam salir.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('86', '10.4.10.4.10.10.10.4.', '173', '146');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '1', '1', 'NELL\'amore di Dio Salvatore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '1', '2', 'Sì, tutto è ben;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '1', '3', 'Immutabil è il Suo favore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '1', '4', 'E tutto è ben.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '1', '5', 'Da una forza invincibil salvati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '1', '6', 'Da una grazia fedel suggellati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '1', '7', 'Da una mano possente guardati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '1', '8', 'Sì, tutto è ben.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '2', '1', 'Qui proviamo la tribolazione,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '2', '2', 'Ma tutto è ben;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '2', '3', 'Nostra è pur una tal salvazione:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '2', '4', 'Sì, tutto è ben.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '2', '5', 'Or felici, in Dio confidiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '2', '6', 'E fruttuosi, se in Cristo abitiamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '2', '7', 'Per lo Spirito fermi pur siamo -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '2', '8', 'Sì, tutto è ben.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '3', '1', 'Un glorioso domani ci attende:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '3', '2', 'Sì, tutto è ben.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '3', '3', 'Nel dolor può cantare la fede;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '3', '4', 'Ché tutto è ben.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '3', '5', 'Nell\'amore del Padre fidiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '3', '6', 'Nel bisogno, Gesù accanto abbiamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '3', '7', 'Sia in vita che in morte, sappiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('86', '3', '8', 'Che tutto è ben.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('87', '10.10.10.9.(a)', '168', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('87', '1', '1', 'PADRE, quando da Te noi lontano,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('87', '1', '2', 'Fatti schiavi eravam del peccato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('87', '1', '3', 'Ci cercava l\'amor Tuo sovrano');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('87', '1', '4', 'Che ci diede con Te libertà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('87', '2', '1', 'Or dinanzi a Te, quali figlioli,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('87', '2', '2', 'D\'allegrezza ricolmi, al beato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('87', '2', '3', 'Luogo andiam da Gesù preparato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('87', '2', '4', 'Ove eterno l\'amor durerà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('87', '3', '1', 'Te lodiam! La Tua gloria noi siamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('87', '3', '2', 'Gloria a Te diamo, Amore divino.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('87', '3', '3', 'A Te sempre ci tieni vicino');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('87', '3', '4', 'Fino a che noi saremo quaggiù.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('88', '10.10.10.9.(a)', '168', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '1', '1', 'PADRE, a Cristo ci desti in amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '1', '2', 'Per averci a Lui simili, figli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '1', '3', 'Col Tuo Figlio, nell\'alte dimore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '1', '4', 'Conformati ai Tuoi propri pensier -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '2', '1', 'Nella casa Tua, Padre, ove amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '2', '2', 'Empie i santi cortili di gioia;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '2', '3', 'Sì; l\'amor che ci fe\' Tuoi ognora');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '2', '4', 'Colma tutta la casa nel ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '3', '1', 'Grazia immensa! Di gioia sì pura,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '3', '2', 'Tutti quei che là entran ricolma');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '3', '3', 'L\'amor santo, di Dio la natura,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '3', '4', 'E i cuor nostri ne gustan fin d\'or.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '4', '1', 'La giustizia di Dio, d\'una intensa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '4', '2', 'Gloria, tutta la sfera pervade -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '4', '3', 'Cristo, luce di Dio e potenza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '4', '4', 'Quella luce ci dà di goder.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '5', '1', 'Oh, la Mente divina esaltiamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '5', '2', 'A Dio solo appartiene la gloria!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '5', '3', 'Oh, l\'Amore divin! Possediamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('88', '5', '4', 'Là una parte, mediante Gesù!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('89', '8.7.8.7.8.7.8.7.', '25', '10');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('89', '1', '1', 'BENEDETTO Spirto Santo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('89', '1', '2', 'Tua potenza or è con noi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('89', '1', '3', 'Mentre al Padre ci appressiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('89', '1', '4', 'Per prostrarci innanzi a Lui.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('89', '1', '5', 'Cristo vuol portarci in questo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('89', '1', '6', 'Luogo benedetto, là');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('89', '1', '7', 'Dove, per divina grazia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('89', '1', '8', 'Noi al Padre accesso abbiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('89', '2', '1', 'Benedetta è nostra parte');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('89', '2', '2', 'Ch\'or noi conosciam per Te,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('89', '2', '3', 'Prima d\'infra le famiglie');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('89', '2', '4', 'Sia in terra che nel ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('89', '2', '5', 'Da un tal luogo di favore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('89', '2', '6', 'Per Tuo mezzo, ascendon già');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('89', '2', '7', 'Lode eterna, adorazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('89', '2', '8', 'Da figlioli in libertà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('90', '11.10.11.10.', '52', '2');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('90', '1', '1', 'DIO Padre, T\'esaltiamo riverenti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('90', '1', '2', 'Ché rivelato è il cuore Tuo d\'amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('90', '1', '3', 'In Quei che disse: "Il Tuo voler sia fatto"');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('90', '1', '4', 'Guardando al frutto immenso pel Tuo cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('90', '2', '1', 'In mezzo all\'assemblea dei Suoi fratelli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('90', '2', '2', 'Ei canta, e il nostro cuore con Lui sal:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('90', '2', '3', 'Con Lui entriam nel luogo della lode');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('90', '2', '4', 'Ov\'è iniziata già l\'eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('90', '3', '1', 'Prima che fosse questo mondo, eletti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('90', '3', '2', 'Nel Figlio del Tuo. amore già eravam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('90', '3', '3', 'Ora con gioia a Te davanti, o Padre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('90', '3', '4', 'Nel godimento del Tuo mondo stiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('90', '4', '1', 'Figli che T\'aman empion la Tua casa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('90', '4', '2', 'Del Figlio han parte nell\'immenso amor -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('90', '4', '3', 'Simili a Lui, i tratti Suoi portando,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('90', '4', '4', 'Per sempre la delizia del Tuo cuor!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('91', '7.7.7.7.7.7.7.7.', '143', '17');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('91', '1', '1', 'O DIO immutabil,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('91', '1', '2', 'Lo Stesso Tu per sempre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('91', '1', '3', 'Da eternità esistente,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('91', '1', '4', 'Tua fama non ha fine!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('91', '1', '5', 'Tua maestà è gloriosa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('91', '1', '6', 'Con gioia T\'adoriamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('91', '1', '7', 'Economia preziosa:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('91', '1', '8', 'Uno e Trino "Il Nome"');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('92', '11.10.11.10.', '52', '72');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '1', '1', 'CHI mai potea pensare che la chiesa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '1', '2', 'Potesse all\'alta glorïa salir');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '1', '3', 'Per esser del Tuo Figlio la compagna,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '1', '4', 'Chi questo pian sapeva suggerir?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '2', '1', 'Tu sol, o Dio, potevi concepire');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '2', '2', 'Già fin dalla passata eternità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '2', '3', 'Questo sí grande piano glorïoso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '2', '4', 'Frutto di Tua sapienza e Tua bontà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '3', '1', 'Certo non v\'era in tutto l\'universo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '3', '2', 'Un\'altra mente che a un sì vasto pian');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '3', '3', 'Giungesse mai: Tu solo lo compisti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '3', '4', 'Nella Tua grazia e il Tuo poter sovran.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '4', '1', 'Pure i motivi tutti furon Tuoi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '4', '2', 'Tuo il consiglio, Tua la potestà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '4', '3', 'Formata pel Tuo Figlio, la Sua sposa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '4', '4', 'Al fianco Suo gloriosa brillerà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '5', '1', 'Con gran diletto, o Dio, contempliamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '5', '2', 'Il Tuo pensiero dall\'eternità:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '5', '3', 'Con Lui nell\'alta gloria, sovra il trono,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '5', '4', 'Di Cristo lacompagna allor sarà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '6', '1', 'Or dallo Spirto Santo suggellati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '6', '2', 'Nel Tuo pensier d\'amore trionfiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '6', '3', 'E nel proponimento Tuo divino');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('92', '6', '4', 'Che con Gesù in eterno parte abbiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('93', '9.6.9.7.', '160', '48');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '1', '1', 'O LUCE del cuor del pellegrin,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '1', '2', 'La Stella Tu del dì,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '1', '3', 'Deh, sorgi, e fuga ogni nostro mal');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '1', '4', 'Coi raggi Tuoi del mattin!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '2', '1', 'Signore, vieni! La terra e il mar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '2', '2', 'Le lodi canteran');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '2', '3', 'Del Nome Tuo, e Te dovran');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '2', '4', 'Qual loro gran Re, onorar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '3', '1', 'L\'intiera terra rieponderà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '3', '2', 'Al mondo di lassù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '3', '3', 'Ed in memoria del Tuo amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '3', '4', 'Di gioia esulterà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '4', '1', 'Signore, geme Tua creazion,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '4', '2', 'La terra, l\'aria, il mar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '4', '3', 'D\'un solo suono coi nostri cuor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '4', '4', 'Attende la redenzion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '5', '1', 'Fu Tua la croce col suo dolor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '5', '2', 'E\' il frutto suo per Te');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '5', '3', 'E la corona di gloria sta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('93', '5', '4', 'Sul Tuo capo, Vincitor!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('94', '9.8.9.8. Giambico.', '161', '74');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('94', '1', '1', 'PADRE, il Tuo amore illimitato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('94', '1', '2', 'E\' sceso a noi nel Tuo Figliol,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('94', '1', '3', 'Or uno siam con Lui nel cielo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('94', '1', '4', 'Per noi l\'eternità iniziò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('94', '2', '1', 'A Te dinanzi senza macchia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('94', '2', '2', 'In Lui che vive noi viviam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('94', '2', '3', 'Il Nome Tuo benediciamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('94', '2', '4', 'E santa adorazion rendiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('94', '3', '1', 'La lode sal, dal Tuo Diletto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('94', '3', '2', 'Guidata, Te per rallegrar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('94', '3', '3', 'Con cuor divinamente mossi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('94', '4', '1', 'Possiamo insiem con Lui lodar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('94', '4', '2', 'Padre, il Tuo amor è nostra parte,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('94', '4', '3', 'A1 Tuo Figliol ci desti Tu;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('94', '4', '4', 'Per la Tua gloria e per la Sua');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('94', '4', '5', 'Siam resi simili a Gesù.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('95', '14.13.14.13.', '203', '105');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('95', '1', '1', 'A TE davanti ora, Dio sommo, Dio supremo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('95', '1', '2', 'La lode cresce, e insieme l\'omaggio presentiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('95', '1', '3', 'In Tua presenza stessa condotti in pace siamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('95', '1', '4', 'Da Cristo, che riveste i Tuoi di dignità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('95', '2', '1', 'Dalla saggezza Tua procede ogni cosa;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('95', '2', '2', 'Ma in Cristo noi vediamo la grazia Tua, il Tuo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('95', '2', '3', 'Sovra di Lui, Dio santo, la gloria Tua riposa:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('95', '2', '4', 'In Lui graditi siamo godendo il Tuo favor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('95', '3', '1', 'Quest\'ineffabil gioia il Tuo sovrano amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('95', '3', '2', 'Avea per noi in serbo da ogni eternità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('95', '3', '3', 'Ed or nel sodisfatto riposo del Tuo cuore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('95', '3', '4', 'Per mezzo dello Spirto possiam con gioia entrar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('95', '3', '5', 'O Dio supremo, il piano mirabil del Tuo cuore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('95', '3', '6', 'Compiuto alfine appieno, ci svela il Tuo splendor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('95', '3', '7', 'Prostrati a Te dinanzi, offriamo lode e onore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('95', '3', '8', 'E T\'adoriam, o Dio di luce, Dio d\'amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('96', '11.10.11.10.11.10.', '182', '92');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('96', '1', '1', 'GLORIOSO nostro Dio, com\'è prezioso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('96', '1', '2', 'Esser vicini, e in Cristo parte aver:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('96', '1', '3', 'L\'amore Tuo ci attrasse con potenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('96', '1', '4', 'ln questa sfera, e piega il nostro cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('96', '1', '5', 'Oh, amor divin! Tu vuoi in Tua presenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('96', '1', '6', 'Dei figli le mirïadi ognor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('96', '2', '1', 'Dio benedetto, allora Tu sarai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('96', '2', '2', 'Tutto ed in tutti, nel riposo ognor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('96', '2', '3', 'E nuovi cieli e terra, benedetti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('96', '2', '4', 'Saranno, sciolti d\'ogni schiavitù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('96', '2', '5', 'Cristo e la chiesa mostreran Tua gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('96', '2', '6', 'Dove ad eternità dimori Tu.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('97', '10.9.10.9.', '114', '10');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '1', '1', 'SANTO Spirito del nostro Dio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '1', '2', 'La Tua voce vogliamo ascoltar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '1', '3', 'Mentre qui d\'un sol cuor ci accingiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '1', '4', 'La parola divina a studiar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '2', '1', 'La Tua voce costante e verace');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '2', '2', 'In accenti d\'amore fedel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '2', '3', 'Parla ai cuori deisanti in ascolto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '2', '4', 'Rivelando il pensiero del ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '3', '1', 'Conosciam la Tua grazia infinita');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '3', '2', 'Sempre pronta soccorso a largir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '3', '3', 'Che compiacesi, in tenera cura,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '3', '4', 'Nuova forza al bisogno fomir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '4', '1', 'Ognor fresche le "cose di Cristo"');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '4', '2', 'Ti diletti di far risaltar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '4', '3', 'Ed ai Suoi, la lor fé ritemprando,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '4', '4', 'Il divino Suo amor rammentar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '5', '1', 'La Tua santa presenza qui in terra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '5', '2', 'I cuor nostri ognor fa gioir:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '5', '3', 'Deh! concedici, Consolatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('97', '5', '4', 'La Tua voce in quest\'ora sentir.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('98', '11.11.11.11.(c)', '193', '119');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('98', '1', '1', 'E\' IL nostro cuor, o Dio, di gioia pieno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('98', '1', '2', 'E ricca lode il nostro labbro esprime');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('98', '1', '3', 'Allor che anticipiamo l\'ora in cui');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('98', '1', '4', 'Il Tuo potere manifesterai -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('98', '2', '1', 'Allor che passeran la terra e il cielo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('98', '2', '2', 'E fine avrà di morte il triste impero:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('98', '2', '3', 'Tu ogni cosa nuova, o Dio, farai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('98', '2', '4', 'E nuovi cieli e terra introdurrai -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('98', '3', '1', 'Quel dì sarà ogni lacrima asciugata');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('98', '3', '2', 'Da Te, e il timor, la pena alfin passata,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('98', '3', '3', 'E - quale gaudio per il cuor dei Tuoi! -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('98', '3', '4', 'Tu con gli uomini dimorerai.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('98', '4', '1', 'Il Tuo tabernacol sarà allora');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('98', '4', '2', 'Il benedetto centro, e tutti ognora');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('98', '4', '3', 'Vedranno la Tua gloria, l\'amor Tuo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('98', '4', '4', 'E tutto in tutti Tu sarai, o Dio!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('99', '11.10.11.10.11.11.', '184', '151');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '1', '1', 'SIGNOR Gesù, Tu che formasti i mondi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '1', '2', 'Qual santo Bimbo fosti visto qui');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '1', '3', 'In umiltà ed in amor profondi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '1', '4', 'Ma un coro d\'angeli, Signor, s\'udì');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '1', '5', 'Che la Persona santa Tua onorava,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '1', '6', 'E gloria a Dio negli alti cieli dava.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '2', '1', 'L\'umì1e Tuo sentiero dispiegava');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '2', '2', 'La verità e la grazia, e pure l\'uom');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '2', '3', 'La fronte Tua con spine coronava;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '2', '4', 'Or in risposta a quell\'obbrobrio estrem');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '2', '5', 'Nel cielo coronato sei di gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '2', '6', 'E i santi Tuoi proclaman Tua vittoria.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '3', '1', 'Oh, qual profondità di duol gustasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '3', '2', 'Per acquisir la sposa Tua, Signor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '3', '3', 'Tradito, afflitto ed oltraggiato fosti!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '3', '4', 'Le mani e il fianco Tuo forati allor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '3', '5', 'La prova son dell\'amor Tuo sì forte,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '3', '6', 'Che suggellato fu con la Tua morte.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '4', '1', 'Or noi bramiamo insieme d\'imparare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '4', '2', 'Da Te, Signor prezioso, ad adempir');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '4', '3', 'La nostra parte, ed a Te somigliare,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '4', '4', 'Con fermo cuor, scegliendo il Tuo sentier,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '4', '5', 'Avendo Te qual nostro tutto ognora,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('99', '4', '6', 'Finché udirem la voce Tua, Signore!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('100', '12.13.12.10.', '48', '99');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('100', '1', '1', 'SANTO, santo, santo! Dio T\'adoriamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('100', '1', '2', 'Dall\'eternità Tu sei: la voce a Te inalziam!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('100', '1', '3', 'Ed in lieti accenti, grati e riverenti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('100', '1', '4', 'Gloria ed onore tributiamo a Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('100', '2', '1', 'Santo, santo, santo! Noi del Tuo T\'offriamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('100', '2', '2', 'Immutabil Dio Tu in potenza e maestà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('100', '2', '3', 'Somma sapïenza, gloria, onnipotenza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('100', '2', '4', 'Solo in Te son, e sempre in Te saran.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('100', '3', '1', 'Santo, santo, santo! Quali sacerdoti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('100', '3', '2', 'Nel santuario parte abbiam e a Te qui culto offriam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('100', '3', '3', 'Ove amore ha sede, quivi entriam per fede,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('100', '3', '4', 'E la Tua gloria (gran mister!) vediam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('100', '4', '1', 'Santo, santo, santo! Dei Tuoi figli il canto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('100', '4', '2', 'Senza fine sale; Tu sei per l\'eternità!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('100', '4', '3', 'Il Tuo amor superno ha per tema eterno:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('100', '4', '4', 'Dio di gloria, a Te sia laude ognor!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('101', '8.7.8.8.7.', '148', '160');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '1', '1', 'SOGGETTI al santo Tuo voler,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '1', '2', 'Per Te interamente,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '1', '3', 'Vorremmo esser, o Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '1', '4', 'Tuoi testimoni in terra, ognor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '1', '5', 'Fedeli a Tua parola.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '2', '1', 'Per Te vorremmo in santità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '2', '2', 'Serbare un luogo puro,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '2', '3', 'E la giustizia, fede e amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '2', '4', 'La pace, insieme procacciar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '2', '5', 'Vivendo separati.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '3', '1', 'Non turbi il compromesso mai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '3', '2', 'La nostra parte Teco,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '3', '3', 'Ma in un cammin di fedeltà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '3', '4', 'Vorremmo con fermezza star,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '3', '5', 'Lontani dal peccato.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '4', '1', 'Oh, possa il Tuo voler suprem');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '4', '2', 'Tenere i nostri cuori');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '4', '3', 'Per Te, Signor, finché vedrem');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '4', '4', 'Te stesso in gloria, e là sarem');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('101', '4', '5', 'Per sempre in Tua presenza.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('102', '11.10.11.10.', '52', '61');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('102', '1', '1', 'ALLA promessa Tua fedele ognora,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('102', '1', '2', 'Orfani non ci lasci Tu quaggiù:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('102', '1', '3', 'A noi Tu vieni, e dici: "A voi sia pace",');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('102', '1', '4', 'E noi gioiamo in Te, Signor Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('102', '2', '1', 'Nella Tua lode noi troviam diletto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('102', '2', '2', 'La Tua presenza è gaudio al nostro cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('102', '2', '3', 'Nei santi trovi gioia, e su di loro');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('102', '2', '4', 'L\'insegna inalzi dell\'eterno amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('103', '10.10.10.9.(b)', '169', '196');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('103', '1', '1', 'CANTIAMO lieti - del buon Pastore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('103', '1', '2', 'Che per la greggia - un dì moriva.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('103', '1', '3', 'D\'amore l\'ardua - prova pativa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('103', '1', '4', 'Ma pure fermo - qual roccia fu.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('103', '2', '1', 'In somma cura - pei Suoi agnelli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('103', '2', '2', 'Il lor nemico - Egli affrontava.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('103', '2', '3', 'Oh, qual immenso - amor mostrava!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('103', '2', '4', 'La propria vita - per lor lasciò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('103', '3', '1', 'Del nostro cuore - l\'eterno canto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('103', '3', '2', 'E\' pel Pastore - pel Benedetto;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('103', '3', '3', 'Più glorïoso - non v\'ha soggetto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('103', '3', '4', 'Più grato tema - di Lui non v\'ha.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('103', '4', '1', 'Di Lui cantianio - e del Suo amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('103', '4', '2', 'Sua lode sempre - vogliam narrare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('103', '4', '3', 'Finché i nostr\'inni - potrem alzare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('103', '4', '4', 'Nella splendente - magion del ciel.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('104', '11.10.11.10.11.11.', '184', '170');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '1', '1', 'NOI attendiamo Te, Figliol di Dio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '1', '2', 'L\'apparizione Tua noi bramiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '1', '3', '"Ancora un po\' di tempo", e Tu verrai,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '1', '4', 'Il nostro cuor di gioia a ricolmar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '1', '5', 'Or attendiam la Tua promessa insieme');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '1', '6', 'Alzando il capo con gioiosa speme.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '2', '1', 'Noi attendiamo Te, contenti ognora');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '2', '2', 'Di prender nostra parte all\'afflizion,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '2', '3', 'Ché Tu portasti il peso della croce,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '2', '4', 'Tutto il peccato, il duolo, il disonor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '2', '5', 'Nel disonor con Te uniti siamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '2', '6', 'Finché il glorioso giorno Tuo vediamo.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '3', '1', 'Noi attendiamo Te, che guadagnasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '3', '2', 'Per sempre l\'affezion del nostro cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '3', '3', 'Tu ci consoli, ci sostieni, e noi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '3', '4', 'In spirto Ti troviam vicin, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '3', '5', 'Presto, rapiti, i Tuoi T\'incontreranno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '3', '6', 'E nella luce Ti saluteranno.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '4', '1', 'Noi attendiamo Te: Tu vieni presto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '4', '2', 'Il tempo del dolor sta per finir!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '4', '3', 'Allora cesseranno pene e affanni,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '4', '4', 'Per sempre taceran tutti i desir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '4', '5', 'L\'alba è vicina: del pellegrinare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('104', '4', '6', 'Il tempo finirà nel Tuo splendore!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('105', '8.7.8.7.8.7.', '147', '196');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('105', '1', '1', 'GLORIA eterna a Lui sia data');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('105', '1', '2', 'Che la croce sopportò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('105', '1', '3', 'Che la morte a noi serbata,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('105', '1', '4', 'Per redimerci gustò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('105', '1', '5', 'Gloria eterna al Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('105', '1', '6', 'Vero Amico al peccator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('105', '2', '1', 'L\'amor Suo non ha misura,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('105', '2', '2', 'Né l\'immensa vastità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('105', '2', '3', 'Pur la mente più matura');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('105', '2', '4', 'Abbracciarne mai potrà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('105', '2', '5', 'Gloria eterna al Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('105', '2', '6', 'Vero Amico al peccator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('105', '3', '1', 'Mentre ridiciam la storia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('105', '3', '2', 'Del Verace, del Fedel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('105', '3', '3', 'Sì, cantiam eterna gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('105', '3', '4', 'A Dio Padre ed all\'Agnel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('105', '3', '5', 'Gloria eterna al Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('105', '3', '6', 'Vero Amico al peccator.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('106', '9.8.9.8. Giambico.', '161', '108');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('106', '1', '1', 'O SPIRTO Santo, a Te in quest\'ora');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('106', '1', '2', 'In lieti accenti noi cantiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('106', '1', '3', 'Di cuor le lodi tributiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('106', '1', '4', 'Consci che in libertà gioiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('106', '2', '1', 'Oh, via d\'amore benedetta,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('106', '2', '2', 'Oh, abil Tuo lavor divin!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('106', '2', '3', 'Presenti Cristo ai nostri cuori');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('106', '2', '4', 'Sì che l\'amor riposi alfin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('106', '3', '1', 'La gloria Tua meravigliosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('106', '3', '2', 'L\'adorazione fa sgorgar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('106', '3', '3', 'O Spirto Santo, i nostri cuori');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('106', '3', '4', 'A Te chiniamo nel cantar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('107', '12.9.12.11.', '199', '192');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '1', '1', 'SCLAMIAMO, noi santi, con gioia, con canti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '1', '2', 'Le lodi del grande Redentor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '1', '3', 'Ben degno è di nostra felice risposta:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '1', '4', 'Oh, quant\'è profonda la Sua bontà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '2', '1', 'Ci vide perduti, nel fallo caduti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '2', '2', 'E pur ci amò d\'un immenso amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '2', '3', 'Sì, Ei ci ha salvato da un misero stato:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '2', '4', 'Oh, quant\'è mirabil la Sua bontà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '3', '1', 'Nemici possenti son sempre presenti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '3', '2', 'E terra e inferno son contro a noi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '3', '3', 'Ma i santi Egli cura con mano sicura:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '3', '4', 'Oh, quant\'è possente la Sua bontà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '4', '1', 'Se duolo e spavento, qual nembo violento,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '4', '2', 'S\'addensan cupi d\'intorno la noi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '4', '3', 'Ei presso la chiesa Si tiene a difesa:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '4', '4', 'Oh, quant\'è preziosa la Sua bontà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '5', '1', 'Ben presto all\'eterno reame superno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '5', '2', 'Ei fuor dal mondo ci chiamerà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '5', '3', 'Allor Lo vedremo, con Lui noi saremo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('107', '5', '4', 'Per sempre gustando la Sua bontà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('108', '10.10.10.10.', '21', '203');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('108', '1', '1', 'O SANTO Spirto, Ti benediciam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('108', '1', '2', 'La Tua Persona e il Tuo poter lodiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('108', '1', '3', 'Egual di Deità nello splendor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('108', '1', '4', 'L\'alma chiniamo a Te in adorazion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('108', '2', '1', 'Tu, che in perfetto amore ed unità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('108', '2', '2', 'Sei Uno della santa Trinità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('108', '2', '3', 'Dal ciel scendesti, O Santo, qui in amor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('108', '2', '4', 'Quanto glorioso e grande è il Tuo valor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('108', '3', '1', 'Coi santi Ti compiaci d\'abitar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('108', '3', '2', 'In terra, o Pozzo Tu, Consolator:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('108', '3', '3', 'Or canti di risposta a Te leviam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('108', '3', '4', 'Con gioia nostralode Ti rendiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('108', '4', '1', 'Così adoriam in Tua presenza or,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('108', '4', '2', 'Gioiosi che con noi Tu sei ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('108', '4', '3', 'Oh, pregustiam la gioia senza vel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('108', '4', '4', 'Della prossimità che avremo in ciel!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('109', '9.8.9.8.8.8.', '104', '181');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '1', '1', 'O BENEDETTO Spirto Santo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '1', '2', 'Tu che contesti qui con l\'uom,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '1', '3', 'Il Tuo servizio noi chiediamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '1', '4', 'Desiderando un\'impression');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '1', '5', 'Vivente e fresca del poter');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '1', '6', 'Di Dio, il servizio a coronar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '2', '1', 'All\'inscrutabil Tua sapienza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '2', '2', 'Nulla nasconder noi possiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '2', '3', 'A causa della Tua Essenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '2', '4', 'Non v\'è mister nel cuore uman;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '2', '5', 'I suoi segreti puoi svelar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '2', '6', 'Il suo volere soggiogar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '3', '1', 'Possa ancor oggi la Parola');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '3', '2', 'Di Dio il nostro cuor toccar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '3', '3', 'E nulla offuschi il nostro sguardo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '3', '4', 'Né possa il seme soffocar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '3', '5', 'Mentre Tua voce è fatta udir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '3', '6', 'Puoi ciò che è detto rivestir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '4', '1', 'Presto avrà fin un tal servizio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '4', '2', 'La Tua fatica cesserà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '4', '3', 'Cresciuta appieno, la raccolta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '4', '4', 'A Dio per sempre apparterrà-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '4', '5', 'Allor che avrà tutt\'il tesor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('109', '4', '6', 'Portato in luce il Tuo lavor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('110', '11.10.11.10.', '52', '68');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('110', '1', '1', 'GESU\', Signor, con gioia noi rendiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('110', '1', '2', 'Al Nome Tuo adorazione e onor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('110', '1', '3', 'Incomparabil, unico in Tua gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('110', '1', '4', 'Noi acclamiamo Te nel Tuo splendor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('110', '2', '1', 'Dio sopra tutto sempre Tu rimani,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('110', '2', '2', 'Tu sei l\'Onnipotente Creator;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('110', '2', '3', 'Con la parola della Tua potenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('110', '2', '4', 'Reggi ogni cosa: a Te l\'adorazion!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('110', '3', '1', 'E pur in grazia e devozion immensa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('110', '3', '2', 'La volontà di Dio per adempir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('110', '3', '3', 'Moristi - un Uomo qui pel Suo piacere,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('110', '3', '4', 'I piani del Suo amore per compir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('110', '4', '1', 'Vinti i nemici, Tu sei vittorioso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('110', '4', '2', 'Glorie infinite a Te d\'intorno stan.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('110', '4', '3', 'Ai Tuoi, Signor, Tu vieni glorïoso:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('110', '4', '4', 'Adorazione e omaggio Ti rendiam!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('111', '6.6.8.6.', '106', '9998');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('111', '1', '1', 'O GIOIA senza fin,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('111', '1', '2', 'Real felicità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('111', '1', '3', 'D\'aver Gesù Maestro qui');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('111', '1', '4', 'Seguendolo ogni dì.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('111', '2', '1', 'L\'amor ch\'Egli ha per noi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('111', '2', '2', 'Nulla può ritener;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('111', '2', '3', 'Per Sé a prezzo ci acquistò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('111', '2', '4', 'Se stesso a noi donò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('111', '3', '1', 'Così il Suo amor fedel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('111', '3', '2', 'Ricolma ogni desir:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('111', '3', '3', 'Fonte che non s\'esaurirà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('111', '3', '4', 'Per tutta eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('111', '4', '1', 'Ei vuol che noi Lo amiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('111', '4', '2', 'Con piena fedeltà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('111', '4', '3', 'Poiché Egli stesso appien ci amò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('111', '4', '4', 'E l\'amor Suo svelò.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('112', '11.10.11.10.', '52', '18');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '1', '1', 'ALMA tremante, guarda al Salvatore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '1', '2', 'Sul trono assiso del Suo Padre in ciel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '1', '3', 'Oggetto del suprem divin favore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '1', '4', 'Di Dio diletto Figlio, Ei l\'Agnel!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '2', '1', 'Qual santo, Bimbo pur quaggiù fu visto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '2', '2', 'Di Betleem nella mangiatoia allor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '2', '3', 'Dio sceso in terra, qual Stranier celeste,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '2', '4', 'Per rivelar amore ai peccator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '3', '1', 'O peccator, guarda al tuo Dio che accanto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '3', '2', 'A te, di servo in forma, vien quaggiù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '3', '3', 'Parla al tuo cuor tenendosi al tuo fianco!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '3', '4', 'Di Sinai il monte non temere più.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '4', '1', 'Verso il Calvario in grazia procedendo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '4', '2', 'Il Suo cammino Egli traccia ancor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '4', '3', 'La volontà del Padre Suo compiendo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '4', '4', 'Ai peccatori rivelando amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '5', '1', 'Ascolta la novella benedetta:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '5', '2', 'Gesù morì e risuscitò per te;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '5', '3', 'Or Dio nel cielo di salvarti aspetta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('112', '5', '4', 'E tu, credendo, liberato se\'.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('113', '11.10.11.10.', '52', '19');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('113', '1', '1', 'VIENI, Signor! I santi Tuoi T\'attendon');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('113', '1', '2', 'Per Te veder e star con Te lassù;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('113', '1', '3', 'E mentre pregustiamo questa gioia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('113', '1', '4', 'Di cuor diciam: "Vieni, Signor Gesù!"');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('113', '1', '5', 'Vieni, Signor! I nostri cuori braman');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('113', '1', '6', 'Di star con Te del cielo nel fulgor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('113', '1', '7', 'Là dove i santi Ti circonderanno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('113', '1', '8', 'Nella pienezza del Tuo santo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('113', '3', '1', 'Vieni, Signor! Del Padre nella casa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('113', '3', '2', 'Di nostre lodi tema sarai Tu;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('113', '3', '3', 'Un inno eterno allora canteremo -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('113', '3', '4', 'Ora cantiam: "Vieni, Signor Gesù! "');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('114', '11.10.11.10.', '52', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('114', '1', '1', 'SIGNOR Gesù, sorgente d\'ogni grazia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('114', '1', '2', 'Glorioso in luce ed in divin splendor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('114', '1', '3', 'Ben presto Te vedremo faccia a faccia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('114', '1', '4', 'E in quella gloria brilleremo allor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('114', '2', '1', 'Con Te saremo ognor, Tua voce udremo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('114', '2', '2', 'Liberamente gusterem lassù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('114', '2', '3', 'L\'amor che qui rallegra i nostri cuori');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('114', '2', '4', 'Benché sia assente dal deserto Tu.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('114', '3', '1', 'Noi adoriamo, contemplando in pace');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('114', '3', '2', 'L\'eterno piano del divino amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('114', '3', '3', 'Che in quella sfera unisce eternamente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('114', '3', '4', 'La nostra sorte con la Tua, Signor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('115', '8.8.8.7.', '151', '196');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('115', '1', '1', 'O SIGNORE Onnipotente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('115', '1', '2', 'Deh, ci guida alla vittoria!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('115', '1', '3', 'Tua parola c\'incoraggia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('115', '1', '4', 'E con gioia Ti seguiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('115', '2', '1', 'Te seguiamo, nostra Guida');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('115', '2', '2', 'Che portasti salvazione;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('115', '2', '3', 'Te seguiam, mediante grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('115', '2', '4', 'Dispensata a noi dal ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('115', '3', '1', 'Fino a che, raggiunto il premio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('115', '3', '2', 'I conflitti cesseranno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('115', '3', '3', 'E per sempre poseremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('115', '3', '4', 'Nella pace di lassù.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('116', '8.8.8.8.', '30', '150');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '1', '1', 'DIO nostro Padre, che da Te');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '1', '2', 'Vien ogni grazia, confessiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '1', '3', 'E dal Tuo Figlio che ci diè,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '1', '4', 'Morendo, piena libertà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '2', '1', 'Del Santo Spirto nel poter');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '2', '2', 'Quel ch\'è la pace nostra appar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '2', '3', 'Niun mal può qui l\'accesso aver,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '2', '4', 'Il canto nulla può turbar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '3', '1', 'Come potrem Tua volontà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '3', '2', 'Comprender mai, o i Tuoi pensier -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '3', '3', 'La grazia che ci pose là,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '3', '4', 'L\'amor che ognor ci appressa a Te?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '3', '5', 'Avvinti nel Tuo eterno amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '3', '6', 'Il santo stimol ne sentiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '3', '7', 'Che desta della lode il cor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '3', '8', 'In esso appien attratti siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '5', '1', 'Mirabil sfera! Vibra or');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '5', '2', 'D\'un sol felice accordo già');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '5', '3', 'Da figli che l\'adorazion');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '5', '4', 'Ti rendon per l\'eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '6', '1', 'Assorti in tal divin favor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '6', '2', 'Largito a quei che eletti son,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '6', '3', 'A Te s\'inchina il nostro cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('116', '6', '4', 'In quell\'amor si vasto e pien.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('117', '8.9.9.8.9.8.9.8.', '159', '9');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '1', '1', 'SIGNOR, nelle lontane età,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '1', '2', 'Ben lungi pria che l\'uomo fosse,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '1', '3', 'Pria che la luce qui apparisse,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '1', '4', 'Che fosser fatti terra e ciel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '1', '5', 'Tu eri in tutta la Tua gloria-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '1', '6', 'Signore, a Te noi c\'inchiniam-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '1', '7', 'In sommo amore dimorando:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '1', '8', 'A Te l\'omaggio noi rendiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '2', '1', 'Niun può sondare quell\'amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '2', '2', 'Né labbro umano definire');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '2', '3', 'Tali inscrutabili, divine,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '2', '4', 'Eterne e sante relazion!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '2', '5', 'Pur Tu in umanità volesti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '2', '6', 'Di Dio qui il Nome dichiarar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '2', '7', 'In relazioni benedette');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '2', '8', 'A cui possiam partecipar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '3', '1', 'Compisti l\'opra ch\'Ei Ti diè,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '3', '2', 'Facesti tutto il Suo volere;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '3', '3', 'Uno in proposito, in pensiero,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '3', '4', 'Tu, il Figlio, al Padre unito ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '3', '5', 'Pur, allorché risuscitasti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '3', '6', 'Tu dichiarasti ai Tuoi, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '3', '7', 'Che il Padre Tuo è Padre loro');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('117', '3', '8', 'Ed hanno parte nel Suo amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('118', '8.7.8.7.', '24', '96');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '1', '1', 'A DIO Padre sia la gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '1', '2', 'Gloria a Cristo, il Figlio, diam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '1', '3', 'Gloria sia allo Spirto Santo -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '1', '4', 'Uno per l\'eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '2', '1', 'Nel guardar la creazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '2', '2', 'La sapienza Tua vediam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '2', '3', 'Con profonda adorazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '2', '4', 'L\'alma nostra a Te chiniam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '3', '1', 'Pur dei figli, O Dio, che T\'aman');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '3', '2', 'Brami aver in Tua magion,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '3', '3', 'Ove rendon già le lodi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '3', '4', 'Che daranno in ciel ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '4', '1', 'Nella rivelazïone');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '4', '2', 'Le affezioni del Tuo cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '4', '3', 'Agli uomini svelasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '4', '4', 'Per attrar gli affetti lor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '5', '1', 'Per la redenzion che Cristo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '5', '2', 'Compiè, vinto il male ognor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '5', '3', 'Hai, in nuova creazione,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '5', '4', 'In Lui degli adorator!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '6', '1', 'A Dio Padre sia la gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '6', '2', 'Gloria a Cristo, il Figlio, diam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '6', '3', 'Gloria sia allo Spirto Santo -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('118', '6', '4', 'Uno per l\'eternità.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('119', '11.10.11.10.', '52', '147');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('119', '1', '1', 'DIO nostro Padre, a Te ci avviciniamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('119', '1', '2', 'Nei santi meriti del Tuo Figliol:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('119', '1', '3', 'Quanto dall\'uom desiderasti avere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('119', '1', '4', 'Nell\'Unto Tuo trovasti, in Cristo sol.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('119', '2', '1', 'Ogni Suo passo a Te recò diletto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('119', '2', '2', 'A Te fedele in ogni Suo pensier,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('119', '2', '3', 'Dal ciel disceso, qui in un mondo ostile');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('119', '2', '4', 'Diede espression perfetta al Tuo voler.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('119', '3', '1', 'Sempre L\'amasti: pria che il mondo fosse');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('119', '3', '2', 'Era al Tuo fianco, gioia del Tuo cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('119', '3', '3', 'Di Deità i consigli condivise,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('119', '3', '4', 'Uno con Te nel piano Tuo d\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('119', '4', '1', 'Ed ancor L\'ami, ché Se stesso diede,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('119', '4', '2', 'La vita Sua quaggiù sacrificò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('119', '4', '3', 'E a Te condusse figli e adoratori,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('119', '4', '4', 'I frutti del Tuo amor ch\'Ei rivelò.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('120', '9.8.9.8. Giambico.', '161', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '1', '1', 'PADRE, nel Tuo potere eterno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '1', '2', 'Grazia e divina maestà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '1', '3', 'Brilla una gloria che qui in terra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '1', '4', 'Niun afferrare mai potrà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '2', '1', 'I suoi pensier d\'immensa grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '2', '2', 'Troppo elevati per noi son:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '2', '3', 'L\'amor che dà con Cristo un posto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '2', '4', 'Supera nostra comprension!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '3', '1', 'Pur non è ignoto quell\'amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '3', '2', 'A quei che han visto il Salvator;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '3', '3', 'Non è straniero ai Suoi, che sono');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '3', '4', 'In terra pellegrini ancor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '4', '1', 'Da Lui svelato, il Tuo perfetto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '4', '2', 'Amor adduce i nostri cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '4', '3', 'Là dove, appieno rivelato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '4', '4', 'Noi contempliamo quell\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '5', '1', 'Qui camminiam qual figli, in grazia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '5', '2', 'L\'amor di Padre nel gustar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '5', '3', 'Figli dinanzi a Te, troviamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('120', '5', '4', 'Pace che nulla può turbar!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('121', '9.8.9.8.9.8.9.8. Giambico.', '137', '56');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '1', '1', 'PREZIOSO Spirito del Padre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '1', '2', 'Oh, qual servizio pien d\'amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '1', '3', 'Tu compi - addurre l\'assemblea');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '1', '4', 'Così vicina al Figlio or!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '1', '5', 'Alfin compiuto è il pian di Dio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '1', '6', 'Consiglio ricco, pien d\'amor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '1', '7', 'Cristo possiede la Sua sposa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '1', '8', 'A Lui simìl, Sua gloria ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '2', '1', 'L\'amor del Padre per il Figlio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '2', '2', 'Diletto ben conosci Tu;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '2', '3', 'Tutte le cose il Padre diede');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '2', '4', 'Sì, nelle mani di Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '2', '5', 'Glorificato ed esaltato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '2', '6', 'Su tutto Capo Egli è e Signor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '2', '7', 'E l\'assemblea con Lui si tiene,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '2', '8', 'A Lui unita già fin d\'or.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '3', '1', 'Di quale gloria Tu sei degno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '3', '2', 'E quale grande parte hai pur');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '3', '3', 'In quella lode che s\'eleva');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '3', '4', 'A Dio rivelato or!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '3', '5', 'E l\'assemblea ch\'è in Gesù Cristo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '3', '6', 'T\'esprime lode e ricco onor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '3', '7', 'O Santo Spirito di Dio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('121', '3', '8', 'Noi T\'esaltiam con grato cuor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('122', '8.7.8.7.Datt.Coro.5.7.8.7.', '54', '82');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '1', '1', 'SOL Cristo toglie i peccati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '1', '2', 'E\' il Salvatore per me;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '1', '3', 'Già fui nei lacci del mondo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '1', '4', 'Ora son salvo per fé.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '1', '5', 'Sol Cristo salva');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '1', '6', 'Un peccator come me;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '1', '7', 'Ei m\'ha col sangue redento,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '1', '8', 'Altro che salvi non v\'è.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '2', '1', 'Tolto da tenebre e morte,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '2', '2', 'Libero da schiavitù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '2', '3', 'Ei nuova vita m\'ha dato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '2', '4', 'Il mio Signore Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '3', '1', 'Egli m\'accolse qual ero,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '3', '2', 'Pieno di colpe e terror,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '3', '3', 'Egli portò la mia pena,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '3', '4', 'Il mio divin Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '4', '1', 'Or dal Suo amor benedetto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '4', '2', 'Pieno di lode è il mio cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '4', '3', 'Mentre per grazia io seguo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '4', '4', 'Il mio divino Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '5', '1', 'Or a Lui solo appartengo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '5', '2', 'Finché dal cielo Ei verrà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '5', '3', 'E nel vedere il Suo volto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('122', '5', '4', 'Colmo il mio gaudio sarà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('123', '11.10.11.10.10.10.', '180', '13');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '1', '1', 'IN grazia attende Dio per benedire:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '1', '2', 'Liete novelle vengono dal ciel!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '1', '3', 'Ei può in giustizia la Sua grazia offrire,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '1', '4', 'I peccatori perdonare appien.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '1', '5', 'All\'uom Ei chiede pentimento sol');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '1', '6', 'E fede in Cristo, il santo Suo Figliol.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '2', '1', 'Un tal favor prezioso puoi gustare:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '2', '2', 'Liberamente vien offerto in don,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '2', '3', 'Poiché Gesù, sul legno del Calvario,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '2', '4', 'Sofferse, Ei Sostituto là per l\'uom;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '2', '5', 'Fatto peccato il Giusto fu e pagò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '2', '6', 'Col sangue il prezzo del riscatto allor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '3', '1', 'Giudizio inesorabil, in quell\'ora');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '3', '2', 'Solenne e oscura, sopportò in amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '3', '3', 'La vita Sua depose, e della morte');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '3', '4', 'Spezzò il poter: compiuto è il Suo lavor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '3', '5', 'Dio sodisfatto fu nell\'espiazion,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '3', '6', 'Or è risorto e asceso il Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '4', '1', 'Di Dio il tesoro, ch\'è riposto in cielo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '4', '2', 'Manifestato in Cristo noi vediam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '4', '3', 'La pace, il dono dello Spirto Santo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '4', '4', 'La gioia, l\'adozion in Lui gustiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '4', '5', 'A Dio ti volgi, e avrai benedizion,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('123', '4', '6', 'La guida dello Spirito, il Suo amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('124', '10.10.10.10.', '21', '127');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '1', '1', 'GESU\', Signore, Stella del Mattin');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '1', '2', 'Il Nome Tuo ben noi conosciam!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '1', '3', 'Gesù. il Signore, il Crocifisso, Tu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '1', '4', 'Sempre lo stesso in gloria sei lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '2', '1', 'Gesù, Colui che venne qui dal ciel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '2', '2', 'In grazia, l\'uom perduto per salvar -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '2', '3', 'Sul glorïoso volto Tuo ancor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '2', '4', 'Brillan la Tua umiltà ed il Tuo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '3', '1', 'Gesù, Colui che in terra camminò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '3', '2', 'Umìle fosti, sottomesso ognor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '3', '3', 'Obbedïenza fino a morte fu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '3', '4', 'In Te, di Dio diletto Figlio Tu!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '4', '1', 'Gesù, il cuor nostro ama ricordar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '4', '2', 'I benedetti passi Tuoi quaggiù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '4', '3', 'Mentre lo sguardo verso il ciel volgiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '4', '4', 'E Te là nella gloria Tua vediam!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '5', '1', 'Gesù, o benedetto Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '5', '2', 'Vieni e ci prendi ad esser presso Te;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '5', '3', 'Glorioso il dì celeste apparirà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('124', '5', '4', 'Quand\'il Tuo volto ognun di noi vedrà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('125', '9.8.9.8.9.8.9.8. Giambico.', '137', '44');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '1', '1', 'O DIO, la lode T\'appartiene');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '1', '2', 'Di creature in libertà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '1', '3', 'Tu sei possente, glorïoso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '1', '4', 'Sommo in divina maestà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '1', '5', 'Inaccessibil è la luce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '1', '6', 'Dove Tu abiti, Sovran;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '1', '7', 'Narran Tua gloria e Tua potenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '1', '8', 'I cieli e l\'opra di Tue man.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '2', '1', 'Dai tempi eterni Tu sei Dio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '2', '2', 'E per i secoli a venir;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '2', '3', 'Grazia riveli e Ti compiaci');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '2', '4', 'Misericordia nel largir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '2', '5', 'Sapienza appar nelle Tue vie,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '2', '6', 'Giustizia v\'è in attività,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '2', '7', 'In Tua presenza sta il superno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '2', '8', 'Dominio della verità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '3', '1', 'L\'amore ch\'è la Tua natura,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '3', '2', 'Santo, immutabile, divin,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '3', '3', 'Sovra il creato Tuo risplende:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '3', '4', 'Benedizione senza fin!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '3', '5', 'La Tua dimora è tra le lodi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '3', '6', 'Che Tue saran per ogni età:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '3', '7', 'Dio nostro, a Te nell\'assemblea');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('125', '3', '8', 'Sia gloria per l\'eternità!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('126', '7.7.7.6.7.7.7.6.', '142', '9998');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('126', '1', '1', 'SANTIFICA, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('126', '1', '2', 'I nostri giorni in terra;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('126', '1', '3', 'Fa\' che quaggiù T\'onori');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('126', '1', '4', 'La nostra vita ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('126', '1', '5', 'Di santa Tua presenza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('126', '1', '6', 'Che in mezzo a noi sentiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('126', '1', '7', 'Deh, l\'inclita influenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('126', '1', '8', 'Ricolmi i nostri cuor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('126', '2', '1', 'Ci da\' di camminare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('126', '2', '2', 'Per fé costantemente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('126', '2', '3', 'E a Te, Signor, guardare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('126', '2', '4', 'Se siamo nel dolor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('126', '2', '5', 'Felice chi riposa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('126', '2', '6', 'Sul braccio Tuo possente!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('126', '2', '7', 'I Tuoi han ogni cosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('126', '2', '8', 'Avendo Te, Signor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('127', '8.5.8.5.', '56', '59');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '1', '1', 'O SIGNOR, dove hai dimora');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '1', '2', 'Più non domandiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '1', '3', 'Ben sappiam dove dimori,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '1', '4', 'Ben lo conosciam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '2', '1', 'Tu dimori in seno al Padre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '2', '2', 'Nel Suo santo amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '2', '3', 'In eterno sei l\'oggetto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '2', '4', 'Del divin Suo cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '3', '1', 'Ed averci Tuoi compagni');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '3', '2', 'Vuoi, Signor Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '3', '3', 'Nella santa, eccelsa sfera');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '3', '4', 'Dove vivi Tu.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '4', '1', 'E così con grato cuore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '4', '2', 'Mentre T\'attendiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '4', '3', 'Già l\'amore, il gaudio eterno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '4', '4', 'Oggi anticipiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '5', '1', 'Deh! ci tieni a Te vicini');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '5', '2', 'Nel fedel Tuo amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '5', '3', 'Fino al dì che Teco in gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('127', '5', '4', 'Noi sarem, Signor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('128', '11.4.11.4.10.10.', '196', '95');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('128', '1', '1', 'NOI Ti lodiam, O Dio, gloriosa fonte');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('128', '1', '2', 'Di luce e amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('128', '1', '3', 'Ogni benedizion da Te discende,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('128', '1', '4', 'E\' Tuo il poter.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('128', '1', '5', 'Tuoi sono terra e ciel, e noi vediam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('128', '1', '6', 'La Tua supremazia, e ne gioiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('128', '2', '1', 'Tu sei supremo Capo d\'ogni cosa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('128', '2', '2', 'In maestà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('128', '2', '3', 'Il Nome Tuo glorioso l\'alma adora');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('128', '2', '4', 'Con umiltà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('128', '2', '5', 'Tu nell\'amor riposi, e noi per fé');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('128', '2', '6', 'Vediamo tutto sottoposto a Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('128', '3', '1', 'Anticipiamo il giorno in cui il Tuo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('128', '3', '2', 'Riposerà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('128', '3', '3', 'E ognuno, O Re dei secoli, al potere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('128', '3', '4', 'Tuo piegherà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('128', '3', '5', 'L\'eterna scena riempirai allor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('128', '3', '6', 'E tutto in tutti Tu sarai ognor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('129', '11.10.11.10. Dattilico.', '17', '17');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('129', '1', '1', '"TU sei quel Dio", in eterno immutato:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('129', '1', '2', 'Un dì mirïadi T\'adoreran');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('129', '1', '3', 'E nel paterno Tuo amor riposando');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('129', '1', '4', 'Liete famiglie a Te lodi offriran.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('129', '2', '1', 'Or nel poter dello Spirto del Padre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('129', '2', '2', 'Cristo per fede già in cuore teniam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('129', '2', '3', 'E comprendendo una sfera sì vasta-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('129', '2', '4', 'Pur definita - il Suo amor conosciam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('129', '3', '1', 'O Dio, Tu puoi di Tua santa pienezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('129', '3', '2', 'I cuor colmar cui svelasti il Tuo cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('129', '3', '3', 'Nell\'assemblea ch\'è in Gesù benedetta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('129', '3', '4', 'A Te in eterno sia gloria ed onor!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('130', '9.9.9.8.6.', '163', '191');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('130', '1', '1', 'O PADRE, a Te ci avviciniamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('130', '1', '2', 'Col Primogenito Figliolo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('130', '1', '3', 'Ed "Abba, Padre" noi sclamiamo.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('130', '1', '4', 'A Te la lode presentiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('130', '1', '5', 'Che non avrà mai fin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('130', '2', '1', 'O nostro Padre, a Te conduce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('130', '2', '2', 'L\'amor Tuo santo, pieno, immenso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('130', '2', '3', 'Lo Spirto ci empie i cuor di luce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('130', '2', '4', 'E già con Cristo parte abbiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('130', '2', '5', 'Rendendo gloria a Te.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('131', '10.9.10.9.10.9.10.9.', '177', '42');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '1', '1', 'CON l\'orecchio ed il cuore a Te volti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '1', '2', 'Attendiam la Tua voce, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '1', '3', 'Il Tuo grido che chiamaci al cielo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '1', '4', 'Dove sempre godrem del Tuo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '1', '5', 'La parola e lo Spirto alla sposa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '1', '6', 'L\'arra sono del dì che verrà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '1', '7', 'Tu vicin le sei già per la fede,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '1', '8', 'Ma al Tuo fianco ella presto sarà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '2', '1', 'Vieni dunque, Signor, T\'aspettiamo!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '2', '2', 'La Tua sposa deh! prendi con Te;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '2', '3', 'La Tua assenza ella sente, ed anela');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '2', '4', 'Di vederti: il suo Sposo Tu se\'.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '2', '5', 'Nell\'attesa, d\'amore ricolmo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '2', '6', 'E\' il Tuo cuore, già ben lo sappiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '2', '7', 'E noi grati al Tuo amor rispondendo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '2', '8', 'Con le lampade accese attendiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '3', '1', 'La Tua sposa e lo Spirito uniti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '3', '2', 'A Te dicono: "Vieni", Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '3', '3', 'Nelle veglie notturne ella ha atteso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '3', '4', 'll suo Sposo con fervido cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '3', '5', 'Se la notte con funebre manto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '3', '6', 'Ogni cosa quaggiù copre ancor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '3', '7', 'Il Tuo gregge è ancor qui, da Tua mano');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '3', '8', 'Sostenuto, amoroso Pastor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '4', '1', 'Già da lungi alla fede risplende');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '4', '2', 'Il fulgore del dì che verrà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '4', '3', 'Tu a noi sei del Mattino la Stella');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '4', '4', 'Ed eterno il Tuo giorno sarà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '4', '5', 'La parola di Tua pazienza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '4', '6', 'Noi serbiamo; ci tien Tuo splendor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '4', '7', 'In disparte e qual faro ci guida');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('131', '4', '8', 'Al Tuo incontro, Speranza del cuor!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('132', '8.7.8.7.', '24', '139');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('132', '1', '1', 'E\' LA fonte d\'ogni grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('132', '1', '2', 'La Persona del Signor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('132', '1', '3', 'Che morì, ma vive in cielo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('132', '1', '4', 'Degno d\'ogni lode e onor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('132', '2', '1', 'In Lui pure noi morimmo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('132', '2', '2', 'Nostra vita ascosa or');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('132', '2', '3', 'E\' nel ciel, in Dio, con Cristo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('132', '2', '4', 'Capo della chiesa ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('132', '3', '1', 'Or aperti sono i cieli:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('132', '3', '2', 'Per la fé ci è dato entrar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('132', '3', '3', 'E Gesù, Signore e Cristo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('132', '3', '4', 'Là possiamo contemplar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('133', '10.9.10.9.10.9.10.9.', '177', '69');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '1', '1', 'OH, mirabile tempo di grazia!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '1', '2', 'Dio risplendere fa il Suo favor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '1', '3', 'Per avere una sfera di gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '1', '4', 'Che risponde al divino Suo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '1', '5', 'Or, in Cristo, d\'eterni pensieri');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '1', '6', 'Manifesto è l\'immenso valor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '1', '7', 'Per gli uomini, un posto di figli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '1', '8', 'Conosciuto mediante il Figliol.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '2', '1', 'Ma di schiavi il legame avvinceva');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '2', '2', 'Qui gli oggetti d\'un tale favor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '2', '3', 'Il perduto doveasi trovare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '2', '4', 'E redimere l\'uom peccator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '2', '5', 'Sì, l\'amor cercò in grazia i caduti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '2', '6', 'Prigionieri del male quaggiù:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '2', '7', 'Per salvarli - oh, la storia preziosa-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '2', '8', 'Sulla croce moriva Gesù!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '3', '1', 'Or quell\'opera nella sua gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '3', '2', 'I pensieri di Dio affermò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '3', '3', 'Ed or regna mediante giustizia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '3', '4', 'La Sua grazia che appien trionfò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '3', '5', 'Ogni cosa è compiuta: ai cuor nostri');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '3', '6', 'Lo conferma lo Spirto quaggiù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '3', '7', 'Oh, mirabile tempo presente-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('133', '3', '8', 'Dio risplende nel Figlio, in Gesù!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('134', '10.10.10.9.10.10.10.9.', '170', '95');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '1', '1', 'O SIGNORE Gesù, noi cantiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '1', '2', 'Mossi dai Tuoi supremi diritti;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '1', '3', 'Di Tua santa Persona ammiriamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '1', '4', 'La grandezza con gioia nel cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '1', '5', 'La Tua gloria di Uomo e la grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '1', '6', 'Tua son tema che unisce nel canto:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '1', '7', 'Noi cediam al Tuo amor che ci sazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '1', '8', 'Della Tua bellezza, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '2', '1', 'Com\'è bella la Tua compagna!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '2', '2', 'Piace agli occhi Tuoi santi per sempre;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '2', '3', 'E\' delizia al Tuo cuore che l\'ama,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '2', '4', 'Di Tua gioia l\'oggetto ad ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '2', '5', 'Frutto del Tuo glorioso servizio-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '2', '6', 'Fu per lei che Tu desti la vita! -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '2', '7', 'Ti risponde con santo esercizio:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '2', '8', 'E\' Tua gloria, Tua moglie, Signor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '3', '1', 'Già ricolma il Tuo cuor la Tua sposa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '3', '2', 'Dell\' union nel fedel compimento,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '3', '3', 'Ora libera nella gioiosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '3', '4', 'Rispondente espressione d\'amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '3', '5', 'E\' di Dio la risposta preziosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '3', '6', 'Al Tuo santo, profondo desìo-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '3', '7', 'Controparte celeste e gloriosa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('134', '3', '8', 'Simigliante a Te stesso, Signor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('135', '8.5.8.3.', '53', '84');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '1', '1', 'DIO e Padre, Ti lodiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '1', '2', 'Il Tuo amor sappiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '1', '3', 'Pria che il mondo fosse, eletti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '1', '4', 'Da Te siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '2', '1', 'Il Figliol che per noi desti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '2', '2', 'Ti glorificò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '2', '3', 'Per condurci a Te vicino');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '2', '4', 'Ei spirò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '3', '1', 'Or con Cristo per lo Spirto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '3', '2', 'Pur noi parte abbiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '3', '3', 'Padre - fatti Tuoi figlioli,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '3', '4', 'Ti chiamiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '4', '1', 'Del Tuo amore la dolcezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '4', '2', 'Già noi conosciam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '4', '3', 'Dio e Padre, a Te davanti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '4', '4', 'T\'adoriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '5', '1', 'Presto nella Tua dimora');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '5', '2', 'Noi con Te sarem,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '5', '3', 'In eterno quali figli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '5', '4', 'Loderem.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '6', '1', 'Primogenito Figliolo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '6', '2', 'Cristo ognor sarà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '6', '3', 'Dei fratelli Suoi la lode');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('135', '6', '4', 'Condurrà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('136', '11.10.11.10.11.10.11.10.', '183', '200');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '1', '1', 'PADRE, Sorgente di benedizione,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '1', '2', 'Riconoscente lode T\'apportiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '1', '3', 'Oggetti del sovrano Tuo favore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '1', '4', 'L\'amore Tuo con gioia noi cantiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '1', '5', 'L\'amore che trovò la sua espressione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '1', '6', 'Perfetta nel diletto Tuo Figliol,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '1', '7', 'In Lui che, dimorando nel Tuo seno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '1', '8', 'Appieno l\'amor Tuo ci rivelò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '2', '1', 'L\'eterno Tuo proposito di grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '2', '2', 'E\' ora in Cristo manifesto a noi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '2', '3', 'Piano ricolmo di benedizione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '2', '4', 'Per i preconosciuti figli Tuoi.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '2', '5', 'Portati nel riposo in quella sfera');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '2', '6', 'Dove l\'amor dispiega i suoi tesor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '2', '7', 'Là noi beviamo l\'acqua della vita');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '2', '8', 'Gustando gioie che saranno ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '3', '1', 'Condotti or a conoscere il Diletto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '3', '2', 'A Lui attratti in grazia immensa siam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '3', '3', 'Il Tuo fulgor, amore e gloria splender');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '3', '4', 'Nel benedetto volto Suo vediam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '3', '5', 'Noi T\'adoriamo, nostro Dio e Padre-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '3', '6', 'Sempre esaltato il Nome Tuo sarà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '3', '7', 'Omaggio e lode insieme Ti rendiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('136', '3', '8', 'Fin d\'ora, come nell\'eternità.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('137', '11.10.11.10.', '52', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '1', '1', 'SIGNOR Gesù, sei Fonte d\'ogni gioia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '1', '2', 'La voce Tua d\'amore or ascoltiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '1', '3', 'Alle celesti sfere Tu ci adduci');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '1', '4', 'E, rispondendo a Te, noi Ti lodiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '2', '1', 'Sì, Ti lodiamo! Nel Tuo santo volto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '2', '2', 'Di Dio la gloria splende senza vel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '2', '3', 'Ed ora in giusta grazia Tu ci guidi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '2', '4', 'Dove Ti loderem per sempre in ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '3', '1', 'Di Te viviamo, perché abbiam udito');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '3', '2', 'La voce Tua che a noi la vita dà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '3', '3', 'Che parla d\'un amore illimitato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '3', '4', 'D\'ogni pensiero uman molto al di là.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '4', '1', 'E\' l\'amor del Tuo Padre che riveli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '4', '2', 'E che di gioia a noi ricolma il cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '4', '3', 'Ed ora al Padre Tuo ci conduci');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '4', '4', 'In spirto per godere quell\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '5', '1', 'Qual infinita gioia! Nella Tua');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '5', '2', 'Persona il Padre noi possiam veder:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '5', '3', 'Contenti siamo pure nell\'attender');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('137', '5', '4', 'L\'amor Suo pienamente di goder.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('138', '11.10.11.10.', '52', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '1', '1', 'CON amorosa cura un santo Padre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '1', '2', 'Costantemente veglia per veder');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '1', '3', 'Se i figli Suoi dan frutti che convengon');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '1', '4', 'Alla lor vocazion, pel Suo piacer.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '2', '1', 'Egli conosce tutt\'il nostro stato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '2', '2', 'E tutto quel che può intervenir');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '2', '3', 'Ad oscurar la comunion con Lui');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '2', '4', 'Ed il progresso nostro ad impedir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '3', '1', 'Oh, santo amor, che mai dimenticare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '3', '2', 'Non può gli oggetti cari al divin cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '3', '3', 'E, se ritenga a volte castigarci,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '3', '4', 'Lo fa per ricondurci con amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '4', '1', 'Ei ci ricorda sempre, e ci nutrisce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '4', '2', 'Con fresche prove del Suo santo amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '4', '3', 'Finché noi, liberati d\'ogni male,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '4', '4', 'In Sua presenza riposiamo ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '5', '1', 'Divino amor che nessun altro eguaglia!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '5', '2', 'Sian l\'alme nostre mantenute là');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '5', '3', 'Dove una gloria, degna del fulgore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '5', '4', 'Del volto Suo, risplende a eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '6', '1', 'Oh, umiltà, si poco conosciuta,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '6', '2', 'Che alla Sua grazia corrisponder può');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '6', '3', 'Servendo Lui quaggiù, finché la grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('138', '6', '4', 'Coroni quel che grazia incominciò.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('139', '11.10.11.10.', '52', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '1', '1', 'E\' QUESTO mondo un arido deserto:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '1', '2', 'Nessun desìo di rimanervi abbiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '1', '3', 'Nulla possiamo scegliere o cercare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '1', '4', 'Né danno alcuno qui temer dobbiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '2', '1', 'Oh, che dobbiamo dunque paventare?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '2', '2', 'Dai passi del divino Salvator');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '2', '3', 'La via che noi seguiamo è ben tracciata,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '2', '4', 'Sicura come il Suo provato amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '3', '1', 'Egli ci dona tutta la Sua forza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '3', '2', 'Per proseguire lungo quel cammin');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '3', '3', 'Che al Suo Dio e Padre Lo condusse,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '3', '4', 'Là dove giungeremo noi al fin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '4', '1', 'In santità con Lui dimoreremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '4', '2', 'Quando sul trono Cristo noi vedrem');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '4', '3', 'E nella gioia della Sua presenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '4', '4', 'Pace e riposo eterno troverem.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '5', '1', 'Sì, fu il tesoro nel Suo amor trovato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '5', '2', 'Che fa di noi dei pellegrini qui;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '5', '3', 'Con Lui, così qual siamo conosciuti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '5', '4', 'Conoscerem la Sua pienezza un dì.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '6', '1', 'Or attendiam che Tu dal ciel ritorni');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '6', '2', 'Con Te a rapire, nostro Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '6', '3', 'I Tuoi che hai con l\'occhio Tuo condotti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '6', '4', 'Alla dimora del Tuo santo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '7', '1', 'Finché ritorni, sempre troveremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '7', '2', 'Diletto nel seguire il Tuo cammin');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '7', '3', 'Contenti di Tua verga e Tua bacchetta,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('139', '7', '4', 'Finché la gloria Tua vedrem alfin.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('140', '9.8.9.8.9.8.9.8. Giambico.', '137', '73');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '1', '1', 'SIGNORE, i nostri cuori attendon');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '1', '2', 'Il grande grido trionfal');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '1', '3', 'Che desta i santi ch\'ora dormon');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '1', '4', 'E presso Te li porterà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '1', '5', 'Allor con loro saliremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '1', '6', 'Nell\'aria Te ad incontrar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '1', '7', 'Per contemplar la gloria Tua,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '1', '8', 'La somiglianza Tua portar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '2', '1', 'Sì, è quell\'ora che, paziente,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '2', '2', 'Lungo la notte attendi Tu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '2', '3', 'Finché i Tuoi santi sian riuniti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '2', '4', 'E nella luce sian lassù!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '2', '5', 'Allor, la chiesa completata,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '2', '6', 'Nessun indugio Iddio porrà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '2', '7', 'Signor, con grida di trionfo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '2', '8', 'Nel giorno Tuo potremo entrar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '3', '1', 'Oh, ora di benedizione!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '3', '2', 'Così vicin portati a Te,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '3', '3', 'Sarem la gioia Tua per sempre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '3', '4', 'Con Te lassù dimorerem,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '3', '5', 'Per riposar in quel fulgore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '3', '6', 'E sempre rimanere là:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '3', '7', 'In noi, Tua sposa, il cuore Tuo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '3', '8', 'Signor, delizia troverà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '4', '1', 'Or attendiam così quel grido,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '4', '2', 'O benedetto Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '4', '3', 'A cui risponde, grato, il cuore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '4', '4', 'Dei Tuoi:"Per sempre col Signor".');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '4', '5', 'Con Te, prezioso Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '4', '6', 'Sarem in sempiterno allor-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '4', '7', 'Benedizione sì profonda! -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('140', '4', '8', 'Uno con Te saremo ognor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('141', '9.8.9.8. Giambico.', '161', '47');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '1', '1', 'PADRE, di sopra d\'ogni cosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '1', '2', 'Eccelso, il Dio di gloria Tu!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '1', '3', 'D\'amor il Tuo messaggio è espresso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '1', '4', 'Nel Figlio del Tuo amor, Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '2', '1', 'Oggetti per il Tuo piacere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '2', '2', 'Cercasti dall\'eternità:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '2', '3', 'Dei figli per un giorno eterno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '2', '4', 'Dei cuori che T\'adoreran.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '3', '1', 'Il Tuo Figliolo Tu nel mondo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '3', '2', 'Mandasti, il piano Tuo a compir:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '3', '3', 'Lui sol comprenderlo poteva,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '3', '4', 'Lui sol sapeva i Tuoi desir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '4', '1', 'Nessun servizio troppo umìle');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '4', '2', 'Ritenne, o sacrifizio alcun');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '4', '3', 'Per Lui fu troppo grande, a compier');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '4', '4', 'Il Tuo proposito sovran.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '5', '1', 'Or il Tuo amor riposo trova,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '5', '2', 'I Tuoi pensier compiuti son,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '5', '3', 'E i figli che Tu guadagnasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('141', '5', '4', 'Ti danno eterna adorazion.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('142', '9.8.9.8.Dattilico.', '112', '146');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('142', '1', '1', '"LODATE il Signore, lodate",');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('142', '1', '2', 'Ripete lo Spirito ognor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('142', '1', '3', 'Non tocca Egli invano i cuor nostri:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('142', '1', '4', 'La lode Ti diamo, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('142', '2', '1', 'In Lui rallegratevi, o santi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('142', '2', '2', 'Ridice lo Spirito ancor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('142', '2', '3', 'La fede risponde col canto:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('142', '2', '4', 'E\' in Te nostra gioia, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('142', '3', '1', 'Per sempre a Te gloria sia resa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('142', '3', '2', 'Signore, di Dio l\'Agnel!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('142', '3', '3', 'Tu stesso sarai nostro tema');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('142', '3', '4', 'Di gioia, in terra ed in ciel.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('143', '11.10.11.10.', '52', '110');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('143', '1', '1', 'DALLA Tua mente e dal Tuo cuore, o Dio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('143', '1', '2', 'La luce di sapienza ai nostri cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('143', '1', '3', 'Emana, sì che Cristo nostro Capo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('143', '1', '4', 'Riconosciam, godendo del Suo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('143', '2', '1', 'Ma più di questo, Tu nell\'assemblea');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('143', '2', '2', 'Riveli alle celesti potestà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('143', '2', '3', 'Tua varia sapïenza ed il Tuo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('143', '2', '4', 'Che tutto l\'universo un dì unirà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('143', '3', '1', 'A Te dinanzi, Padre, c\'inchiniamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('143', '3', '2', 'Rinforza per lo Spirto i nostri cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('143', '3', '3', 'In essi possa Cristo dimorare,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('143', '3', '4', 'E pieni sian di lode pel Tuo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('143', '4', '1', 'O amore, che sorpassa ogni pensiero,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('143', '4', '2', 'Amor di Cristo, che ben conosciam!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('143', '4', '3', 'Colmati della santa Tua pienezza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('143', '4', '4', 'Portati nell\'eterna luce siam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('144', '11.10.11.10.11.10.11.10.', '183', '110');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('144', '1', '1', 'NELLA dimora dell\'amor divino,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('144', '1', '2', 'Del Padre la magione di splendor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('144', '1', '3', 'I pieni raggi della gloria brillan');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('144', '1', '4', 'In Quei che fino a morte Si abbassò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('144', '1', '5', 'E noi avremo parte a quella casa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('144', '1', '6', 'Che nel Suo amor Ei stesso ci acquistò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('144', '1', '7', 'Come abbiam parte già all\'amor del Padre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('144', '1', '8', 'Con Lui, il Primogenito Figliol.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('144', '2', '1', 'Con Lui sarem dov\'Egli già dimora,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('144', '2', '2', 'Poiché sappiam che tale è il Suo desir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('144', '2', '3', 'Allo splendor guardando di Sua gloria:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('144', '2', '4', 'Vision che fa la lode scaturir!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('144', '2', '5', 'Del Padre l\'infinito, eterno amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('144', '2', '6', 'Davanti al nostro sguardo brillerà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('144', '2', '7', 'In Lui, ch\'è Capo sopra ogni cosa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('144', '2', '8', 'Durante il giorno dell\'eternità.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('145', '10.9.10.9.', '114', '215');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '1', '1', 'RIGUARDATE l\'Agnello, il cui sangue');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '1', '2', 'Dal Suo fianco forato sgorgò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '1', '3', 'Ogni macchia cancella per sempre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '1', '4', 'E la pace con Dio ci donò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '2', '1', 'Il ladrone morente all\'Agnello,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '2', '2', 'Che spirava al suo fianco, guardò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '2', '3', 'E il valore prezioso del Nome');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '2', '4', 'Di Gesù crocifisso provò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '3', '1', 'Ricevuta quel di in paradiso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '3', '2', 'L\'alma sua fu del sangue in virtù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '3', '3', 'Quale primo trofeo del trionfo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '3', '4', 'Che compì sulla morte Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '4', '1', 'Or del sangue di Cristo il potere,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '4', '2', 'Che purifica, noi pur sappiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '4', '3', 'Il Suo Nome, nel quale condotti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '4', '4', 'Siam a Dio, per grazia onoriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '5', '1', 'A Colui che scendè fino a morte');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '5', '2', 'Gl\'inni nostri si levino ognor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '5', '3', 'Lode eterna sia a Cristo, l\'Agnello,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('145', '5', '4', 'Ei l\'Amico dell\'uom peccator.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('146', '8.8.8.8.', '30', '110');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('146', '1', '1', 'IN Tua presenza noi veniam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('146', '1', '2', 'Signor, sedendoci ai Tuoi piè');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('146', '1', '3', 'Il volto Tuo per contemplar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('146', '1', '4', 'Ed in Te dimorar per fé,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('146', '2', '1', 'Le Tue parole ad ascoltar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('146', '2', '2', 'Piene di grazia e verità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('146', '2', '3', 'Pegno di gioia celestial');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('146', '2', '4', 'Di cui Tu sei la realtà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('146', '3', '1', 'Liberi qui da distrazion,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('146', '3', '2', 'La voce Tua vogliam udir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('146', '3', '3', 'La Tua bellezza contemplar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('146', '3', '4', 'E nell\'amore Tuo gioir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('146', '4', '1', 'Tu vieni a noi, Signor Gesù:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('146', '4', '2', 'Nel mondo sei sprezzato ancor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('146', '4', '3', 'Ma una dimora puoi trovar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('146', '4', '4', 'Dei Tuoi diletti nell\'amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('147', '10.9.10.9.', '114', '70');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('147', '1', '1', 'O GLORIOSO Figliolo di Dio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('147', '1', '2', 'A Te sempre sia lode ed onor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('147', '1', '3', 'Riverenti or a Te ci prostriamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('147', '1', '4', 'E T\'offriamo l\'omaggio del cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('147', '2', '1', 'Or risorto Tu entri fra noi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('147', '2', '2', 'Vittorioso, Ti riconosciam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('147', '2', '3', 'Ci dài pace che liberi rende,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('147', '2', '4', 'Nella gioia d\'amor T\'adoriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('147', '3', '1', 'Tu sei Uomo e pure sei Dio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('147', '3', '2', 'Queste glorie risplendono in Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('147', '3', '3', 'Esultando proviam il Tuo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('147', '3', '4', 'Mentre qui Ti vediamo per fé.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('148', '9.8.9.8. Dattilico.', '112', '68');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('148', '1', '1', 'SIGNORE, dall\'anime nostre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('148', '1', '2', 'La gloria, la lode T\'offriam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('148', '1', '3', 'Prostrati in omaggio a Te innanzi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('148', '1', '4', 'I cuori e le voci eleviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('148', '2', '1', 'Con spirti adoranti miriamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('148', '2', '2', 'L\'amor che la morte affrontò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('148', '2', '3', 'E il Tuo sacrificio cruento');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('148', '2', '4', 'Che a Te l\'alme nostre portò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('148', '3', '1', 'La via di Tua devozione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('148', '3', '2', 'Amiamo, Signor, contemplar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('148', '3', '3', 'E come il voler del Tuo Dio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('148', '3', '4', 'Potesti Tu sol completar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('148', '4', '1', 'Risorto e vivente, Tu sei');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('148', '4', '2', 'Supremo ai Tuoi santi, Signor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('148', '4', '3', 'Con cuori gioiosi T\'offriamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('148', '4', '4', 'La lode, risposta d\'amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('149', '11.11.11.10.11.11.11.10.', '190', '97');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '1', '1', 'NOSTRO Signor Gesù, noi ricordiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '1', '2', 'Dell\'alma Tua il travaglio ed il dolore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '1', '3', 'Allor che a causa del Tuo grande amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '1', '4', 'I flutti son passati su di Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '1', '5', 'Nell\'acque della morte battezzato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '1', '6', 'Per noi il sangue Tuo Tu spandesti:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '1', '7', 'Fra i morti pur annoverato fosti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '1', '8', 'Per noi, Signor di gloria, Salvator!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '2', '1', 'Signor Gesù, Tu ora sei risorto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '2', '2', 'Il Tuo lavoro tutto fu compiuto;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '2', '3', 'Soffristi Tu una volta pel peccato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '2', '4', 'Vivente or sei, per non morir mai più.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '2', '5', 'Peccato, inferno e morte sono vinti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '2', '6', 'Da Te, il Primogenito fra i morti;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '2', '7', 'Ai Tuoi trionfi noi abbiamo parte:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '2', '8', 'Abbiamo vinto in Te, Signor Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '3', '1', 'Alla Tua morte battezzati, ora');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '3', '2', 'Noi d\'esser con Te morti confessiamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '3', '3', 'Con Te risorti, nostra vita, siamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '3', '4', 'E pur sarem glorificati in Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '3', '5', 'Da Satana, dal mondo, dal peccato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '3', '6', 'Col sangue Tuo siamo riscattati;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '3', '7', 'E camminar vorremmo qui appartati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('149', '3', '8', 'Quali stranier, vivendo a Dio con Te.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('150', '8.8.8.8.8.8.8.8. (b)', '158', '111');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '1', '1', 'IL nostro canto parlerà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '1', '2', 'Di Te, Gesù Signore, il Re:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '1', '3', 'Ora un tributo T\'apportiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '1', '4', 'E lo rendiam con gioia a Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '1', '5', 'Le labbra mute la Tua man');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '1', '6', 'Aprì, Tue lodi per cantar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '1', '7', 'Ed in quest\'arido sentier');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '1', '8', 'Di Te cantiam nel camminar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '2', '1', 'L\'uom rende sol la lode all\'uom,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '2', '2', 'Debole creatura fral;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '2', '3', 'I giorni suoi qual nube son,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '2', '4', 'La breve gloria sua scompar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '2', '5', 'Di Te, Figliol di Dio, cantiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '2', '6', 'In Te la nostra gloria sta-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '2', '7', 'L\'Eterno, l\'Immutabil Tu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '2', '8', 'Dei santi tema a eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '3', '1', 'Pur l\'opra della creazion,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '3', '2', 'Che adorna da Tua mano fu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '3', '3', 'Guastò l\'ingrata man dell\'uom');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '3', '4', 'Che crocifisse Te, Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '3', '5', 'Così un deserto noi stimiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '3', '6', 'La terra, con il suo splendor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '3', '7', 'Né parte in questo luogo abbiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '3', '8', 'Che rifiutava il Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '4', '1', 'Qui T\'attendiam, Gesù, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '4', '2', 'E nell\'attender noi cantiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '4', '3', 'O Re, quaggiù respinto ancor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '4', '4', 'Tua Stella del Mattin vediam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '4', '5', 'Sarà la nostra parte allor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '4', '6', 'Dinanzi al volto Tuo cantar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '4', '7', 'Ed in Tua lode, in quel fulgor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('150', '4', '8', 'Eterna gioia là trovar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('151', '8.8.8.7.', '151', '97');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '1', '1', 'SIGNOR, quando a Te pensiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '1', '2', 'A Tua grazia ed al Tuo amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '1', '3', 'Noi bramiamo con ardore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '1', '4', 'Il Tuo volto di veder.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '2', '1', 'Benché nel deserto erriamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '2', '2', 'Col nemico a noi vicino;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '2', '3', 'Benché arido il cammino,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '2', '4', 'Pien di spine e di dolor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '3', '1', 'Lodi alziamo nel vedere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '3', '2', 'La grandezza del Tuo amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '3', '3', 'Mentre, uniti, a Te Signore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '3', '4', 'Lieti un cantico leviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '4', '1', 'Signor, Vita nostra e Luce,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '4', '2', 'Rocca, Scudo, Asil, Riposo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '4', '3', 'Il pensare a Te, glorioso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '4', '4', 'Dà delizia al nostro cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '5', '1', 'Deh, mantieni i nostri spirti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '5', '2', 'Presso Te, finché, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '5', '3', 'Noi, vestiti di splendore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('151', '5', '4', 'Nella gloria Ti vedrem.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('152', '8.7.8.7.8.7.8.7.', '25', '121');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '1', '1', 'O SIGNORE, nel dominio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '1', '2', 'Della morte andasti sol -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '1', '3', 'Essa non avea diritti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '1', '4', 'Su di Te, di Dio Figliol!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '1', '5', 'Là colui che avea di morte');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '1', '6', 'Il poter, vincesti Tu:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '1', '7', 'In quell\'ora tenebrosa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '1', '8', 'Da Te sol sconfitto fu.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '2', '1', 'Il sepolcro Tu spezzasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '2', '2', 'E risorto sei, Signor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '2', '3', 'No, la morte trattenerti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '2', '4', 'Non poteva: a Te piegò!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '2', '5', 'Vittorioso, in gloria uscivi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '2', '6', 'Dall\'oscura tomba allor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '2', '7', 'Sciolti i lacci suoi, Tu vivi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '2', '8', 'Al di là di morte ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '3', '1', 'Quali fulgidi trionfi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '3', '2', 'Riportasti Tu, Signor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '3', '3', 'Quale grande frutto Dio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '3', '4', 'Ricevè dal Tuo lavor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '3', '5', 'Una schiera diviventi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '3', '6', 'Dalla morte Tua provien,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '3', '7', 'In Te vive eternamente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '3', '8', 'E per sempre T\'appartien.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '4', '1', 'Primogenito di tutti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '4', '2', 'C\'inchiniamo a Te, Signor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '4', '3', 'Per il cuor del Padre Tuo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '4', '4', 'E per noi, sei sommo ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '4', '5', 'Ai cuor nostri sei supremo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '4', '6', 'Grande tema eterno Tu-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '4', '7', 'D\'ogni gloria Tu sei degno:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('152', '4', '8', 'Degno sei, Signor Gesù!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('153', '14.14.14.14.', '85', '9998');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('153', '1', '1', 'IL Dio possente, che dimora dall\'eternità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('153', '1', '2', 'In luce che mortale occhio mai non penetrò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('153', '1', '3', 'In terra venne quale Uomo, venne per morir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('153', '1', '4', 'Ed il crudel nemico allor per sempre debellò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('153', '2', '1', 'La luce dell\'amor e della glorïa brillò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('153', '2', '2', 'Allor che del peccato Ei sopportò la punizion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('153', '2', '3', 'Chi se non Lui poteva a Dio tal sacrificio offrir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('153', '2', '4', 'O chi pei falli miei potea mai far espïazion?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('153', '3', '1', 'Dal cielo Gesù venne per salvare il peccator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('153', '3', '2', 'Per liberare l\'alma mia da vile schiavitù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('153', '3', '3', 'Ognor nell\'opra Sua compiuta appien confiderò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('153', '3', '4', 'E l\'ira meritata non dovrò temer mai più.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('153', '4', '1', 'Or Egli vive in cielo, vive per non morir più');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('153', '4', '2', 'E Dio può giustamente il peccatore perdonar-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('153', '4', '3', 'Or vivo per lodarlo, ma ben presto Lo vedrò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('153', '4', '4', 'E le Sue lodi a casa in ciel allor potrò cantar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('154', '8.7.8.7.8.7.8.7.', '25', '131');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '1', '1', 'VIENI! E\' Cristo.che ti chiama,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '1', '2', 'Alma oppressa dal dolor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '1', '3', 'Sotto il peso. dei peccati:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '1', '4', '"Io riposo ti darò".');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '1', '5', 'Sulla croce Egli sofferse,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '1', '6', 'Compì l\'opera per te;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '1', '7', 'Ad ogni alma affaticata');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '1', '8', 'Ora dice: Vieni a Me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '2', '1', 'Vieni! Aperta sta la porta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '2', '2', 'Dove attende il Salvator;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '2', '3', 'Egli vuol che a Lui tu venga');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '2', '4', 'Via dal mondo di dolor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '2', '5', 'Dove regna carestia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '2', '6', 'E fatica v\'è per te;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '2', '7', 'Egli t\'offre ogni ricchezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '2', '8', 'Mentre dice: Vieni a Me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '3', '1', 'Vieni a Cristo, ché sul mondo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '3', '2', 'Scende già l\'oscurità:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '3', '3', 'Se per poco ancora indugi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '3', '4', 'Troppo tardi allor sarà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '3', '5', 'Pieno è il mondo d\'illusioni -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '3', '6', 'Cristo ancor si volge a te');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '3', '7', 'E l\'invito ripetiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('154', '3', '8', 'Mentr\'Ei dice: Vieni a Me.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('155', '13.6.13.6.', '202', '132');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('155', '1', '1', 'CHE cosa indusse Te, o Dio benedetto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('155', '1', '2', 'A dar pei peccator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('155', '1', '3', 'Per noi perduti, in don il Figlio Tuo diletto?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('155', '1', '4', 'Oh, l\'infinito amor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('155', '2', '1', 'Che cosa mai portò il Figlio Tuo a venire');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('155', '2', '2', 'Del cielo dal fulgor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('155', '2', '3', 'Il sangue Suo versar, in umiltà morire?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('155', '2', '4', 'Fu l\'infinito amor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('155', '3', '1', 'Che mai Ti mosse a dar lo Spirto Tuo dal cielo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('155', '3', '2', 'Che colma il nostro cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('155', '3', '3', 'Di tal celeste amor e pace senza velo?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('155', '3', '4', 'Sì, l\'infinito amor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('155', '4', '1', 'Oh, quanto amor dobbiam a Te per la superna');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('155', '4', '2', 'Tua grazia, il Tuo favor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('155', '4', '3', 'Trabocca il nostro cuor, o Dio, di lode eterna');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('155', '4', '4', 'Pel Tuo supremo amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('156', '8.8.8.7.8.8.8.7.', '153', '83');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '1', '1', 'O SIGNORE benedetto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '1', '2', 'Con gioiose pie melodi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '1', '3', 'Inalziamo a Te le lodi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '1', '4', 'Delle quali degno se\'.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '1', '5', 'Il Tuo sangue Tu spargesti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '1', '6', 'Per redimere i Tuoi santi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '1', '7', 'Che or son fatti, a Te dinanti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '1', '8', 'Sacerdoti a Dio e re.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '2', '1', 'Te lodiamo che ci amasti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '2', '2', 'E con opera efficace');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '2', '3', 'Ci associasti, nella pace,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '2', '4', 'Teco per l\'eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '2', '5', 'Ora Tuoi per sempre siamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '2', '6', 'Uno siam con Te, Signore:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '2', '7', 'Alleluia! mai il Tuo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '2', '8', 'In eterno cesserà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '3', '1', 'Con i santi Tuoi redenti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '3', '2', 'D\'ogni lingua, d\'ogni regno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '3', '3', 'Esaltiamo Te che degno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '3', '4', 'D\'ogni lode sei, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '3', '5', 'Alleluia! Sia la lode');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '3', '6', 'All\'Agnel che fu immolato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '3', '7', 'Degno d\'esser adorato.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('156', '3', '8', 'Amen: diamo lode ognor!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('157', '11.10.11.11.10.', '185', '126');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('157', '1', '1', 'NOI T\'adoriam insieme, O nostro Dio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('157', '1', '2', 'L\'incomparabil grazia Tua lodiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('157', '1', '3', 'Il Figlio Tuo manifestò il Tuo amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('157', '1', '4', 'E noi portiam la nostra adorazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('157', '1', '5', 'E inanzi a la Tua faccia ci prostriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('157', '2', '1', 'Nel Figlio Tuo l\'amore Tuo vediamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('157', '2', '2', 'In Lui portati siam a Te vicin:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('157', '2', '3', 'Or "Abba, Padre! ", accetti in Lui, gridiamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('157', '2', '4', 'Con riverenza a Te noi ci prostriamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('157', '2', '5', 'Dio nostro Padre, in lodi senza fin!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('158', '11.10.11.10.', '52', '174');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('158', '1', '1', 'DIVIN Consolatore, Spirto Santo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('158', '1', '2', 'L\'aiuto Tuo veniamo ad invocar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('158', '1', '3', 'Dacci d\'udir la voce Tua benigna,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('158', '1', '4', 'Il Tuo poter ci dona di provar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('158', '2', '1', 'Tu le profondità di Dio conosci,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('158', '2', '2', 'Tu che dispensi a noi celesti ben,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('158', '2', '3', 'Che sei la nostra Guida, ci da\' grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('158', '2', '4', 'Le vie d\'amor per esplorare appien.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('158', '3', '1', 'Guidato ogni pensier da Te, seguiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('158', '3', '2', 'La luce pura della verità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('158', '3', '3', 'Agli occhi nostri svela, Spirto Santo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('158', '3', '4', 'Le glorie che saranno a eternità.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('159', '9.8.9.8. Giambico.', '161', '182');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('159', '1', '1', 'SIGNORE, hai mosso i nostri cuori');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('159', '1', '2', 'Sì che vicini a Te noi stiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('159', '1', '3', 'Tua sposa è oggetto del Tuo amore -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('159', '1', '4', 'Uno con Te così noi siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('159', '2', '1', 'Tutto ed in tutti a noi Tu sei,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('159', '2', '2', 'A Te congiunti siam, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('159', '2', '3', 'L\'amor Tuo santo il cuore colma,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('159', '2', '4', 'E Tu nei Tuoi gioisci ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('159', '3', '1', 'Esser per Te soltanto è gaudio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('159', '3', '2', 'Che umana lingua dir non sa;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('159', '3', '3', 'E la dolcezza del Tuo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('159', '3', '4', 'Sgorgar dai cuori un canto fa.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('160', '6.4.6.4.6.4.6.4.', '32', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '1', '1', 'O SPEME fulgida!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '1', '2', 'Quando vedrem');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '1', '3', 'Il volto di Gesù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '1', '4', 'Brillar appien?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '1', '5', 'Quando potrem mirar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '1', '6', 'Senza più vel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '1', '7', 'Colui di cui sappiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '1', '8', 'L\'amor fedel;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '2', '1', 'Godere quell\'amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '2', '2', 'Che nel cammin');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '2', '3', 'Sostenne il suo lavor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '2', '4', 'Ognor vicin?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '2', '5', 'Non sconosciuto più');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '2', '6', 'Rïempirà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '2', '7', 'I cuori in cui Gesù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '2', '8', 'Dimorerà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '3', '1', 'Vedere Te, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '3', '2', 'Tua voce udir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '3', '3', 'Conoscer il Tuo amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '3', '4', 'A Te vicin;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '3', '5', 'A Te, Signor, guardar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '3', '6', 'Così fedel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '3', '7', 'Il cui aiuto mai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '3', '8', 'Non venne men.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '4', '1', 'Vedere quell\'amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '4', '2', 'Su noi posar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '4', '3', 'Noi, Tue delizie ognor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '4', '4', 'In dignità!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '4', '5', 'Né ciò ch\'è pel Tuo cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '4', '6', 'Dimentichiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '4', '7', 'I santi Tuoi, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '4', '8', 'Con Te incontriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '5', '1', 'Perfetti in beltà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '5', '2', 'Dinanzi a Te,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '5', '3', 'Tua grazia esalteran,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '5', '4', 'La Tua mercè;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '5', '5', 'Insieme i canti lor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '5', '6', 'Che fin non han,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '5', '7', 'In armonioso cor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('160', '5', '8', 'Eleveran!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('161', '11.10.11.10.', '52', '29');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '1', '1', 'FIGLIOL di Dio, con gioia Ti vediamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '1', '2', 'Supremo oggetto del paterno amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '1', '3', 'E già fin d\'or ci è dato di godere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '1', '4', 'D\'ogni benedizione in Te, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '2', '1', 'Te Primogenito d\'una celeste');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '2', '2', 'Stirpe, Signore, noi riconosciam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '2', '3', 'E Quei che T\'ha di gloria coronato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '2', '4', 'C\'invita a Sé, là dove dimoriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '3', '1', 'L\'amor divino il piano avea formato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '3', '2', 'Già fin dalla passata eternità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '3', '3', 'Daverci Tuoi, Signore, e in quell\'amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '3', '4', 'Il cuore Tuo riposo sempre avrà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '4', '1', 'Morendo in croce Tu ci liberasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '4', '2', 'Dall\'uomo del peccato, si che or');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '4', '3', 'Del Padre il santo nome Tu riveli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '4', '4', 'A noi che Tuoi fratelli siam, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '5', '1', 'E rispondendo al desiderio Tuo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '5', '2', 'Noi nell\'amor vogliamo dimorar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '5', '3', 'Consci che a Te nel cielo apparteniamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '5', '4', 'E la Tua gioia già possiam gustar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '6', '1', 'Signore nostro, in santa adorazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '6', '2', 'Ai piedi Tuoi, devoti, ci prostriam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '6', '3', 'Poiché per l\'opra Tua rigenerati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '6', '4', 'Di Dio figlioli a Lui davanti stiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '6', '5', 'Ed ora nel santuario sal un canto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '6', '6', 'Dolce, di Dio l\'orecchio a dilettar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '6', '7', 'Da ciascun cuor s\'inalza la Sua lode,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('161', '6', '8', 'Lode che Tu soltanto puoi guidar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('162', '11.10.11.10.', '52', '78');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('162', '1', '1', 'A TE, Dio Padre, offriamo il nostro omaggio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('162', '1', '2', 'La gloria di Tua grazia celebriam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('162', '1', '3', 'Lieti che per il piano Tuo divino');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('162', '1', '4', 'In Tua presenza noi venir possiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('162', '2', '1', 'Padre. Colui che Ti conosce appieno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('162', '2', '2', 'Il Nome Tuo quaggiù ci dichiarò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('162', '2', '3', 'E del Tuo amor per Lui, che mai non cambia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('162', '2', '4', 'Insieme a Lui godere ci donò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('162', '3', '1', 'Or la Tua gloria a noi dinanzi splende,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('162', '3', '2', 'Di Cristo il posto noi condividiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('162', '3', '3', 'Uniti al Primogenito Figliolo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('162', '3', '4', 'Al Tuo cospetto Ti benediciam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('163', '11.10.11.10.', '52', '110');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('163', '1', '1', '"ANCORA un po\' di tempo": Tu ritorni!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('163', '1', '2', 'Han Tua promessa tutti i Tuoi, Signor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('163', '1', '3', 'Sì, la pazienza attende, ma vederti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('163', '1', '4', 'Nell\'aria è desiderio dell\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('163', '2', '1', 'Color che dormon sorgeran risorti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('163', '2', '2', 'Ed i viventi trasformati insiem;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('163', '2', '3', 'Rapiti allora alla gloriosa porta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('163', '2', '4', 'Il benedetto Salvator vedrem.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('163', '3', '1', 'Così qual sei nel sommo Tuo fulgore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('163', '3', '2', 'Celeste, la Tua imagin porterem-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('163', '3', '3', 'Beato fin dell\'opra dell\'amore!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('163', '3', '4', 'Al trono, al regno Tuo parte avrem.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('163', '4', '1', 'Oh, qual beatitudin senza fine');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('163', '4', '2', 'Sarà con Te per sempre rimaner!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('163', '4', '3', 'Colmi di gioia che non ha confine,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('163', '4', '4', 'Il volto Tuo glorioso nel veder!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('164', '11.10.11.10.', '52', '44');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('164', '1', '1', 'SIGNOR Gesù, noi qui siam radunati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('164', '1', '2', 'Per ricordarti, perché noi T\'amiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('164', '1', '3', 'Sentiamo inver l\'assenza Tua, se pure');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('164', '1', '4', 'La gloria Tua nel cielo contempliam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('164', '2', '1', 'Or radunati in santa comunione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('164', '2', '2', 'Noi Ti lodiamo mentre T\'attendiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('164', '2', '3', 'Presto a regnare Tu verrai, Signore:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('164', '2', '4', 'Ed or fedeli a Te restar vogliam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('164', '3', '1', 'Infino a quel momento glorïoso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('164', '3', '2', 'Te nella morte amiamo ricordar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('164', '3', '3', 'Poiché Tu hai conquistato i nostri cuori');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('164', '3', '4', 'Soffrendo con amor che non ha par.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('164', '4', '1', 'La vita Tua, Te stesso, per noi desti;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('164', '4', '2', 'Si, Tu ci amasti d\'un eterno amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('164', '4', '3', 'Che fu provato - forte come morte-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('164', '4', '4', 'E trionfò, avvincendo i nostri cuor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('165', '10.10.10.2.', '87', '140');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '1', '1', 'L\'ORA è vicina: Cristo chiamerà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '1', '2', 'La voce Sua possente tutti i Suoi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '1', '3', 'Ben tosto udran: Ei stesso allor verrà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '1', '4', 'A noi.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '2', '1', 'I giorni, gli anni presto passeran-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '2', '2', 'Signor Gesù, vicino è il Tuo venir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '2', '3', 'Mentre il Tuo volto amato noi bramiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '2', '4', 'Veder.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '3', '1', 'Per noi è pronto un posto a Te vicin,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '3', '2', 'La casa che Dio stesso edificò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '3', '3', 'Eterna e pura, piena di divin');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '3', '4', 'Fulgor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '4', '1', 'Avran gli stanchi piè del pellegrin');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '4', '2', 'Riposo dolce, e nell\'eternità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '4', '3', 'Qual cor di lode là, perfetta alfin,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '4', '4', 'S\'udrà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '5', '1', 'Pazienti, or attendiam che adempi Tu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '5', '2', 'La Tua parola in grazia, e che nel ciel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '5', '3', 'Ci prenda: vieni, deh, Signor Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('165', '5', '4', 'Amen!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('166', '11.10.11.10.', '52', '209');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('166', '1', '1', 'DA scene di conflitto e di dolore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('166', '1', '2', 'Alla presenza Tua, Signor, veniam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('166', '1', '3', 'All\'ombra Tua ci dài calmo un rifugio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('166', '1', '4', 'Dove conforto e forza ognor troviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('166', '2', '1', 'D\'ogni sospiro a Te la causa è nota:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('166', '2', '2', 'Il nostro duol volesti Tu portar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('166', '2', '3', 'Cure segrete, ardue questïoni');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('166', '2', '4', 'Alla Tua luce devon dileguar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('166', '3', '1', 'Il Tuo divino amor la fé sorregge;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('166', '3', '2', 'Sull\'instancabil grazia Tua contiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('166', '3', '3', 'Mentre or le cose Tue, che a cuor ci stanno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('166', '3', '4', 'Dinanzi a Te in preghiera noi portiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('167', '8.6.8.6.', '105', '138');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '1', '1', 'PREZIOSO sangue che Gesù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '1', '2', 'Là sul Calvario diè!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '1', '3', 'Versato fu pei peccator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '1', '4', 'Versato fu per me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '2', '1', 'Prezioso sangue di Gesù!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '2', '2', 'Il prezzo intier pago,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '2', '3', 'Ed or ci è dato un pien perdon');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '2', '4', 'E pace è fatta ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '3', '1', 'Prezioso sangue di Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '3', '2', 'Gesù, di Dio Figliol!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '3', '3', 'Compiuta è l\'opra in sua virtù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '3', '4', 'Finito fu il lavor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '4', '1', 'Se rossi qual scarlatto son');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '4', '2', 'I tuoi peccati ancor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '4', '3', 'Qual neve il sangue di Gesù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '4', '4', 'Li renderà ad ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '5', '1', 'Prezioso sangue, il cui valor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '5', '2', 'A Dio ci può portar!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '5', '3', 'La nostra gloria e lode ognor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('167', '5', '4', 'E cantico sarà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('168', '11.10.11.10.11.10.11.10.', '183', '10');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '1', '1', 'NELL\' infinita Tua sapienza, o Dio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '1', '2', 'Già fin dalla passata eternità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '1', '3', 'Di gloria preparavi un universo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '1', '4', 'Di nostra comprension ben al di là:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '1', '5', 'Volevi avere uomini immortali');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '1', '6', 'Che in gloria, sempre, fossero con Te,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '1', '7', 'E che col Creator la creatura');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '1', '8', 'Potesse nella sfera Tua goder.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '2', '1', 'Quanto possenti sono i Tuoi consigli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '2', '2', 'Pei quali a noi riveli i Tuoi tesor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '2', '3', 'Possiam i Tuoi disegni contemplare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '2', '4', 'Guardando al piano Tuo pien d\'amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '2', '5', 'D\'aver dinanzi a Te, col Tuo Diletto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '2', '6', 'Noi, Tuoi figlioli, per il Tuo piacer:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '2', '7', 'Là le ricchezze della grazia Tua');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '2', '8', 'Or, senza nubi, già possiam goder.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '3', '1', 'Tutto operasti nella Tua sapienza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '3', '2', 'Di figli questa gloria a noi per dar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '3', '3', 'Sì che nel giorno eterno in Tua presenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '3', '4', 'Possiamo giubilanti dimorar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '3', '5', 'Ed in risposta, con un grato cuore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '3', '6', 'Le nostre voci a Te leviamo già:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '3', '7', 'A Te, o Padre, Figlio e Spirto Santo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('168', '3', '8', 'Or sia la lode, e per l\'eternità.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('169', '11.11.11.11.(c)', '193', '15');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('169', '1', '1', 'DEGNO di lode sei, o Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('169', '1', '2', 'Tu che col sangue Tuo ci hai comprati;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('169', '1', '3', 'Dall\'ira siam salvati e dal giudizio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('169', '1', '4', 'Ed al Tuo Dio e Padre siam portati.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('169', '2', '1', 'Or nella gloria attendi, pronto a dare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('169', '2', '2', 'Alla coscienza pace, gioia al cuore;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('169', '2', '3', 'A ognun che sente il peso delle colpe');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('169', '2', '4', 'La grazia ed il perdono dài, Signore.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('169', '3', '1', 'Al fianco Tuo trafitto son accorse');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('169', '3', '2', 'Migliaia d\'alme afflitte, per trovare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('169', '3', '3', 'Rifugio, pace, gioia, ed or felici');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('169', '3', '4', 'In Te per sempre posson riposare.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('170', '11.10.11.10.', '52', '173');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('170', '1', '1', 'DAVANTI a Te con Cristo, o nostro Dio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('170', '1', '2', 'In libertà d\'amore noi veniam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('170', '1', '3', 'In Gesù Cristo è posta l\'assemblea');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('170', '1', '4', 'E noi, in essa, a Te la gloria diam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('170', '2', '1', 'Essa, ch\'è frutto del consiglio Tuo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('170', '2', '2', 'Formata per offrire eterno onor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('170', '2', '3', 'Della beltà celeste rivestita,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('170', '2', '4', 'Alla presenza Tua riposa ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('170', '3', '1', 'Vaso ricolmo sino alla pienezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('170', '3', '2', 'Tua santa e risplendente di fulgor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('170', '3', '3', 'Essa nel Tuo dominio glorïoso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('170', '3', '4', 'Può rïempir di gioia or il Tuo cuor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('171', '10.9.10.9.', '114', '190');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '1', '1', 'SANTO Figlio di Dio, T\'adoriamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '1', '2', 'Ti diletti fra noi di venir');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '1', '3', 'Dove cuori amorosi T\'attendon,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '1', '4', 'La Tua assenza quaggiù nel sentir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '2', '1', 'Quando in terra venisti, si mosse');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '2', '2', 'Nella lode del ciel la legion;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '2', '3', 'Or in mezzo dei Tuoi senza posa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '2', '4', 'Sal l\'omaggio e l\'adorazion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '3', '1', 'Tu una gloria possiedi che niuna');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '3', '2', 'Mente umana potrà mai narrar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '3', '3', 'Pur Ti degni venire qual Uomo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '3', '4', 'Fra gli umani quaggiù a dimorar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '4', '1', 'Sei venuto da parte di Dio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '4', '2', 'Le Sue vie tutte per coronar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '4', '3', 'Primogenito, guidi una schiera');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '4', '4', 'In eterno le lodi a levar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '5', '1', 'Ti lodiam e adoriamo, vedendo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '5', '2', 'La Tua gloria che ovunque brillò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '5', '3', 'E l\'amore che, tutto donando,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('171', '5', '4', 'L\'universo per Dio assicurò.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('172', '11.10.11.10.', '52', '101');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('172', '1', '1', 'C\'INSEGNA le Tue vie benedette,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('172', '1', '2', 'O santo Agnel di Dio, Signor Gesù!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('172', '1', '3', 'Fa\' che in Tua grazia siamo radicati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('172', '1', '4', 'Poiché col sangue ci hai redenti Tu.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('172', '2', '1', 'Oh, parla a noi sovente del Tuo amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('172', '2', '2', 'Di tutte le Tue pene, il Tuo dolor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('172', '2', '3', 'Che ciò è la fonte d\'ogni nostro bene');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('172', '2', '4', 'Con gioia riconosca il nostro cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('172', '3', '1', 'Le cose prezïose della terra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('172', '3', '2', 'Non abbian per i Tuoi alcun valor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('172', '3', '3', 'Senza di Te, una perdita stimiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('172', '3', '4', 'L\'oggetto più gradito al nostro cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('172', '4', '1', 'Imprimi Tu, Signor, nei nostri cuori');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('172', '4', '2', 'Il benedetto marchio del Tuo amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('172', '4', '3', 'Così che noi possiamo maggiormente,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('172', '4', '4', 'Amandoti, risponder al Tuo cuor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('173', '11.10.11.10.', '52', '60');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('173', '1', '1', 'TU, Dio, dimori tra fragranti lodi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('173', '1', '2', 'Che frutto son dell\'opra Tua d\'amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('173', '1', '3', 'In Gesù Cristo l\'assemblea Tua');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('173', '1', '4', 'Riposo in Tua pienezza trova ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('173', '2', '1', 'Nel Tuo Diletto gode il Tuo favore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('173', '2', '2', 'La sposa che ora a Cristo appartien già;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('173', '2', '3', 'Nell\'amor Suo per lei Se stesso diede,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('173', '2', '4', 'Ella al Suo fianco in gloria apparirà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('173', '3', '1', 'Il giorno eterno è pieno di freschezza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('173', '3', '2', 'Di pace e gioia che non hanno fin,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('173', '3', '3', 'E ricche offerte, o Dio, Ti son recate');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('173', '3', '4', 'Di lode pel lavoro Tuo divin.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('174', '11.10.11.10.', '52', '28');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('174', '1', '1', 'O SALVATOR paziente, immacolato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('174', '1', '2', 'I nostri cuori guida in umiltà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('174', '1', '3', 'Si che il Tuo facil giogo noi portiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('174', '1', '4', 'Che il Tuo riposo di goder ci dà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('174', '2', '1', 'Gesù, la Tua Persona pienamente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('174', '2', '2', 'Può sodisfar la mente e il nostro cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('174', '2', '3', 'La Tua paziente vita ci dà calma');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('174', '2', '4', 'E l\'amor Tuo disperde ogni timor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('174', '3', '1', 'Fa\' che costantemente il nostro sguardo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('174', '3', '2', 'A Te rivolto sia, Gesù Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('174', '3', '3', 'Sì che, rapito dalla Tua bellezza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('174', '3', '4', 'Null\'altro possa attrarre il nostro cuor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('175', '11.11.11.11. Trocaico.', '64', '140');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('175', '1', '1', 'GLORIA, eterna gloria a Gesù rendiam!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('175', '1', '2', 'Della Sua vittoria il valor cantiam!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('175', '1', '3', 'Delle Sue dimore lo splendor lasciò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('175', '1', '4', 'Venne qui in amore, fino a morte andò!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('175', '2', '1', 'Si, dal cielo Ei scese, qui per noi morì,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('175', '2', '2', 'Per le nostro offese nel Suo amor soffrì;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('175', '2', '3', 'Umile e mansueto Egli trionfò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('175', '2', '4', 'Primo di tra i morti Ei risuscitò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('175', '3', '1', 'Cristo è il Re di gloria, lodi a Lui leviam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('175', '3', '2', 'Ridiciam la storia, il Suo favor cantiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('175', '3', '3', 'Mai non cessi il canto al Dominator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('175', '3', '4', 'Nel Suo Nome santo si trionfi ognor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('176', '9.8.9.8.9.8.9.8. Dattilico.', '125', '9998');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('176', '1', '1', 'SIGNOR, Tu che sempre Ti tieni');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('176', '1', '2', 'Davanti al Tuo Dio per i Tuoi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('176', '1', '3', 'Infino al momento in cui vieni');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('176', '1', '4', 'Soccorso opportuno ci dài.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('176', '1', '5', 'Tu ognor fedelmente ci ami,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('176', '1', '6', 'Il gran Sacerdote sei Tu;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('176', '1', '7', 'Tua man ci sostien nel sentiero');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('176', '1', '8', 'Che adduce alla gloria lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('176', '2', '1', 'Tu sei l\'Avvocato per noi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('176', '2', '2', 'Signor, finché siamo quaggiù;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('176', '2', '3', 'Giammai non dimentichi i Tuoi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('176', '2', '4', 'Ma a Te li conduci lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('176', '2', '5', 'Se infuria su noi 1\'uragano,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('176', '2', '6', 'A Te niun strappar ci potrà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('176', '2', '7', 'Per noi le Tue man sono alzate:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('176', '2', '8', 'Al ciel fiduciosi guardiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('177', '9.8.9.8.9.8.9.8. Giambico.', '137', '214');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '1', '1', 'NON vuoi venire al Salvatore?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '1', '2', 'Egli t\'attende in grazia ancor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '1', '3', 'Per liberare l\'alma tua');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '1', '4', 'Ed il tuo cuor colmar d\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '1', '5', 'Per espiare i tuoi peccati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '1', '6', 'Il Salvator, Gesù, morì');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '1', '7', 'Ed anche, per giustificarti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '1', '8', 'Glorioso dall\'avello uscì.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '2', '1', 'Or alla destra di Dio Padre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '2', '2', 'Signore e Cristo fatto Egli è,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '2', '3', 'Ei che compì la redenzione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '2', '4', 'E la Sua grazia or offre a te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '2', '5', 'Ogni bisogno Egli sodìsfa:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '2', '6', 'In Lui tu puoi ben confidar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '2', '7', 'Dalla Sua man ricever tutto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '2', '8', 'E nel Suo amore dimorar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '3', '1', 'Lo Spirto Santo Ei ti vuol dare,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '3', '2', 'Tuo cuor di gioia per colmar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '3', '3', 'Darti la forza per la vita');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '3', '4', 'E far la lode tua sgorgar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '3', '5', 'E quando in gloria giungerai,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '3', '6', 'Le gioie ch\' Egli già ti dà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '3', '7', 'Il ciel faranno risonare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('177', '3', '8', 'Di lode per l\'eternità.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('178', '11.10.11.10.', '52', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '1', '1', 'LA grazia Tua sovrana celebriamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '1', '2', 'O Padre, fonte d\'infinito amor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '1', '3', 'Da Te condotti, nostra mente alziamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '1', '4', 'All\'immortal riposo del Tuo cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '2', '1', 'Tu troverai fra quelli il Tuo riposo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '2', '2', 'Che in Te godranno per l\'eternita;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '2', '3', 'Là dov\'è tutto santo e glorïoso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '2', '4', 'Lodarti il lor servizio allor sarà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '3', '1', 'L\'eterno amor sarà la loro parte');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '3', '2', 'Dove l\'amor riposo troverà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '3', '3', 'Colma di Te, la mente lor costante');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '3', '4', 'E\' benedetta per l\'eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '4', '1', 'Al centro della radïosa sfera,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '4', '2', 'Supremo in gloria Cristo brillerà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '4', '3', 'Ogni redento della santa schiera');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '4', '4', 'Il Tuo fulgor in Lui spiccar vedrà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '5', '1', 'D\'amor i Tuoi consigli con potenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '5', '2', 'Compiuti nella chiesa Tua saran,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '5', '3', 'E le Tue glorie con magnificenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '5', '4', 'Per il creato intier si stenderan.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '6', '1', 'Un dolce impiego troverà nostr\'alma');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '6', '2', 'Nel celebrare là Tua lode ognor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '6', '3', 'Con gioia più profonda e pur più calma,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '6', '4', 'O Padre, gusterem l\'eterno amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '7', '1', 'E prima di quel giorno la dolcezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '7', '2', 'Quaggiù del Tuo riposo anticipiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '7', '3', 'L\'amor di Padre, nella Sua pienezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('178', '7', '4', 'Dal Figlio rivelato, conosciam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('179', '11.10.11.10.', '52', '117');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '1', '1', 'LODIAMO il Salvator per il Suo amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '1', '2', 'L\'amor per cui Ei prende i Suoi con Sé!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '1', '3', 'Questa parola basta al nostro cuore:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '1', '4', '"In paradiso oggi sarai con Me".');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '2', '1', 'Ascoltan le Sue pecore Sua voce,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '2', '2', 'Ei le conosce, la Sua scelta son.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '2', '3', 'Lodiamo Lui, di Dio diletto Figlio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '2', '4', 'Che sulla morte è stato vincitor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '3', '1', 'Quanto miglior dei beni della terra!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '3', '2', 'In vita o in morte, del Signor noi siam!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '3', '3', 'Ad onta dei disegni del nemico,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '3', '4', 'Resi viventi tutti in Lui saran.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '4', '1', 'E "Gesù pianse"! Quali sentimenti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '4', '2', 'Verso un oggetto del Suo amor sovran!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '4', '3', 'L\'amor di Dio, che supera ogni lode,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '4', '4', 'In Padre, Figlio e Spirto conosciam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '5', '1', 'Sì, Dio li condurrà, ed ogni orecchio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '5', '2', 'Signor, Tuo grido di raduno udrà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '5', '3', 'Si leveranno, e noi con lor saremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '5', '4', 'Rapiti, ognor con Te per dimorar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '6', '1', 'Preconosciuti siam, predestinati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '6', '2', 'Chiamati ad esser conformati a Te,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '6', '3', 'Giustificati e pur glorificati:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('179', '6', '4', 'Riuniti intorno a Te, Signor, sarem!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('180', '7.6.7.6.7.6.7.6.', '34', '197');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '1', '1', 'MENTRE qui, pellegrini,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '1', '2', 'Signor, la via tracciam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '1', '3', 'Ci dona gran letizia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '1', '4', 'Saper che Tuoi noi siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '1', '5', 'Pel sangue che spargesti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '1', '6', 'Facendo espïazion,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '1', '7', 'Per sempre siam i frutti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '1', '8', 'Della redenzïon.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '2', '1', 'L\'amor che ci ha redenti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '2', '2', 'Solo non può restar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '2', '3', 'Gli oggetti del Tuo cuore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '2', '4', 'Con Te dovranno star');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '2', '5', 'Godendo il Tuo riposo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '2', '6', 'Uniti per la fé');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '2', '7', 'A Te, divin Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '2', '8', 'Che ci hai condotti a Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '3', '1', 'Deh, muovi i nostri cuori,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '3', '2', 'Signore, a Te seguir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '3', '3', 'Dal pane Tuo nutriti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '3', '4', 'Forti per Te servir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '3', '5', 'Qui, dove Tu moristi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '3', '6', 'Fa\' che il cammin tracciam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '3', '7', 'Vincendo nel Tuo Nome,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('180', '3', '8', 'Finché con Te noi siam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('181', '11.10.11.10.11.10.11.10.', '183', '59');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '1', '1', 'A TE, Signor Gesù, gloria appartiene:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '1', '2', 'Per sempre benedetto, se\' il Figliol!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '1', '3', 'Grande è la gloria che Tu hai meritata,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '1', '4', 'La gloria che Tu ricevesti sol.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '1', '5', 'Grande è la gloria e grande lo splendore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '1', '6', 'Di quel celeste luogo di lassù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '1', '7', 'E della Deità la somma gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '1', '8', 'Brilla nel volto Tuo, Signor Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '2', '1', 'Signor di gloria, Tu quaggiù venisti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '2', '2', 'In quest\'oscuro mondo di dolor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '2', '3', 'E di Tua gloria furon testimoni');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '2', '4', 'I Tuoi che qui conobbero il Tuo cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '2', '5', 'Tu qui moristi ed ora Ti lodiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '2', '6', 'Nella Tua gloria, santo Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '2', '7', 'Poiché Tu nella morte hai dichiarato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '2', '8', 'Nella pienezza sua, di Dio l\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '3', '1', 'Si , Ti vediam di gloria coronato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '3', '2', 'Il cielo a Te l\'onore sommo dà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '3', '3', 'Pur è la gloria Tua che tutto eccede');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '3', '4', 'Che in esso brilla per l\'eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '3', '5', 'Che Tu più grande sei della Tua gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '3', '6', 'O Salvator, con gioia noi vediam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '3', '7', 'Grande "IO SONO", Ti benediciamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('181', '3', '8', 'Iddio possente, Eterno, e T\'adoriam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('182', '9.8.9.8.9.8.9.8. Giambico.', '137', '154');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '1', '1', 'I NOSTRI cuori a Te si chinan,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '1', '2', 'O Santo Spirto, e Ti lodiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '1', '3', 'Noi che da Cristo siam salvati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '1', '4', 'E che per Te Lo conosciam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '1', '5', 'Tu Ti diletti di venire,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '1', '6', 'In Tua mirabil umiltà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '1', '7', 'Nell\'alme nostre a dimorare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '1', '8', 'E Cristo ognor glorificar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '2', '1', 'Per il bisogno Tu provvedi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '2', '2', 'Tu ci conforti nel dolor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '2', '3', 'E per noi pure Tu intercedi:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '2', '4', 'Quant\'è prezioso il Tuo amor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '2', '5', 'Tu ci prepari fedelmente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '2', '6', 'In ciel, con Cristo, a dimorar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '2', '7', 'Fa\' che nessuna macchia in noi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '2', '8', 'Nascosta possa ancor restar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '3', '1', 'Fa\' che, con lampade lucenti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '3', '2', 'I santi possano gridar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '3', '3', '"Signore, vieni! " con ardore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '3', '4', 'Lo Sposo pronti ad incontrar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '3', '5', 'Allor la voce Sua udiremo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '3', '6', 'Il volto Suo allor vedrem');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '3', '7', 'E trasformati, sempre Teco,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('182', '3', '8', 'A casa in cielo giungerem.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('183', '11.10.11.10.', '52', '69');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('183', '1', '1', 'VIENI! L\'amor del Padre per te splende');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('183', '1', '2', 'E ricchi beni Ei vuol donare a te:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('183', '1', '3', 'Nel Suo profondo amor ti vuole offrire');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('183', '1', '4', 'Del ciel le dolci gioie, per la fé.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('183', '2', '1', 'Cristo, il Suo Figlio, venne qui a morire,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('183', '2', '2', 'In croce volle il sangue Suo versar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('183', '2', '3', 'Per toglier in eterno i tuoi peccati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('183', '2', '4', 'Sì che la pace possa tu trovar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('183', '3', '1', 'Lo Spirto Santo allora il cuore tuo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('183', '3', '2', 'Del sommo amor di Dio colmerà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('183', '3', '3', 'Al Suo desir s\'unisce il nostro cuore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('183', '3', '4', 'Che tu ne goda per 1\'eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('183', '4', '1', 'Non rifiutar il santo Suo messaggio;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('183', '4', '2', 'Egli ti chiama: vieni al Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('183', '4', '3', 'Tutte per te saranno allor le gioie');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('183', '4', '4', 'Che t\'empiranno di dolcezza il cuor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('184', '11.10.11.10.', '52', '159');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '1', '1', 'IL volto Tuo glorioso, mio Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '1', '2', 'Contemplo nella semplice mia fé');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '1', '3', 'Ed il divin, costante Tuo favore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '1', '4', 'Mi dà riposo e pace certa, in Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '2', '1', 'Ogni mia brama trova in Te risposta,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '2', '2', 'Ogni bisogno Tu puoi sodisfar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '2', '3', 'E la potenza Tua, Signore, basta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '2', '4', 'Ogni timor dell\'alma a dissipar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '3', '1', 'Signore, Tu sei tutto il mio conforto:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '3', '2', 'Ti desti, Salvatore, un dì per me;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '3', '3', 'In Te son ricco amore e somma grazia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '3', '4', 'Ogni benedizione trovo in Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '4', '1', 'Nel volto Tuo l\'eterna gloria splende,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '4', '2', 'Di pace sei la fonte pel mio cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '4', '3', 'Mi tieni nella gioia di Tua grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '4', '4', 'Finché vedrò il Tuo volto, Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '5', '1', 'Oh, quanto è grande l\'amor Tuo, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '5', '2', 'Più grande e più profondo d\'ogni mar!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '5', '3', 'Quanto gloriose le benedizioni');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '5', '4', 'Che nella grazia Tua mi vuoi donar!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '6', '1', 'Chi mai può misurar l\'amor prezioso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '6', '2', 'Che su di me Tu versi, Salvator?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '6', '3', 'E tutte le promesse son sicure');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('184', '6', '4', 'Ché sopra Te fondate son, Signor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('185', '9.8.9.8. Dattilico.', '112', '213');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('185', '1', '1', 'GLORIOSO, Possente, Maestoso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('185', '1', '2', 'Ai Tuoi Ti presenti, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('185', '1', '3', 'Risorto, di la dall\'avello,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('185', '1', '4', 'Noi qui T\'acclamiam Vincitor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('185', '2', '1', 'Eterno, Immortale, Supremo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('185', '2', '2', 'Sei l\'Alfa e l\'Omega, Signor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('185', '2', '3', 'Vedendoti nella Tua gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('185', '2', '4', 'T\'offriamo l\'omaggio d\'amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('186', '11.10.11.10.', '52', '91');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '1', '1', 'SIGNOR, le glorie della Tua Persona');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '1', '2', 'Nessuna mente umana può afferrar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '1', '3', 'Ma in forma d\'Uomo in terra Tu venisti:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '1', '4', 'Mai cesserem Tua lode di cantar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '2', '1', 'Scendesti in terra come Figlio, e il Padre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '2', '2', 'Amando, nel compire il Suo voler');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '2', '3', 'Trovasti ognor Tua gioia: Suo Diletto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '2', '4', 'Facesti tutto per il Suo piacer.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '3', '1', 'Nei piani eterni Tu con Lui sei Uno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '3', '2', 'Nei piani che ora contempliam per fé,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '3', '3', 'D\'aver in Tuo possesso interamente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '3', '4', 'Uomini resi somiglianti a Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '4', '1', 'Legati insieme in santa comunione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '4', '2', 'Or all\'amore Tuo rispondiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '4', '3', 'I nostri cuor uniti Tu mantieni');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '4', '4', 'Sì che, gioiosi, intorno a Te veniam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '5', '1', 'Felici nel prezioso Tuo favore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '5', '2', 'La nostra lode, grati, T\'apportiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '5', '3', 'E, dallo Spirto Santo sostenuti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('186', '5', '4', 'Della Tua somma gloria noi cantiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('187', '8.7.8.7.8.6.8.6. Giambico.', '146', '98');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '1', '1', 'OH, quale Amico è il Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '1', '2', 'Il mio divin Signore!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '1', '3', 'Pria ancor che a Lui volgessi il cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '1', '4', 'M\'amò d\'immenso amore.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '1', '5', 'Legato a Lui, questo mio cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '1', '6', 'Niun mai Gli strapperà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '1', '7', 'Io per Lui son ed Ei per me');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '1', '8', 'Per tutta eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '2', '1', 'Oh, quale Amico è il Salvator!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '2', '2', 'Moriva per salvarmi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '2', '3', 'E non soltanto vita e amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '2', '4', 'Ma Sé pur volle darmi.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '2', '5', 'Di quanto in terra Ei mi donò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '2', '6', 'Più nulla mio sarà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '2', '7', 'Con gioia tutto a Lui ridò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '2', '8', 'Per tutta eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '3', '1', 'Oh, quale Amico è il Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '3', '2', 'Costante e pien d\'amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '3', '3', 'Sicura Guida e Consiglier,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '3', '4', 'Potente Difensore.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '3', '5', 'O vita o morte, o terra o avel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '3', '6', 'Nixm mi separerà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '3', '7', 'Da Lui che resta ognor fedel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('187', '3', '8', 'Per tutta eternità.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('188', '10.9.10.9.', '114', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '1', '1', 'TE, Signore di gloria, vediamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '1', '2', 'Discendente dall\'alto splendor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '1', '3', 'E, commossi, apprendiamo la storia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '1', '4', 'Come Dio venne qui nel Suo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '2', '1', 'Fu Tua culla un umìle presepe:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '2', '2', 'Senza casa né tetto, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '2', '3', 'Tu passasti qui in terra, straniero,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '2', '4', 'Per gustar ogni nostro dolor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '3', '1', 'Strano, invero, e pur atto principio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '3', '2', 'A Tua vita quaggiù di dolor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '3', '3', 'Mentre in grazia Tu all\'uomo facevi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '3', '4', 'Del suo Dio conoscer il cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '4', '1', 'Il Tuo amore sorpassa ogni cosa:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '4', '2', 'Ti degnasti quaggiù di venir');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '4', '3', 'Non passando in trionfo né in gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '4', '4', 'Ma d\'un bimbo la forma a vestir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '5', '1', 'Noi la Tua debolezza ammiriamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '5', '2', 'Nel presepe, la croce e l\'avel;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '5', '3', 'Umilmente la via Tu tracciasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '5', '4', 'E moristi quaggiù, Santo Agnel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '6', '1', 'Pur traverso l\'umano Tuo velo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '6', '2', 'La divina Tua gloria brillar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '6', '3', 'Noi vediam, apprendendo l\'amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('188', '6', '4', 'Che Ti fece venire a sanar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('189', '10.9.10.9.', '114', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '1', '1', 'O SIGNORE, in un mondo corrotto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '1', '2', 'Dove l\'odio e l\'invidia abbondò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '1', '3', 'La Tua vita devota e perfetta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '1', '4', 'D\'una luce divina brillò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '2', '1', 'Tu con grazia paziente affrontasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '2', '2', 'Ogni insulto, l\'obbrobrio e il dolor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '2', '3', 'Non dell\'uomo potè la malizia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '2', '4', 'Da Tua via stornarti, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '3', '1', 'Più di tutto la grazia divina');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '3', '2', 'Nei Tuoi passi d\'amore brillò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '3', '3', 'Ogni cuor di tristezza abbattuto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '3', '4', 'Nel cuor Tuo riposo trovò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '4', '1', 'L\'uomo forte ed armato incontrasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '4', '2', 'In Tua grazia perfetta, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '4', '3', 'E vittoria ad ognor riportasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '4', '4', 'Sul Maligno, dell\'uom tentator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '5', '1', 'Alla Tua parola ogni male,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '5', '2', 'Il demonio e la morte fuggîr,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '5', '3', 'Come quando, al ritorno del sole,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '5', '4', 'Ogni tenebra deve sparir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '6', '1', 'Fosti in terra Tu l\'Uom dei dolori');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '6', '2', 'Perché pieno era il cuor Tuo d\'amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '6', '3', 'E in risposta a Tua grazia divina');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '6', '4', 'Ricevesti il disprezzo dell\'uom.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '7', '1', 'O Signor, del Tuo amor la fragranza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '7', '2', 'In ogni atto Tuo santo esalò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '7', '3', 'Ed all\'uom bisognoso la grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('189', '7', '4', 'E il favore di Dio mostrò.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('190', '12.13.12.10.', '48', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '1', '1', 'E\' MERAVIGLIOSA, O Signor, Tua storia!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '1', '2', 'L\'alme nostre muove nella lor intimità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '1', '3', 'Mentre qui il cammino del Tuo amor, che in gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '1', '4', 'Finì, possiamo contemplare già.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '2', '1', 'Non a Te uno sguardo di pietà fu volto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '2', '2', 'Nessun cuor poteva sopportare il Tuo dolor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '2', '3', 'Solo il vituperio, onta e sputi in volto:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '2', '4', 'Nessun cercava il Nome Tuo d\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '3', '1', 'Di tristezza grande fu quel giorno pieno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '3', '2', 'Giorno d\'insondabil duolo, quando Tu, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '3', '3', 'Senza alcun sollievo, conoscesti appieno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '3', '4', 'D\'inesorabil collera l\'orror.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '4', '1', 'Fosti benedetto Uomo dei dolori,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '4', '2', 'Nei languori esperto-sì, la perfezion d\'amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '4', '3', 'Che guidò i Tuoi passi, tocca i nostri cuori:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '4', '4', 'Fino alla morte li condusse allor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '5', '1', 'Pure nella morte, umile, al volere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '5', '2', 'Del Tuo Dio e Padre obbediente fosti Tu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '5', '3', 'Del Tuo amor mostrasti là tutto il potere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '5', '4', 'Vincendo ogni male di quaggiù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '6', '1', 'Un divin Straniero fosti nell\'estremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '6', '2', 'Male umano, ma il Tuo amore fino in fondo andò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '6', '3', 'No, non può narrare l\'uom il Tuo supremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '6', '4', 'Amore, che nel duolo Ti portò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '7', '1', 'Quando il solitario Tuo sentier di pena');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '7', '2', 'Noi qui contempliam, Signore, grati T\'adoriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '7', '3', 'Tu che sopportasti per noi l\'ira piena,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '7', '4', 'Presto al Tuo fianco d\'esser noi bramiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '8', '1', 'Vieni dunque, atteso nostro Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '8', '2', 'Uomo di dolori, vieni! O Signor Gesù:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '8', '3', 'Tu, l\'Onnipotente, il Liberatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('190', '8', '4', 'Nella Tua casa prendici lassù.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('191', '11.10.11.10.', '52', '106');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('191', '1', '1', 'O PADRE, Lodi a Te di cuor rendiamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('191', '1', '2', 'Nel Tuo favore, liberi, viviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('191', '1', '3', 'Lieti godiamo del Tuo santo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('191', '1', '4', 'E della luce che dal cielo abbiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('191', '2', '1', 'A Te, Signor, rendiam la nostra lode,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('191', '2', '2', 'Cristo, Profeta, Sacerdote, Re;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('191', '2', '3', 'Un giubilante canto or inalziamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('191', '2', '4', 'Di lode, Agnello che moristi, a Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('191', '3', '1', 'O Santo Spirto, a Te, che a Pentecoste');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('191', '3', '2', 'Mandato fosti in terra, lode diam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('191', '3', '3', 'Mediante Te la vita conosciamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('191', '3', '4', 'Per mezzo Tuo le lodi noi rendiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('191', '4', '1', 'Quant\'è felice inver la nostra parte');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('191', '4', '2', 'In Te, Dio benedetto, d\'esultar!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('191', '4', '3', 'Le voci di figlioli, a Te elevate,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('191', '4', '4', 'Al cuore Tuo diletto posson dar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('192', '10.10.10.9.10.9.', '171', '137');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('192', '1', '1', 'TE, Signore, vogliam ricordare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('192', '1', '2', 'Ché per noi sulla croce Ti desti.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('192', '1', '3', 'Tu, morendo, la morte vincesti:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('192', '1', '4', 'A Te grati, Signore, noi siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('192', '1', '5', 'Col cuor pieno di santo fervore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('192', '1', '6', 'La Tua gloria vedere bramiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('192', '2', '1', 'La Tua morte i cuor nostri costringe');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('192', '2', '2', 'A lasciare le cose terrene;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('192', '2', '3', 'Dove l\'uomo la croce Ti diede');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('192', '2', '4', 'Nulla più che ci attiri non v\'è.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('192', '2', '5', 'La Tua assenza, Signore, sentiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('192', '2', '6', 'Nostra méta è trovarci con Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('192', '3', '1', 'Vane sono le offerte del mondo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('192', '3', '2', 'Mentre Te noi dal cielo attendiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('192', '3', '3', 'La Tua morte qui uniti annunciamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('192', '3', '4', 'Rispondendo, Signore, al Tuo cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('192', '3', '5', 'Sempre a Te vogliam esser fedeli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('192', '3', '6', 'Nella forza del santo Tuo amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('193', '11.10.11.10.', '52', '167');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('193', '1', '1', 'SIGNOR Gesù, Tu trovi in noi diletto:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('193', '1', '2', 'Fonte di gioia è questo ai nostri cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('193', '1', '3', 'Resi preziosi e santi al Tuo cospetto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('193', '1', '4', 'Per grazia Tuoi fratelli siam, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('193', '2', '1', 'L\'amor Tuo santo toglie ogni distanza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('193', '2', '2', 'I nostri cuori avvince sempre a Te;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('193', '2', '3', 'E per lo Spirto Tuo, con esultanza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('193', '2', '4', 'Godiam l\'amor che libertà ci diè.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('193', '3', '1', 'Del Padre primogenito Figliolo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('193', '3', '2', 'Noi, Tuoi fratelli, Ti riconosciam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('193', '3', '3', 'Un tal supremo onor è per Te solo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('193', '3', '4', 'Con gioia noi la gloria Tua vediam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('193', '4', '1', 'Ai nostri cuori sommo sei, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('193', '4', '2', 'Uniti a Te dinanzi ci prostriam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('193', '4', '3', 'Presi di Tua bellezza dal fulgore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('193', '4', '4', 'Con cuori a Te devoti T\'adoriam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('194', '11.11.11.11.(b)', '192', '196');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '1', '1', 'LA notte s\'avanza, il giorno è vicin,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '1', '2', 'E\' sorta la Stella che annuncia il mattin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '1', '3', 'O santi, levate con giubilo il cuor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '1', '4', 'Vicino è il ritorno del nostro Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '2', '1', 'Qual giorno gioioso pei santi sarà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '2', '2', 'Allor che in trionfo Gesù tornerà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '2', '3', 'Se in terra la croce ci è dato portar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '2', '4', 'Un serto immortale nel ciel ci vuol dar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '3', '1', 'Del mondo il disprezzo ben poco parrà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '3', '2', 'Di fronte alla gloria che allora sarà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '3', '3', 'Colui che attendiamo con fervido cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '3', '4', 'Allora vedremo, Gesù, il Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '4', '1', 'Tu sei nostro Sol, nostro Scudo, Signor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '4', '2', 'Di santo desir Tu ricolmaci il cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '4', '3', 'Sì come il \'l‘uo popol d\'un tempo, che fu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '4', '4', 'Fedel in pazienza ed amore quaggiù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '5', '1', 'Oh, dacci di vivere, mentre quaggiù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '5', '2', 'Con cuori anelanti, Signore Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '5', '3', 'Gustando il Tuo amore pur mentre attendiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('194', '5', '4', 'Finché nella gloria il Tuo volto vediam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('195', '11.10.11.10.', '52', '139');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('195', '1', '1', 'SIGNOR, sei degno d\'ogni lode e omaggio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('195', '1', '2', 'Degno Tu sei d\'adorazione e onor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('195', '1', '3', 'A Te s\'eleva ognor del ciel la lode:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('195', '1', '4', 'Eternamente degno sei, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('195', '2', '1', 'A Te noi pur leviamo il nostro canto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('195', '2', '2', 'Debole benché sia, noi lo sentiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('195', '2', '3', 'Con mortal lingue mai le glorie Tue');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('195', '2', '4', 'Sì vaste noi descriver non possiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('195', '3', '1', 'Ma presto avrai, Signore, piena lode:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('195', '3', '2', 'Allor che nelle nubi Ti vedrem');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('195', '3', '3', 'Eternamente noi con Te saremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('195', '3', '4', 'E degnamente allor Ti loderem.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('196', '10.9.10.9.', '114', '15');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '1', '1', 'TUTTO è pronto - venite alla cena:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '1', '2', 'Dio v\'invita con grazia ed amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '1', '3', 'Ricchi e poveri, giovani e vecchi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '1', '4', 'A gustare il divino favor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '2', '1', 'Tutto è pronto - venite alla cena:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '2', '2', 'Là v\'invita il Signore Gesù-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '2', '3', 'Ei sofferse pei vostri peccati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '2', '4', 'Nella gloria ora siede lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '3', '1', 'Tutto è pronto - venite alla cena:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '3', '2', 'Mentre aperta la porta ora sta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '3', '3', 'E chi viene, per quanto reietto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '3', '4', 'Dell\'amore di Diogodrà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '4', '1', 'Tutto è pronto - venite alla cena:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '4', '2', 'Nulla possa impedirvi mai più,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '4', '3', 'Dio vi offre l\'amor Suo prezioso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '4', '4', 'Pienamente provato in Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '5', '1', 'Tutto è pronto-venite alla cena,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '5', '2', 'Ascoltate l\'invito d\'amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '5', '3', 'Non contate su un vano domani.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('196', '5', '4', 'Oggi stesso venite al Signor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('197', '11.10.11.10.', '52', '50');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('197', '1', '1', 'SIGNOR che sei, che fosti e che sarai,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('197', '1', '2', 'A Te, IO SONO, lode sia ed onor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('197', '1', '3', 'Alfa ed Omega, vivi e ognor vivrai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('197', '1', '4', 'Al di là della morte e del dolor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('197', '2', '1', 'Ed ora in mezzo alle assemblee Tu vieni:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('197', '2', '2', 'La loro fé ricordi, il loro amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('197', '2', '3', 'Con forte voce parli e noi T\'udiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('197', '2', '4', 'Ed ai Tuoi piè cadiam, Gesù Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('197', '3', '1', 'Tu stai diritto in mezzo ai candelieri');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('197', '3', '2', 'Ed il Tuo sguardo scruta ogni pensier,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('197', '3', '3', 'La voce Tua, come di molte acque,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('197', '3', '4', 'Parla ed i suoni umani fa tacer.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('197', '4', '1', 'Le Tue promesse per colui che vince,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('197', '4', '2', 'C\'incitan pur, Signore, a Te servir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('197', '4', '3', 'Il Nome Tuo quaggiù non rinnegando');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('197', '4', '4', 'Finché verrai i Tuoi a Te rapir.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('198', '9.8.9.8.9.8.9.8. Dattilico.', '125', '124');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '1', '1', 'DAVANTI a Te siam radunati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '1', '2', 'Signore, ed uniti di cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '1', '3', 'Vogliamo i Tuoi santi interessi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '1', '4', 'Curare con fede ed amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '1', '5', 'Oh, vieni! Il Tuo aiuto chiediamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '1', '6', 'Signor, la Tua guida ci da\'');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '1', '7', 'Sì che, dallo Spirto diretti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '1', '8', 'Possiam la Tua mente afferrar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '2', '1', 'Le tenebre intorno sentiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '2', '2', 'E freddo è dei molti l\'amor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '2', '3', 'C\'illumini ancora la luce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '2', '4', 'Di Tua verità, O Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '2', '5', 'Tu nell\'assemblea confidi-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '2', '6', 'Sì puro è di moglie il suo amor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '2', '7', 'Possiam noi restare fedeli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '2', '8', 'Se pur qui soffriamo, Signor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '3', '1', 'Signore, il poter di discerner');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '3', '2', 'Fra tenebre e luce ci da\'');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '3', '3', 'E che, pel Tuo Nome gelosi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '3', '4', 'Possiam ciò ch\'è falso oppugnar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '3', '5', 'Fa\' che, mentre Tu sei assente,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '3', '6', 'Possiam le Tue cose curar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '3', '7', 'Finché, nel Tuo giorno vicino,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('198', '3', '8', 'Con Te Tu ci chiami a regnar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('199', '11.11.11.11.(c)', '193', '30');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '1', '1', 'SIGNOR Gesù, vivente nostro Capo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '1', '2', 'Oh, quanto la Tua gloria è risplendente!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '1', '3', 'Unico sei nell\'umanità Tua');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '1', '4', 'E pure sei divino eternamente.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '2', '1', 'Tu esistevi prima d\'ogni cosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '2', '2', 'Creata, e Tu di tutte sei l\'Autore;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '2', '3', 'Con riverenza a Te noi c\'inchiniamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '2', '4', 'Dell\'universo sei Sostenitore.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '3', '1', 'Neppur la più sublime mente umana');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '3', '2', 'Comprender può, Signore, la Tua Essenza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '3', '3', 'Ma pur noi ci prostriamo a Te, Sovrano,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '3', '4', 'Ripieni di gioiosa riverenza.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '4', '1', 'Nel glorïoso stato della Tua');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '4', '2', 'Umanità gioisce il nostro cuore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '4', '3', 'Perché del corpo Tuo, Signor, noi siamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '4', '4', 'La scelta eterna del divino amore.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '5', '1', 'Tu sei sorgente di sapienza, forza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '5', '2', 'E cibo; Tu ci dài ricchezze grandi:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '5', '3', 'Sulla Tua chiesa, ch\'è quaggiù il Tuo corpo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '5', '4', 'I Tuoi tesori largamente spandi.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '6', '1', 'Cosi a Te, glorioso nostro Capo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '6', '2', 'L\'adorazione nostra tributiamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '6', '3', 'Sorretti dallo Spirto, or in celesti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('199', '6', '4', 'Misure, a Te vicini, noi cantiamo.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('200', '9.8.9.8. Giambico.', '161', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '1', '1', 'GESU\', prezioso Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '1', '2', 'Il Tuo ritorno noi bramiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '1', '3', 'Con cuori che il dolor conoscon,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '1', '4', 'A Te, Sovrano, ci volgiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '2', '1', 'Il nostro duolo su Te prendi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '2', '2', 'E nel Tuo amor ci fai gioir:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '2', '3', 'Usi il dolor, come la gioia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '2', '4', 'I nostri cuori a Te a rapir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '3', '1', 'A Te guardiamo, Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '3', '2', 'Il cui amore conosciam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '3', '3', 'E d\'esser liberi dal male,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '3', '4', 'Peccato e schiavitù, bramiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '4', '1', 'In Tua presenza tutto il male');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '4', '2', 'Pur dalla terra svanirà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '4', '3', 'E liberal benedizione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '4', '4', 'Sul Tuo creato scenderà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '5', '1', 'Ma quanto meglio d\'ogni bene');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '5', '2', 'Che sulla terra aver possiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '5', '3', 'Sarà il trovarci Teco sempre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '5', '4', 'Lungi dal mal che qui soffriam!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '6', '1', 'Allora, senza velo o nubi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '6', '2', 'La faccia Tua, Signor, vedrem,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '6', '3', 'Ed il Tuo amore e la Tua grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '6', '4', 'Più pienamente gusterem.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '7', '1', 'Con Te di gioia sempre piena');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '7', '2', 'L\'anima nostra allor sarà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '7', '3', 'Quando nessun pensier terreno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '7', '4', 'Da Te divider ci potrà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '8', '1', 'Gioiosi, nel favor perfetto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '8', '2', 'Del Padre Tuo dimorerem');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '8', '3', 'E di Sua gloria lo splendore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '8', '4', 'In Te riflesso, mirerem.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '9', '1', 'Si, vieni presto, Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '9', '2', 'Noi con pazienza T\'attendiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '9', '3', 'E di trovarci con Te assisi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('200', '9', '4', 'Per sempre in libertà, bramiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('201', '6.6.8.6.', '106', '18');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('201', '1', '1', 'SIGNOR santo e fedel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('201', '1', '2', 'In Te noi confidiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('201', '1', '3', 'E qui, nel cerchio del Tuo amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('201', '1', '4', 'Fratelli, dimoriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('201', '2', '1', 'Del Padre santo il cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('201', '2', '2', 'Riposo trova in Te');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('201', '2', '3', 'E noi la gioia del Suo amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('201', '2', '4', 'Condividiam per fé.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('201', '3', '1', 'Per grazia Tua noi siam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('201', '3', '2', 'Fratelli Tuoi, Signor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('201', '3', '3', 'Qual primo Ti riconosciam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('201', '3', '4', 'E a Te diam lode e onor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('201', '4', '1', 'Fa\' che fedeli siam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('201', '4', '2', 'Al Nome Tuo, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('201', '4', '3', 'Che dal peccato rifuggiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('201', '4', '4', 'E d\'ogni mal, ognor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('202', '11.10.11.10.9.11.', '67', '83');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('202', '1', '1', 'UDITE! In grazia parla il Salvatore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('202', '1', '2', 'Sul trono assiso del Suo Padre in ciel;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('202', '1', '3', 'Offre il perdono ed il divin favore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('202', '1', '4', 'A ognun che crede in Lui, il santo Agnel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('202', '1', '5', 'Gesù ancor parla, parla in amor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('202', '1', '6', 'Egli offre gioia e pace al peccator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('202', '2', '1', 'Ci parla in grazia della salvazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('202', '2', '2', 'Che sulla croce Ei, solo, completò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('202', '2', '3', 'Si che da ogni lingua, ogni nazione,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('202', '2', '4', 'Un popol di redenti Si acquistò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('202', '2', '5', 'Gesù ancor parla, parla in amor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('202', '2', '6', 'Egli offre gioia e pace al peccator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('202', '3', '1', 'Presto il Suo dolce appello può cessare,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('202', '3', '2', 'Il dì di grazia tosto può finir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('202', '3', '3', 'L\'amore Suo profondo non sprezzare:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('202', '3', '4', 'Ei lo provò venendo qui a morir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('202', '3', '5', 'Gesù ancor parla, parla in amor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('202', '3', '6', 'Egli offre gioia e pace al peccator.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('203', '11.10.11.10.', '52', '16');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('203', '1', '1', 'AL Nome Tuo, Signor, siam radunati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('203', '1', '2', 'In mezzo al mondo che Ti rigettò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('203', '1', '3', 'Le Tue parole amiamo ricordare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('203', '1', '4', 'Ed il Tuo amor che a morte Ti portò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('203', '2', '1', 'In questi emblemi che noi contempliamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('203', '2', '2', 'Vediam la prova del Tuo santo amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('203', '2', '3', 'Che tutto diè, Signor, per acquistarci');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('203', '2', '4', 'E a Te ci dedichiam con grato cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('203', '3', '1', 'Ed or insiem leviam d\'amore un canto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('203', '3', '2', 'Rendendo con letizia lode a Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('203', '3', '3', 'I nostri cuori in Te son giubilanti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('203', '3', '4', 'Per il Tuo amor che libertà ci diè.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('204', '8.7.8.7.', '24', '39');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('204', '1', '1', 'OR chinati in Tua presenza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('204', '1', '2', 'O Signore, T\'adoriam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('204', '1', '3', 'Consci della Tua grandezza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('204', '1', '4', 'A Te l\'animo eleviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('204', '2', '1', 'Di Dio Figlio glorïoso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('204', '2', '2', 'Della morte Vincitor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('204', '2', '3', 'Il Tuo amor, la Tua potenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('204', '2', '4', 'Noi vediam nel Tuo splendor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('204', '3', '1', 'La Persona Tua divina');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('204', '3', '2', 'Piena è ognor di maestà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('204', '3', '3', 'Tu sei Capo d\'ogni cosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('204', '3', '4', 'Ora e per l\'eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('204', '4', '1', 'A Te un cantico eleviamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('204', '4', '2', 'In offerta pel Tuo cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('204', '4', '3', 'Te lodando T\'apportiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('204', '4', '4', 'La risposta dell \'amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('205', '9.8.9.8. Giambico.', '161', '9999');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('205', '1', '1', 'DAI nostri falli per salvarci,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('205', '1', '2', 'Agnel di Dio, Signor Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('205', '1', '3', 'L\'amaro calice gustasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('205', '1', '4', 'Di morte sulla croce Tu!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('205', '2', '1', 'Pietoso Sommo Sacerdote,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('205', '2', '2', 'Pastore, Amico, Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('205', '2', '3', 'Fino alla fine confidiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('205', '2', '4', 'Nel Tuo fedel, profondo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('205', '3', '1', 'L\'anime nostre Tu sostieni,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('205', '3', '2', 'Da Te la forza riceviam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('205', '3', '3', 'Sei nostra Guida, finché in gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('205', '3', '4', 'Il volto Tuo, Signor, vediam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('206', '11.10.11.10.', '52', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '1', '1', 'LA\' dove i santi in gloria radunati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '1', '2', 'Dell\'Albero di vita il frutto avran,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '1', '3', 'Con Te, Signor, i lor desir profondi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '1', '4', 'Appieno sodisfatti allor saran.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '2', '1', 'In sicurtà, lontani dal nemico,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '2', '2', 'Riposo avran, che nulla turberà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '2', '3', 'Gioia non interrotta dal dolore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '2', '4', 'Pace, ove lotta mai più non sarà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '3', '1', 'Dove non entra mai l\'ingannatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '3', '2', 'Non giungon mai contaminati piè,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '3', '3', 'In pace e libertà potremo entrare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '3', '4', 'Di Dio nel paradiso, là, con Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '4', '1', 'Potremo bere del perenne fiume');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '4', '2', 'Ed il perenne cibo gusterem,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '4', '3', 'Cristo, di vita frutto e Donatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '4', '4', 'Da Lui redenti, tutto in Lui godrem.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '5', '1', 'Signor di gloria, oggetto del piacere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '5', '2', 'Eterno sei: perfetto è il Tuo lavor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '5', '3', 'Senza misura a Te vogliam recare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('206', '5', '4', 'Adorazione, lode, omaggio, onor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('207', '14.14.14.14.', '85', '143');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('207', '1', '1', 'DIO benedetto e Padre nostro, a Te noi rispondiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('207', '1', '2', 'E in Tua presenza, figli con Gesù, possiam entrar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('207', '1', '3', 'Nell\'amor Tuo perfetto ed in santa libertà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('207', '1', '4', 'E gloria che nessuna nube mai potrà offuscar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('207', '2', '1', 'Gesù ci ha rivelato che Tu nostro Padre sei');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('207', '2', '2', 'E pure Padre Suo, eterno oggetto del Suo cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('207', '2', '3', 'In Lui trovasti tutto l\'infinito Tuo piacer;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('207', '2', '4', 'Ei diè Se stesso per compire il piano Tuo d\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('207', '3', '1', 'Ei tutti ci ha narrati i segreti del Tuo cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('207', '3', '2', 'E i piani che in eterno Tu volesti preparar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('207', '3', '3', 'Nei nostri cuori per lo Spirto rivelati son');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('207', '3', '4', 'E l\'alme nostre son sospinte, O Dio, ad adorar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('207', '4', '1', 'In questo cerchio di divini affetti noi posiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('207', '4', '2', 'Dove il Tuo amore splende d\'una gloria senza par');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('207', '4', '3', 'E già le gioie eterne, già la pace e libertà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('207', '4', '4', 'Che Tu ci hai preparate noi possiamo pregustar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('208', '11.10.11.10.', '52', '100');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('208', '1', '1', 'VENITE, voi che siete affaticati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('208', '1', '2', 'Il Salvator v\'invita a riposar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('208', '1', '3', 'Egli v\'attende con amor e grazia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('208', '1', '4', 'Perché volete ancora dubitar?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('208', '2', '1', 'Se la coscienza vostra vi condanna,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('208', '2', '2', 'Egli la può appien purificar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('208', '2', '3', 'Se stesso ha dato in grazia per salvarvi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('208', '2', '4', 'Nulla riman che voi possiate far.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('208', '3', '1', 'Basta che vi sentiate bisognosi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('208', '3', '2', 'E che veniate a Lui con umil cuor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('208', '3', '3', 'Mai non potrete meritar la grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('208', '3', '4', 'Che senza prezzo v\'offre il Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('208', '4', '1', 'Egli non venne per chiamare i giusti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('208', '4', '2', 'Ma quei che sanno d\'esser peccator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('208', '4', '3', 'Venite a Lui, voi stanchi, affaticati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('208', '4', '4', 'Venite senza indugio al Salvator.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('209', '11.10.11.10.', '52', '143');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('209', '1', '1', 'TU sol, Signor, Tu sol sai risvegliare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('209', '1', '2', 'Affetti intensi e lode in ogni cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('209', '1', '3', 'E gaudio infonde all\'anima il Tuo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('209', '1', '4', 'Che dalla morte è uscito vincitor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('209', '2', '1', 'Da quel prezioso amor, Signor, toccati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('209', '2', '2', 'Canti di lode grati a Te leviam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('209', '2', '3', 'Riconoscenti d\'esser Tuoi, T\'amiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('209', '2', '4', 'E, dallo Spirto mossi, T\'adoriam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('210', '10.10.10.9.(b)', '169', '207');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '1', '1', 'I NOSTRI giorni son in Tua mano,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '1', '2', 'Né mai vorremmo saperli altrove.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '1', '3', 'La vita e l\'alma, no, non invano');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '1', '4', 'Alle Tue cure, Padre, lasciam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '2', '1', 'I nostri giorni son in Tua mano');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '2', '2', 'Sian essi lieti oppur penosi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '2', '3', '(Importa poco - il lor arcano)');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '2', '4', 'Siccome meglio Ti piacerà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '3', '1', 'I nostri giorni son in Tua mano:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '3', '2', 'Perché temere - o dubitare?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '3', '3', 'D\'un Padre pieno d\'amor, la mano');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '3', '4', 'Al figlio inutil pena non dà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '4', '1', 'I nostri giorni son in Tua mano:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '4', '2', 'Gesù, morente un giorno in croce,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '4', '3', 'Ora conduce, Pastor sovrano,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '4', '4', 'Con pace e gioia - i Tuoi a Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '5', '1', 'I nostri giorni son in Tua mano:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '5', '2', 'Ei l\'Avvocato per noi rimane;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '5', '3', 'Dal divo amore nessun estrano');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '5', '4', 'Mai separarci, no, non potrà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '6', '1', 'I nostri giorni son in Tua mano:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '6', '2', 'In Te fidare ognor vogliamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '6', '3', 'Finché, lasciato - i1 mondo vano,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('210', '6', '4', 'Gesù in gloria contemplerem.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('211', '8.7.8.7.8.7.8.7.', '25', '67');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '1', '1', 'DIO e Padre, noi, Tuoi figli,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '1', '2', 'Ora qui raccolti siam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '1', '3', 'A studiar la Tua parola');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '1', '4', 'E l\'aiuto Tuo chiediam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '1', '5', 'Fa\' che siam devoti, attenti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '1', '6', 'Senza alcuna distrazion,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '1', '7', 'Contemplando i Tuoi consigli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '1', '8', 'E la Tua rivelazion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '2', '1', 'Dallo Spirto Tuo guidati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '2', '2', 'L\'alte glorie noi vediam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '2', '3', 'Cristo in cielo alla Tua destra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '2', '4', 'Per la fede contempliam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '2', '5', 'Come Uomo sulla terra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '2', '6', 'Compì il santo Tuo voler,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '2', '7', 'Ora in cielo a Te conduce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '2', '8', 'Figli per il Tuo piacer.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '3', '1', 'Nel vederlo coronato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '3', '2', 'Ei, l\'oggetto del Tuo amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '3', '3', 'Ogni cosa è a Lui soggetta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '3', '4', 'E soggetto è il nostro cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '3', '5', 'Già del mondo lo splendore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '3', '6', 'In presenza Sua scompar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '3', '7', 'Nella gloria Sua rapiti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '3', '8', 'Nulla qui ci può più attrar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '4', '1', 'Dio e Padre, T\'adoriamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '4', '2', 'E con gioia Ti lodiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '4', '3', 'In trionfo Tu ci guidi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '4', '4', 'E il Tuo amore conosciam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '4', '5', 'Fa\' che i santi Tuoi consigli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '4', '6', 'Meglio dì per dì apprendiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '4', '7', 'Finché, in cielo, di Tua grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('211', '4', '8', 'L\'opra intera contempliam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('212', '8.7.8.7.8.7.8.7.7.7.', '68', '180');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '1', '1', 'OH! l\'immenso amor di Dio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '1', '2', 'Senza inizio e senza fin!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '1', '3', 'Non ha dubbi né timore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '1', '4', 'Chi gustò l\'amor divin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '1', '5', 'Fonte d\'ogni puro bene,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '1', '6', 'Quell\'amor su me posò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '1', '7', 'E per me diè il santo Agnello');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '1', '8', 'Che sul Golgota spirò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '1', '9', 'Gesù l\'ha rivelato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '1', '10', 'Quel divino, immenso amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '2', '1', 'Meraviglia della croce!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '2', '2', 'Là, fra tenebre e dolor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '2', '3', 'Viene al cuore rivelato:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '2', '4', 'Dio è luce, Dio è amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '2', '5', 'Sodisfatta la giustizia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '2', '6', 'Or si svela il divin cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '2', '7', 'Dio Si volge verso l\'uomo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '2', '8', 'Pien di grazia e pien d\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '2', '9', 'Gesù pei miei peccati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '2', '10', 'Nelle tenebre soffrì.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '3', '1', 'Or nel ciel, glorificato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '3', '2', 'Coronato d\'ogni onor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '3', '3', 'Vediam Quei che un dì sofferse:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '3', '4', 'Il divino Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '3', '5', 'Alla destra di Dio Padre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '3', '6', 'Or sta l\'Uom che un giorno fu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '3', '7', 'Flagellato e crocifisso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '3', '8', 'Il divin Signor Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '3', '9', 'A Lui sia lode e gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('212', '3', '10', 'Che morendo ci salvò.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('213', '11.10.11.10.', '52', '97');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '1', '1', 'AL ciel leviam desiderosi gli occhi:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '1', '2', 'Presto di gloria il Sole sorgerà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '1', '3', 'Presto il Signor Gesù verrà dal cielo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '1', '4', 'Splendente in radïosa maestà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '2', '1', 'Il volto Suo con gioia allor vedremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '2', '2', 'Che già pur nella notte conosciam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '2', '3', 'Appieno la Sua voce ascolteremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '2', '4', 'Da cui pur ora già conforto abbiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '3', '1', 'Non più nemici intorno allora avremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '3', '2', 'E puro il nostro cuore alfin sarà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '3', '3', 'Nel pien riposo che lassù godremo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '3', '4', 'Più melodiosa lode salirà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '4', '1', 'Se mentre sulla terra nell\'amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '4', '2', 'Prezioso di Gesù conforto abbiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '4', '3', 'Se già fin d\'or gustiamo nel deserto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '4', '4', 'Della celeste fonte, e ne gioiam:-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '5', '1', 'Qual gioia avremo nella Sua presenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '5', '2', 'Quando il Suo amore appieno gusterem!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '5', '3', 'Con alleluia eterni allor la lode');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('213', '5', '4', 'Da cuori giubilanti eleverem.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('214', '7.6.7.6.', '41', '44');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('214', '1', '1', 'O SPIRTO benedetto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('214', '1', '2', 'Omaggio a Te rendiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('214', '1', '3', 'Ed alla Tua Persona');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('214', '1', '4', 'Devoti c\'inchiniam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('214', '2', '1', 'Noi non possiam la gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('214', '2', '2', 'Di Tua Deità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('214', '2', '3', 'Comprender; essa dura');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('214', '2', '4', 'Da tutta eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('214', '3', '1', 'Non visto, tutto vedi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('214', '3', '2', 'Nel Tuo poter e amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('214', '3', '3', 'Tu ami dispensarci');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('214', '3', '4', 'Tutt\'il divin tesor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('214', '4', '1', 'La santa Tua Persona');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('214', '4', '2', 'Commossi riveriam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('214', '4', '3', 'E insiem, con grato cuore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('214', '4', '4', 'O Spirto, T\'adoriam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('215', '9.8.9.8. Giambico.', '161', '48');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('215', '1', '1', 'DEL nostro cuor, Signor, la speme');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('215', '1', '2', 'Sei Tu, la Stella, nunzio al dì,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('215', '1', '3', 'Che già la notte fuga e insieme');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('215', '1', '4', 'Del pianto il fonte inaridì.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('215', '2', '1', 'Qui non troviamo alcun riposo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('215', '2', '2', 'Lo sguardo alziamo a Te lassù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('215', '2', '3', 'A quel diadema glorïoso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('215', '2', '4', 'Disposto a noi, Signor Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('215', '3', '1', 'Ma molto più di tal corona,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('215', '3', '2', 'Che ci conservi in ciel, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('215', '3', '3', 'Risplende a noi la speme buona');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('215', '3', '4', 'Di dimorare nel Tuo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('215', '4', '1', 'Presso il Tuo cuor, sul trono ognora,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('215', '4', '2', 'Vedrà la sposa Tua nel ciel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('215', '4', '3', 'La grazia che mostrasti allora');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('215', '4', '4', 'Per noi morendo, santo Agnel.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('216', '11.10.11.10.', '52', '97');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '1', '1', 'CI rallegriam, Signore, che sul trono');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '1', '2', 'Tu stai del Padre, coronato ognor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '1', '3', 'Passate son le sofferenze Tue');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '1', '4', 'Né più il Tuo cuore gusterà il dolor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '2', '1', 'La vita Tua di grazia e di potenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '2', '2', 'Con cuori avvinti amiamo ricordar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '2', '3', 'Ed ai Tuoi piedi in umiltà seduti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '2', '4', 'Le dolci Tue parole or ascoltar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '3', '1', 'Commossi contempliamo la Tua croce,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '3', '2', 'La croce di vergogna e di dolor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '3', '3', 'Dove soffristi per le nostre colpe');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '3', '4', 'E le togliesti, santo Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '4', '1', 'Vuota la tomba, tolta via la pietra,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '4', '2', 'Vediamo Te di morte vincitor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '4', '3', 'E come frutto della Tua vittoria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '4', '4', 'Per noi la morte non ha più terror.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '5', '1', 'Risorto Ti vediamo al ciel salire,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '5', '2', 'Compiuta l\'opra della redenzion,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '5', '3', 'E udiamo tutto il cielo giubilante');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '5', '4', 'Degno acclamarti di salir sul tron.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '6', '1', 'Ben presto Tu verrai, portando i Tuoi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '6', '2', 'Del Padre nella casa di fulgor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '6', '3', 'Qual gioia immensa allor sarà restare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('216', '6', '4', 'Eternamente presso Te, Signor!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('217', '9.9.6.6.6.4.', '69', '9999');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('217', '1', '1', 'PERCHE\' non credi? Perché sprezzar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('217', '1', '2', 'L\'amor che a Cristo ti vuole attrar?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('217', '1', '3', 'Il vano tuo gioir');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('217', '1', '4', 'In pena dee finir;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('217', '1', '5', 'Deh, vieni ad ubbidir:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('217', '1', '6', 'Vieni a Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('217', '2', '1', 'Perché non credi? Vieni al Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('217', '2', '2', 'Confida in Cristo, nel Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('217', '2', '3', 'Egli per te morì,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('217', '2', '4', 'Sul Golgota soffrì,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('217', '2', '5', 'Risorto, in ciel salì:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('217', '2', '6', 'Vieni a Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('217', '3', '1', 'Perché non credi? T\'offre Gesù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('217', '3', '2', 'Perdono e pace con Lui lassù:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('217', '3', '3', 'La porta aperta sta,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('217', '3', '4', 'Ma l\'opportunità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('217', '3', '5', 'Fra breve cesserà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('217', '3', '6', 'Vieni a Gesù.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('218', '10.9.10.9.10.9.', '176', '37');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('218', '1', '1', 'SANTO Spirito, a Te che sei Dio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('218', '1', '2', 'Or l\'omaggio vogliamo apportar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('218', '1', '3', 'Tu oprasti in amore sovrano');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('218', '1', '4', 'E i cuor nostri inducesti a piegar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('218', '1', '5', 'Da Te mossi, il poter Tuo acclamiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('218', '1', '6', 'Tua divina Persona esaltiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('219', '11.10.11.10.11.10.11.10.', '183', '21');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '1', '1', 'DIO la Sua grazia ed il Suo sommo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '1', '2', 'Rivela all\'uom del cielo dal fulgor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '1', '3', 'Dall\'alta gloria che lassù risplende');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '1', '4', 'Nel volto del divino Salvator:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '1', '5', 'Questa preziosa luce narra all\'uomo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '1', '6', 'Tutto il favore del divino cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '1', '7', 'Qual vasto fiume la rivelazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '1', '8', 'Dalla presenza scorre del Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '2', '1', 'Nel Suo Figliolo trova Dio diletto:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '2', '2', 'Alla Sua destra or seduto Egli è,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '2', '3', 'Ei che compì morendo l\'opra santa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '2', '4', 'Che al cuor di Dio piacer supremo diè.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '2', '5', 'Benedizione somma noi godiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '2', '6', 'Credendo in Lui che venne qui a morir;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '2', '7', 'Vediam la gloria del Figliol di Dio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '2', '8', 'Sul trono in cielo, nel fulgor divin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '3', '1', 'Dio tutto ha dato in mano al Suo Figliolo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '3', '2', 'Nell\'universo presto Ei regnerà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '3', '3', 'Tutti dovranno allor a Dio ubbidire,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '3', '4', 'Ogni ginocchio allor si piegherà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '3', '5', 'Al Salvatore vieni, peccatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '3', '6', 'La grazia gusta che offre di lassù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '3', '7', 'Vivi per sempre nel divin favore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('219', '3', '8', 'Che splende già nel volto di Gesù!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('220', '11.10.11.10.', '52', '138');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '1', '1', 'SENZA di Te, Signor, non posso viver,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '1', '2', 'Nulla qui in terra mi sodisfa il cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '1', '3', 'Il sangue per redimermi Tu hai dato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '1', '4', 'A qual terribil costo, Salvator!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '2', '1', 'Sì, nel Tuo sangue trovo la giustizia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '2', '2', 'Perdono e pace, gioia, speme, amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '2', '3', 'Tu sei per me conforto nel dolore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '2', '4', 'Per me sei tutto, santo Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '3', '1', 'O peccator, perché senza di Lui');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '3', '2', 'Viver vorresti nell\'oscurità?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '3', '3', 'Certa è la Sua parola: il mondo passa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '3', '4', 'E presto la tua vita finirà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '4', '1', 'Noi non sappiam se sorgerà un domani');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '4', '2', 'Pria che il Signor ci chiami innanzi a Sé.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '4', '3', 'Perché rischiar l\'eterna perdizione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '4', '4', 'Mentr\'Ei la vita t\'offre per la fé?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '5', '1', 'Ma se a Gesù tu vieni in pentimento,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '5', '2', 'Il cuore tuo di gioia Egli empirà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '5', '3', 'E in Sua presenza, nella santa gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('220', '5', '4', 'Con Lui vivrai per tutta eternità.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('221', '9.8.9.8.9.8.9.8. Dattilico.', '125', '191');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '1', '1', 'O GERUSALEMME, la santa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '1', '2', 'Città che il suo Dio edificò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '1', '3', 'Fulgente d\'eterna Sua gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '1', '4', 'Effonde suo immenso splendor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '1', '5', 'Colei che dal cielo discende,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '1', '6', 'Con Cristo per amministrar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '1', '7', 'In grazia, ed il posto glorioso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '1', '8', 'Di sposa e di moglie a occupar!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '2', '1', 'O Gerusalemme, l\'eterna!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '2', '2', 'Del Dio di Cristo città,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '2', '3', 'L\'origine tua è celeste,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '2', '4', 'In te Sua dimora sarà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '2', '5', 'Tua santa beltà tutto adorna');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '2', '6', 'Per Cristo, la cui sposa sei:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '2', '7', 'Tu occupi, in gioia superna,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '2', '8', 'L\'eterna tua parte con Lui!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '3', '1', 'O tu, residenza di gloria!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '3', '2', 'Di Dio tabernacolo allor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '3', '3', 'Dov\' Egli-mirabile storia-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '3', '4', 'Dimora così presso l\'uom!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '3', '5', 'La luce di nuova creazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '3', '6', 'Possiamo, rapiti, ammirar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '3', '7', 'Ci tien dello Spirto il potere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '3', '8', 'E muoveci Cristo a lodar!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '4', '1', 'Il Padre, sorgente di gloria-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '4', '2', 'Mirabile centro il Figliol-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '4', '3', 'Lo Spirto, che tutto pervade-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '4', '4', 'Pienezza in riposo ad ognor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '4', '5', 'Dio Sommo, Ti benediciamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '4', '6', 'E gloria al Tuo Nome rendiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '4', '7', 'Da Te sono tutte le cose,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('221', '4', '8', 'Per Te e mediante Te, Amen.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('222', '8.7.8.7.', '24', '40');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('222', '1', '1', 'BENEDETTO Spirto Santo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('222', '1', '2', 'Noi con canti Ti lodiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('222', '1', '3', 'Tu c\'insegni gioie pure');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('222', '1', '4', 'Che in eterno dureran.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('222', '2', '1', 'Contemplando la Tua gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('222', '2', '2', 'Mentre servi in umiltà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('222', '2', '3', 'I cuor nostri a Te si chinan,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('222', '2', '4', 'Riverenti a Tua Deità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('222', '3', '1', 'Tu nei piani prezïosi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('222', '3', '2', 'Che son per l\'eternità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('222', '3', '3', 'Ci conduci con pazienza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('222', '3', '4', 'Spirito di verità.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('223', '10.9.10.9.10.9.10.9.', '177', '38');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('223', '1', '1', 'SANTO Spirito, nostro conforto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('223', '1', '2', 'E sostegno qui in terra sei Tu;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('223', '1', '3', 'Il Tuo aiuto ci è sempre costante');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('223', '1', '4', 'Lungo il nostro cammino quaggiù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('223', '1', '5', 'Or riuniti per opera Tua,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('223', '1', '6', 'I cuor pieni di santo fervor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('223', '1', '7', 'Consci siam del divin Tuo servizio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('223', '1', '8', 'E del Tuo immutabile amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('223', '2', '1', 'Or al trono di grazia dinanzi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('223', '2', '2', 'In fidente letizia veniam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('223', '2', '3', 'Conoscendo Colui che intercede');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('223', '2', '4', 'Al cospetto del Padre che amiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('223', '2', '5', 'I cuor nostri in quest\'ora di quiete');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('223', '2', '6', 'A Dio dicono i loro desir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('223', '2', '7', 'E ne traggono forza e conforto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('223', '2', '8', 'Il cammino terren per compir.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('224', '9.8.9.8.9.8.9.8. Giambico.', '137', '196');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '1', '1', 'NESSUN terrestre sacrificio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '1', '2', 'Potrebbe mai incominciar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '1', '3', 'Ad espïare un sol peccato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '1', '4', 'O un\'alma qui a purificar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '1', '5', 'Un sacrificio ben migliore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '1', '6', 'Occorre per poter calmar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '1', '7', 'Della coscienza il turbamento');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '1', '8', 'E un giusto Dio per sodisfar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '2', '1', 'Sol con il sangue del Figliolo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '2', '2', 'Di Dio, che venne qui dal ciel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '2', '3', 'Espïazion fu fatta appieno:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '2', '4', 'Ei qui sofferse come Agnel:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '2', '5', 'Là nell\'eternità passata');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '2', '6', 'Di Dio Compagno sempre fu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '2', '7', 'Egli il cui nome è la Parola,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '2', '8', 'Il Cristo, il Salvator-Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '3', '1', 'Sol con il sangue che in amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '3', '2', 'Gesù versò pel peccator');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '3', '3', 'Pagato è il prezzo del riscatto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '3', '4', 'Libera è l\'alma da terror.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '3', '5', 'Eternamente glorïoso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '3', '6', 'Egli è dei mondi Creator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '3', '7', 'Pur chinò il capo nella morte');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '3', '8', 'Per riscattare il peccator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '4', '1', 'E\' questo il piano che in amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '4', '2', 'Iddio formò da eternità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '4', '3', 'Per aver l\'uomo a Sé vicino');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '4', '4', 'In pace eterna, in libertà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '4', '5', 'Là dove Cristo sovra il trono');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '4', '6', 'Or siede in gloria senza egual,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '4', '7', 'Da tutti i santi ch\'Ei redense');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('224', '4', '8', 'A Lui la gloria eterna sal.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('225', '9.8.9.8.Dattilico.', '112', '197');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '1', '1', 'OH scene di gloria celeste,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '1', '2', 'La casa del Padre lassù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '1', '3', 'Là dove ogni cosa riflette');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '1', '4', 'L\'amor rivelato in Gesù!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '2', '1', 'Del Padre il supremo diletto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '2', '2', 'Riposa su Cristo, il Figliol,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '2', '3', 'E in cielo ogni lingua Lui loda');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '2', '4', 'Per l\'opera ch\'Ei compì sol.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '3', '1', 'Le lodi del Padre or cantiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '3', '2', 'L\'amor Suo che ben conosciam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '3', '3', 'Di star nella luce coi santi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '3', '4', 'Da Lui resi degni noi siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '4', '1', 'Già ora gustiam quell\'amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '4', '2', 'Che presto ci trasformerà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '4', '3', 'Con grande potenza, ed al cielo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '4', '4', 'Ognuno di noi rapirà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '5', '1', 'Colui che per noi qui sofferse');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '5', '2', 'E\' il centro del sommo splendor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '5', '3', 'Di fulgida gloria celeste,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '5', '4', 'E\' il tema divin d\'ogni cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '6', '1', 'Intorno all\'Agnello sul trono');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '6', '2', 'Miriadi di santi saran:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '6', '3', 'Avran loro parte con Lui,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '6', '4', 'L\'imagine Sua porteran.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '7', '1', 'La croce per noi Ei sofferse:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '7', '2', 'A Lui sia la lode e l\'onor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '7', '3', 'In Lui or è il Sì, in Lui l\'Amen');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('225', '7', '4', 'Per sempre-sia gloria al Signor!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('226', '10.9.10.9.10.9.l0.9.', '177', '76');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '1', '1', 'QUALI santi pensieri, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '1', '2', 'La Tua mente potevano empir');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '1', '3', 'Quando qui dal Tuo Dio Tu venisti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '1', '4', 'Il Suo santo volere a compir!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '1', '5', 'Quanto intensa e profonda la gioia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '1', '6', 'Che il Tuo cuore poteva colmar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '1', '7', 'Al pensiero dei figli ed eredi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '1', '8', 'Che Tu al Padre volevi portar!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '2', '1', 'I Tuoi propri diletti fratelli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '2', '2', 'Già tenevi davanti al Tuo cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '2', '3', 'Alla Tua somiglianza mutati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '2', '4', 'Per restar con Te sempre, Signor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '2', '5', 'La Tua chiesa, completa e perfetta,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '2', '6', 'Rivestita di Tua beltà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '2', '7', 'Già gustavi il riposo che Dio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '2', '8', 'In quel giomo di gloria godrà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '3', '1', 'Or, Signor, contemplando il Tuo volto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '3', '2', 'Quei pensier comprendiamo per fé');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '3', '3', 'Nella luce che tutto pervade,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '3', '4', 'Nella gioia che viene da Te;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '3', '5', 'Una vasta distesa di gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '3', '6', 'Già con gli occhi del cuore vediam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '3', '7', 'E, qual frutto di Tua vittoria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('226', '3', '8', 'Lodi eterne di cuore eleviam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('227', '8.8.8.8.8.8.8.7.', '156', '158');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('227', '1', '1', 'AL Tuo Nome radunati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('227', '1', '2', 'La Tua via quaggiù vediamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('227', '1', '3', 'Contemplando l\'amor Tuo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('227', '1', '4', 'La Tua grazia celebriamo.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('227', '1', '5', 'A morire sulla croce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('227', '1', '6', 'Tu scendesti nel Tuo amore:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('227', '1', '7', 'Finché venga Tu, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('227', '1', '8', 'La Tua morte or annunziam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('227', '2', '1', 'I cuor nostri sono mossi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('227', '2', '2', 'Mentre Te noi contempliamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('227', '2', '3', 'E il comando Tuo d\'amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('227', '2', '4', 'O Signor Gesù, ascoltiamo.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('227', '2', '5', 'Or uniti siam di cuore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('227', '2', '6', 'Perché Tu ci hai liberati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('227', '2', '7', 'Ed a Te con cuori grati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('227', '2', '8', 'E con gioia rispondiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('228', '8.7.8.7.8.7.8.7.', '25', '9998');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '1', '1', 'IN quest\'arido deserto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '1', '2', 'Per me Cristo già passò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '1', '3', 'Qui per il mio piede è aperto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '1', '4', 'Il sentiero ch\'Ei tracciò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '1', '5', 'Egli al Padre mi conduce,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '1', '6', 'Di letizia m\'empie il cuor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '1', '7', 'Oh, che nulla sulla terra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '1', '8', 'Attirarmi possa ancor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '2', '1', 'Il mio cuore in Cristo posa:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '2', '2', 'Come invan Lo seguirei,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '2', '3', 'Mancherei d\'alcuna cosa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '2', '4', 'Poi che il mio guadagno è Lui?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '2', '5', 'Le ricchezze della vita');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '2', '6', 'Sol intralcio son per me:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '2', '7', 'La potenza Sua infinita');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '2', '8', 'Mi fa libero per fé.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '3', '1', 'Ora verso il ciel cammino');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '3', '2', 'In felice libertà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '3', '3', 'Vibra l\'alma mia nel suono');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '3', '4', 'Dell\'eterno canto già.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '3', '5', 'Se la fede mi sostiene,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '3', '6', 'Triste il mio sentier non è;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '3', '7', 'Ben v\'incontro delle pene,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '3', '8', 'Ma son utili per me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '4', '1', 'Oh, favor meraviglioso!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '4', '2', 'Il conoscerti quaggiù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '4', '3', 'E\' la parte sì gioiosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '4', '4', 'Di chi segue Te, Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '4', '5', 'E ben presto nella gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '4', '6', 'Ti contemplerò, Signor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '4', '7', 'In Te sta la mia vittoria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('228', '4', '8', 'O possente Salvator.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('229', '11.10.11.10.', '52', '83');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('229', '1', '1', 'IL Nome Tuo, Gesù, vivrà in eterno:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('229', '1', '2', 'Come oggi il ciel, la terra un dì empirà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('229', '1', '3', 'Nazioni e re a Te s\'inchineranno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('229', '1', '4', 'Ed il Tuo Nome ognun conoscerà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('229', '2', '1', 'Signor, Tu vivi e la divina grazia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('229', '2', '2', 'Che ognor brillò sul Tuo cammin quaggiù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('229', '2', '3', 'Oltre la morte non mutata splende');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('229', '2', '4', 'Di luce eterna a noi, Signor Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('229', '3', '1', 'Più non chiediam: abbiamo Te, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('229', '3', '2', 'La gloria Tua con gioia contempliam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('229', '3', '3', 'Ciò che Tu sei sostiene i nostri cuori,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('229', '3', '4', 'Mentre la Tua venuta qui attendiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('230', '10.9.10.9.', '114', '97');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '1', '1', 'CONTEMPLIAMO la via, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '1', '2', 'Che tracciasti quaggiù in umiltà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '1', '3', 'La Tua grazia e l\'amore per l\'uomo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '1', '4', 'E per Dio la Tua fedeltà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '2', '1', 'Fra gl\'infidi Tu fosti fedele,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '2', '2', 'Sola luce nell\'oscurità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '2', '3', 'Confessando qui il nome del Padre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '2', '4', 'Tuo diletto la Sua volontà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '3', '1', 'Non Ti mosser di Satana i dardi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '3', '2', 'Privazioni, vergogna e dolor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '3', '3', 'La Tua via, senza umano conforto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '3', '4', 'Alla croce condusse, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '4', '1', 'Il Tuo amore, dall\'uomo provato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '4', '2', 'Della tomba più forte fu ancor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '4', '3', 'L\'uom in odio il Tuo fianco trafisse:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '4', '4', 'Diè il Tuo sangue risposta d\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '5', '1', 'L\'umiltà Tua profonda ammiriamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '5', '2', 'E vogliam somigliarti, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '5', '3', 'E trovare la gioia e il riposo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('230', '5', '4', 'Nell\'apprender la via Tua d\'amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('231', '7.7.7.7. ', '29', '30');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '1', '1', 'PADRE, al tron di grazia ognor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '1', '2', 'Nel bisogno noi veniam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '1', '3', 'Consci che nel Tuo Figliol');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '1', '4', 'A Te accetti sempre siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '2', '1', 'Gloria al Nome Tuo divin');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '2', '2', 'Sia qui in terra come in ciel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '2', '3', 'A Te lode e adorazion');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '2', '4', 'Dalla chiesa Tua fedel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '3', '1', 'Fra nemici, in mezzo al duol,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '3', '2', 'Qui nel mondo ci troviam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '3', '3', 'Ma protetti dal Tuo amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '3', '4', 'Fiduciosi riposiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '4', '1', 'Possa il santo Tuo Figliol');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '4', '2', 'Dimorar nei nostri cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '4', '3', 'Deh, ci dona di gioir');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '4', '4', 'Nel Tuo piano pien d\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '5', '1', 'Nuova forza dì per dì');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '5', '2', 'Ci sia dato di provar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '5', '3', 'E al di sopra d\'ogni mal');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('231', '5', '4', 'In amore camminar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('232', '11.10.11.10.11.11.', '184', '191');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('232', '1', '1', 'LE voci a Te, Signore Gesù Cristo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('232', '1', '2', 'Come una voce sola, noi leviam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('232', '1', '3', 'Il Nome Tuo fra i Tuoi qui esaltiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('232', '1', '4', 'A Te cantiam, tributo Ti rendiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('232', '1', '5', 'O Re dei re, Signore dei signori,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('232', '1', '6', 'Le glorie Tue son tema ai nostri cori.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('232', '2', '1', 'I canti lor le stelle del mattino');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('232', '2', '2', 'Insieme già facevan risonar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('232', '2', '3', 'A lor seguì la lode d\'Israele');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('232', '2', '4', 'In salmi e canti; or rivelata appar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('232', '2', '5', 'Di creazione e redenzion la gloria:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('232', '2', '6', 'Le schiere in ciel ne esaltano la storia!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('232', '3', '1', 'Sei degno Tu! E\' pure nostro il canto;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('232', '3', '2', 'Tu sei il Primo, l\'Ultimo Tu se\',');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('232', '3', '3', 'Di David la Radice Tu, l\'Agnello');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('232', '3', '4', 'Un dì immolato, nostro Capo e Re!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('232', '3', '5', 'A Te, Colui che è, ch\'era e che viene,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('232', '3', '6', 'La gloria diam; l\'onore T\'appartiene!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('233', '9.8.9.8. Giambico.', '161', '196');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('233', '1', '1', 'NOSTRO è il perdono nel Suo sangue,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('233', '1', '2', '(Meravigliosa verità! )');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('233', '1', '3', 'Il sangue di Colui che aveva');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('233', '1', '4', 'Diritto a eterna maestà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('233', '2', '1', 'Niun se non Lui portar poteva');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('233', '2', '2', 'Della giustizia il peso allor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('233', '2', '3', 'Altri che Lui nessun offriva');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('233', '2', '4', 'Quel ch\'Egli diede nel Suo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('233', '3', '1', 'Egli, il Signore della gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('233', '3', '2', 'Chinò il Suo capo un dì quaggiù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('233', '3', '3', 'Soffrì il dolore, il vituperio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('233', '3', '4', 'Coi morti prigioniero fu.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('233', '4', '1', 'Ma ecco, sorse dal sepolcro,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('233', '4', '2', 'Nome supremo porta ognor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('233', '4', '3', 'Onnipotente è per salvarci');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('233', '4', '4', 'Da morte, male e eterno orror.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('234', '11.10.11.10.', '52', '33');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('234', '1', '1', 'SIGNOR, Tu sei di gloria coronato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('234', '1', '2', 'Tu che moristi noi per riscattar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('234', '1', '3', 'E perdonati, al Padre Tuo condotti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('234', '1', '4', 'A Te la lode eterna amiamo alzar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('234', '2', '1', 'Noi Ti lodiam: per noi la Tua preziosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('234', '2', '2', 'Vita Tu desti, offerta senza par;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('234', '2', '3', 'Sei nostra Guida, tutto a Te dobbiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('234', '2', '4', 'Per il Tuo sangue che sol può nettar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('234', '3', '1', 'Risorto sei, Signore glorïoso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('234', '3', '2', 'E di là dalla morte con Te siam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('234', '3', '3', 'In Te gioiamo nella vita eterna');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('234', '3', '4', 'E lieti a Te la voce e il cuor leviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('234', '4', '1', 'Presto verrai, Signore, T\'attendiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('234', '4', '2', 'Presto nell\'aria noi T\'incontrerem,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('234', '4', '3', 'E trasformati e resi a Te simìli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('234', '4', '4', 'La Tua presenza senza vel godrem.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('235', '10.9.10.9.', '114', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '1', '1', 'TI lodiamo, Signore glorioso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '1', '2', 'Che moristi per noi liberar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '1', '3', 'Una gioia sì piena, sì pura,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '1', '4', 'Solo il canto celeste può dar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '2', '1', 'Il Tuo amore divino lodiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '2', '2', 'Che crudel sofferenza affrontò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '2', '3', 'Che per noi fece l\'espïazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '2', '4', 'Ed a Te, Salvator, ci portò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '3', '1', 'Il Tuo amore lodiamo che in terra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '3', '2', 'Solitario Ti fece passar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '3', '3', 'Ed in mezzo alle pene e al dolore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '3', '4', 'Con Tua grazia infinita parlar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '4', '1', 'Il Tuo amor nella valle di morte');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '4', '2', 'La più pura fragranza esalò:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '4', '3', 'In presenza del male, la gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '4', '4', 'Della redenzïone brillò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '5', '1', 'Ti vediamo, Signore, or risorto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '5', '2', 'Che per noi Ti donasti quaggiù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '5', '3', 'Alla destra del Padre seduto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '5', '4', 'Coronato di gloria lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '6', '1', 'E ben presto, Signor, regnerai;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '6', '2', 'Tutto il male allor vinto sarà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '6', '3', 'Ed in gloria la Tua assemblea');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '6', '4', 'Al Tuo fianco il Tuo amore godrà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '7', '1', 'Signor nostro Gesù, T\'attendiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '7', '2', 'D\'esser Teco per sempre bramiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '7', '3', 'Sarà allor nostra gioia compiuta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('235', '7', '4', 'Quando Te faccia a faccia vediam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('236', '8.7.8.7.7.7.7.6.', '145', '129');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '1', '1', 'CON gran desìo, Signor, bramiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '1', '2', 'Il volto Tuo vedere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '1', '3', 'E sempre dimorar con Te');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '1', '4', 'In quelle eccelse sfere;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '1', '5', 'Non più addolorarti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '1', '6', 'Per triste debolezza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '1', '7', 'Ma pieni d\'allegrezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '1', '8', 'Raggiunger Te nel ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '2', '1', 'Qual gioia allor sarà, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '2', '2', 'Per il fedel Tuo cuore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '2', '3', 'Avere i santi Tuoi con Te');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '2', '4', 'Nell\'alte Tue dimore!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '2', '5', 'Da morte e dal peccato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '2', '6', 'Per sempre liberati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '2', '7', 'Saranno i riscattati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '2', '8', 'E giubilanti in Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '3', '1', 'Allor la sposa Tua, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '3', '2', 'Frutto del Tuo dolore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '3', '3', 'Completa, ed a Te unita, allor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '3', '4', 'Rallegrerà il Tuo cuore;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '3', '5', 'E insiem la loro voce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '3', '6', 'Lo Spirito e la sposa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '3', '7', 'Fan risonar gioiosa:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('236', '3', '8', '"Vieni, Signor Gesù! "');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('237', '11.10.11.10.', '52', '176');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('237', '1', '1', 'PADRE, il Tuo santo Nome celebriamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('237', '1', '2', 'E con adorazione a Te veniam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('237', '1', '3', 'Nella rivelazione del Tuo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('237', '1', '4', 'La santa Tua giustizia pur vediam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('237', '2', '1', 'Là dove tutto parla di Tua gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('237', '2', '2', 'Nel tempio Tuo, qual figli a Te veniam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('237', '2', '3', 'Ed elevando a Te la nostra lode');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('237', '2', '4', 'Nell\'amor Tuo divino noi gioiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('237', '3', '1', 'E\' Cristo stesso che la lode guida,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('237', '3', '2', 'Egli che il Nome Tuo ci rivelò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('237', '3', '3', 'E che, purificati e resi degni,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('237', '3', '4', 'Figlioli in Tua presenza ci portò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('237', '4', '1', 'Quale il Tuo Nome, tale è la Tua lode:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('237', '4', '2', 'Con una voce lieti a Te cantiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('237', '4', '3', 'Nel Tuo diletto Figlio a Te la gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('237', '4', '4', 'A Te l\'adorazione noi rendiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('238', '11.8.11.9.', '71', '77');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('238', '1', '1', 'SE pace qual fiume inonda il mio cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('238', '1', '2', 'Se il riempie qual mare il dolor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('238', '1', '3', 'Signor, Tu m\'insegni a sclamare per fé:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('238', '1', '4', 'Tutto è ben, tutto è bene per me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('238', '2', '1', 'Se giungon le prove, se Satana vien,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('238', '2', '2', 'Felice certezza è per me');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('238', '2', '3', 'Che Cristo al mio misero stato guardò-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('238', '2', '4', 'Per salvarmi, il Suo sangue versò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('238', '3', '1', 'I miei falli (o gioia di questo pensier! )');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('238', '3', '2', 'I miei falli, nel lor intier,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('238', '3', '3', 'Per sempre Egli tolse alla croce in amor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('238', '3', '4', 'Alma mia, benedici il Signor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('238', '4', '1', 'Il ciel, non la tomba, è la méta che abbiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('238', '4', '2', 'Signor, Te dal cielo attendiam!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('238', '4', '3', 'La tromba, la voce d\'arcangelo udrem,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('238', '4', '4', 'Nel riposo per sempre sarem!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('239', '11.10.11.10.10.10.', '180', '6');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('239', '1', '1', 'CRISTO Se stesso diede sulla croce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('239', '1', '2', 'E pei peccati fece espïazion');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('239', '1', '3', 'Con il Suo sangue, sì che fosse dato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('239', '1', '4', 'A te goder la pace ed il perdon:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('239', '1', '5', 'Dalle tue colpe te vuol liberar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('239', '1', '6', 'Ed il Tuo cuor di gioia vuol colmar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('239', '2', '1', 'Senza esitare Ei fe\' tutto il cammino');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('239', '2', '2', 'Che a morte sulla croce Lo portò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('239', '2', '3', 'Così che, sodisfatta la giustizia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('239', '2', '4', 'Ad un tal costo, pace a noi recò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('239', '2', '5', 'Or l\'Iddio santo, nel Suo sommo amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('239', '2', '6', 'Può dispensare grazia al peccator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('239', '3', '1', 'Le sofferenze Sue son passate');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('239', '3', '2', 'E Gesù vive per non morir più,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('239', '3', '3', 'In gloria attende che noi parte abbiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('239', '3', '4', 'Alla dimora Sua con Lui lassù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('239', '3', '5', 'Del Padre nella casa, ove sarà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('239', '3', '6', 'Luce e splendor per tutta eternità.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('240', '10.9.10.9.(b)', '175', '15');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '1', '1', 'EI non poteva salvar Se stesso-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '1', '2', 'Cristo dovette Se stesso dar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '1', '3', 'Solo in tal modo pel peccatore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '1', '4', 'Misericordia potè mostrar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '2', '1', 'Ei non poteva salvar Se stesso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '2', '2', 'Ché la giustizia di sodisfar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '2', '3', 'Egli soltanto avea il potere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '2', '4', 'Ed i peccati appien espiar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '3', '1', 'Ei non poteva salvar Se stesso:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '3', '2', 'In luogo nostro Egli soffrì,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '3', '3', 'Sparse il Suo sangue, diede la vita,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '3', '4', 'La redenzione Egli compì.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '4', '1', 'Ei non poteva salvar Se stesso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '4', '2', 'Ché tanto grande era il Suo amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '4', '3', 'Tutto Egli volle pagare il prezzo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '4', '4', 'Per il riscatto del peccator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '5', '1', 'Ora nel cielo glorificato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '5', '2', 'Principe Ei siede e Salvator');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '5', '3', 'Ed a chi viene a Lui per fede');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('240', '5', '4', 'La vita dona, pace ed amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('241', '8.6.8.4.', '72', '83');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '1', '1', 'NON per il nostro amor per Te');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '1', '2', 'Tu desti il Tuo Figliol:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '1', '3', 'Vediam la fonte dell\'amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '1', '4', 'In Te, Dio, sol.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '2', '1', 'Oh, quale amor, Signor Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '2', '2', 'Ti spinse qui a venir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '2', '3', 'Obbrobrio e pene a sopportar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '2', '4', 'Ed a morir!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '3', '1', 'Dei nostri falli il peso allor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '3', '2', 'Appien su Te gravò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '3', '3', 'Quando il Tuo Dio, nel Tuo dolor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '3', '4', 'T\'abbandonò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '4', '1', 'Oh, quale grido trionfal');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '4', '2', 'Facesti allor udir');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '4', '3', 'Quando "E\' compiuto" Tu, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '4', '4', 'Potesti dir!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '5', '1', 'Or sei risorto, e dubitar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '5', '2', 'Noi non possiamo più.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '5', '3', 'Perfetta pace ai nostri cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '5', '4', 'Tu dài, Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '6', '1', 'Sì, nel Tuo sangue ogni question');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '6', '2', 'Risolta è, Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '6', '3', 'Tu, nostra pace, vivi in ciel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '6', '4', 'In gloria ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '7', '1', 'Nella Tua grazia, Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '7', '2', 'Il cuore Tuo vediam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '7', '3', 'Ed al Tuo amor, con grato cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('241', '7', '4', 'Noi rispondiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('242', '11.11.11.11.(c)', '193', '214');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('242', '1', '1', 'O DIO, Tu fonte sei d\'eterna gioia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('242', '1', '2', 'Con pieno cuor le lodi Tue cantiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('242', '1', '3', 'Mentre col Primogenito Figliolo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('242', '1', '4', 'L\'eterna gloria Tua contempliamo.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('242', '2', '1', 'Sublime è invero questa relazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('242', '2', '2', 'In cui per il Tuo Spirto ci hai portati:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('242', '2', '3', 'Uomini uniti a Cristo vuoi avere,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('242', '2', '4', 'Consoni ai Tuoi pensier, glorificati!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('242', '3', '1', 'L\'economia d\'amor ci hai rivelata,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('242', '3', '2', 'Pur in Tua propria maestà dimori,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('242', '3', '3', 'Eterno Dio, sovrano ed esaltato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('242', '3', '4', 'In sfere inaccessibili in fulgore.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('243', '9.8.9.8.9.8.9.8. Giambico.', '137', '180');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '1', '1', 'COME vediam l\'amor di Dio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '1', '2', 'Nel Suo Figliolo, ch\'Eg1i diè');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '1', '3', 'E che, morendo sulla croce,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '1', '4', 'Per sempre liberi ci fe\'.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '1', '5', 'Col sangue ch\'Ei per noi versava');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '1', '6', 'Fece perfetta espïazion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '1', '7', 'Dio è appien glorificato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '1', '8', 'Compiuta è la redenzïon.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '2', '1', 'Or coronato in cielo Ei siede,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '2', '2', 'Dell\'alta gloria nel fulgor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '2', '3', 'Oggetto dell\'adorazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '2', '4', 'Del cielo, Cristo, il Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '2', '5', 'Oh, quanto è degno d\'ogni onore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '2', '6', 'Ei che per noi Se stesso diè!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '2', '7', 'Quanto è gloriosa la salvezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '2', '8', 'Che ci è donata per la fé!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '3', '1', 'Or a chi crede ed ubbidisce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '3', '2', 'Il Padre in dono vuole dar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '3', '3', 'Lo Spirto Santo, il cuore suo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '3', '4', 'D\'immensa gioia per colmar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '3', '5', 'Lo Spirto è l\'Arra della gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '3', '6', 'Che già ci attende là nel ciel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '3', '7', 'Ove con Cristo abiteremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('243', '3', '8', 'E Lo vedremo senza vel.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('244', '11.10.11.10.', '52', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '1', '1', 'NON con incerto e timoroso passo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '1', '2', 'Per il deserto noi la via seguiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '1', '3', 'Una ben nota voce che c\'invita');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '1', '4', 'Verso un glorioso, eterno dì sentiam-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '2', '1', 'La voce di Colui che, nel deserto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '2', '2', 'Passando solitario, vi tracciò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '2', '3', 'La via che ñno a Dio ci conduce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '2', '4', 'E le Sue orme qui per noi lasciò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '3', '1', 'Ei non ci lascia soli nel cammino:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '3', '2', 'La Sua vivente grazia conosciam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '3', '3', 'Mentre Egli ver\' la casa ci conduce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '3', '4', 'Dove con Lui trovarci noi bramiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '4', '1', 'Or per la porta ch\'Egli ha aperta in cielo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '4', '2', 'La gloria Sua vediamo già brillar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '4', '3', 'Mostrando il bene che lassù godremo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '4', '4', 'La nostra via quaggiù ad illuminar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '5', '1', 'Pur se provata ancor è nostra fede,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '5', '2', 'Noi con pazienza questa via seguiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '5', '3', 'Fidenti nell\'amor che ci sorregge,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('244', '5', '4', 'In Lui conforto nel dolor troviam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('245', '6.6.8.6.6.8.', '73', '84');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '1', '1', 'DAL trono Suo lassù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '1', '2', 'Dio mandò qui Gesù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '1', '3', 'Il Suo Figliolo, in sommo amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '1', '4', 'L\'uom vile a riscattar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '1', '5', 'Giustizia a sodisfar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '1', '6', 'E a rivelare il divin cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '2', '1', 'Dal cielo il Salvator');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '2', '2', 'Scese, Gesù, il Signor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '2', '3', 'La morte venne a debellar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '2', '4', 'E dalla schiavitù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '2', '5', 'In cui tenuto fu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '2', '6', 'Il Suo credente a liberar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '3', '1', 'Perdono al peccator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '3', '2', 'Riposo al vïator');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '3', '3', 'E all\'uom perduto amore Ei diè.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '3', '4', 'Ognun che s\'appressò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '3', '5', 'La grazia Sua gustò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '3', '6', 'E la potenza Sua per fé.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '4', '1', 'Ma senza posa ancor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '4', '2', 'Ei, l\'Uomo di dolor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '4', '3', 'Fino alla croce proseguì:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '4', '4', 'Ei l\'ira sopportò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '4', '5', 'Le colpe Egli espiò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '4', '6', 'E la redenzïon compì.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '5', '1', 'Or coronato Egli è,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '5', '2', 'Noi Lo vediam per fé');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '5', '3', 'Sul trono in santa maestà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '5', '4', 'Deh, vieni, peccator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '5', '5', 'Si, vieni al Salvator');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('245', '5', '6', 'Che t\'offre pace e libertà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('246', '11.10.11.10.', '52', '31');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '1', '1', 'MAI non ci stancheremo di cantare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '1', '2', 'La storia dell\'amore di Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '1', '3', 'Di Lui che dalla glorïa del cielo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '1', '4', 'Venne a morir pel peccator quaggiù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '2', '1', 'E\' una gloriosa storia, sempre nuova,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '2', '2', 'Che ci è narrata appieno nel vangel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '2', '3', 'Soggetto della lode dei redenti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '2', '4', 'Già sulla terra e poi per sempre in ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '3', '1', 'Oh, quale amor Lo spinse qui a venire,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '3', '2', 'Di Dio la grazia all\'uom a rivelar!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '3', '3', 'Per qual oscurità dovè passare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '3', '4', 'Dei nostri falli il peso per portar!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '4', '1', 'Ma, vittorioso, il Salvator risorse,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '4', '2', 'La morte nol poteva ritener,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '4', '3', 'Ed ora vive in cielo, per salvare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '4', '4', 'Chi viene a Lui con pentimento ver.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '5', '1', 'Presto Ei verrà dal ciel e i Suoi redenti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '5', '2', 'In somiglianza a Sé trasformerà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '5', '3', 'E nella Sua dimora glorïosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('246', '5', '4', 'A viver là con Sé li chiamerà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('247', '11.10.11.10.', '52', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('247', '1', '1', 'SAREMO dunque simili al Tuo Figlio?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('247', '1', '2', 'E\' questo il dono ch\'Egli ci acquistò?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('247', '1', '3', 'Padre di gloria! Nella Tua presenza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('247', '1', '4', 'Figlioli a Lui simìli, ci portò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('247', '2', '1', 'Tal è il Tuo piano! Resi alfin perfetti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('247', '2', '2', 'Saremo, per rispondere al Suo amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('247', '2', '3', 'Ma già fin d\'or, per l\'opra dello Spirto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('247', '2', '4', 'Di vive gioie colmo abbiamo il cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('247', '3', '1', 'Appieno sodisfatti allor saremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('247', '3', '2', 'E nulla più desiderar potrem:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('247', '3', '3', 'Cristo, il perfetto Oggetto al nostro cuore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('247', '3', '4', 'Per sempre nell\'amore adorerem.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('248', '8.6.8.6.8.6.8.6.', '126', '75');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '1', '1', 'UDII la voce di Gesù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '1', '2', 'Che disse: Vieni a Me;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '1', '3', 'Affaticato peccator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '1', '4', 'Riposo v\'è per te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '1', '5', 'A Lui io venni ed il mio cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '1', '6', 'Sì stanco in Lui trovò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '1', '7', 'Perdono, pace, gioia, amor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '1', '8', 'Pieno riposo or ho.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '2', '1', 'Udii la voce di Gesù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '2', '2', 'Che disse: In grazia dò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '2', '3', 'L\'acqua di vita-se berrai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '2', '4', 'Tua sete toglierò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '2', '5', 'A quel vivente fiume allor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '2', '6', 'Venni e ne bevvi appien:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '2', '7', 'L\'ardente sete s\'acquetò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '2', '8', 'E vita Ei mi diè.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '3', '1', 'A me la voce di Gesù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '3', '2', 'Disse: La luce Io son;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '3', '3', 'A Me tu guarda e sorgerà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '3', '4', 'Il giomo nel tuo cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '3', '5', 'A Lui guardai e vidi il Sol');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '3', '6', 'Che l\'alma mia inondò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '3', '7', 'Di quella luce nel fulgor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('248', '3', '8', 'Sempre camminerò.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('249', '11.10.11.10.', '52', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('249', '1', '1', 'GESU\', Signore, quale amor fu mai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('249', '1', '2', 'Simìle al Tuo? Con Te dimorerem,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('249', '1', '3', 'Frutto del Tuo travaglio, e la Tua gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('249', '1', '4', 'Per tutta eternità contemplerem.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('249', '2', '1', 'Se i Tuoi con Te non fossero, riposo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('249', '2', '2', 'Mai non potrebbe l\'amor Tuo trovar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('249', '2', '3', 'L\'amore Tuo che dà, non come il mondo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('249', '2', '4', 'Ma tutto vuol con noi partecipar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('249', '3', '1', 'Completa allor sarà la compagnia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('249', '3', '2', 'Che in gloria intorno a Te s\'adunerà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('249', '3', '3', 'Ognuno, per Tua gloria a Te simìle,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('249', '3', '4', 'Te, suo supremo Oggetto, adorerà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('250', '8.8.8.8.6.', '58', '51');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '1', '1', 'SIA fatta la Tua volontà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '1', '2', 'Dobbiamo tutto a Te, Signor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '1', '3', 'Tu ci conduci con amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '1', '4', 'E Tu ci hai posti in libertà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '1', '5', 'Per fare il Tuo voler.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '2', '1', 'Sia fatta la Tua volontà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '2', '2', 'E\' il desiderio del Tuo cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '2', '3', 'Fa\' che possiamo in ciò trovar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '2', '4', 'La nostra gioia, mentre ancor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '2', '5', 'La notte attraversiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '3', '1', 'Sia fatta la Tua volontà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '3', '2', 'Riposo avrem pel nostro cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '3', '3', 'Portando il giogo Tuo in amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '3', '4', 'Seguendo Te nel Tuo sentier');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '3', '5', 'Finché ci chiamerai.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '4', '1', 'Sia fatta la Tua volontà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '4', '2', 'Fa\' che viviamo a Te, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '4', '3', 'Fino a che Dio ci chiamerà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '4', '4', 'A viver per l\'eternità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('250', '4', '5', 'Nel Tuo profondo amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('251', '11.10.11.10.', '52', '194');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '1', '1', 'SIGNORE Gesù Cristo, Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '1', '2', 'Con gioia noi l\'omaggio a Te rendiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '1', '3', 'Sappiamo che per noi la vita desti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '1', '4', 'E che dal sangue Tuo redenti siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '2', '1', 'Pur conosciam l\'amor che Ti condusse');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '2', '2', 'Dall\'alta gloria in terra per soffrir');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '2', '3', 'La pena e l\'onta, sì, per dar Te stesso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '2', '4', 'Ed al Calvario in croce per morir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '3', '1', 'O Salvatore nostro, sei il Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '3', '2', 'Dura il Tuo amor per tutta eternità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '3', '3', 'Eterni pure son di lode i canti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '3', '4', 'Che con Te ognun, Signore, canterà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '4', '1', 'La Tua divina grazia già lodiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '4', '2', 'Ed il profondo amor che splende in Te;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '4', '3', 'Per noi Tu, ricco, in povertà scendesti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '4', '4', 'E la Tua morte libertà ci diè.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '5', '1', 'Oh, quale tema per la lode abbiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '5', '2', 'Nella Tua croce, in Te, nel Tuo lavor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '5', '3', 'Mai non potrem l\'amor Tuo misurare,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('251', '5', '4', 'Vivente e benedetto Salvator!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('252', '10.10.10.10.', '21', '83');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('252', '1', '1', '"VENITE a Me: riposo vi darò!"');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('252', '1', '2', 'Dolci parole per lo stanco cuor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('252', '1', '3', 'Esse fûr dette da Colui che qui');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('252', '1', '4', 'Sofferse tutto per il peccator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('252', '2', '1', '"Venite a Me". Sì, il sangue di Gesù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('252', '2', '2', 'Può l\'alma vostra appien purificar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('252', '2', '3', 'A chiunque viene a Lui con umil cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('252', '2', '4', 'Perdono e gioia Cristo vuole dar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('252', '3', '1', '"Venite a Me" Sì, il Padre, nel Suo amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('252', '3', '2', 'Attende il peccator da Lui lontan;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('252', '3', '3', 'Appena ei volge ver\' la casa il piè');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('252', '3', '4', 'Corre e lo abbraccia nel Suo amor sovran.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('252', '4', '1', '"Venite a Me". La porta aperta sta,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('252', '4', '2', 'La sola speme per il peccator;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('252', '4', '3', 'Di Cristo sulla croce Dio svelò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('252', '4', '4', 'La grazia Sua, il Suo immenso amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('253', '8.7.8.7.', '24', '80');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('253', '1', '1', 'HAI tu udito la parola');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('253', '1', '2', 'Che il tuo Dio rivolge a te?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('253', '1', '3', 'Vuoi resister all\'appello');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('253', '1', '4', 'Di Sua grazia alla tua fé?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('253', '2', '1', 'Già più volte ti ha parlato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('253', '2', '2', 'Il tuo cuor per conquistar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('253', '2', '3', 'Egli gioia è pronto a darti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('253', '2', '4', 'Le tue colpe a perdonar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('253', '3', '1', 'Or ti chiama un\'altra volta:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('253', '3', '2', 'Il Suo appello può cessar!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('253', '3', '3', 'Vuoi respinger tale grazia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('253', '3', '4', 'La pazienza Sua sprezzar?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('253', '4', '1', 'A Lui volgiti pentito');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('253', '4', '2', 'Il Signore a confessar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('253', '4', '3', 'E venendo al Salvatore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('253', '4', '4', 'Oh, qual gioia puoi provar!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('254', '11.10.11.10.', '52', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('254', '1', '1', 'AI nostri cuor la luce Tua, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('254', '1', '2', 'Porta dal ciel quel che Tu sol puoi dar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('254', '1', '3', 'Te stesso porta, la rivelazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('254', '1', '4', 'D\'eterne gioie: in Te noi già viviam!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('254', '2', '1', 'Noi Ti lodiam! Dei nostri cuor la lode,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('254', '2', '2', 'Benché sì debol, noi a Te rendiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('254', '2', '3', 'Deh, vieni e regna Tu nei nostri cuori:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('254', '2', '4', 'Vivendo nell\'amore, in Dio viviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('254', '3', '1', 'Resta con noi! Nessun pensier terreno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('254', '3', '2', 'S\'iutruda la Tua luce ad offuscar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('254', '3', '3', 'Sii nostra forza! Fa\' che nulla possa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('254', '3', '4', 'Toglierci la Tua grazia d\'apprezzar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('254', '4', '1', 'Sii nostro tutto! All\'amor Tuo supremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('254', '4', '2', 'La mente umana mai non può arrivar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('254', '4', '3', 'Ma per lo Spirto siamo a Te elevati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('254', '4', '4', 'A Te che i nostri cuori sai colmar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('255', '13.13.14.14.', '201', '188');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('255', '1', '1', 'SEI degno, nostro Dio, di lode e d\'ogni onore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('255', '1', '2', 'Tu che ci fai entrar insiem nel Tuo riposo!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('255', '1', '3', 'Tu vuoi riunire in uno e posseder coloro');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('255', '1', '4', 'Che sono l\'opra Tua-piano meraviglioso!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('255', '2', '1', 'L\'amore, in libertà, ricaccia ogni timore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('255', '2', '2', 'In nuovi accenti a Te la lode scaturisce.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('255', '2', '3', 'Come un\'offerta santa eleva il nostro cuore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('255', '2', '4', 'L\'adorazion, che quale incenso Tu gradisci.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('255', '3', '1', 'Ognor riluce, O Dio, la Tua magnificenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('255', '3', '2', 'E il volto di Gesù illumina radioso.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('255', '3', '3', 'Con gioia, l\'alma nostra s\'inchina in Tua presenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('255', '3', '4', 'Per benedire sempre Te, Dio glorïoso.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('255', '4', '1', 'Beato e sol Sovran, lo Stesso, il Dio vivente,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('255', '4', '2', 'Tua gloria e Tua maestà risplendon su di noi.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('255', '4', '3', 'In noi Tu Ti compiaci, poiché sovranamente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('255', '4', '4', 'Per esser tutto in tutti, in Cristo unisci i Tuoi.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('256', '7.6.7.6.7.6.7.6.', '34', '97');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '1', '1', 'AL fianco Tuo trafitto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '1', '2', 'Ci tieni ognor vicin:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '1', '3', 'Là sol rifugio e pace');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '1', '4', 'Troviam, Agnel divin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '1', '5', 'Intorno v\'è il nemico,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '1', '6', 'Fallace è il nostro cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '1', '7', 'Ma sol la grazia Tua');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '1', '8', 'Serbarci può, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '2', '1', 'Se in Te ci nascondiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '2', '2', 'Sicuri ci sentiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '2', '3', 'In Te sol dimorando');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '2', '4', 'La lotta sosteniam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '2', '5', 'Il braccio Tuo riporta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '2', '6', 'Per noi vittoria ognor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '2', '7', 'E, dal Tuo amor sorretto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '2', '8', 'Conforto ha il nostro cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '3', '1', 'Ben presto faccia a faccia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '3', '2', 'Noi Te contemplerem;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '3', '3', 'Tua gloria, Tua potenza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '3', '4', 'Tua grazia canterem.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '3', '5', 'Signor, la Tua bellezza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '3', '6', 'H Tuo divino amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '3', '7', 'Celebreran con gioia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('256', '3', '8', 'I santi Tuoi ognor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('257', '12.11.12.11.', '33', '69');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('257', '1', '1', 'OH, come il Dio nostro compiacesi a dare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('257', '1', '2', 'Le benedizioni Sue ricche, in amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('257', '1', '3', 'Ché, per sodisfare i diritti del trono,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('257', '1', '4', 'Il Suo sangue Cristo sul legno versò!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('257', '2', '1', 'Le buone novelle di pace e perdono');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('257', '2', '2', 'In Sua parola Dio stesso fa udir;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('257', '2', '3', 'Aperta è la via pel ravvedimento:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('257', '2', '4', 'Ricchezze di grazia può in Cristo largir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('257', '3', '1', 'E pur conosciam, per il don dello Spirto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('257', '3', '2', 'La fonte di gioia e di forza quaggiù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('257', '3', '3', 'Così, liberati dal mondo, eleviamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('257', '3', '4', 'Di cuor la Sua lode, mediante Gesù.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('258', '11.11.6.11.11.6.', '195', '32');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('258', '1', '1', 'O NOSTRO Dio, da Te in divino amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('258', '1', '2', 'Grandezza e gloria brillano, e splendore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('258', '1', '3', 'Potenza e maestà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('258', '1', '4', 'Capo supremo, il Nome Tuo lodiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('258', '1', '5', 'E con volonterosi cuori diamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('258', '1', '6', 'Adorazione a Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('258', '2', '1', 'In verità e spirto noi cantiamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('258', '2', '2', 'L\'adorazione nostra a Te apportiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('258', '2', '3', 'Perfetta in santità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('258', '2', '4', 'Nello splendor divino del Tuo volto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('258', '2', '5', 'Noi, conoscendo in Cristo il nostro posto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('258', '2', '6', 'Nel Nome Tuo esultiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('258', '3', '1', 'In sua bellezza e luce prezïosa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('258', '3', '2', 'Adorna in gloria fulgida qual sposa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('258', '3', '3', 'Risplende la città.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('258', '3', '4', 'L\'eternità è in vista, e Tu che puoi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('258', '3', '5', 'Far ogni cosa nuova, tutto vuoi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('258', '3', '6', 'In sommo amor scrutar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('259', '7.6.7.6.7.6.7.6.', '34', '126');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '1', '1', 'SIGNOR Gesù, se\' il Centro');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '1', '2', 'Del mondo di splendor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '1', '3', 'Ove non è peccato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '1', '4', 'Non pianto né dolor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '1', '5', 'Ma dove regna amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '1', '6', 'E gioia senza fin:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '1', '7', 'Tu sei di tutto il Capo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '1', '8', 'Tu che soffristi qui.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '2', '1', 'Di Deità pienezza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '2', '2', 'Gesù, dimora in Te');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '2', '3', 'E dell\'eccelsa gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '2', '4', 'Signor, ben degno se\'.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '2', '5', 'Negli alti cieli asceso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '2', '6', 'Sul trono Ti vediam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '2', '7', 'Sei Capo d\'ogni cosa:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '2', '8', 'In Te compiuti siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '3', '1', 'Con Te, Signore e Capo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '3', '2', 'Per grazia parte abbiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '3', '3', 'A Te la chiesa è unita,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '3', '4', 'Sì, uno Teco siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '3', '5', 'Qual Uomo nella gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '3', '6', 'Asceso, sei suprem.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '3', '7', 'Tue glorie e Tua Persona');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('259', '3', '8', 'Per sempre canterem.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('260', '11.10.11.10.', '52', '78');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('260', '1', '1', 'O BENEDETTO Spirto, Ti lodiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('260', '1', '2', 'Un inno a Te veniamo ad inalzar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('260', '1', '3', 'Tu con noi sei, ognor in noi dimori');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('260', '1', '4', 'E i nostri cuori guidi ad adorar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('260', '2', '1', 'La Tua presenza l\'alme nostre muove');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('260', '2', '2', 'E quali figli al Padre noi veniam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('260', '2', '3', 'Adito a Lui in Cristo ci vien dato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('260', '2', '4', 'Ed or con Cristo al Padre noi cantiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('261', '10.10.10.10.6.', '167', '191');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('261', '1', '1', 'O SPIRTO benedetto, a Te cantiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('261', '1', '2', 'Tu fonte sei di vita e libertà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('261', '1', '3', 'Sorgenti di rinfresco noi gustiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('261', '1', '4', 'Che son dal ciel; Tua grazia conosciam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('261', '1', '5', 'Inesprimibil Don!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('261', '2', '1', 'Tu nella gloria della Deità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('261', '2', '2', 'Sei uno con il Padre e col Figliol,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('261', '2', '3', 'In luce non creata Tu a Lor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('261', '2', '4', 'Eguale sei di gloria nel fulgor-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('261', '2', '5', 'Sei Dio: noi T\'adoriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('261', '3', '1', 'Prezioso è il Tuo servizio che l\'amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('261', '3', '2', 'Di Dio effonde dentro ai nostri cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('261', '3', '3', 'Fra i molti che Tu guidi, noi possiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('261', '3', '4', 'Trovar la nostra parte in libertà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('261', '3', '5', 'Di Dio figlioli siam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('262', '11.10.11.10.10.10.', '180', '189');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('262', '1', '1', 'O SOMMO Dio che opri meraviglie,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('262', '1', '2', 'Tua gloria brilla nel creato inter,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('262', '1', '3', 'Ma nella grazia Tua che dà il perdono');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('262', '1', '4', 'Più vediam splender la Tua gloria inver.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('262', '1', '5', 'Chi come Te, o Dio, sa perdonar?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('262', '1', '6', 'Nella Tua grazia la Tua gloria appar!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('262', '2', '1', 'Pieni di santa gioia e meraviglia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('262', '2', '2', 'O Dio, il Tuo perdono celebriam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('262', '2', '3', 'Nel sangue da Gesù per noi versato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('262', '2', '4', 'Perdon per ogni colpa riceviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('262', '2', '5', 'Misericordia e grazia sono in Te:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('262', '2', '6', 'Tu sol dài tal perdono per la fé.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('262', '3', '1', 'Presto sarà la terra tutta piena');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('262', '3', '2', 'Di questo Tuo miracolo d\'amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('262', '3', '3', 'Mentre i Tuoi santi, in cielo radunati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('262', '3', '4', 'Tue lodi canteranno in lieto cor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('262', '3', '5', 'Chi come Te, o Dio, sa perdonar?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('262', '3', '6', 'Nella Tua grazia la Tua gloria appar!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('263', '9.8.9.8.9.8.9.8. Dattilico.', '125', '126');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('263', '1', '1', 'TUA morte, Signor, le Tue pene');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('263', '1', '2', 'Han detto il divino Tuo amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('263', '1', '3', 'Gli abissi profondi sondasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('263', '1', '4', 'Nel Tuo abbassamento, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('263', '1', '5', 'L\'immenso, insondato Tuo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('263', '1', '6', 'L\'obbrobrio al Calvario mostrò:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('263', '1', '7', 'A noi qual unguento è il Tuo Nome,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('263', '1', '8', 'Preziosa la via Tua d\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('263', '2', '1', 'Ed or che Tu sei nella gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('263', '2', '2', 'Rimane lo stesso il Tuo amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('263', '2', '3', 'Come allor che la sua pienezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('263', '2', '4', 'In mezzo al peccato brillò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('263', '2', '5', 'L\'amor Tuo su tutto trionfante');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('263', '2', '6', 'Di essere Tuoi ci donò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('263', '2', '7', 'Ché fu nella morte provato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('263', '2', '8', 'D\'amore divino il valor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('264', '10.10.10.10.', '21', '83');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('264', '1', '1', '"TU sei lo Stesso", nostro Dio, che stai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('264', '1', '2', 'Tanto al di sopra del ruggente mar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('264', '1', '3', 'Con Te per rocca e forza, noi potrem,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('264', '1', '4', 'Malgrado i flutti, il porto alfin toccar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('264', '2', '1', 'Se per la via le lacrime, il dolor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('264', '2', '2', 'E scene di tristezza noi troviam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('264', '2', '3', 'Sappiam che il tempo sarà breve ancor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('264', '2', '4', 'E la mestizia in canti volgerà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('264', '3', '1', 'Quaggiù soffriam, e pur Ti ringraziam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('264', '3', '2', 'Ché, nelle pene, Tu sei più vicin:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('264', '3', '3', 'Tu tocchi i Tuoi con la Tua dolce man');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('264', '3', '4', 'E volgi la lor notte nel mattin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('264', '4', '1', 'Come potrem le lodi Tue cantar?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('264', '4', '2', 'Ne son indegni i nostri umani cuor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('264', '4', '3', 'Pur per lo Spirto a Te ci avviciniam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('264', '4', '4', 'E Ti rechiam la nostra adorazion.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('265', '8.8.8,8.8.8.8.7.', '150', '73');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '1', '1', 'DIO di grazia, Padre nostro,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '1', '2', 'Il \'l‘uo Nome noi lodiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '1', '3', 'E da Te santificati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '1', '4', 'Il favore Tuo godiamo.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '1', '5', 'Tu, nel Tuo profondo amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '1', '6', 'Nel deserto ci hai cercati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '1', '7', 'E al riposo ci hai portati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '1', '8', 'Della casa Tua nel ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '2', '1', 'Prima ancor che il mondo fosse');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '2', '2', 'Nel Tuo Cristo ci scegliesti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '2', '3', 'E, svolgendo i Tuoi consigli,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '2', '4', 'Tuoi figlioli ci facesti.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '2', '5', 'Nel diletto Tuo Figliolo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '2', '6', 'Or a Te vicini siamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '2', '7', 'E con Lui noi Ti lodiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '2', '8', 'Da Lui resi degni appien.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '3', '1', 'Padre nostro, T\'adoriamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '3', '2', 'Presto tutti i Tuoi saranno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '3', '3', 'Nella casa Tua gloriosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '3', '4', 'Ove gioia piena avranno;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '3', '5', 'Or in santa adorazione,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '3', '6', 'Mentre noi quel dì attendiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '3', '7', 'Le Tue lodi già cantiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('265', '3', '8', 'E gioiamo nel Tuo amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('266', '12.11.12.11.', '33', '15');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('266', '1', '1', 'O STANCHI, aggravati, udite la voce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('266', '1', '2', 'Di Cristo che chiama: Venite a Me,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('266', '1', '3', 'Io v\'offro il riposo, la gioia, la pace.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('266', '1', '4', 'O anima stanca, l\'invito è per te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('266', '2', '1', 'In gloria Egli siede sul trono nel cielo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('266', '2', '2', 'Ma pure ti parla con voce d\'amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('266', '2', '3', 'Se presti l\'orecchio per fede udirai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('266', '2', '4', 'Gli accenti di grazia del Dio Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('266', '3', '1', 'Ei t\'offre il perdono, Ei t\'offre la vita,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('266', '3', '2', 'La gioia e la pace che sono in Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('266', '3', '3', 'Per te non vi è costo, è il dono di Dio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('266', '3', '4', 'Più nulla rimane che possa far tu.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('266', '4', '1', 'Ascolta la voce che ancora ti chiama,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('266', '4', '2', 'Ben presto l\'invito cessare dovrà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('266', '4', '3', 'Se tu prontamente ti volgi al Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('266', '4', '4', 'Eterno rifugio il tuo cuor troverà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('267', '10.9.10.9.10.9.10.9.', '177', '214');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('267', '1', '1', 'A TE gloria ed adorazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('267', '1', '2', 'Sempre sian, divino Signor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('267', '1', '3', 'Noi, primizie di Tua creazione,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('267', '1', '4', 'A Te lode rendiam ed onor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('267', '1', '5', 'Re di gloria, possente Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('267', '1', '6', 'Della morte Tu sei Vincitor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('267', '1', '7', 'Vaste schiere a Te cadon davanti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('267', '1', '8', 'Presto tutti diran Te Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('267', '2', '1', 'L\'Invisibile ci hai dichiarato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('267', '2', '2', 'In Te piena dimora Deità;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('267', '2', '3', 'Tuo soltanto è quel posto di gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('267', '2', '4', 'Alla destra dell\'alta Maestà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('267', '2', '5', 'Circondato di adoratori,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('267', '2', '6', 'Sei supremo, Signore, fin d\'or:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('267', '2', '7', 'Primo sempre sarai sulla stirpe');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('267', '2', '8', 'Celestial che a Te rende l\'onor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('268', '11.10.11.10.', '52', '121');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('268', '1', '1', 'SIGNORE, Tu fissasti fermamente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('268', '1', '2', 'Il volto Tuo la morte ad incontmr');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('268', '1', '3', 'E, in mezzo all\'odio che dall\'uom avesti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('268', '1', '4', 'Di Dio la volontà volesti far.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('268', '2', '1', 'Offerta pura, tutto Ti donasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('268', '2', '2', 'Là dove l\'uom ribelle si mostrò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('268', '2', '3', 'E qual fragrante incenso ascese a Dio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('268', '2', '4', 'Del sacrificio Tuo il soave odor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('268', '3', '1', 'La coppa d\'amarezza Tu bevesti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('268', '3', '2', 'Ognun dei Tuoi seguaci Ti lasciò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('268', '3', '3', 'Del tutto solo Tu sul legno fosti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('268', '3', '4', 'Quando il Suo volto Dio da Te celò!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('268', '4', '1', 'In Te, divino Uomo glorïoso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('268', '4', '2', 'Di Dio compito tutto il piano fu;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('268', '4', '3', 'Ché tutto quello ch\'Ei dall\'uom cercava');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('268', '4', '4', 'Gli assicurasti Tu, Signor Gesù.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('269', '11.10.11.10.', '52', '211');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('269', '1', '1', 'A TE, Gesù, dall\'arido deserto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('269', '1', '2', 'Tu ci hai chiamati nel divin Tuo amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('269', '1', '3', 'Di pan vivente le nostr\'alme cibi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('269', '1', '4', 'A noi Tu sei Maestro e sei Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('269', '2', '1', 'Signore e Cristo Ti riconosciamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('269', '2', '2', 'Tu nel bisogno ci soccorri ognor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('269', '2', '3', 'Deh, lungo le acque vive ognor ci guida');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('269', '2', '4', 'E tienci a Te vicini, buon Pastor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('269', '3', '1', 'Ed ora nel santuario Tuo, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('269', '3', '2', 'Apprender noi bramiamo il Tuo voler');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('269', '3', '3', 'Con cuori al Santo Spirito soggetti:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('269', '3', '4', 'Ci dona la Tua faccia di veder.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('270', '9.8.9.8. Giambico.', '161', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '1', '1', 'DUNQUE il Tuo volto un dì vedremo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '1', '2', 'La voce Tua potremo udir');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '1', '3', 'Che già, Signor, qui conosciamo?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '1', '4', 'Il nostro cuor può ben gioir!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '2', '1', 'Allor con Te cammineremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '2', '2', 'In bianche vesti, e in quel fulgor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '2', '3', 'Di tutte le Tue sofferenze');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '2', '4', 'Con Te converserem, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '3', '1', 'Stretti al Tuo fianco in comunione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '3', '2', 'Divina, che mai fine avrà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '3', '3', 'Le glorie Tue contempleremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '3', '4', 'Che niuna nube oscurerà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '4', '1', 'Noi siamo i frutti del Tuo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '4', '2', 'Che Ti condusse qui a morir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '4', '3', 'Ed a Te accanto proveremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '4', '4', 'Che Tu ci ami ancor così;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '5', '1', 'E benché deboli, fin d\'ora');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '5', '2', 'All\'amor Tuo noi rispondiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '5', '3', 'Pel Tuo dolor e la Tua croce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '5', '4', 'Portati a Te vicini siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '6', '1', 'Il Tuo ritorno noi bramiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '6', '2', 'Ma già quaggiù Ti conosciam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '6', '3', 'Ché nei cuor nostri Tu dimori-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '6', '4', 'La gioia del Tuo amor gustiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '7', '1', 'Ma pur bramiamo di vederti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '7', '2', 'Così qual sei, Gesù Signor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '7', '3', 'Allor con Te saremo sempre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('270', '7', '4', 'E T\'amerem con tutto il cuor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('271', '11.10.11.10.', '52', '146');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '1', '1', 'MENTRE il deserto ardente traversiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '1', '2', 'Le orme Tue troviam, Signor Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '1', '3', 'E conoscendo che il Dio nostro è luce,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '1', '4', 'Verso la méta Ti seguiam lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '2', '1', 'Tu ci conduci pel cammin scabroso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '2', '2', 'Ad ogni passo consci del Tuo amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '2', '3', 'Amor fedel, che nulla può cambiare-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '2', '4', 'Tu ci sorreggi con Tua man, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '3', '1', 'Se pure noi sovente ci stanchiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '3', '2', 'Tu non Ti stanchi mai, divin Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '3', '3', 'E ci sostieni con la Tua parola');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '3', '4', 'Fresca ogni giorno per il nostro cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '4', '1', 'Pur l\'acque della morte, a noi sì amare,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '4', '2', 'Con la Tua morte raddolcisti Tu;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '4', '3', 'Puro e divin rinfresco Tu ci dài');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '4', '4', 'Che noi godiam con Te, Signor Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '5', '1', 'Quel che ci occorre tutto Tu provvedi:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '5', '2', 'La manna e il pozzo che zampilla ognor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '5', '3', 'E a noi d\'Escol il grappolo rivela');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('271', '5', '4', 'Dove la via conduce, Salvator.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('272', '11.10.11.10.', '52', '86');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('272', '1', '1', 'ALLOR che la Tua croce, Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('272', '1', '2', 'Contemplo con lo sguardo della fé,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('272', '1', '3', 'Tutta la gloria, tutta la ricchezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('272', '1', '4', 'Del mondo impallidisce innanzi a Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('272', '2', '1', 'Oh, di che cosa mai potrei gloriarmi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('272', '2', '2', 'Se non della Tua croce, mio Signor?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('272', '2', '3', 'Tutto quel che ho più caro in questo mondo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('272', '2', '4', 'Al Tuo confronto non ha più valor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('272', '3', '1', 'Dal fianco Tuo, dai piedi, dalle mani,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('272', '3', '2', 'Col sangue scorre l\'infinito amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('272', '3', '3', 'E vedo una corona glorïosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('272', '3', '4', 'Nel serto Tuo di spine e di dolor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('272', '4', '1', 'Di Te un\'offerta degna non sarebbe');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('272', '4', '2', 'Se fosse l\'universo in mio poter:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('272', '4', '3', 'La vita mia, la mente ed il mio tutto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('272', '4', '4', 'L\'amor richiede, per il suo piacer.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('273', '9.8.9.8.9.8.9.8. Giambico.', '137', '122');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '1', '1', 'CHE Salvator meraviglioso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '1', '2', 'Abbiamo nel Signor Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '1', '3', 'Di Dio Figlio glorïoso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '1', '4', 'Che venne per morir quaggiù!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '1', '5', 'Di Dio la gloria Egli mantenne');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '1', '6', 'Quando il Suo sangue per noi diè,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '1', '7', 'Eterna è l\'opra ch\'Egli fece,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '1', '8', 'Che sempre liberi ci fe\'.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '2', '1', 'Or per quel sangue è offerto in dono,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '2', '2', 'Per fede in Cristo Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '2', '3', 'Il Suo favore e il Suo perdono');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '2', '4', 'A chi confessa Lui Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '2', '5', 'O peccator, guarda al Calvario');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '2', '6', 'Ove il Signor per te morì,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '2', '7', 'Sopportò l\'ira a te dovuta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '2', '8', 'E la vittoria conseguì.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '3', '1', 'Or Cristo è in ciel, glorificato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '3', '2', 'E da quel luogo di splendor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '3', '3', 'Il Santo Spirito ha mandato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '3', '4', 'A dimorar nei nostri cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '3', '5', 'Ed a chi crede ed ubbidisce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '3', '6', 'Dio questo Dono è pronto a dar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '3', '7', 'Che a noi le glorie del Figliolo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('273', '3', '8', 'Or Si compiace d\'annunziar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('274', '6.7.11.11.6.', '139', '149');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '1', '1', 'VIENI, Signor Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '1', '2', 'A prendere il Tuo posto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '1', '3', 'Di Figlio d\'uomo, d\'ogni canto tema!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '1', '4', 'Vieni, Signore, per regnar supremo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '1', '5', 'Vieni, Signor Gesù!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '2', '1', 'Vieni, Signor Gesù!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '2', '2', 'Un dì Uom di dolori,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '2', '3', 'Or, nell\'attesa, Uomo di pazienza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '2', '4', 'Uomo di gioia Tu sarai per sempre:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '2', '5', 'Vieni, Signor Gesù!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '3', '1', 'Vieni, Signor Gesù!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '3', '2', 'Ogni ginocchio pieghi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '3', '3', 'Confessi ogni lingua Te il Signore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '3', '4', 'Sopra ogni cosa, sceso a benedire:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '3', '5', 'Vieni, Signor Gesù!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '4', '1', 'Vieni, Signor Gesù!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '4', '2', 'Lo Spirito e la sposa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '4', '3', 'Insieme dicon: "Vieni! " e pur Tu stesso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '4', '4', 'Dal cielo hai detto: "Ecco, vengo presto! "');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('274', '4', '5', 'Amen, Signor Gesù!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('275', '11.10.11.10.', '52', '51');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('275', '1', '1', 'TUTTI han peccato, dice la Scrittura,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('275', '1', '2', 'Non v\'è nessuno giusto, neppur un,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('275', '1', '3', 'Il peso delle colpe e del peccato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('275', '1', '4', 'Grava sulla coscienza di ciascun.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('275', '2', '1', 'V\'è un solo Mediator fra Dio e l\'uomo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('275', '2', '2', 'Cristo, che sulla morte trionfò:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('275', '2', '3', 'Egli morì e risorse, ed il Suo Nome');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('275', '2', '4', 'E\' il sol che può salvare il peccator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('275', '3', '1', 'Egli, il Signor di gloria, diè il Suo sangue');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('275', '3', '2', 'Per compier l\'opra della redenzion');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('275', '3', '3', 'Ed or chiunque viene a Lui per fede');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('275', '3', '4', 'Riceve grazia ed il divin perdon.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('275', '4', '1', 'Or, suggellati dallo Spirto Santo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('275', '4', '2', 'Cristo attendiam, lo Sposo, che verrà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('275', '4', '3', 'Prendendo a Sé la sposa Sua diletta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('275', '4', '4', 'Che il trono Suo condividerà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('276', '11.4.11.4.11.10.', '197', '51');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '1', '1', 'NON hai udito il suono del vangelo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '1', '2', 'Di carità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '1', '3', 'Di salvazion, di pace, di perdono,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '1', '4', 'Di libertà?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '1', '5', 'Di Dio la parola hai tu creduto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '1', '6', 'Hai ricevuto il santo Suo Figliol?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '2', '1', 'Non t\'attardar ché pieno di spavento');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '2', '2', 'S\'affretta un dì:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '2', '3', 'Corri al rifugio che Gesù t\'ha dato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '2', '4', 'Morendo qui.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '2', '5', 'Salvezza è in Lui che il sangue Suo ha versato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '2', '6', 'Che glorïoso or è risorto in ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '3', '1', 'Non vuoi tu dunque in Cristo, ed in Lui solo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '3', '2', 'Appien fidar?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '3', '3', 'Perché morire Lui se l\'opre tue');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '3', '4', 'Potean salvar?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '3', '5', 'Riguarda a Lui: su Sé il giudizio prese,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '3', '6', 'Disse: "E\' compiuto". Coronato è or!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '4', '1', 'Or, pronto per la gloria, innanzi a Lui');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '4', '2', 'Puoi camminar-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '4', '3', 'Compiuto in Lui, dal sangue avvicinato-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '4', '4', 'Partecipar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '4', '5', 'D\'una celeste stirpe; e, per Sua grazia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('276', '4', '6', 'Lo puoi servire qui con pio timor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('277', '10.9.10.9.10.9.10.9.', '177', '51');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '1', '1', 'DIO e Padre, di cuor T\'adoriamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '1', '2', 'Rivelato in Cristo, il Figliol,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '1', '3', 'Nella Tua presenza esultiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '1', '4', 'Per quell\'opera ch\'Ei compì sol.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '1', '5', 'Sei l\'Eterno, per sempre lo Stesso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '1', '6', 'Di Tua lode ricolmi noi siam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '1', '7', 'E con cuori adoranti a Te innanzi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '1', '8', 'Il Tuo Nome noi magnifichiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '2', '1', 'Lode, gloria ed adorazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '2', '2', 'A Te render, O Dio, vogliam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '2', '3', 'Ché la profondità e l\'altezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '2', '4', 'Del Tuo amore supremo vediam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '2', '5', 'La Tua gloria perfetta risplende');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '2', '6', 'Nel Figliolo, nel Cristo Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '2', '7', 'Che di redenzïone la gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '2', '8', 'Acquistò nel morire quaggiù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '3', '1', 'Per lo Spirito già Lo vediamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '3', '2', 'Il Tuo oggetto d\'amore, Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '3', '3', 'Sommo tema dell\'adorazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '3', '4', 'Nella scena di gioia lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '3', '5', 'Per Tua grazia da Te siam chiamati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '3', '6', 'La Tua gioia a partecipar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '3', '7', 'A conoscer il Tuo segreto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('277', '3', '8', 'Che ora all\'uom Ti diletti svelar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('278', '10.9.10.9.', '114', '97');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '1', '1', 'TE, Signore, vogliamo seguire:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '1', '2', 'Nei cuor nostri, deh, opera Tu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '1', '3', 'Sì che nulla qui in terra ci attiri');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '1', '4', 'E da Te ci allontani, Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '2', '1', 'Dal Tuo sangue prezioso redenti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '2', '2', 'A Te sempre, Gesù, apparteniam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '2', '3', 'E, per grazia ed amore divini,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '2', '4', 'Di Dio figli ed eredi noi siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '3', '1', 'Or lo Spirto, suggello d\'amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '3', '2', 'Che dal Padre mandato qui fu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '3', '3', 'Dimorando qui in noi, ci rivela');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '3', '4', 'Il riposo glorioso lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '4', '1', 'Or di là dalla tomba Tu vivi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '4', '2', 'In Te liberi siamo, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '4', '3', 'Ed uniti a Te per Tua grazia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '4', '4', 'Vita abbiamo e pace e valor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '5', '1', 'Deh, c\'insegna a conoscerti meglio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '5', '2', 'Ché con Te siam risorti, Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '5', '3', 'Sì che, mentre ancor qui sulla terra,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('278', '5', '4', 'Nostra vita, Signore, sia Tu.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('279', '9.8.9.8. Dattilico.', '112', '27');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '1', '1', 'GESU\', di dolcezza ci colma');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '1', '2', 'A Te pur il solo pensar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '1', '3', 'Ma tanto più dolce è vederti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '1', '4', 'E presso di Te riposar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '2', '1', 'Non può voce umana cantare,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '2', '2', 'Né può immaginare alcun cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '2', '3', 'Un suono più dolce del santo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '2', '4', 'Tuo Nome, divin Salvator!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '3', '1', 'La speme del cuore contrito,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '3', '2', 'La gioia dell\'umile Tu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '3', '3', 'Con quale dolcezza rispondi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '3', '4', 'A quei che Ti cercan, Gesù!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '4', '1', 'Sol quelli che T\'hanno trovato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '4', '2', 'Conoscon l\'immenso gioir');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '4', '3', 'Del don dell\'amor Tuo divino:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '4', '4', 'Nessun quell\'amor può ridir!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '5', '1', 'Gesù, nostra sola letizia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '5', '2', 'Il nostro sol premio in Te sta:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '5', '3', 'Tu sei nostra gloria al presente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('279', '5', '4', 'E sempre, per l\'eternità.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('280', '10.10.10.10.', '21', '214');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('280', '1', '1', 'UN inno a Te, Signor Gesù, leviam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('280', '1', '2', 'D\'un cuore e d\'una voce a Te cantiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('280', '1', '3', 'Assorti nella somma Tua beltà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('280', '1', '4', 'A Te sia onor, potenza e maestà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('280', '2', '1', 'Oh, quale amore provi Tu, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('280', '2', '2', 'Per la Tua sposa, oggetto del Tuo cuor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('280', '2', '3', 'Per lei completa gioia è nel saper');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('280', '2', '4', 'D\'esser per Te, pel solo Tuo piacer.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('280', '3', '1', 'Da Te proviene, al fianco Tuo sarà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('280', '3', '2', 'La Tua compagna in somma maestà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('280', '3', '3', 'Nel pieno godimento del Tuo amor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('280', '3', '4', 'Per lei su tutto Capo sei, Signor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('281', '9.8.9.8. Dattilico.', '112', '97');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('281', '1', '1', 'GESU\', Salvatore, sei mio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('281', '1', '2', 'Del Padre sei il dono d\'amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('281', '1', '3', 'Tu stesso, e l\'opera Tua,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('281', '1', '4', 'Mi colman di giubilo il cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('281', '2', '1', 'Or, povero e debol qual sono,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('281', '2', '2', 'Mi glorio nel Tuo Nome ognor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('281', '2', '3', 'Dal sangue Tuo purificato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('281', '2', '4', 'Son giusto per Dio, o Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('281', '3', '1', 'In Te le mie fonti si trovan,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('281', '3', '2', 'La Tua pienezza è per me;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('281', '3', '3', 'In Te io possiedo ogni cosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('281', '3', '4', 'E vivo soltanto per Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('281', '4', '1', 'Oh tienimi, mio Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('281', '4', '2', 'Vicino al Tuo fianco fedel;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('281', '4', '3', 'Tu grazia su grazia mi doni');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('281', '4', '4', 'Finché il volto Tuo vedrò in ciel.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('282', '7.6.7.6.7.6.7.6.', '34', '51');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '1', '1', 'DIO diede il Suo Figliolo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '1', '2', 'Gesù per noi morì');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '1', '3', 'E l\'opra glorïosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '1', '4', 'Di redenzion compì.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '1', '5', 'Leviamo a Lui la voce,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '1', '6', 'Noi che salvati siam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '1', '7', 'Lodiamo il Salvatore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '1', '8', 'E il Nome Suo onoriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '2', '1', 'A Lui la gloria sia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '2', '2', 'Ché nel Suo grande amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '2', '3', 'Portò la salvazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '2', '4', 'All\'uomo peccator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '2', '5', 'Risorto e trionfante,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '2', '6', 'Ei vive sempre in ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '2', '7', 'Eterna gloria sia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '2', '8', 'A Cristo, al santo Agnel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '3', '1', 'Lavàti col Suo sangue,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '3', '2', 'Noi tutto a Lui dobbiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '3', '3', 'Eredi della gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '3', '4', 'Etemamente siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '3', '5', 'Leviamo a Lui la voce,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '3', '6', 'Noi che salvati siam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '3', '7', 'Lodiamo il Salvatore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('282', '3', '8', 'E il Nome Suo onoriam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('283', '11.10.11.10.', '52', '205');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('283', '1', '1', 'LIBERI nella santa Tua presenza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('283', '1', '2', 'A Te, Signor, con gioia rispondiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('283', '1', '3', 'Noi Tuoi fratelli per Tua grazia siamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('283', '1', '4', 'E santa intimità con Te gustiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('283', '2', '1', '"I miei fratelli" Tu, Signor, dicesti:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('283', '2', '2', 'Oh, qual gloriosa luce noi godiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('283', '2', '3', 'Mentre, recando gioia al cuore Tuo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('283', '2', '4', 'In vicinanza, un canto a Te leviam!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('283', '3', '1', 'Noi Ti lodiam, Signore benedetto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('283', '3', '2', 'All\'amor Tuo con gioia rispondiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('283', '3', '3', 'E, lieti che il Tuo cuore è sodisfatto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('283', '3', '4', 'Del ciel le gioie già con Te gustiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('284', '14.14.14.14.', '85', '162');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('284', '1', '1', '"NON son del mondo", furon le parole di Gesù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('284', '1', '2', 'Dei pochi che seguivan la Persona Sua quaggiù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('284', '1', '3', 'Or dette son di noi, che pellegrini in terra siam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('284', '1', '4', 'O Padre, e ci attiran alla sfera. del Tuo pian.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('284', '2', '1', '"Non son del mondo"-per Te stesso, Padre pien d\'amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('284', '2', '2', 'Col Suo prezioso sangue Ei dal mondo ci acquistò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('284', '2', '3', 'I passi Suoi seguendo, ora noi possiam cantar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('284', '2', '4', '"Non son del mondo" i santi: oh, gioiosa verità!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('284', '3', '1', '"Non son del mondo", qual preziosa pace, qual desir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('284', '3', '2', 'Riposo e forza, stanno in questo benedetto dir!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('284', '3', '3', 'Stranieri in terra, la cittadinanza nostra è in ciel:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('284', '3', '4', 'Oh, possa tal certezza su di noi brillare appien!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('284', '4', '1', 'O Padre, insegna in grazia, Ti preghiamo, ai nostri cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('284', '4', '2', 'A non cercare nulla qui dove non è il Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('284', '4', '3', 'Ma fa\' che nel deserto noi possiam cantar con fè:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('284', '4', '4', 'I Tuoi "non son del mondo", le lor fonti sono in Te.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('285', '11.10.11.10.', '52', '182');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('285', '1', '1', 'O GLORЇOSO Spirto benedetto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('285', '1', '2', 'Con cuor riconoscenti T\'adoriam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('285', '1', '3', 'Pel Tuo potere noi l\'amor di Cristo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('285', '1', '4', 'Or conosciamo e Lui servir possiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('285', '2', '1', 'Sì, Tu sei Dio, o Santo, e pur non visto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('285', '2', '2', 'Ben conosciuto sei ai nostri cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('285', '2', '3', 'Tu stesso sei il legame che congiunge');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('285', '2', '4', 'A Gesù Cristo i santi Suoi ognor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('285', '3', '1', 'E pur tra il Padre e il Figlio sei il legame-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('285', '3', '2', 'Misterïosa e santa verità! -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('285', '3', '3', 'Con Loro etemamente coeguale,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('285', '3', '4', 'Uno nella gloriosa Deità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('285', '4', '1', 'Grati, alla Tua Persona benedetta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('285', '4', '2', 'Con cuori riverenti c\'inchiniam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('285', '4', '3', 'Spirito benedetto, T\'adoriamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('285', '4', '4', 'Ed un gioioso canto T\'eleviam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('286', '11.10.11.10.11.10.11.10.', '183', '73');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '1', '1', 'QUAL ricco, eterno cantico di lode');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '1', '2', 'Nei giorni senza fine colmerà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '1', '3', 'Quelle dimore fulgide, celesti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '1', '4', 'Allor che il tempo più non vi sarà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '1', '5', 'Attorno attorno sgorgheran le note-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '1', '6', 'Ogni redento unisce al grande cor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '1', '7', 'La voce sua, per celebrar l\'amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '1', '8', 'Tuo tanto vasto e tanto pien, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '2', '1', 'Ognuno porterà la somiglianza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '2', '2', 'Del Salvator gloriosa, e recherà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '2', '3', 'Una regal corona sulla fronte,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '2', '4', 'La veste bianca immacolata avrà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '2', '5', 'Il canto che giammai non prende fine');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '2', '6', 'Per Te, Agnel di Dio, per Te sarà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '2', '7', 'In scene risplendenti della luce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '2', '8', 'Più pura, ove Tua gloria brillerà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '3', '1', 'La nostra gioia senza impedimenti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '3', '2', 'Con Te godrem allor, e mirerem');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '3', '3', 'Con occhi non velati la Tua gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '3', '4', 'Mentre una degna lode renderem.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '3', '5', 'Ed or che quel mattino senza nubi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '3', '6', 'Noi attendiam, Signor, vogliamo dir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '3', '7', 'Con cuori ardenti, con rapita voce:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('286', '3', '8', 'Alfin che noi vivessimo, Ei morì!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('287', '11.10.11.10.', '52', '35');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('287', '1', '1', 'O NOME di Gesù che dà la vita,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('287', '1', '2', 'Fonte di gioia per la terra e il ciel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('287', '1', '3', 'Altro non v\'è che sia simìle al Nome');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('287', '1', '4', 'Di Lui che qui sofferse come Agnel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('287', '2', '1', 'Dalle sue colpe ottien liberazione,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('287', '2', '2', 'Quando quel Nome ascolta, il peccator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('287', '2', '3', 'Il suo dolor si muta in somma gioia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('287', '2', '4', 'Ed un gioioso canto eleva allor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('287', '3', '1', 'Gesù, il Tuo Nome è sopra d\'ogni nome.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('287', '3', '2', 'Noi Ti lodiamo pel Tuo grande amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('287', '3', '3', 'Che Ti condusse qui a morir per noi:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('287', '3', '4', 'Risorto or sei, glorioso Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('287', '4', '1', 'Presto, Signore, l\'universo intero');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('287', '4', '2', 'Il Nome Tuo con gioia loderà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('287', '4', '3', 'E dei Tuoi santi allor l\'immenso coro');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('287', '4', '4', 'Di lodi cielo e terra colmerà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('288', '10.9.10.9.', '114', '9998');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '1', '1', 'I CUOR nostri Tu guidi e consoli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '1', '2', 'Mentre ancor sei assente, Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '1', '3', 'Ché il Tuo Spirto e la Tua parola');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '1', '4', 'Con gli eletti dimoran quaggiù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '2', '1', 'La Tua voce si fa sempre udire:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '2', '2', 'La rivela lo Spirito a noi;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '2', '3', 'Ei ci aiuta a comprenderla, e in grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '2', '4', 'Tocca il cuor, apre gli occhi dei Tuoi.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '3', '1', 'Egli della Tua gloria ci parla');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '3', '2', 'E dei nostri celesti tesor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '3', '3', 'Senza posa ai cuor nostri ricorda');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '3', '4', 'Per i Tuoi l\'infinito Tuo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '4', '1', 'O Signor, Tua parola di vita');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '4', '2', 'E\' migliore d\'un grappol d\'Escol:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '4', '3', 'Ci dà forza e rinfresco nel viaggio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '4', '4', 'A traverso quest\'arido suol.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '5', '1', 'Ma ben presto il prezioso servizio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '5', '2', 'Dello Spirto avrà fine, ed allor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '5', '3', 'Faccia a faccia con Te parleremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('288', '5', '4', 'In Tua luce, nel cielo, Signor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('289', '11.10.11.10.', '52', '168');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('289', '1', '1', 'O SANTO Agnel di Dio, Gesù, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('289', '1', '2', 'Che il sangue Tuo per noi volesti dar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('289', '1', '3', 'Donaci di gustare più il Tuo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('289', '1', '4', 'Che il pianto in gioia fa per noi mutar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('289', '2', '1', 'Nell\'alme nostre regna, santo Agnello,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('289', '2', '2', 'E fa\' che sempre a Te devoti siam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('289', '2', '3', 'E, in cuor portando il santo Tuo suggello,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('289', '2', '4', 'All\'amor Tuo per sempre rispondiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('289', '3', '1', 'Oh, quanto è bello, dal Tuo amor protetti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('289', '3', '2', 'Al fianco Tuo, Signore, camminar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('289', '3', '3', 'E, dalla santa mano Tua sorretti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('289', '3', '4', 'La forza pel cammino ognor trovar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('289', '4', '1', 'Le nostre menti apri Tu, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('289', '4', '2', 'Sì che le meraviglie Tue vediam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('289', '4', '3', 'Sciogli le nostre lingue, dacci ardore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('289', '4', '4', 'Sì che il Tuo amore immenso celebriam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('290', '7.6.7.6.7.6.7.6.', '34', '180');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '1', '1', 'IO amo ognor cantare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '1', '2', 'La storia di Gesù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '1', '3', 'Che dall\'eccelsa gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '1', '4', 'Venne a morir quaggiù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '1', '5', 'Oh, quant\'è dolce e vera');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '1', '6', 'La storia del Suo amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '1', '7', 'E del prezioso sangue');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '1', '8', 'Ch\'Ei diè pel peccator!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '2', '1', 'Fino alla morte andava');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '2', '2', 'Il Salvator per me,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '2', '3', 'Compiendo l\'opra santa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '2', '4', 'Che libertà mi diè.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '2', '5', 'Il peso dei peccati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '2', '6', 'Ei tutto sopportò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '2', '7', 'Di Satana il potere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '2', '8', 'Per sempre debellò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '3', '1', 'Or è risuscitato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '3', '2', 'Il mio Signor Gesù:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '3', '3', 'Nell\'alto cielo siede');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '3', '4', 'Né morirà mai più;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '3', '5', 'E per lo Spirto Santo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '3', '6', 'Mi dona già fin d\'or');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '3', '7', 'Benedizioni ricche,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '3', '8', 'Le gioie del Suo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '4', '1', 'Di viver qui per Dio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '4', '2', 'Mediante Lui, il favor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '4', '3', 'Mi dona, per Sua grazia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '4', '4', 'Il santo Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '4', '5', 'Presto Ei verrà dal cielo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '4', '6', 'Con Lui allor sarò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '4', '7', 'Le glorie del Suo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('290', '4', '8', 'Per sempre canterò.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('291', '8.7.8.7.4.7.', '50', '35');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '1', '1', 'EGLI viene! Gesù stesso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '1', '2', 'Che morì pel peccator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '1', '3', 'Viene con i Suoi redenti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '1', '4', 'Della gloria nel fulgor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '1', '5', 'Alleluia!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '1', '6', 'Gesù viene per regnar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '2', '1', 'Il glorioso Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '2', '2', 'Quei che a lungo atteso fu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '2', '3', 'Viene con i santi Suoi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '2', '4', 'Che soffrirono quaggiù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '2', '5', 'Di Dio Figlio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '2', '6', 'Nella gloria Lo vediam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '3', '1', 'Il Suo popol d\'Israele');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '3', '2', 'Che quaggiù Lo rigettò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '3', '3', 'Lo percosse, Lo trafisse,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '3', '4', 'D\'ignominia Lo colmò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '3', '5', 'Il Messia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '3', '6', 'Vedrà, in grazia e maestà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '4', '1', 'La Tua sposa con lo Spirto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '4', '2', 'Grida: Vieni! a Te, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '4', '3', 'Vieni a prender il Tuo trono');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '4', '4', 'Nella gloria e lo splendor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '4', '5', 'Il creato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '4', '6', 'Soffre, geme fino a allor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '5', '1', 'Vieni! Presto l\'universo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '5', '2', 'Le Tue lodi canterà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '5', '3', 'Regnerai sulle nazioni');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '5', '4', 'In potenza e maestà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '5', '5', 'Alleluia!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('291', '5', '6', 'Amen, vieni Tu, Signor!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('292', '8.6.8.6.8.8.', '55', '214');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('292', '1', '1', 'TU, Dio, supremo in maestà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('292', '1', '2', 'Sapienza, forza, amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('292', '1', '3', 'Dimori in immortalità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('292', '1', '4', 'Di luce nel fulgor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('292', '1', '5', 'A Te le voci e i cuori alziam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('292', '1', '6', 'Lode ed omaggio Ti rendiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('292', '2', '1', 'La vasta scena di fulgor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('292', '2', '2', 'Gloriosa durerà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('292', '2', '3', 'Per il piacere del Tuo cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('292', '2', '4', 'Per tutta eternità:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('292', '2', '5', 'Questo Tua mente concepì,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('292', '2', '6', 'Il Tuo potere lo compì!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('292', '3', '1', 'Con meraviglia e adorazion');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('292', '3', '2', 'Dinanzi a Te gioiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('292', '3', '3', 'Fra i molti figli intomo a Te');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('292', '3', '4', 'La grazia Tua esaltiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('292', '3', '5', 'Te per l\'eternità lodiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('292', '3', '6', 'Dio tutto in tutti, e T\'adoriam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('293', '11.10.11.10.', '52', '29');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '1', '1', 'LA grazia Tua, Signore, in cui scendesti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '1', '2', 'Fino al Calvario i Tuoi per riscattar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '1', '3', 'Profondamente tocca i nostri cuori');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '1', '4', 'E solo Te ci fa desiderar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '2', '1', 'La gloria Tua, Signor, di Dio alla destra,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '2', '2', 'Suprema in quella scena dell\'amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '2', '3', 'Ci ha rivelato il posto di figlioli,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '2', '4', 'Accetti in Te del Padre nel favor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '3', '1', 'La Tua bellezza, il sommo Tuo valore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '3', '2', 'Tanto maggior dei beni di quaggiù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '3', '3', 'I nostri cuori attira a Te che sempre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '3', '4', 'Supremo oggetto in gloria sei lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '4', '1', 'D\'amor divin, Signor, la Tua pienezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '4', '2', 'Umana mente mai potrà afferrar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '4', '3', 'Ma presto in gloria tutta rivelata');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '4', '4', 'Quella pienezza noi potrem mirar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '5', '1', 'Da Te ogni cosa allor sarà riempita');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '5', '2', 'E in Te l\'amor di Dio riposo avrà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '5', '3', 'Te vedrà allora tutto l\'universo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('293', '5', '4', 'La Tua grandezza ognun esalterà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('294', '9.8.9.8. Giambico.', '161', '167');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('294', '1', '1', 'LA forza dell\'amor supremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('294', '1', '2', 'Ci adduce a Te, Gesù Signor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('294', '1', '3', 'In questa santa ora avremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('294', '1', '4', 'Dolcezza per i nostri cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('294', '2', '1', 'Nel Tuo abbraccio la Tua chiesa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('294', '2', '2', 'E\' interamente data a Te:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('294', '2', '3', 'Tu le sei Capo e la conduci;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('294', '2', '4', 'La sua risposta rende a Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('294', '3', '1', 'Tutta la sfera Tu rïempi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('294', '3', '2', 'Dove al Tuo fianco noi possiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('294', '3', '3', 'Con Te restar insiem contenti:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('294', '3', '4', 'Tua sposa e il corpo Tuo noi siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('294', '4', '1', 'E\' benedetto lassù il posto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('294', '4', '2', 'Che l\'assemblea con Te ha;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('294', '4', '3', 'L\'amor del Padre l\'ha disposto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('294', '4', '4', 'Per gioia Sua e Tua già.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('295', '8.7.8.7.', '24', '41');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('295', '1', '1', 'BENEDETTO Spirto Santo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('295', '1', '2', 'Ora a Te la lode offriam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('295', '1', '3', 'E di grata adorazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('295', '1', '4', 'Lieti accenti a Te leviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('295', '2', '1', 'Tu di Cristo la celeste');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('295', '2', '2', 'Sposa, con il Tuo lavor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('295', '2', '3', 'Di ricchezze immense adorni,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('295', '2', '4', 'Che provvedi con amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('295', '3', '1', 'Tu le parli di Sua gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('295', '3', '2', 'E la grazia riceviam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('295', '3', '3', 'Pel possente mutamento');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('295', '3', '4', 'Di quest\'ora, da Tua man.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('295', '4', '1', 'T\'adoriamo, Spirto Santo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('295', '4', '2', 'Tua Persona conosciam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('295', '4', '3', 'E dal nostro cuor la lode');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('295', '4', '4', 'Riverente a Te rendiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('296', '11.10.11.10.', '52', '51');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('296', '1', '1', 'FIGLIO di Dio glorioso e benedetto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('296', '1', '2', 'In Te son luce, amore, verità:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('296', '1', '3', 'Di Dio la gloria nel Tuo volto splende');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('296', '1', '4', 'Dove Tu siedi in somma maestà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('296', '2', '1', 'Noi Ti benediciamo per l\'amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('296', '2', '2', 'Che, dalla gloria, in croce Ti portò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('296', '2', '3', 'Qual Uomo fosti in terra, e la Tua morte');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('296', '2', '4', 'Di Satana il potere debellò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('296', '3', '1', 'Oh, quale amor profondo ed insondato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('296', '3', '2', 'Tua croce, Salvatore, rivelò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('296', '3', '3', 'Allor che, fra le tenebre e il dolore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('296', '3', '4', 'L\'ira di Dio su Te si riversò!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('296', '4', '1', 'Sì, "E\' compiuto! " Dall\'oscura tomba');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('296', '4', '2', 'Del Padre Tuo la gloria Te chiamò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('296', '4', '3', 'Glorificato Egli è, e coronato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('296', '4', '4', 'Al fianco Suo Tu siedi, Vincitor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('297', '8.8.8.7.8.8.8.7.', '153', '79');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('297', '1', '1', 'PADRE, Figlio e Spirto Santo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('297', '1', '2', 'In quest\'ora benedetta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('297', '1', '3', 'Ti lodiamo e T\'adoriamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('297', '1', '4', 'Tu sei Dio per ogni età.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('297', '1', '5', 'Nella luce inaccessibil');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('297', '1', '6', 'Ed eterna Tu dimori,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('297', '1', '7', 'Ma in Gesù Ti conosciamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('297', '1', '8', 'In sapienza ed in amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('297', '2', '1', 'Negli eterni Tuoi consigli,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('297', '2', '2', 'Dio nostro, hai operato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('297', '2', '3', 'Per averci quali figli-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('297', '2', '4', 'Or con Cristo Ti lodiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('297', '2', '5', 'Gloria a Te nell\'assemblea');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('297', '2', '6', 'Sia per sempre in Gesù Cristo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('297', '2', '7', 'Dio, Capo d\'ogni cosa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('297', '2', '8', 'Ora e per l\'eternità.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('298', '11.10.11.10.', '52', '126');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('298', '1', '1', 'I NOSTRI cuor, Signore, son commossi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('298', '1', '2', 'Guardando a la Tua via di dolor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('298', '1', '3', 'E l\'afflizione che per noi portasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('298', '1', '4', 'A Te ci attira, santo Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('298', '2', '1', 'L\'uom non potrà comprendere il dolore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('298', '2', '2', 'Tutta l\'angoscia che affrontasti Tu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('298', '2', '3', 'Le Tue profonde e sante sofferenze');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('298', '2', '4', 'Mai non potrem narrar, Signor Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('298', '3', '1', 'Nessun potè seguirti, Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('298', '3', '2', 'Allor che Tu compisti l\'espiazion;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('298', '3', '3', 'Fosti dall\'uom tradito e crocifisso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('298', '3', '4', 'E ancor di Dio provasti l\'abbandon.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('298', '4', '1', 'Tutta Tu sol sentisti la distanza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('298', '4', '2', 'Che del peccato conseguenza fu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('298', '4', '3', 'E nell\'immensità del Tuo dolore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('298', '4', '4', 'L\'amore Tuo vediam, Signor Gesù.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('299', '11.10.11.10.', '52', '162');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('299', '1', '1', 'CHE mai sarà il dimorar con Dio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('299', '1', '2', 'Vedere il santo volto di Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('299', '1', '3', 'Il nostro Salvatore e Sacerdote');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('299', '1', '4', 'Ch\'è sì vicino e caro a noi quaggiù?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('299', '2', '1', 'Di Cristo al tribunale ci terremo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('299', '2', '2', 'Con Lui riguarderemo ad ogni azion');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('299', '2', '3', 'Quaggiù compiuta sotto la Sua mano');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('299', '2', '4', 'E ne comprenderemo la ragion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('299', '3', '1', 'Là chiaramente alfin contempleremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('299', '3', '2', 'La grazia che Dio, nostro Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('299', '3', '3', 'Costantemente usò con noi qui in terra,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('299', '3', '4', 'Nel Suo sì grande e sì prezioso amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('299', '4', '1', 'Oh, qual beatitudin gusteremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('299', '4', '2', 'Allora che il deserto lascierem,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('299', '4', '3', 'Ed affrancati, pel piacer di Dio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('299', '4', '4', 'Nel dì di Cristo ci rallegrerem!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('300', '11.10.11.10', '52', '141');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('300', '1', '1', 'SPIRTO di Dio, a Te noi c\'inchiniamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('300', '1', '2', 'Ché il Santo sei da tutta eternità:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('300', '1', '3', 'Tu opri con il Padre ed il Figliolo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('300', '1', '4', 'Uno con Loro nella Deità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('300', '2', '1', 'Pria ancor che Dio formasse la distesa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('300', '2', '2', 'Ove i pensieri Suoi si dispiegâr,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('300', '2', '3', 'Nei sentimenti Tuoi, sul vasto abisso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('300', '2', '4', 'Tu Ti movesti in grazia senza par.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('300', '3', '1', 'E quando il Figlio venne sulla terra,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('300', '3', '2', 'Su Lui scendesti e la potenza Tu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('300', '3', '3', 'Fosti per tutte l\'opre ch\'Egli fece');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('300', '3', '4', 'Fino ad offrir Se stesso a Dio quaggiù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('300', '4', '1', 'Ed or da Cristo in cielo sei disceso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('300', '4', '2', 'Umilemente in noi per dimorar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('300', '4', '3', 'Gli occhi dei nostri cuori per aprire,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('300', '4', '4', 'I nostri passi al cielo per guidar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('301', '7.6.7.6.', '41', '4');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '1', '1', 'LA gloria Tua suprema');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '1', '2', 'Produce in ogni cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '1', '3', 'Un gran desìo di darti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '1', '4', 'Ciò che Tu vuoi, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '2', '1', 'Dei Tuoi santificati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '2', '2', 'La lode in unità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '2', '3', 'Si leva: la Tua sposa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '2', '4', 'A Te risponde già.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '3', '1', 'La gioia a lungo attesa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '3', '2', 'Or non aspetti più:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '3', '3', 'La sposa Tua Ti loda,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '3', '4', 'Devota a Te, Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '4', '1', 'La somma Tua bellezza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '4', '2', 'Pel Tuo divino amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '4', '3', 'Riflessa è nella sposa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '4', '4', 'Ch\'è tutta pel Tuo cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '5', '1', 'Divin proponimento:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '5', '2', 'La sposa Tua, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '5', '3', 'Unita a Te qual Uomo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('301', '5', '4', 'Sodisfa or il Tuo cuor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('302', '10.9.10.9.', '114', '134');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '1', '1', 'NELLA gloria, Signor, Ti guardiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '1', '2', 'Mentre Te, riverenti, adoriam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '1', '3', 'Là, con cuori commossi, la storia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '1', '4', 'Delle Tue sofferenze leggiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '2', '1', 'Sul Tuo capo, da spine trafitto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '2', '2', 'Cadde l\'onta e l\'umano furor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '2', '3', 'Nella gloria che adesso Ti cinge');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '2', '4', 'V\'è risposta al Tuo immenso dolor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '3', '1', 'Sulla croce Tu solo soffristi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '3', '2', 'Niun potè la Tua angoscia alleviar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '3', '3', 'Or Te, assiso alla destra di Dio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '3', '4', 'Ama il cielo con lodi esaltar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '4', '1', 'Tu provasti di Dio l\'abbandono,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '4', '2', 'Il Suo volto celato a Te fu;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '4', '3', 'Sul Tuo volto, non più sfigurato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '4', '4', 'La Sua gloria vediamo, Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '5', '1', 'Te con cuori devoti adoriamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '5', '2', 'Degno sempre sei Tu, santo Agnel!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '5', '3', 'A Te sal dei redenti la lode');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('302', '5', '4', 'In unione col canto del ciel.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('303', '8.8.8.8.', '30', '72');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('303', '1', '1', 'OH, quanto debitori siam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('303', '1', '2', 'A Quei che il sangue Suo versò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('303', '1', '3', 'E ci redense, e diè poter');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('303', '1', '4', 'Di star dinanzi al Dio d\'amor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('303', '2', '1', 'Signore e Salvator, vediam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('303', '2', '2', 'Della Tua grazia il gran valor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('303', '2', '3', 'Poiché il Tuo Dio chiamar possiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('303', '2', '4', 'Dio nostro, ed adorarlo ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('303', '3', '1', 'Ed il Tuo Padre, là nel ciel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('303', '3', '2', 'Qual Padre nostro or adoriam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('303', '3', '3', 'Che il grido dello Spirto diè');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('303', '3', '4', 'A noi, che Suoi figlioli siam.');
