INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('304', '3', '6', 'Di Dio l\'amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('304', '3', '7', 'La croce sopportasti.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('304', '4', '1', 'A Te la lode or eleviam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('304', '4', '2', 'Il Nome Tuo onoriamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('304', '4', '3', 'E il giorno che verrai dal ciel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('304', '4', '4', 'Con gran desìo attendiamo.');
