INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('305', '1', '2', 'Chiediam, Padre, il Tuo voler;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('305', '1', '3', 'Ci proteggi nel Tuo amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('305', '1', '4', 'Manifesta il Tuo poter.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('305', '1', '5', 'In preghiera a Te veniam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('305', '1', '6', 'E l\'aiuto Tuo chiediam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('305', '2', '1', 'Per Tua grazia radunati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('305', '2', '2', 'Or a Te davanti siam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('305', '2', '3', 'E le cose a Te preziose,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('305', '2', '4', 'Dio e Padre, a cuor abbiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('305', '2', '5', 'In preghiera a Te veniam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('305', '2', '6', 'E l\'aiuto Tuo chiediam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('306', '11.10.11.10.', '52', '31');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('306', '1', '1', 'INTORNO a Te, Signore, radunati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('306', '1', '2', 'La Tua parola a legger ci accingiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('306', '1', '3', 'Con cuor soggetti a Te, Signore nostro');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('306', '1', '4', 'E pur Maestro Ti riconosciam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('306', '2', '1', 'Nel tempio Tuo, Signore, siam venuti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('306', '2', '2', 'A ricercar la Tua verità:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('306', '2', '3', 'Dispiega maggiormente a noi Tua luce,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('306', '2', '4', 'Che i nostri cuori pone in libertà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('306', '3', '1', 'Voglia Tu, per lo Spirito, insegnarci');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('306', '3', '2', 'La santa Tua parola ad ubbidir');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('306', '3', '3', 'E fa\' che i nostri cuori sian attenti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('306', '3', '4', 'La voce Tua, Signore, per udir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('306', '4', '1', 'Fa\' che, accettando la parola Tua,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('306', '4', '2', 'Di giorno in giorno innanzi a Te cresciam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('306', '4', '3', 'Si che, dall\'opra Tua santificati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('306', '4', '4', 'A Dio la gloria render noi possiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('307', '8.7.8.7.', '24', '206');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '1', '1', 'DIO Si muove in gran mistero');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '1', '2', 'Meraviglie per oprar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '1', '3', 'Sopra il mare Egli cammina');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '1', '4', 'E può il turbin dominar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '2', '1', 'In profondità sì grandi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '2', '2', 'Di possente abilità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '2', '3', 'Egli cela i Suoi consigli,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '2', '4', 'Per oprar Sua volontà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '3', '1', 'Deponete ogni timore:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '3', '2', 'Piene di benedizion,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '3', '3', 'Quelle nubi paventate');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '3', '4', 'Sopra voi si verseran.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '4', '1', 'I propositi divini');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '4', '2', 'Si dispiegano ognor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '4', '3', 'Se il germoglio è prima amaro');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '4', '4', 'Dolce alfine sarà il fior.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '5', '1', 'La Sua opra vuol invano');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '5', '2', 'L\'incredulità scrutar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '5', '3', 'Dio, interprete d\'amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('307', '5', '4', 'Egli sol la può svelar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('308', '11.8.11.8.11.8.', '198', '114');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('308', '1', '1', 'IN terra inizia il canto che, più dolce,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('308', '1', '2', 'Risuonerà per sempre in ciel:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('308', '1', '3', 'A Quei che col Suo sangue espïatorio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('308', '1', '4', 'I nostri falli tolse appien,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('308', '1', '5', 'A Lui rendiamo, con gioioso coro,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('308', '1', '6', 'Onor, potenza e lode, Amen.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('308', '2', '1', 'Egli fu solo nel portar la croce,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('308', '2', '2', 'Solo, il dolor ne sopportò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('308', '2', '3', 'Fu Suo l\'obbrobrio e il vituperio estremo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('308', '2', '4', 'Ma la vittoria riportò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('308', '2', '5', 'Compiè in potenza l\'opra, e sul Suo trono');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('308', '2', '6', 'Glorioso, un posto ci donò.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('309', '11.10.11.10.', '52', '211');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '1', '1', 'O DIO, la gloria Tua suprema splende;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '1', '2', 'Com\'è perfetto il Tuo divino amor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '1', '3', 'Amor che noi comprender non possiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '1', '4', 'Ben al di là di nostra lode ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '2', '1', 'Al Tuo parlar l\'inter creato sorse,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '2', '2', 'A Te appartiene eterna Deità!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '2', '3', 'Fonte di vita, tutte l\'opre Tue');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '2', '4', 'Rivelan Tua potenza e Tua bontà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '3', '1', 'Oh quanto giuste, quanto savie e vere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '3', '2', 'Son le Tue vie, di là d\'ogni pensier!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '3', '3', 'Noi Ti benediciam per la Tua grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '3', '4', 'Che pur nell\'uom trovato ha il suo piacer.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '4', '1', 'E più di questo, nel Tuo santo Figlio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '4', '2', 'Cristo Gesù, svelato fu il Tuo cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '4', '3', 'Ei venne qui a morir, ed or risorto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '4', '4', 'Nel cielo, nella gloria, vive ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '5', '1', 'In Cristo son compiuti i Tuoi consigli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '5', '2', 'Che Tu formasti dall\'eternità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '5', '3', 'Ed ora innanzi alla Tua faccia stiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '5', '4', 'Già rivestiti della Sua beltà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '6', '1', 'A Te, Dio nostro, ogni gloria sia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '6', '2', 'Onor, potere, lode a Te rendiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '6', '3', 'E riposando nel Tuo santo amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('309', '6', '4', 'Dai nostri cuori un canto a Te leviam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('310', '11.10.11.10.10.', '179', '8');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '1', '1', 'O PADRE benedetto, nella Tua');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '1', '2', 'Grazia infinita, abbiamo libertà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '1', '3', 'Di star dinanzi a Te con il Tuo Figlio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '1', '4', 'Or rivestiti di Sua degnità -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '1', '5', 'E\' l\'amor Suo che un posto tal ci dà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '2', '1', 'Ei quale Uomo venne qui a morire,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '2', '2', 'Tutti i consigli Tuoi per effettuar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '2', '3', 'Or, quale Tua risposta al Suo soffrire,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '2', '4', 'Cristo esaltato nella gloria sta;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '2', '5', 'Mediante Lui la nostra lode sal.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '3', '1', 'O Padre, come amiam così elevare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '3', '2', 'Il nostro canto a Te, con gioia e amor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '3', '3', 'Te, nella Tua pienezza benedetta,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '3', '4', 'Perfettamente espresse il Tuo Figliol:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '3', '5', 'La lode sgorga a Te dal nostro cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '4', '1', 'Noi T\'adoriam, o Padre benedetto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '4', '2', 'Ed il Tuo Nome qui magnifichiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '4', '3', 'Tua gloria riempie i nostri cuor, la gioia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '4', '4', 'Dell\'adozion lo Spirto Tuo ci dà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('310', '4', '5', 'Mentre dinanzi a Te noi c\'inchiniam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('311', '14.14.4.7.8.', '78', '179');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('311', '1', '1', 'GESU\', Signore, Tu siedi del Padre sul trono,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('311', '1', '2', 'Tu che al Calvario soffristi, deriso dall\'uomo.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('311', '1', '3', 'Degno sei Tu!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('311', '1', '4', 'La somma gloria lassù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('311', '1', '5', 'La fronte Tua corona!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('311', '2', '1', 'Noi, Tuoi diletti, riuniti qui Te rammentiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('311', '2', '2', 'E alla Tua morte noi grati, Signor, rispondiamo.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('311', '2', '3', 'Ci amasti Tu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('311', '2', '4', 'Per noi Ti desti, Gesù;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('311', '2', '5', 'Noi sul Tuo amor riposiamo.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('311', '3', '1', 'Finché ritorni, Tua morte qui in terra annunciamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('311', '3', '2', 'Ma nella gloria per fede noi già Ti vediamo.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('311', '3', '3', 'Nostro Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('311', '3', '4', 'Centro di gloria e d\'amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('311', '3', '5', 'Con lieto cuor T\'adoriamo.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('312', '12.11.12.11.', '33', '83');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('312', '1', '1', 'O DIO, quale grande porzione è la nostra,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('312', '1', '2', 'Uniti al Tuo Cristo, godendo il Tuo amor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('312', '1', '3', 'Perfetto riposo, Dio nostro, in Te abbiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('312', '1', '4', 'In Tua presenza, gioiosi ad ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('312', '2', '1', 'Mirabil pensiero! Tu vuoi che siam degni');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('312', '2', '2', 'D\'aver nostra parte per sempre con Te');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('312', '2', '3', 'Là dove il Tuo Figlio è il centro glorioso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('312', '2', '4', 'E dov\'è ogni cosa da Te e per Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('312', '3', '1', 'O Padre, al Figliolo hai voluto donarci');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('312', '3', '2', 'E vuoi che con Lui per sempre noi siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('312', '3', '3', 'In Lui ci riveli i Tuoi santi consigli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('312', '3', '4', 'E la gloria Tua in Lui contempliam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('312', '4', '1', 'Mirando Tua gloria, di cuor T\'adoriamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('312', '4', '2', 'T\'amiamo di più, più apprendiamo il Tuo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('312', '4', '3', 'Che "Tu sei quel Dio" adoranti sclamiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('312', '4', '4', 'Al santo Tuo Nome diam gloria ed onor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('313', '8.8.4.8.8.4.', '65', '148');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('313', '1', '1', 'GESU\', Signore, Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('313', '1', '2', 'Sei degno dell\'adorazion');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('313', '1', '3', 'Che T\'apportiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('313', '1', '4', 'Perfetta grazia splende in Te,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('313', '1', '5', 'Perfetto in tutto il Tuo cammin:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('313', '1', '6', 'Noi c\'inchiniam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('313', '2', '1', 'La grazia che mostrasti qui');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('313', '2', '2', 'Qual puro e grato incenso ognor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('313', '2', '3', 'Al Padre sal;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('313', '2', '4', 'Di gioia fonte pel Suo cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('313', '2', '5', 'Prezioso, santo Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('313', '2', '6', 'Sei senza egual.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('313', '3', '1', 'Più bello Tu sei d\'ogni uom,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('313', '3', '2', 'Niun le Tue glorie può narrar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('313', '3', '3', 'Tu regni sol.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('313', '3', '4', 'A Te si leva il nostro cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('313', '3', '5', 'E Te in eterno loderem,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('313', '3', '6', 'Di Dio Figliol.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('314', '11.10.11.10.', '52', '165');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('314', '1', '1', 'DIO nostro e Padre, lodi a Te apportiamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('314', '1', '2', 'Chi della lode degno mai sarà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('314', '1', '3', 'Più di Te stesso, che quaggiù cercasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('314', '1', '4', 'Adoratori in spirto e verità?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('314', '2', '1', 'Tutto creasti Tu pel Tuo Figliolo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('314', '2', '2', 'Tutto Egli tien nel sommo Suo poter,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('314', '2', '3', 'E pure in Lui a Te ci avviciniamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('314', '2', '4', 'Qual causa d\'adorare abbiamo inver!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('314', '3', '1', 'Ei ci conduce in questa santa sfera');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('314', '3', '2', 'E della chiesa il canto guida a Te;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('314', '3', '3', 'Egli gioisce che in perfetta pace');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('314', '3', '4', 'Al Tuo cospetto averci può con Sé.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('314', '4', '1', 'Il cuore Tuo, O Dio, è sodisfatto:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('314', '4', '2', 'Uniti qui con gioia a Te cantiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('314', '4', '3', 'Tu già dimori in mezzo delle lodi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('314', '4', '4', 'Che, dal Figliol guidati, noi T\'offriam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('315', '11.10.11.10.10.10.', '180', '187');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('315', '1', '1', 'CON lode e adorazion, Signor glorioso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('315', '1', '2', 'Umilemente a Te noi ci prostriam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('315', '1', '3', 'E in una sfera d\'infinita gioia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('315', '1', '4', 'La santa Tua Persona contempliam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('315', '1', '5', 'Tu stesso Ti riveli ai nostri cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('315', '1', '6', 'Nel Tuo riposo entriam per fé, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('315', '2', '1', 'Ti riveriamo come Creatore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('315', '2', '2', 'E pur dell\'opre Tue sei ben maggior;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('315', '2', '3', 'I Tuoi diritti nella redenzione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('315', '2', '4', 'Riconosciam e T\'adoriam, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('315', '2', '5', 'Tu sei lo Stesso dall\'eternità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('315', '2', '6', 'In Te dimora appieno la Deità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('315', '3', '1', 'A umanità disceso Ti vediamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('315', '3', '2', 'Mentre la gloria Tua contempliam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('315', '3', '3', 'E trasformati innanzi a la Tua faccia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('315', '3', '4', 'Te Primogenito riconosciam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('315', '3', '5', 'Simìli a Te, da Te, per Te noi siam-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('315', '3', '6', 'Uomo glorioso! Lieti T\'adoriam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('316', '8.7.8.7.', '24', '20');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('316', '1', '1', 'NOSTRO Padre benedetto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('316', '1', '2', 'Or a Te ci avviciniam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('316', '1', '3', 'La Tua grazia ci dà forza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('316', '1', '4', 'E l\'amore Tuo gustiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('316', '2', '1', 'Il Tuo Figlio contempliamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('316', '2', '2', 'Nella gloria Sua lassù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('316', '2', '3', 'E il Tuo amor benediciamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('316', '2', '4', 'Che riposa su Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('316', '3', '1', '"Padre mio e Padre vostro"');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('316', '3', '2', 'Ei ci dice, e noi gioiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('316', '3', '3', 'Come Lui noi siamo amati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('316', '3', '4', 'Figli innanzi a Te noi siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('316', '4', '1', 'Piena gioia già gustiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('316', '4', '2', 'Che né morte né timor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('316', '4', '3', 'Può turbare, e il nostro omaggio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('316', '4', '4', 'Or T\'offriam con lieto cuor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('317', '11.10.11.10.', '52', '48');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('317', '1', '1', 'SIGNOR Gesù, la speme benedetta,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('317', '1', '2', 'Speme che ci ha allegrati nel cammin,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('317', '1', '3', 'D\'un pieno, eterno, fulgido riposo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('317', '1', '4', 'Con Te, Signor, sarà compiuta alfin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('317', '2', '1', 'Portati là da un\'infinita grazia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('317', '2', '2', 'Sul santo volto Tuo vedrem brillar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('317', '2', '3', 'Una gloriosa luce, e Te per sempre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('317', '2', '4', 'Potremo senza nubi contemplar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('317', '3', '1', 'Lode, infinita lode pur ricolma');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('317', '3', '2', 'Quel benedetto, santo luogo, là');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('317', '3', '3', 'Dove ciascuno appieno le ricchezze');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('317', '3', '4', 'Della Tua grazia senza vel vedrà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('317', '4', '1', 'Non più conflitto: nell\'eterno giorno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('317', '4', '2', 'Sarà la nostra parte di cantar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('317', '4', '3', 'Signor, per sempre il canto di vittoria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('317', '4', '4', 'E solamente viver per lodar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('318', '13.12.13.12.12.', '200', '61');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '1', '1', 'PER noi, Signor Gesù, venisti dalla gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '1', '2', 'Scendendo fino a nascer in presepe umìl;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '1', '3', 'Di duolo in duolo, di vittoria Tu in vittoria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '1', '4', 'Andasti fino in croce e i nostri falli là');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '1', '5', 'Prendesti su di Te, vincendo nel soffrir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '2', '1', 'L\'immenso Tuo dolor, l\'angoscia senza posa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '2', '2', 'Te dall\'oggetto Tuo mai non potêr sviar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '2', '3', 'Fino alla morte tutte le Tue sofferenze');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '2', '4', 'Sovra il Tuo santo spirito si addensâr,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '2', '5', 'Ma Tu scegliesti ancor, Signore, d\'obbedir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '3', '1', 'I nostri duoli appien, Signore, sopportasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '3', '2', 'E la Tua vita - offerta senza paragon-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '3', '3', 'Per noi volesti dar, in grazia tanto grande');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '3', '4', 'Che non saremo mai capaci d\'apprezzar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '3', '5', 'Per Te il diritto sol tenesti ancor d\'amar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '4', '1', 'Passate tutte son le Tue sofferenze');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '4', '2', 'Ed or la gioia regna, santo Salvator;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '4', '3', 'Risorto sei nel ciel, di gloria coronato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '4', '4', 'Ed i redenti Tuoi Tua pace godon già');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '4', '5', 'E il Tuo profondo amor che non avrà mai fin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '5', '1', 'Di là da morte or, eterno ed immutato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '5', '2', 'Vivo e possente ancor è il Tuo prezioso amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '5', '3', 'Presto verrai dal cielo per chiamare i Tuoi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '5', '4', 'E allora noi sarem ognor con Te, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('318', '5', '5', 'Dove il Tuo santo amor per sempre loderem.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('319', '11.10.11.10.', '52', '94');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('319', '1', '1', 'O BENEDETTO Dio, la Tua grandezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('319', '1', '2', 'Per tutta eternità riconosciam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('319', '1', '3', 'Per grazia siam condotti a Te vicini');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('319', '1', '4', 'E quel ch\'è Tuo con gioia a Te rendiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('319', '2', '1', 'Su tutto Capo sei, a Te cantiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('319', '2', '2', 'Tua gloria senza fine contempliam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('319', '2', '3', 'Quale il Tuo Nome, tale è la Tua lode:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('319', '2', '4', 'Dio - Padre, Figlio e Spirto, T\'adoriam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('320', '9.8.9.8. Dattilico.', '112', '9998');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '1', '1', 'DA Te ogni dono perfetto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '1', '2', 'O Padre dei lumi, ci vien;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '1', '3', 'Ai nostri desir Tu rispondi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '1', '4', 'Ci accordi Tua benedizion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '2', '1', 'O Padre di misericordia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '2', '2', 'Tua man ci sostiene ogni dì;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '2', '3', 'In terra ci dài a conoscer');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '2', '4', 'L\'amor Tuo perfetto e divin,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '3', '1', 'E quale fiducia gli eletti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '3', '2', 'Or han, Padre santo, quaggiù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '3', '3', 'Ché son conservati, in Tua grande');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '3', '4', 'Potenza, nel Cristo Gesù!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '4', '1', 'O Padre di gloria, è pur grande');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '4', '2', 'La Tua possessione nei Tuoi!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '4', '3', 'E quanto son vasti, o Dio savio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '4', '4', 'I santi Tuoi piani per noi!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '5', '1', 'O Padre, a Te grazie rendiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '5', '2', 'E Te celebriam ad ognor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '5', '3', 'Nel grande Tuo amor Tu sorpassi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('320', '5', '4', 'Appieno il desir d\'ogni cuor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('321', '8.5.8.3.', '53', '80');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '1', '1', 'COME puoi restar lontano');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '1', '2', 'Dal tuo Dio, che ancor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '1', '3', 'Senza posa a Sé ti chiama');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '1', '4', 'Con amor?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '2', '1', 'Non lo senti che hai vagato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '2', '2', 'Lungi dal Suo amor?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '2', '3', 'Al glorioso Suo messaggio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '2', '4', 'Apri il cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '3', '1', 'Ei dal peso dei peccati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '3', '2', 'Ti vuol liberar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '3', '3', 'Vuol salvarti ed al tuo cuore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '3', '4', 'Pace dar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '4', '1', 'Non rimprovero o condanna');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '4', '2', 'Vuol per te serbar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '4', '3', 'Può Sua grazia la giustizia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '4', '4', 'Sodisfar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '5', '1', 'Alla fine del tuo viaggio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '5', '2', 'Col tuo Salvator');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '5', '3', 'Sarai sempre, qual trofeo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('321', '5', '4', 'Del Suo amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('322', '10.9.10.9.', '114', '47');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '1', '1', '"ECCO l\'Uomo!" O prezioso Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '1', '2', 'Tal parola commuoveci il cuor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '1', '3', 'Nel sentier del dolor Ti vediamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '1', '4', 'Che T\'addusse alla croce, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '2', '1', 'Eri il Re, pur se cinto di spine');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '2', '2', 'E respinto in violento furor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '2', '3', 'Tu portasti le colpe d\'altrui');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '2', '4', 'Sopportando per noi il disonor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '3', '1', 'Rinnegato, tradito, negletto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '3', '2', 'Il nemico incontrasti Tu sol;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '3', '3', 'Fosti in odio dall\'uomo scacciato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '3', '4', 'Tu, dell\'uomo l\'Amico miglior!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '4', '1', 'In fedel, santo amor sopportasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '4', '2', 'Della croce il profondo dolor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '4', '3', 'Non curando la Tua sofferenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '4', '4', 'Tu pregasti per i trasgressor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '5', '1', 'Te, Signor, loderemo per sempre;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '5', '2', 'Tua Persona ricolma ogni cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '5', '3', 'Ché nessuno ha un amor come il Tuo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('322', '5', '4', 'Così ricco d\'immenso valor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('323', '10.10.4.10.10.4.', '18', '51');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('323', '1', '1', 'DISSE "E\' compiuto" il nostro Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('323', '1', '2', 'Chinò il Suo capo santo in umiltà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('323', '1', '3', 'E l\'alma diè.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('323', '1', '4', 'Del tempio il velo fu squarciato allor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('323', '1', '5', 'Gesù morì, ma ora vive ognor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('323', '1', '6', 'Gioioso ver!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('323', '2', '1', 'Disse "E\' compiuto": amor senza confin');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('323', '2', '2', 'Sgorga da questo benedetto dir');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('323', '2', '3', 'Conforto a dar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('323', '2', '4', 'Oltre il sapere d\'angeli è l\'amor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('323', '2', '5', 'L\'opra di Cristo, l\'uomo peccator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('323', '2', '6', 'Sì, può guarir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('323', '3', '1', 'Disse "E\' compiuto": in gioia noi cantiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('323', '3', '2', 'Ché niuna mano all\'opra aggiungerà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('323', '3', '3', 'Perfetta è già.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('323', '3', '4', 'Di Dio giustizia ora conosciam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('323', '3', '5', 'Dal Santo Spirto suggellati siam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('323', '3', '6', 'A eternità.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('324', '11.11.11.11.(d)', '194', '180');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('324', '1', '1', 'DEH! Vieni al Signore che ti chiama a Sé;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('324', '1', '2', 'Più non indugiare: l\'appello è per te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('324', '1', '3', 'Ei parla dal cielo in grazia al tuo cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('324', '1', '4', 'Per noi diè il Suo sangue: sì, vieni al Signor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('324', '2', '1', 'Il Padre ti chiama con voce d\'amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('324', '2', '2', 'La grazia Sua volge verso i peccator;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('324', '2', '3', 'Poich\'Ei Si compiace l\'uom a benedir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('324', '2', '4', 'Riposo agli stanchi continua ad offrir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('324', '3', '1', 'Or nulla hai da fare - compiuto è il lavor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('324', '3', '2', 'Accetta la grazia, credi nel Figliol!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('324', '3', '3', 'La morte di Cristo salvezza ci diè:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('324', '3', '4', 'La croce Ei sofferse per me e per te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('324', '4', '1', 'Il Signore viene verso tutti i Suoi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('324', '4', '2', 'Per prendere i santi discenderà a noi.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('324', '4', '3', 'Vieni, peccatore, confessa il Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('324', '4', '4', 'E con Lui in gloria tu sarai ognor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('325', '7.7.7.6.7.7.7.6.', '142', '90');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '1', '1', 'O DIO nostro e Padre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '1', '2', 'A Te rendiam omaggio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '1', '3', 'E il Tuo proponimento');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '1', '4', 'Con gioia contempliam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '1', '5', 'Con somma pazïenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '1', '6', 'E con immensa grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '1', '7', 'Oprasti in sapïenza:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '1', '8', 'Noi gloria a Te rendiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '2', '1', 'La santa Tua Persona');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '2', '2', 'Dinanzi a noi risplende,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '2', '3', 'Ed il Tuo amore eterno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '2', '4', 'Di gioia ci empie il cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '2', '5', 'E trova una risposta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '2', '6', 'In noi che pel Figliolo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '2', '7', 'E nello Spirto Santo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '2', '8', 'A Te ci avviciniam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '3', '1', 'In figli che T\'adoran');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '3', '2', 'Or trovi la Tua parte;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '3', '3', 'Felici in Tua presenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '3', '4', 'A Te noi rispondiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '3', '5', 'E presto le famiglie');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '3', '6', 'Che son in terra e in cielo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '3', '7', 'In un immenso coro');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('325', '3', '8', 'Te, Padre, loderan.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('326', '11.10.11.10.', '52', '120');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('326', '1', '1', 'SIGNORE, i nostri cuori son commossi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('326', '1', '2', 'Perché l\'amore Tuo ci procurò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('326', '1', '3', 'Un\'opportunità per incontrarti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('326', '1', '4', 'In mezzo al mondo che Ti rifiutò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('326', '2', '1', 'La grazia Tua, Signore, ci ha fornito');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('326', '2', '2', 'Calmo un rifugio pien di libertà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('326', '2', '3', 'Dove i Tuoi santi insieme Ti salutan');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('326', '2', '4', 'E contemplar or braman Tua beltà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('326', '3', '1', 'Per la potenza dello Spirto Santo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('326', '3', '2', 'Riconosciam la forza del Tuo amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('326', '3', '3', 'E, radunati al Tuo prezioso Nome,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('326', '3', '4', 'Noi Ti benediciam con grato cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('326', '4', '1', 'L\'amore che a morire Ti condusse');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('326', '4', '2', 'Noi non possiamo mai dimenticar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('326', '4', '3', 'Fresco è il suo appello ognor e reca gioia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('326', '4', '4', 'A quelli che Ti voglion ricordar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('327', '7.6.7.6.7.6.7.6.', '34', '34');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('327', '1', '1', 'CON gioia gli alleluia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('327', '1', '2', 'A Te, o Dio, leviam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('327', '1', '3', 'Anticipando il coro');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('327', '1', '4', 'Di lode universal.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('327', '1', '5', 'Lodiam la Tua grandezza:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('327', '1', '6', 'Su tutto Capo se\';');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('327', '1', '7', 'In santa adorazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('327', '1', '8', 'Noi ci prostriamo a Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('327', '2', '1', 'Tu sei l\'Iddio di gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('327', '2', '2', 'Che abiti il fulgor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('327', '2', '3', 'Tua maestà lodiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('327', '2', '4', 'Tua forza e Tuo splendor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('327', '2', '5', 'A Te sia gloria eterna');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('327', '2', '6', 'Ché tutto, o Dio, sarà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('327', '2', '7', 'Da Te, per Te, mediante');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('327', '2', '8', 'Te, per l\'eternità.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('328', '10.10.10.10.10.10.', '165', '35');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('328', '1', '1', 'IL nostro cuor esulta in Cristo, e vuol');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('328', '1', '2', 'La sua parola eccelsa dichiarar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('328', '1', '3', 'Glorioso un canto sgorga per Te sol,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('328', '1', '4', 'Tua lode trattenere non possiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('328', '1', '5', 'La nostra lingua è pronta per cantar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('328', '1', '6', 'Del nostro Re le glorie senza par.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('328', '2', '1', 'Più bello Tu sei d\'ogni figlio d\'uom,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('328', '2', '2', 'Perfetto in avvenenza sei ognor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('328', '2', '3', 'Colme di grazia le Tue labbra son,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('328', '2', '4', 'Tenero è il cuore Tuo e pien d\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('328', '2', '5', 'Dio benedetto! Noi riconosciam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('328', '2', '6', 'Ch\'è la pienezza in Te, e c\'inchiniam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('328', '3', '1', 'Sii Tu l\'oggetto fulgido esovran');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('328', '3', '2', 'Che colma e che sodisfa il nostro cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('328', '3', '3', 'Te d\'incontrar nell\'aria noi bramiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('328', '3', '4', 'Per esser sempre là con Te, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('328', '3', '5', 'Fa\' sì che senza distrazion possiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('328', '3', '6', 'Quaggiù servirti, mentre T\'attendiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('329', '9.8.9.8. Dattilico.', '112', '72');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('329', '1', '1', 'CANTIAM, con trionfo cantiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('329', '1', '2', 'Le lodi del gran Redentor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('329', '1', '3', 'Le glorie di Dio rivelate');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('329', '1', '4', 'Nel volto del nostro Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('329', '2', '1', 'Dio volle nel grande Suo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('329', '2', '2', 'Salvarci da colpe e dolor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('329', '2', '3', 'E diede il Figliol, il cui sangue');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('329', '2', '4', 'Fe\' libero l\'uom peccator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('329', '3', '1', 'Vedendo l\'amore del Padre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('329', '3', '2', 'In Lui, la pace troviam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('329', '3', '3', 'Un Dio Salvator conosciamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('329', '3', '4', 'Più pene e terror non abbiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('329', '4', '1', 'Cantiamo, con gioia cantiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('329', '4', '2', 'Le lodi del gran Redentor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('329', '4', '3', 'Le glorie del Dio vivente,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('329', '4', '4', 'La ricca Sua grazia, il Suo amor!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('330', '9.8.9.8. Giambico.', '161', '202');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('330', '1', '1', 'PADRE, dai nostri cuor s\'eleva,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('330', '1', '2', 'Del Santo Spirto nel poter,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('330', '1', '3', 'La lode ch\'Egli, il Tuo Figliolo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('330', '1', '4', 'Conduce a Te pel Tuo piacer.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('330', '2', '1', 'Col Tuo Figliolo benedetto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('330', '2', '2', 'Qual Padre noi Ti conosciam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('330', '2', '3', 'E, frutto della Sua vittoria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('330', '2', '4', 'In vicinanza a Te noi siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('330', '3', '1', 'Quanto fu grande, Padre, il costo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('330', '3', '2', 'Per Te che desti il Tuo Figliol!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('330', '3', '3', 'Ora in risposta a Te davanti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('330', '3', '4', 'D\'adoratori è un vasto stuol.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('330', '4', '1', 'E Te, supremo in ogni cosa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('330', '4', '2', 'O Padre, noi benediciam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('330', '4', '3', 'Nel Tuo riposo lode e onore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('330', '4', '4', 'E adorazione T\'apportiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('331', '11.10.11.10.', '52', '103');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('331', '1', '1', 'A TE le nostre voci or eleviamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('331', '1', '2', 'O Spirto d\'adozione, e Ti lodiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('331', '1', '3', 'Per Te, alla luce del glorioso posto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('331', '1', '4', 'Di figli, innanzi al Padre noi serviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('331', '2', '1', 'La Tua Persona santa sia adorata');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('331', '2', '2', 'Da quei che Ti rispondon d\'un sol cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('331', '2', '3', 'Tu servi sì che in grazia comprendiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('331', '2', '4', 'Con Cristo il posto di figlioli ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('331', '3', '1', 'Per Te l\'accesso, in Cristo, là ci è dato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('331', '3', '2', 'L\'amor che caccia ogni timor gustiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('331', '3', '3', 'E. per divina grazia avvicinati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('331', '3', '4', 'Con Te "Abba, Padre!" in gioia noi gridiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('332', '9.8.9.8.9.8.9.8. Dattilico.', '125', '31');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '1', '1', 'ASCOLTA il messaggio glorioso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '1', '2', 'Che viene dal ciel, dal Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '1', '3', 'Messaggio che parla di grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '1', '4', 'E dell\'infinito Suo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '1', '5', 'Ascolta: di redenzïone');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '1', '6', 'Il prezzo pagato appien fu;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '1', '7', 'Gesù, coronato di gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '1', '8', 'E\' Cristo e Signore lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '2', '1', 'Non v\'è altro nome che il Suo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '2', '2', 'In cui possa un\'alma trovar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '2', '3', 'La pace, la gioia, il perdono:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '2', '4', 'Soltanto Gesù può salvar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '2', '5', 'In grazia Egli venne dal cielo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '2', '6', 'Per te sulla croce si diè-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '2', '7', 'Oh, qual sacrificio mirabil! -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '2', '8', 'L\'amor Suo profondo è per te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '3', '1', 'Ed ora lo Spirito Santo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '3', '2', 'Mandato da Cristo quaggiù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '3', '3', 'Ci parla di tutte le glorie');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '3', '4', 'In ciel del Signore Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '3', '5', 'E ancora il Signore t\'invita,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '3', '6', 'Ti chiama con voce d\'amor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '3', '7', 'Ascolta, non esser ribelle,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('332', '3', '8', 'Accettalo tuo Salvator.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('333', '11.10.11.10.11.10.', '182', '153');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('333', '1', '1', 'DIO nostro Padre, insieme radunati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('333', '1', '2', 'I santi Tuoi interessi abbiamo a cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('333', '1', '3', 'E con genuina cura noi vogliamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('333', '1', '4', 'Le cose Tue guardare con amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('333', '1', '5', 'Di Cristo i sentimenti aver in cuore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('333', '1', '6', 'E quali sacerdoti a Lui servir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('333', '2', '1', 'Vogliam con cuor devoti conservare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('333', '2', '2', 'Della Tua casa qui la santità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('333', '2', '3', 'E far che nulla intervenendo guasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('333', '2', '4', 'Del suo valor profondo la beltà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('333', '2', '5', 'Con riverenza e amore, noi vogliamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('333', '2', '6', 'Di Salomone il letto circondar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('333', '3', '1', 'O Santo Spirto, Tu che gli interessi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('333', '3', '2', 'Di Dio sì prezïosi curi qui,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('333', '3', '3', 'Noi T\'invochiamo, nostro Paracleto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('333', '3', '4', 'Mentre aspettiamo in umiltà così.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('333', '3', '5', 'Ed in quest\'ora santa e prezïosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('333', '3', '6', 'Tienci in potenza, fede e dignità.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('334', '11.11.11.10.', '189', '51');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '1', '1', 'IN luce senza nubi Dio dimora,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '1', '2', 'Tutto il creato la Sua gloria acclama;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '1', '3', 'Spirito Egli è - amore e luce, il Santo-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '1', '4', 'Lo Stesso, ch\'è, che era e che sarà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '2', '1', 'Il solo, glorïoso, eterno Dio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '2', '2', 'Che sempre fu pria ancor che inizio fosse!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '2', '3', 'Le stelle impallidiscono dinanzi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '2', '4', 'Allo splendor di Lui che le creò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '3', '1', 'Il Sommo Dio, Eterno, Onnipotente,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '3', '2', 'Egli invisibil, Santo, Santo, Santo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '3', '3', 'La cui parola diede l\'esistenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '3', '4', 'Ai mondi, allor che solo Egli era là!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '4', '1', 'Qual gioia abbiam nel contemplar Te stesso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '4', '2', 'In Cristo rivelato, eterno Dio!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '4', '3', 'Apprender Tua sapienza ela Tua grazia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '4', '4', 'Qual santi riscattati, Te adorar!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '5', '1', 'Veder la gloria Tua brillar nel volto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '5', '2', 'Di Cristo e senza fine in Lui godere-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '5', '3', 'Di luce, gioia e pace nei reami-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('334', '5', '4', 'Dell\'immutabil Tuo perfetto amor!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('335', '11.10.11.10.', '52', '51');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('335', '1', '1', 'QUANTO profondi sono i Tuoi pensieri,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('335', '1', '2', 'E le Tue vie insondabili, Signor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('335', '1', '3', 'Tu spezzi i nostri vincoli terreni');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('335', '1', '4', 'Ed a Te stesso leghi i nostri cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('335', '2', '1', 'Con corde di amore Tu avvicini');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('335', '2', '2', 'A Te gli oggetti di Tua grazia ognor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('335', '2', '3', 'Costantemente accanto a Te ci tieni,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('335', '2', '4', 'Finché il Tuo volto in ciel vedrem, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('335', '3', '1', 'Pur se il nemico intralcia i nostri passi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('335', '3', '2', 'La nostra gioia in Te non mancherà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('335', '3', '3', 'Ben presto pena e duol saran mutati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('335', '3', '4', 'In una risplendente eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('335', '4', '1', 'In Te, pur non veduto, confidando');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('335', '4', '2', 'Sappiam che la Tua via è la miglior:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('335', '4', '3', 'Oscura o lieta, su di Te posando');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('335', '4', '4', 'Riposo e pace trova il nostro cuor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('336', '11.10.11.10.', '52', '83');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '1', '1', 'DIO nostro e Padre, fonte sei di gioia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '1', '2', 'A noi che per Tua grazia figli siam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '1', '3', 'Canti di lode a Te or eleviamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '1', '4', 'E, nella Tua presenza, T\'adoriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '2', '1', 'Lo Spirto Tuo sostiene il nostro cuore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '2', '2', 'A Te vicini noi per Cristo siam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '2', '3', 'L\'amor Tuo santo colma l\'alme nostre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '2', '4', 'E in Tua presenza d\'ogni ben godiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '3', '1', 'Tu nel Tuo sommo amor hai ordinato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '3', '2', 'Che noi con Cristo nostra parte abbiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '3', '3', 'Che nella Tua dimora glorïosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '3', '4', 'Col Tuo Diletto sempre dimoriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '4', '1', 'Oh, casa benedetta, ove Tu stesso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '4', '2', 'Dimori in gloria e amore senza par!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '4', '3', 'Già noi Ti siam vicini ed il Tuo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '4', '4', 'Su noi riposa, poiché in Cristo siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '5', '1', 'E benedetti nella Tua presenza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '5', '2', 'A Te la lode sal dal nostro cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '5', '3', 'Per il Tuo Spirto "Padre" a Te gridiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('336', '5', '4', 'E T\'adoriamo, Dio di luce e amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('337', '11.10.11.10.', '52', '46');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('337', '1', '1', 'CONSOLATORE, Spirto benedetto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('337', '1', '2', 'Sceso sei Tu a servirci in umiltà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('337', '1', '3', 'Santo mister, che pure a noi non cela');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('337', '1', '4', 'Il posto Tuo nella Deità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('337', '2', '1', 'Tutta inscrutabil è la Tua Persona,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('337', '2', '2', 'Eppur con noi Tu ami dimorar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('337', '2', '3', 'Quant\'è preziosa a noi la Tua presenza!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('337', '2', '4', 'Te come Dio gioiamo d\'adorar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('338', '11.11.11.11.(a)', '191', '67');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('338', '1', '1', 'IL Signore viene! Leviam, o santi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('338', '1', '2', 'Della lode il canto, con gioioso cuor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('338', '1', '3', 'Presto Lo vedremo venir nell\'aria:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('338', '1', '4', 'Dell\'attesa il tempo è pur breve ancor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('338', '2', '1', 'Il Signore viene! Quanto crediamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('338', '2', '2', 'Sta per trasformarsi in lieta realtà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('338', '2', '3', 'E di ciò che passa prenderà il posto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('338', '2', '4', 'Quello che rimane per l\'eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('338', '3', '1', 'Si, la Tua venuta ci dà letizia:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('338', '3', '2', 'Speme benedetta, dolce al nostro cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('338', '3', '3', 'Che, quel dì felice già pregustando,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('338', '3', '4', 'Guarda ansiosamente verso il cielo ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('338', '4', '1', 'Presto la Tua voce, Signor, udremo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('338', '4', '2', 'Glorïoso a noi Tu Ti mostrerai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('338', '4', '3', 'E la sposa Tua, Signor, con gioia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('338', '4', '4', 'Tu nell\'aria alfine Teco prenderai.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('339', '10.10.10.9.10.9.', '171', '67');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('339', '1', '1', 'NELLA santa Tua cena, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('339', '1', '2', 'Il Tuo amore infinito vediamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('339', '1', '3', 'Che più forte fu assai della morte:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('339', '1', '4', 'Da Te nulla or divider ci può.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('339', '1', '5', 'Tu la pace e la gioia ci apporti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('339', '1', '6', 'Ed in Te benedetti noi siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('339', '2', '1', 'Sono il pane ed il calice segno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('339', '2', '2', 'Che Tu l\'opera tutta compisti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('339', '2', '3', 'Per le tenebre estreme passasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('339', '2', '4', 'E incontrasti di morte il terror.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('339', '2', '5', 'Or Ti siamo vicini e lodiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('339', '2', '6', 'E ben presto Te in ciel loderem.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('340', '8.8.8.8.8.8.', '26', '22');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('340', '1', '1', 'O DIO, da tutta eternità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('340', '1', '2', 'Tu solo hai l\'immortalità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('340', '1', '3', 'Potere e gloria sono a Te,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('340', '1', '4', 'Eterno, santo Re dei re,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('340', '1', '5', 'Ed al di sopra d\'ogni onor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('340', '1', '6', 'Supremo vivi nel fulgor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('340', '2', '1', 'Savio, invisibil, senza par,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('340', '2', '2', 'Incorruttibil Creator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('340', '2', '3', 'Pur Ti volesti rivelar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('340', '2', '4', 'In Cristo, in gloria ed in amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('340', '2', '5', 'Con riverenza Ti lodiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('340', '2', '6', 'Dio tutto in tutti, e T\'esaltiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('341', '10.9.10.9.', '114', '113');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '1', '1', 'QUANTO pieno, divin Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '1', '2', 'Quanto vasto e profondo è il Tuo amor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '1', '3', 'Tu sei degno che a Te sol pensiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '1', '4', 'Che null\'altro ci occupi il cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '2', '1', 'Noi T\'amiamo pel grande valore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '2', '2', 'Che in Te stesso, Signore, vediam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '2', '3', 'E per quel che in pazienza soffristi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '2', '4', 'Sulla croce, noi pure T\'amiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '3', '1', 'Non v\'è prova d\'amore più grande:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '3', '2', 'Per amici la vita donar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '3', '3', 'Fino a morte Tu fosti fedele!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '3', '4', 'Chi può mai l\'amor Tuo misurar?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '4', '1', 'Tuoi fratelli, Signor, ci facesti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '4', '2', 'E soffristi quaggiù in umiltà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '4', '3', 'Per morir carne e sangue prendesti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '4', '4', 'Per donarci la Tua libertà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '5', '1', 'Che Tu sol, come Uomo, restassi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '5', '2', 'No, non era il pensiero divin:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '5', '3', 'Hai trovato una degna compagna');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '5', '4', 'Quale frutto del Tuo patir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '6', '1', 'La memoria del sommo Tuo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '6', '2', 'Pei cuor nostri, Signore, è tesor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '6', '3', 'Quale unguento fragrante il Tuo Nome');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('341', '6', '4', 'Ci diletta, ci stimola il cuor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('342', '11.10.11.10.10.10.', '180', '51');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '1', '1', 'SIGNOR, la conoscenza del Tuo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '1', '2', 'A Te nel cielo inchina i nostri cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '1', '3', 'Davanti a la Tua faccia noi cadiamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '1', '4', 'La Tua fulgente gloria brilla ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '1', '5', 'Prostrati, Ti lodiam e T\'adoriam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '1', '6', 'In sempiterno il Nome Tuo esaltiam!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '2', '1', 'La chiesa Tua, Tuo corpo, la Tua sposa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '2', '2', 'Con Te identificata già fin d\'or-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '2', '3', 'A Te qual casta vergin fidanzata');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '2', '4', 'Mentre procede nel deserto ancor-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '2', '5', 'Trova sua speme ed il suo tutto in Te:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '2', '6', 'Lo Sposo attende, che la chiami a Sé.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '3', '1', 'Ei vien! L\'atteso, il glorioso e santo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '3', '2', 'Signor, che ognuno un giorno adorerà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '3', '3', 'Ei viene a prender la Sua sposa al cielo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '3', '4', 'Per condivider nell\'eternità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '3', '5', 'Il frutto del consiglio che, pria ancor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '3', '6', 'Che il tempo avesse inizio, Dio formò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '4', '1', 'Il ciel, la terra e il mare pienamente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '4', '2', 'Dimostran di Sua man la potestà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '4', '3', 'Tutte l\'incomparabili Sue vie');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '4', '4', 'Ridondan a Sua lode a eternità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '4', '5', 'Ma in quel mister glorioso noi vediam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('342', '4', '6', 'L\'amore Suo insondabil e sovran.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('343', '11.10.11.10.10.10.', '180', '97');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('343', '1', '1', '"CHE cos\'è l\'uomo?" E\' Cristo che, morendo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('343', '1', '2', 'La Tua natura, O Dio, glorificò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('343', '1', '3', 'Mostrò la Tua giustizia e la Tua grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('343', '1', '4', 'Facendo pel peccato espïazion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('343', '1', '5', 'Obbediente, fino a morte andò:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('343', '1', '6', 'E\' degno d\'ogni lode e adorazion!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('343', '2', '1', 'I Tuoi consigli pria che il mondo fosse');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('343', '2', '2', 'Eran centrati nel Figliol dell\'uom;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('343', '2', '3', 'Tu Lo facesti Capo della chiesa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('343', '2', '4', 'E la Tua gloria sul Suo volto appar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('343', '2', '5', 'A Lui, sul trono in somma maestà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('343', '2', '6', 'Ogni ginocchio allor si piegherà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('343', '3', '1', 'Degno, Figliol dell\'uomo, degno sei');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('343', '3', '2', 'D\'ogni corona, d\'ogni eterno onor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('343', '3', '3', 'Sei degno d\'esser adorato sempre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('343', '3', '4', 'Riconosciuto universal Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('343', '3', '5', 'Affretta il lieto giomo che attendiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('343', '3', '6', 'Quando su tutto Tu dominerai!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('344', '8.8.8.7.8.8.8.7.', '153', '82');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('344', '1', '1', 'VIENI! Più non indugiare,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('344', '1', '2', 'Ché ti chiama il Salvatore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('344', '1', '3', 'Morte e tenebre a lasciare,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('344', '1', '4', 'Del peccato schiavitù;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('344', '1', '5', 'Il più vile peccatore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('344', '1', '6', 'Può in Cristo confidare:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('344', '1', '7', 'Per salvarti, nel Suo amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('344', '1', '8', 'Il Signor Gesù morì.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('344', '2', '1', 'Deh, riguarda al sangue e odi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('344', '2', '2', 'Di redenzïon la storia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('344', '2', '3', 'E per fede in gloria vedi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('344', '2', '4', 'Il Figliol di Dio lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('344', '2', '5', 'Ei ti parla di perdono:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('344', '2', '6', 'Deh, confida nel Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('344', '2', '7', 'E il tuo cuore-quale dono! -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('344', '2', '8', 'Pace e gioia troverà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('345', '8.8.6.8.8.6.', '20', '135');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '1', '1', 'DEH, l\'alme nostre Tu, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '1', '2', 'Ispira di fervente amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '1', '3', 'E di desir sincer,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '1', '4', 'Sì che il Tuo Nome confessiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '1', '5', 'E d\'esser Tuoi noi dimostriam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '1', '6', 'Quaggiù seguendo Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '2', '1', 'Per noi Tua vita desti Tu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '2', '2', 'E di giustizia serbi pur');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '2', '3', 'Una corona a noi.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '2', '4', 'Oh, come in piena devozion');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '2', '5', 'Dovremmo darci a Te, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '2', '6', 'Uniti a tutti i Tuoi!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '3', '1', 'I nostri cuor, Signore, Tu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '3', '2', 'Prepara al giorno che lassù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '3', '3', 'Nell\'aria T\'incontriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '3', '4', 'Mutati i nostri corpi allor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '3', '5', 'Gli spirti in libertà, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '3', '6', 'Con Te per dimorar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '4', '1', 'Il grido di raduno udrem');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '4', '2', 'Che al grido del Calvario appien');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '4', '3', 'Risponderà, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '4', '4', 'I santi Tuoi Tu prenderai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '4', '5', 'Ed in trionfo porterai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('345', '4', '6', 'Sul trono Tuo ad ognor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('346', '7.6.7.6.', '41', '57');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('346', '1', '1', 'SIGNOR Gesù, sei degno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('346', '1', '2', 'D\'adorazione e onor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('346', '1', '3', 'L\'eterne glorie Tue');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('346', '1', '4', 'Dan piena gioia al cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('346', '2', '1', 'La santa Tua grandezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('346', '2', '2', 'Niun mai potrà narrar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('346', '2', '3', 'Di Deità pienezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('346', '2', '4', 'In Te può dimorar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('346', '3', '1', 'Di tutto Creatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('346', '3', '2', 'Di Dio la gloria è in Te,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('346', '3', '3', 'La Sua sostanza esprimi:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('346', '3', '4', 'Noi ci prostriamo a Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('346', '4', '1', 'Se\'il Primo di fra i morti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('346', '4', '2', 'E della creazion,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('346', '4', '3', 'Sei Capo della chiesa:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('346', '4', '4', 'A Te l\'adorazion.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('347', '8.8.8.8.8.8.8.8. (b)', '158', '137');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '1', '1', 'IL pane e il calice, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '1', '2', 'A noi ricordan il suprem');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '1', '3', 'Tuo sacrificio santo, allor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '1', '4', 'Che i flutti sorser contro a Te:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '1', '5', 'Noi discerniam il lor valor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '1', '6', 'E il sofferente amor che fu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '1', '7', 'Quel dì provato nel dolor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '1', '8', 'Qui comprendiam, Signor Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '2', '1', 'Tu risolvesti ogni question');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '2', '2', 'Dei falli e dell\'iniquità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '2', '3', 'Quando bevesti appien, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '2', '4', 'La coppa d\'amarezza là.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '2', '5', 'Tutto è compiuto, e il nostro cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '2', '6', 'Ti reca, in piena libertà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '2', '7', 'L\'adorazione, nell\'amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '2', '8', 'Che eternamente scorrerà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '3', '1', 'Nel Tuo travaglio sul Tuo cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '3', '2', 'In morte ci portasti Tu;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '3', '3', 'Con Te siam morti, Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '3', '4', 'Con Te risorti siam lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '3', '5', 'Or del fulgor di gloria abbiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '3', '6', 'Il cuore colmo, mentre qui');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '3', '7', 'L\'oscura notte traversiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('347', '3', '8', 'In cui, Signor, moristi un dì.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('348', '10.9.10.9.10.9.10.9.', '177', '208');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '1', '1', 'QUANTO grandi e mirabili, o Padre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '1', '2', 'Sono, in Cristo, i Tuoi santi pensier');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '1', '3', 'Che, nascosti per savi e prudenti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '1', '4', 'A bambini facesti saper!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '1', '5', 'Per lo Spirito Santo ci è dato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '1', '6', 'Di conoscer appieno il Tuo pian:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '1', '7', 'Per lodarti, o Dio nostro Padre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '1', '8', 'D\'un sol cuore la voce eleviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '2', '1', 'Il Tuo Figlio, di tutto Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '2', '2', 'A Te lodi e preghiere elevò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '2', '3', 'Visse in terra qual umile Uomo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '2', '4', 'Il Tuo Nome qui magnificò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '2', '5', 'Or per grazia noi siam Tuoi figlioli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '2', '6', 'Ed in Lui a Te accetti noi siam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '2', '7', 'Frutto siam dell\'eterno Tuo piano');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '2', '8', 'E diletto al Tuo cuore rechiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '3', '1', 'Ogni cuor Ti conosce qual Padre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '3', '2', 'Poi che il Figlio Te a noi rivelò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '3', '3', 'Ed insiem la Sua gioia gustiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '3', '4', 'In quel pian che il Tuo amore formò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '3', '5', 'Tu sol, Padre, il Figliolo conosci,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '3', '6', 'Ma per Lui a Te innanzi veniam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '3', '7', 'Ed in Lui, a cui tutto Tu hai dato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('348', '3', '8', 'Pienamente riposo troviam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('349', '9.8.9.8. Dattilico.', '112', '75');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '1', '1', 'LA voce d\'amore ascoltiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '1', '2', 'Al sangue prezioso guardiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '1', '3', 'Il gran Sacrificio vediamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '1', '4', 'E pace con Dio gustiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '2', '1', 'E\' pace immutabil, eterna,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '2', '2', 'Durevole come il Suo tron,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '2', '3', 'Sicura sì come il Suo Nome,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '2', '4', 'Che resta lo stesso ad ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '3', '1', 'E\' debol sovente l\'amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '3', '2', 'Mutevol la gioia che abbiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '3', '3', 'Poi ch\'Egli non ha mutamento');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '3', '4', 'La pace ch\'Ei dona riman.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '4', '1', 'Geova è in eterno lo Stesso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '4', '2', 'Se pur noi sovente mutiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '4', '3', 'In Sua verità noi fidiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '4', '4', 'Nel santo Suo amor riposiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '5', '1', 'La croce rimane immutata-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '5', '2', 'Risorto, Ei dimora nel ciel;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '5', '3', 'La pietra si grande fu tolta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '5', '4', 'Poi ch\'Egli lasciava l\'avel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '6', '1', 'Ch\'Ei vive glorioso alla destra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '6', '2', 'Di Dio, nel cielo, sappiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '6', '3', 'Il trono ove siede, l\'amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('349', '6', '4', 'La Sua verità, conosciam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('350', '11.10.11.10.', '52', '116');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('350', '1', '1', 'SIGNORE, nostro Capo glorioso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('350', '1', '2', 'Te, Primo di fra i morti, salutiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('350', '1', '3', 'Di sopra Tu dei cieli, vittorioso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('350', '1', '4', 'Con un sol cuore lodi a Te eleviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('350', '2', '1', 'Nell\'alta gloria fosti ricevuto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('350', '2', '2', 'Il capo Tuo recinto fu d\'onor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('350', '2', '3', 'Del Padre ricevesti il benvenuto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('350', '2', '4', 'Tornando al ciel possente Vincitor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('350', '3', '1', 'Del Padre la natura dichiarasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('350', '3', '2', 'Ed ora sul Suo trono Ti vediam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('350', '3', '3', 'Del Suo voler il costo sopportasti:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('350', '3', '4', 'Te degno d\'ogni lode proclamiam!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('351', '8.7.8.7.', '24', '91');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('351', '1', '1', 'O DIVIN Consolatore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('351', '1', '2', 'Tu che guidi l\'umil cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('351', '1', '3', 'Che nei santi hai Tua dimora,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('351', '1', '4', 'Deh, ci illumini il Tuo amor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('351', '2', '1', 'Contempliam per Tuo potere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('351', '2', '2', 'Le ricchezze di Gesù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('351', '2', '3', 'E la gloria Sua aneliamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('351', '2', '4', 'Di conoscer sempre più.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('351', '3', '1', 'Alla guida Tua soggetti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('351', '3', '2', 'Fa\' che ognora più noi siam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('351', '3', '3', 'E che i santi Tuoi tesori');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('351', '3', '4', 'Con più ardore in cuor serbiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('352', '8.7.8.7.', '24', '60');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('352', '1', '1', 'O SIGNORE, dell\'unione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('352', '1', '2', 'Piena gioia in cuore abbiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('352', '1', '3', 'Ora lode e devozione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('352', '1', '4', 'Pel Tuo merito T\'offriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('352', '2', '1', 'La Tua sposa a Te vicina');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('352', '2', '2', 'Di splendore adorna già');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('352', '2', '3', 'Quella scena in cui sei Capo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('352', '2', '4', 'In potenza e maestà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('352', '3', '1', 'Il Tuo corpo, l\'assemblea,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('352', '3', '2', 'Or unita a Te, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('352', '3', '3', 'Ti risponde con affetto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('352', '3', '4', 'Nel riposo del Tuo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('352', '4', '1', 'Ed in questa relazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('352', '4', '2', 'Or con gioia T\'eleviam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('352', '4', '3', 'Nostra unita adorazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('352', '4', '4', 'E Tue lodi celebriam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('353', '9.8.9.8.9.8.9.8. Giambico.', '137', '114');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '1', '1', 'CHE mai sarà il dimorare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '1', '2', 'Con Te, Signor, con Te regnar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '1', '3', 'Poi che del Tuo prezioso amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '1', '4', 'La conoscenza può bastar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '1', '5', 'La nostra via ad illuminare?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '1', '6', 'Un cuor uman non può pensar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '1', '7', 'Né lingua dir qual sia la gioia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '1', '8', 'Signor, con Te di dimorar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '2', '1', 'Quando lasciata questa scena');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '2', '2', 'Di fede e lotta alfin avrem,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '2', '3', 'Allora, o Principe di vita,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '2', '4', 'Te nella gloria noi vedrem.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '2', '5', 'Contempleremo 1\'opra Tua:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '2', '6', 'L\'altezza e la profondità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '2', '7', 'Immense dell\'amor divino');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '2', '8', 'Risplenderan per ogni età.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '3', '1', 'E Dio ha fissato il lieto giorno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '3', '2', 'Quand\'Egli stesso asciugherà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '3', '3', 'A noi le lacrime dagli occhi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '3', '4', 'E i nostri cuori colmerà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '3', '5', 'Di meraviglia nel vedere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '3', '6', 'Il volto Tuo, divin Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '3', '7', 'Conoscer nella sua pienezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('353', '3', '8', 'Di Dio la grazia e il santo amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('354', '9.9.9.9.', '60', '15');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '1', '1', 'DELLA grazia di Dio noi parliam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '1', '2', 'Così ricca, infinita, fedel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '1', '3', 'Ma il valor l\'alma tua ne godrà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '1', '4', 'Solo allor che l\'accetti per te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '2', '1', 'Noi parliam di salvezza in amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '2', '2', 'Ch\'è dal Padre svelata in Gesù;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '2', '3', 'Ma se vivere a Dio vorrai,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '2', '4', 'Possederla per fé devi tu.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '3', '1', 'Noi parliam del gran Nome nel qual');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '3', '2', 'Dio ricevere può i peccator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '3', '3', 'Ma tu resti perduto e lontan');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '3', '4', 'Se in quel Nome non credi fin d\'or.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '4', '1', 'Noi del sangue parliam dell\'Agnel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '4', '2', 'Per lavarci versato quaggiù:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '4', '3', 'Nei tuoi falli perduto morrai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '4', '4', 'Se provarne non vuoi le virtù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '5', '1', 'Noi parliam della gloria a venir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '5', '2', 'Della casa splendente lassù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '5', '3', 'Ma in quel luogo di gioia e d\'amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('354', '5', '4', 'Come andrai, se non credi in Gesù?');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('355', '9.8.9.8.9.8.9.8. Dattilico.', '125', '136');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '1', '1', 'TE, Spirito Santo, adoriamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '1', '2', 'La lode, l\'omaggio T\'offriam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '1', '3', 'Noi Dio Ti riconosciamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '1', '4', 'E lieti al Tuo amor rispondiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '1', '5', 'A Te i nostri cuor son attratti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '1', '6', 'E meglio vogliamo apprezzar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '1', '7', 'La grazia con cui discendesti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '1', '8', 'E in noi Ti degnasti abitar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '2', '1', 'Vediamo con quale pazienza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '2', '2', 'E cura Tu ami servir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '2', '3', 'Spiegando le cose di Cristo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '2', '4', 'E luce ai cuor nostri largir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '2', '5', 'Deh, fa\' che con Te camminiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '2', '6', 'Per fede ed in grazia quaggiù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '2', '7', 'Poiché della sposa di Cristo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '2', '8', 'Fedel Paracleto sei Tu.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '3', '1', 'Or mentre la via nel deserto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '3', '2', 'Da Te noi guidati tracciam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '3', '3', 'Preparaci Tu sì che insieme');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '3', '4', 'Con Te noi levare possiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '3', '5', 'Il grido che Cristo ora attende:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '3', '6', '-Sì, vieni, Signore Gesù-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '3', '7', 'Così sarà l\'opra compita');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('355', '3', '8', 'Per cui Tu venisti quaggiù.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('356', '10.9.10.9.10.9.10.9.', '177', '44');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '1', '1', 'NOSTRO Dio, Te con gioia adoriamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '1', '2', 'E T\'offriamo l\'omaggio del cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '1', '3', 'Prima ancor della terra e del cielo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '1', '4', 'Tu formasti il Tuo piano d\'amor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '1', '5', 'Il Tuo Cristo ha una degna compagna');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '1', '6', 'Ed, uniti, del Tuopiacer');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '1', '7', 'Son oggetto per sempre, adempiendo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '1', '8', 'Pienamente i Tuoi grandi pensier.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '2', '1', 'Egli rende a Te, Dio, la gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '2', '2', 'Ei che venne qual Uomo quaggiù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '2', '3', 'Ed ancora qual Uomo glorioso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '2', '4', 'Nostro Capo è per sempre lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '2', '5', 'In Tua santa presenza veniamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '2', '6', 'Ché da Lui, a Lui simili, siam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '2', '7', 'Nel potere del Santo Tuo Spirto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '2', '8', 'Or con Lui le Tue lodi cantiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '3', '1', 'T\'adoriamo qual Capo supremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '3', '2', 'Dimorante in celeste splendor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '3', '3', 'In grandezza e potere divino');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '3', '4', 'Che sorpassa il pensier d\'ogni cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '3', '5', 'Benedetto è il Tuo santo volere,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '3', '6', 'E\' il Tuo amore d\'ogni altro al di là:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '3', '7', 'Gloria a Te nella Tua assemblea');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('356', '3', '8', 'Sia già ora e per tutte le età.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('357', '10.9.10.9.', '114', '15');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('357', '1', '1', 'LA perfetta giustizia di Dio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('357', '1', '2', 'Nella croce di Cristo vediam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('357', '1', '3', 'Una giusta e mirabile grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('357', '1', '4', 'Sol nel sangue ch\'Ei diede troviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('357', '2', '1', 'La giustizia esigea nostra morte:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('357', '2', '2', 'Non poteva le colpe ignorar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('357', '2', '3', 'Ma la croce di Cristo ci mostra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('357', '2', '4', 'Come Dio può in giustizia salvar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('357', '3', '1', 'Il Suo sangue ogni debito assolse,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('357', '3', '2', 'Su Lui cadde il giudizio divin;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('357', '3', '3', 'Sodisfatta fu allor la giustizia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('357', '3', '4', 'Or Dio può la Sua grazia largir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('357', '4', '1', 'Quei che crede in quel sangue prezioso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('357', '4', '2', 'Piena pace con Dio può trovar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('357', '4', '3', 'E può dire, con gioia nel cuore:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('357', '4', '4', 'Cristo è morto per me riscattar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('358', '9.8.9.8.9.8.9.8. Dattilico.', '125', '12');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '1', '1', 'HO udito narrare la storia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '1', '2', 'Di Cristo che in croce morì,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '1', '3', 'Che prese la forma di schiavo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '1', '4', 'E poi sul Calvario salì.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '1', '5', 'Io vidi cadere il giudizio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '1', '6', 'Udii il Suo grido, per fé,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '1', '7', 'E seppi che l\'onta e la pena');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '1', '8', 'Ei tutta sofferse per me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '2', '1', 'Ho udito la storia gloriosa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '2', '2', 'Del mio Salvatore, Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '2', '3', 'Che, vinto il poter del nemico,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '2', '4', 'In gloria ora siede lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '2', '5', 'Sul trono glorioso del Padre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '2', '6', 'Ascender Lo vidi lassù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '2', '7', 'E seppi ch\'io son liberato:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '2', '8', 'Per me trionfava Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '3', '1', 'Ho udito narrare che Cristo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '3', '2', 'Appien sodisfatto sarà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '3', '3', 'Nel giorno che ognun dei redenti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '3', '4', 'Sua lode nel ciel canterà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '3', '5', 'Allora, da tutti acclamato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '3', '6', 'Con gioia nel ciel Lo vedrò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '3', '7', 'Del santo Suo amor la pienezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('358', '3', '8', 'Con Lui in eterno godrò.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('359', '8.7.8.7.8.7.8.7.', '25', '210');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '1', '1', 'OH, preziosa è la Tua chiesa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '1', '2', 'Al Tuo cuor, Gesù, Signor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '1', '3', 'Un tesoro senza eguale,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '1', '4', 'E l\'oggetto del Tuo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '1', '5', 'Ogni cosa Tu vendesti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '1', '6', 'Nel consiglio del Tuo cuor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '1', '7', 'Per Te stesso la comprasti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '1', '8', 'Quella perla di valor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '2', '1', 'Il Tuo amor per la Tua chiesa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '2', '2', 'Tanto grande fu, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '2', '3', 'Che per lei Te stesso desti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '2', '4', 'E nel Tuo prezioso amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '2', '5', 'La sostieni, la rallegri;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '2', '6', 'Presto Tu la prenderai:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '2', '7', 'Senza macchia, senza grinza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '2', '8', 'Gloriosa Tu l\'avrai.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '3', '1', 'Per Te, aiuto convenevol,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '3', '2', 'Una sposa Dio formò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '3', '3', 'Ella gode del Tuo amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '3', '4', 'E\' il diletto del Tuo cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '3', '5', 'E con gioia e riverenza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '3', '6', 'Rispondendo al Tuoamor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '3', '7', 'A1 Tuo fianco sarà sempre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('359', '3', '8', 'La Tua chiesa, là, Signor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('360', '10.9.10.9.10.9.10.9.', '177', '9998');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '1', '1', 'TI vediamo, Signore, risorto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '1', '2', 'Perché il Primo dai morti sei Tu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '1', '3', 'Della chiesa sei Capo glorioso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '1', '4', 'Ed asceso nel cielo lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '1', '5', 'In Te accetti per grazia noi siamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '1', '6', 'Contemplar la Tua gloria possiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '1', '7', 'Con cuor liberi e riconoscenti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '1', '8', 'Or che uniti, Signore, a Te siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '2', '1', 'Tu sei Capo su tutte le cose,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '2', '2', 'Coronato di somma maestà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '2', '3', 'E\' supremo il Tuo Nome qual Uomo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '2', '4', 'E\' suprema la Tua beltà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '2', '5', 'Pur supremo è il Tuo amor, che al Calvario');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '2', '6', 'Il suo immenso potere mostrò:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '2', '7', 'Fu nell\'ora più triste ed oscura');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '2', '8', 'Che il Tuo amore, Signor, trionfò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '3', '1', 'D\'ogni nome il Tuo Nome è al di sopra,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '3', '2', 'La Tua fama d\'ogni altra è maggior,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '3', '3', 'La Tua gloria giammai non ha fine,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '3', '4', 'Infinito, immutato è il Tuo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '3', '5', 'Le Tue lodi con gioia cantiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '3', '6', 'A Te uniti per grazia noi siam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '3', '7', 'In eterno con Te noi saremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('360', '3', '8', 'Nella gioia che già pregustiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('361', '11.10.11.10.', '52', '157');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('361', '1', '1', 'PlU\' nulla ci trattiene in questa sfera:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('361', '1', '2', 'Con Te noi siamo in santa intimità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('361', '1', '3', 'E nell\'amore Tuo riposiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('361', '1', '4', 'Già rivestiti della Tua beltà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('361', '2', '1', 'Signore, dallo Spirito insegnati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('361', '2', '2', 'Il desiderio Tuo noi conosciam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('361', '2', '3', 'Con gioia e riverenza già troviamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('361', '2', '4', 'Che di Tua carne e di Tue ossa siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('361', '3', '1', 'Dai nostri cuori un canto a Te s\'eleva:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('361', '3', '2', 'Il frutto ricercato dal Tuo amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('361', '3', '3', 'In questo puro vaso incenso trovi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('361', '3', '4', 'Quel che Ti piace abbonda qui, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('361', '4', '1', 'La sposa Tua risponde all\'amor Tuo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('361', '4', '2', 'Tu solo sei la gioia del suo cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('361', '4', '3', 'Signor, Tu sei lo Sposo: a Te la lode');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('361', '4', '4', 'Della compagna Tua risuona ognor!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('362', '9.8.9.8. Dattilico.', '112', '211');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('362', '1', '1', 'SIGNORE, qual pace e riposo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('362', '1', '2', 'Guardando il Tuo volto troviam!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('362', '1', '3', 'Ai cuori Tu doni conforto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('362', '1', '4', 'Allora che a Te ci volgiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('362', '2', '1', 'Intorno vi è lotta e tormento,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('362', '2', '2', 'Nei cuori vi è spesso timor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('362', '2', '3', 'Tu solo rimani lo Stesso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('362', '2', '4', 'Per sempre immutato, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('362', '3', '1', 'Con umile cuor Ti preghiamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('362', '3', '2', 'Deh, donaci pace, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('362', '3', '3', 'Conservaci il giorno e la notte');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('362', '3', '4', 'In fede, costanza ed amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('362', '4', '1', 'Finché in quella pace serena');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('362', '4', '2', 'In cielo con Te dimoriam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('362', '4', '3', 'E il Dio di pace e d\'amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('362', '4', '4', 'Con cuori adoranti lodiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('363', '10.9.10.9.10.9.10.9.', '177', '9999');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '1', '1', 'IL Signore che, quando fu in terra,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '1', '2', 'Il lebbroso poteva guarir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '1', '3', 'Or ti guarda con occhio d\'amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '1', '4', 'E pietà per il tuo soffrir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '1', '5', 'Le tue colpe e la triste tua storia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '1', '6', 'Ei conosce ancor meglio di te:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '1', '7', 'Fu per questo ch\'Ei venne dal cielo-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '1', '8', 'Disperato il tuo caso non è.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '2', '1', 'Il Signore che, nella Sua grazia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '2', '2', 'Il lebbroso poteva toccar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '2', '3', 'Puro e santo, di tutti i peccati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '2', '4', 'Su di Sé volle il peso portar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '2', '5', 'In ogni atto ed in ogni parola');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '2', '6', 'La bontà del Suo cuore brillò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '2', '7', 'Ma ancor più sulla croce morendo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '2', '8', 'Luce e amore divin rivelò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '3', '1', 'Il Signor, che nettava il lebbroso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '3', '2', 'Anche te può appieno nettar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '3', '3', 'Il Suo sangue da ogni peccato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '3', '4', 'Può il più vile colpevol mondar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '3', '5', 'Vieni dunque a Gesù: nessun dubbio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '3', '6', 'Più t\'oscuri la mente ed il cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '3', '7', 'Or esclama con fede sincera:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('363', '3', '8', 'Tu lo puoi, Tu lo vuoi, o Signor!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('364', '9.9.9.9.9.9.', '164', '47');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('364', '1', '1', 'O DIO, l\'immenso amore Tuo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('364', '1', '2', 'D\'una pienezza santa abbonda;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('364', '1', '3', 'Di sua profondità il tesoro');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('364', '1', '4', 'Espresso è in Cristo, Figlio Tuo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('364', '1', '5', 'Nostra è la gioia sì profonda');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('364', '1', '6', 'Or di adorarti in lieto coro.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('364', '2', '1', 'Fin dall\'etemità passata');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('364', '2', '2', 'Condotti ci ha profonda via,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('364', '2', '3', 'Per ogni passo gloria abbiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('364', '2', '4', 'Che dall\'amore è ricolmata.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('364', '2', '5', 'Per il Tuo Figlio, ch\'è "la Via",');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('364', '2', '6', 'Di già e per sempre T\'adoriamo.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('364', '3', '1', 'O Dio, il nostro cuor si prostra:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('364', '3', '2', 'Con gioia e gaudio anticipiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('364', '3', '3', 'L\'eterno suon di quella scena');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('364', '3', '4', 'Dove l\'adorazione nostra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('364', '3', '5', 'E pur l\'omaggio T\'eleviamo-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('364', '3', '6', 'Del giorno Tuo la lode piena.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('365', '7.7.7.6.7.7.7.6.', '142', '164');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '1', '1', 'GESU\', Signore nostro');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '1', '2', 'Tu ami star vicino');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '1', '3', 'A cuori che Ti aman,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '1', '4', 'Ai quali caro se\':');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '1', '5', 'I frutti del profondo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '1', '6', 'Divin proponimento');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '1', '7', 'Per Te, Signor, tenuti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '1', '8', 'Per il Tuo grande amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '2', '1', 'La sposa, la compagna');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '2', '2', 'Ch\'è cara pel Tuo cuore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '2', '3', 'Può sodisfar, lei sola,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '2', '4', 'I Tuoi desir, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '2', '5', 'E dir: "Sei tutta bella,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '2', '6', 'Amata mia", T\'udiamo-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '2', '7', 'Deh sorgi, amica mia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '2', '8', 'Mia bella, te ne vien".');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '3', '1', 'Così noi stessi diamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '3', '2', 'Al Tuo prezioso amore;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '3', '3', 'Felici rispondiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '3', '4', 'Perché ognor più proviam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '3', '5', 'Che sei, Signor, lo Sposo-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '3', '6', 'Colui che ha la sposa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '3', '7', 'Tenuta nel Suo abbraccio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('365', '3', '8', 'Per Sua sodisfazion.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('366', '11.10.11.10.', '52', '186');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('366', '1', '1', 'DALL\'alto scende la misericordia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('366', '1', '2', 'Di Dio per l\'uom sol degno di morir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('366', '1', '3', 'Misericordia piena, illimitata,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('366', '1', '4', 'Che porta al cuor sollievo nell\'udir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('366', '2', '1', 'Dal dì che il mondo del peccato apparve');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('366', '2', '2', 'Misericordia all\'uom tosto albeggiò:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('366', '2', '3', 'Di donna la Progenie, che tritava');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('366', '2', '4', 'La testa del serpente, Dio annunciò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('366', '3', '1', 'Quando il Fanciullo santo, Cristo, nacque');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('366', '3', '2', 'Sull\'uomo questa luce si levò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('366', '3', '3', 'Più intensa ancor brillò quando "E\' compiuto\'');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('366', '3', '4', 'Gesù morente in croce, un dì, gridò!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('366', '4', '1', 'Appien splende la luce, allor che vinti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('366', '4', '2', 'Tutti i nemici, Ei lasciò l\'avel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('366', '4', '3', 'Ed ora nella gloria del Suo Padre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('366', '4', '4', 'Vive per noi vittorïoso in ciel.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('367', '10.9.10.9.10.9.10.9.', '177', '15');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '1', '1', 'NON m\'è chiesto, né dato, di fare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '1', '2', 'Opra alcuna per cui meritar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '1', '3', 'La salvezza - sì debol io sono');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '1', '4', 'Che neppure potrei cominciar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '1', '5', 'Verità benedetta! conosco');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '1', '6', 'Che per me il Salvatore si diè,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '1', '7', 'Per salvar la mia vita soffriva:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '1', '8', 'Sì, Gesù tutto ha fatto per me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '2', '1', 'E nemmeno saprei or cercarlo-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '2', '2', 'Egli stesso in amor mi cercò:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '2', '3', 'Quando lungi da Lui, nel peccato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '2', '4', 'Camminavo, il Pastor mi trovò!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '2', '5', 'Ed ancor Ei m\'aperse l\'orecchio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '2', '6', 'Sua chiamata d\'udire mi diè;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '2', '7', 'Or in Lui trovo forza e rifugio:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '2', '8', 'Sì, Gesù tutto ha fatto per me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '3', '1', 'Ed allor che del cielo la gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '3', '2', 'L\'alma mia riscattata godrà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '3', '3', 'E di macchia, o peccato, la traccia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '3', '4', 'Tolta alfine, per sempre, sarà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '3', '5', 'Il mio cuore di gioia esultante');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '3', '6', 'Canterà le Sue lodi ad ognor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '3', '7', 'Tu mi hai col Tuo sangue redento');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('367', '3', '8', 'E per me tutto hai fatto, Signor!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('368', '8.8.8.7.8.7.', '152', '172');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('368', '1', '1', 'IL Tuo vasto, immenso amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('368', '1', '2', 'Niun potrà mai misurare:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('368', '1', '3', 'Regna Tu nei nostri cuori,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('368', '1', '4', 'Fa\', Signor, che lo proviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('368', '1', '5', 'Da Te tutto riceviamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('368', '1', '6', 'Per Te viver qui vogliam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('368', '2', '1', 'La Tua via quant\'è gioiosa!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('368', '2', '2', 'Tu ci dài divin conforto;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('368', '2', '3', 'Nella luce del Tuo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('368', '2', '4', 'Ogni cura e duol scompar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('368', '2', '5', 'Solo Te vogliam vedere,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('368', '2', '6', 'Solo Te desiderar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('368', '3', '1', 'Il Tuo amore a noi dà pace');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('368', '3', '2', 'Fra conflitto e debolezza.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('368', '3', '3', 'Quando Tu c\'incontrerai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('368', '3', '4', 'Le tempeste cesseran');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('368', '3', '5', 'E in Te solo i nostri cuori');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('368', '3', '6', 'Sodisfatti appien saran.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('369', '8.8.8.8. Datt. Coro 5.7.8.7.', '154', '161');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '1', '1', 'CRISTO è risorto! Qual gioia!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '1', '2', 'Morte, dov\'è tua vittoria?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '1', '3', 'Egli è salito nel cielo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '1', '4', 'A Lui la forza e la gloria!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '1', '5', 'Le nostre colpe');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '1', '6', 'Tutte portò su di Sé,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '1', '7', 'Per noi la croce sofferse,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '1', '8', 'Vivente in ciel or Egli è.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '2', '1', 'Egli è risorto! Il messaggio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '2', '2', 'Ai Suoi da un angel fu dato;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '2', '3', 'Più non è qui, vive in cielo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '2', '4', 'In somma gloria elevato.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '2', '5', 'L\'amor di Cristo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '2', '6', 'Ci spinge a dar lodi ognor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '2', '7', 'A Dio, che aperse la tomba,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '2', '8', 'Risuscitando il Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '3', '1', 'Egli è risorto! Il frumento');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '3', '2', 'Caduto a terra, moriva,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '3', '3', 'Ma quale frutto per Dio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '3', '4', 'Dalla Sua morte veniva!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '3', '5', 'Egli, Primizia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '3', '6', 'Non sarà solo mai più;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '3', '7', 'I Suoi han parte a Sua gioia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('369', '3', '8', 'Gloria e potenza, lassù.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('370', '14.14.14.14.', '85', '214');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('370', '1', '1', 'O DIO, dall\'assemblea lodi sgorgan or a Te:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('370', '1', '2', 'Unita a Cristo, Capo suo, ha il cuore pien d\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('370', '1', '3', 'Tu questo piano concepisti e conducesti al fin:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('370', '1', '4', 'Or la risposta reca gioia al Tuo divino cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('370', '2', '1', 'Dalle superne scene, da Te scende la città,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('370', '2', '2', 'Di Tuo lavor corona, nella gloria e nel fulgor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('370', '2', '3', 'Né macchia o grinza offusca la splendente sua beltà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('370', '2', '4', 'Di sposa - e Cristo trova in lei la gioia pel Suo cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('370', '3', '1', 'Egli è l\'Oggetto del Tuo amor, ed or nella città');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('370', '3', '2', 'O Dio, Tu con gli uomini puoi sempre dimorar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('370', '3', '3', 'A Te nell\'assemblea la gloria sia per ogni età,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('370', '3', '4', 'Là dove il Tuo piacere può il riposo Suo trovar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('371', '11.10.11.10.', '52', '185');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('371', '1', '1', 'O TU, fulgore dell\'eterna gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('371', '1', '2', 'La lode Tua taciuta mai sarà?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('371', '1', '3', 'Chi soffocare la celeste storia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('371', '1', '4', 'Dell\'immolato Agnello, mai potrà?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('371', '2', '1', 'Dallo splendor di Deità scendesti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('371', '2', '2', 'Fin del Calvario a le profondità;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('371', '2', '3', 'Davanti a Te nel cielo c\'inchiniamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('371', '2', '4', 'A Te l\'eterna lode sgorgherà!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('371', '3', '1', 'Il santo Suo trionfo noi cantiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('371', '3', '2', 'Ei che sul trono del Suo Padre sta-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('371', '3', '3', 'Cantiamo a Lui, finché su cielo e terra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('371', '3', '4', 'Il Nazareno solo regnerà!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('372', '10.9.10.9.', '114', '69');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('372', '1', '1', 'SANTO Spirito, Consolatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('372', '1', '2', 'Il Tuo aiuto vogliamo invocar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('372', '1', '3', 'Mentre insieme noi qui ci accingiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('372', '1', '4', 'Gl\'interessi di Cristo a curar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('372', '2', '1', 'Deh, concedici il discernimento');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('372', '2', '2', 'E una santa saggezza impiegar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('372', '2', '3', 'Per agire in completa giustizia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('372', '2', '4', 'Pur lasciando la grazia operar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('372', '3', '1', 'Possa il cuore di Cristo il Signore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('372', '3', '2', 'Nei Suoi santi così confidar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('372', '3', '3', 'Mentre qui gl\'interessi divini');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('372', '3', '4', 'E null\'altro vogliamo curar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('373', '8.5.8.4.', '144', '49');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '1', '1', 'CARO Nome del Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '1', '2', 'Del Signor Gesù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '1', '3', 'Che in amor pel peccatore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '1', '4', 'Venne quaggiù!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '2', '1', 'Caro Nome che ci narra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '2', '2', 'La Sua via quaggiù;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '2', '3', 'Umil nacque e solitario');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '2', '4', 'Qui Egli fu.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '3', '1', 'Caro Nome del Signore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '3', '2', 'Gesù, Salvator!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '3', '3', 'In Sua grazia tutto diede');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '3', '4', 'Pei peccator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '4', '1', 'Fu Gesù che sulla croce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '4', '2', 'Ogni mal soffrì');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '4', '3', 'E qual Vittima perfetta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '4', '4', 'Se stesso offrì.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '5', '1', 'Or quel Nome sopra il trono');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '5', '2', 'Egli porta ancor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '5', '3', 'Sul Suo capo è la corona');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '5', '4', 'Di gloria ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '6', '1', 'Caro Nome del Signore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '6', '2', 'Gesù, santo Agnel!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '6', '3', 'Non v\'è nome più prezioso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('373', '6', '4', 'In terra o ciel.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('374', '11.10.11.10.', '52', '110');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('374', '1', '1', 'OH quale gioia, Padre, nel Tuo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('374', '1', '2', 'Qui sulla terra il Cristo Tuo trovò!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('374', '1', '3', 'Ei venne quell\'amor per rivelare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('374', '1', '4', 'Ed il Tuo Nome ai Suoi qui dichiarò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('374', '2', '1', 'Nella Sua morte più brillò il Suo amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('374', '2', '2', 'Poi nel vivente Soffio volle dar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('374', '2', '3', 'Ai santi Suoi la Sua perfetta pace,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('374', '2', '4', 'Ed or con noi Tue lodi ama alzar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('374', '3', '1', 'In questo luogo ci conduce, dove');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('374', '3', '2', 'Con Lui un inno di trionfo alziam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('374', '3', '3', 'Dei molti figli a Te la lode guida-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('374', '3', '4', 'L\'amor col quale L\'ami noi gustiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('375', '11.10.11.10.', '52', '157');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('375', '1', '1', 'SIGNOR, allor che i santi nel riposo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('375', '1', '2', 'Entran, la lor felice parte è in Te-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('375', '1', '3', 'Con Te nel paradiso - là il prezioso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('375', '1', '4', 'Tuo sangue a lor un tale posto diè.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('375', '2', '1', '"Addormentati per Gesù"-qual stato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('375', '2', '2', 'Gioioso! Chi da Te lì può strappar?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('375', '2', '3', 'Fra Te e i Tuoi santi nulla può introdursi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('375', '2', '4', 'Non vita o morte mai, né terra o mar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('375', '3', '1', '"Con Cristo" - di gran lunga miglior sorte,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('375', '3', '2', 'Dove peccato e duolo non può entrar!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('375', '3', '3', 'Il dì che fia ogni lacrima asciugata');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('375', '3', '4', 'Può il nostro cuor con gioia anticipar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('375', '4', '1', 'Quando color che dormono saranno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('375', '4', '2', 'Destati, l\'immortalità a vestir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('375', '4', '3', 'E noi con lor ci leveremo insieme,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('375', '4', '4', 'Quando verrai, i santi per rapir!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('376', '10.9.10.9.', '114', '150');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('376', '1', '1', 'IL Tuo Nome, Signore, ci attira;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('376', '1', '2', 'La Tua assenza quaggiù noi sentiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('376', '1', '3', 'Ed al santo Tuo Nome prezioso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('376', '1', '4', 'E fragrante raccolti noi siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('376', '2', '1', 'Pur se intorno v\'è ancora il deserto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('376', '2', '2', 'Siam uniti da lacci d\'amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('376', '2', '3', 'Ed a Te i nostri spirti si levan,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('376', '2', '4', 'Ché per noi Tu sei tutto, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('376', '3', '1', 'Di natura la voce è silente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('376', '3', '2', 'Ché Te solo vogliamo ascoltar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('376', '3', '3', 'Dello Spirto nel santo dominio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('376', '3', '4', 'Le Tue lodi possiamo cantar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('376', '4', '1', 'I cuor nostri, Signor, son commossi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('376', '4', '2', 'Mentre uniti Te stesso esaltiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('376', '4', '3', 'E la gioia, la sodisfazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('376', '4', '4', 'Nel Tuo amore supremo troviam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('377', '8.8.8.8.8.8.8.7.', '156', '165');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('377', '1', '1', 'PADRE, nel Tuo sommo amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('377', '1', '2', 'Tuoi figlioli ci hai chiamati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('377', '1', '3', 'Pria che terra fosse o cielo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('377', '1', '4', 'Come il Tuo Diletto amati.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('377', '1', '5', 'Ei dimora nel Tuo seno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('377', '1', '6', 'E il Tuo amore a noi rivela:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('377', '1', '7', 'Tutto dice e nulla cela');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('377', '1', '8', 'Del consiglio del Tuo cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('377', '2', '1', 'Il Tuo amor su Lui riposa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('377', '2', '2', 'Noi con gioia L\'acclamiamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('377', '2', '3', 'Tuo proposito immutabil');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('377', '2', '4', 'Adempiuto contempliamo.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('377', '2', '5', 'Il Tuo amore ad adorarti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('377', '2', '6', 'Or promuove il nostro cuore:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('377', '2', '7', 'Degno sei di gloria, onore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('377', '2', '8', 'E di lode senza fin.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('378', '8.7.8.7.8.7.8.7.', '25', '196');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('378', '1', '1', 'ALMA mia, guarda alla croce,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('378', '1', '2', 'Là contempla il Salvator:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('378', '1', '3', 'Ei, dall\'uomo rigettato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('378', '1', '4', 'Gesù Cristo, per te muor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('378', '1', '5', 'Sacrificio senza macchia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('378', '1', '6', 'Prese i falli su di Sé-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('378', '1', '7', 'Di Dio Figlio e pur dell\'uomo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('378', '1', '8', 'L\'Unto, la Parola, Egli è.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('378', '2', '1', 'Quale saldo fondamento');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('378', '2', '2', 'Or per fede in Cristo abbiam!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('378', '2', '3', 'Cristo, Rocca di salvezza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('378', '2', '4', 'Nel Tuo Nome confidiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('378', '2', '5', 'Santo Agnel che qui venisti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('378', '2', '6', 'Per salvarci, T\'adoriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('378', '2', '7', 'O perfetto Sacrificio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('378', '2', '8', 'Nostra speme in Te fondiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('379', '11.10.11.10.10.10.', '180', '1');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('379', '1', '1', 'DIO, nostro Padre, a Te noi rispondiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('379', '1', '2', 'In Tua presenza in pace e libertà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('379', '1', '3', 'Tuoi figli siamo, Tu ci hai preparati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('379', '1', '4', 'Per questa sfera a tutta eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('379', '1', '5', 'Padre, Tu molti figli devi aver,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('379', '1', '6', 'Simili a Cristo, per il Tuo piacer.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('379', '2', '1', 'In grazia Tu ci dai d\'avere parte');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('379', '2', '2', 'Nel Tuo piacer che in Lui Tu trovi ognor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('379', '2', '3', 'E pure nell\'amore che Tu mostri');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('379', '2', '4', 'Ver\' Lui, supremo Oggetto del Tuo cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('379', '2', '5', 'La gloria Sua davanti a Te vediam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('379', '2', '6', 'Con Lui l\'amore Tuo noi gustiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('379', '3', '1', 'Egli ora canta in mezzo all\'assemblea');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('379', '3', '2', 'E trova gran diletto nel lodar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('379', '3', '3', 'Te, Padre, mentre molti figli sono');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('379', '3', '4', 'Mossi una sola voce per levar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('379', '3', '5', 'Per darti, Padre, adorazione e onor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('379', '3', '6', 'Supremo nell\'economia d\'amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('380', '11.10.11.10.', '52', '163');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('380', '1', '1', 'CUORI destati, O Salvator, T\'acclaman,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('380', '1', '2', 'Santi dormienti sorgon verso Te,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('380', '1', '3', 'Ad incontrarti con rapito amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('380', '1', '4', 'Levandosi al raduno Tuo dal ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('380', '2', '1', 'Mirïadi, mirïadi, viventi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('380', '2', '2', 'Adoran Te, Colui che aprirà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('380', '2', '3', 'Con la possente voce Sua la tomba,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('380', '2', '4', 'Signore, che i Tuoi santi renderà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('380', '3', '1', 'Or dei risorti e dei mutati insieme');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('380', '3', '2', 'L\'immenso stuol che Dio vivificò-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('380', '3', '3', 'Figli di Dio, divinamente belli,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('380', '3', '4', 'Empiono l\'aria con i canti lor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('380', '4', '1', 'Sì, Tu moristi, ma in risurrezione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('380', '4', '2', 'Una gloriosa spoglia a Dio portar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('380', '4', '3', 'Tu puoi - dell\'universo meraviglia-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('380', '4', '4', 'Schiere infinite pel Tuo faticar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('381', '11.10.11.10.', '52', '104');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('381', '1', '1', 'L\'APPELLO del Tuo amore ci costringe,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('381', '1', '2', 'E un posto presso Te, Signor, troviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('381', '1', '3', 'I nostri cuori la Tua pace avvince,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('381', '1', '4', 'Con gioia la Tua gloria contempliam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('381', '2', '1', 'Ai desideri Tuoi possiam risponder,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('381', '2', '2', 'Uniti a Te, gli oggetti del Tuo cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('381', '2', '3', 'E i nostri cuori già Ti corrispondon,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('381', '2', '4', 'Vibranti nel concento dell\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('381', '3', '1', 'D\'aromati i tesori insiem T\'offriamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('381', '3', '2', 'Il frutto del lavoro Tuo divin;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('381', '3', '3', 'Lo Spirto Santo fa levar le note');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('381', '3', '4', 'Del cantico d\'amor che non ha fin.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('382', '11.4.11.4.10.10.', '196', '172');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('382', '1', '1', 'NON è per nostro merito, O Dio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('382', '1', '2', 'Che Tuoi noi siam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('382', '1', '3', 'Nella Sua grazia qui Gesù discese');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('382', '1', '4', 'Dov\'eravam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('382', '1', '5', 'Portando nella nostra oscurità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('382', '1', '6', 'La luce di Tuo amor e Tua bontà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('382', '2', '1', 'Tutte le pene che noi meritammo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('382', '2', '2', 'Ei sopportò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('382', '2', '3', 'E dal timore del divin giudizio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('382', '2', '4', 'Ci liberò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('382', '2', '5', 'Or confidenti, Padre, a Te veniam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('382', '2', '6', 'E nel Tuo santo amore riposiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('382', '3', '1', 'Ora la gloria che al Tuo Cristo hai data');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('382', '3', '2', 'Noi contempliam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('382', '3', '3', 'E per lo Spirto già nel ciel con Lui');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('382', '3', '4', 'Noi dimoriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('382', '3', '5', 'Siam Tuoi eredi; presto Lo vedrem');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('382', '3', '6', 'E nell\'onore Suoparte avrem.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('383', '11.10.11.10.', '52', '118');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('383', '1', '1', 'O SANTO Spirto, che dal cielo fosti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('383', '1', '2', 'Mandato a questo mondo di dolor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('383', '1', '3', 'I nostri cuori a empir d\'amor e pace,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('383', '1', '4', 'Noi lode a Te rendiam con grato cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('383', '2', '1', 'Vieni, e di grazia colma il nostro cuore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('383', '2', '2', 'Ci aiuta Tu, ché deboli noi siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('383', '2', '3', 'Fa\' che, fedeli e franchi da timore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('383', '2', '4', 'Da Te sorretti l\'alta via seguiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('383', '3', '1', 'Spirto di verità, nei nostri cuori');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('383', '3', '2', 'La luce porta del divin pensier,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('383', '3', '3', 'Sì che siam pieni di saggezza e pace,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('383', '3', '4', 'Guidati da Tua luce e Tuo poter.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('383', '4', '1', 'Spirto di Dio, con gioia T\'acclamiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('383', '4', '2', 'A Te l\'omaggio presentiamo in cor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('383', '4', '3', 'Di Dio i figli guidi nel cammino');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('383', '4', '4', 'Ver\' quella scena dov\'è lode ognor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('384', '10.9.10.9.', '114', '31');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('384', '1', '1', 'O SIGNORE, con cuori devoti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('384', '1', '2', 'I Tuoi santi interessi curar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('384', '1', '3', 'Noi vogliamo, a Te sempre fedeli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('384', '1', '4', 'Fino a che Ti potremo incontrar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('384', '2', '1', 'Liberati dal Santo Tuo Spirto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('384', '2', '2', 'Te servire bramiamo quaggiù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('384', '2', '3', 'In amor diligente e sincero,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('384', '2', '4', 'Perché nostro sol Capo sei Tu;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('384', '3', '1', 'Nelle cose che a Te sono care');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('384', '3', '2', 'Tutto il nostro interesse trovar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('384', '3', '3', 'Ed in mezzo alla Tua assemblea');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('384', '3', '4', 'La Tua gloria, Signor, procacciar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('384', '4', '1', 'Deh, mantieni i cuor nostri, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('384', '4', '2', 'Sottomessi al Tuo santo voler');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('384', '4', '3', 'Si che, appien dallo Spirto guidati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('384', '4', '4', 'Siamo qui pel divino piacer.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('385', '10.11.10.11.', '172', '25');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '1', '1', 'O PADRE, dimorando nel Tuo amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '1', '2', 'Egli, il Figliolo, dichiarò il Tuo Nome;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '1', '3', 'Onnipotente, sei lo Stesso ognor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '1', '4', 'Fidando nella grazia, a Te guardiamo.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '2', '1', 'Or quel poter divino noi cerchiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '2', '2', 'Pregando nello Spirito Tuo Santo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '2', '3', 'E libertà ed accesso Ti chiediam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '2', '4', 'Entro i segreti eccelsi di Tua mente.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '3', '1', 'Nel mondo pien di morte e oscurità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '3', '2', 'Divina luce nel sentier abbiamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '3', '3', 'Deh, fa\' che sottomessi procediam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '3', '4', 'Finché nel giorno alfin di Cristo entriamo!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '4', '1', 'Umìli tienci, e con la verità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '4', '2', 'Santificarci voglia, o Padre santo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '4', '3', 'Dal mondo preservati, sì che abbiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '4', '4', 'Dinanzi a noi la patria in ciel soltanto.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '5', '1', 'Ci dona di rappresentarti qui,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '5', '2', 'Per il Tuo Spirto ognor santificati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '5', '3', 'E nella grazia di Quei che morì');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('385', '5', '4', 'Fa\' che fedeli siam a Tua chiamata.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('386', '10.10.10.10.', '21', '34');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('386', '1', '1', 'GESU\', Tu vieni, vieni come Re,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('386', '1', '2', 'Portando in terra la felicità;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('386', '1', '3', 'La lotta, il male, il pianto cesseran:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('386', '1', '4', 'Prence di pace, il Vincitor Tu se\'!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('386', '2', '1', 'Ti loderan Tue opre, Salvator;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('386', '2', '2', 'Ognuno qual Signor T\'accetterà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('386', '2', '3', 'Ognuno il Nome Tuo benedirà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('386', '2', '4', 'Sol di giustizia, degno sei d\'onor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('386', '3', '1', 'O Sacerdote, di giustizia il Re,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('386', '3', '2', 'Tu Re di Salem, Re di pace se\'.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('386', '3', '3', 'Il popol Tuo da lungi e da vicin');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('386', '3', '4', 'Ti chiama: Vieni, Stella del Mattin!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('386', '4', '1', 'Re trionfante, vieni per regnar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('386', '4', '2', 'La Tua potenza e gloria fa\' brillar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('386', '4', '3', 'Signore degli eserciti nel ciel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('386', '4', '4', 'Vieni, Signor Gesù! Sì, vieni, Amen.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('387', '9.8.9.8. Giambico.', '161', '156');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('387', '1', '1', 'SIGNOR, la gloria Tua divina');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('387', '1', '2', 'Empie di gioia i nostri cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('387', '1', '3', 'Assorti nella Tua Persona,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('387', '1', '4', 'T\'offriamo lode, omaggio, onor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('387', '2', '1', 'Onnipotente! T\'acclamiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('387', '2', '2', 'Tua la pienezza di Deità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('387', '2', '3', 'Signor di tutto, Re di gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('387', '2', '4', 'Ricco in divina maestà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('387', '3', '1', 'La terra e il cielo Tu creasti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('387', '3', '2', 'E\' il trono Tuo per ogni età;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('387', '3', '3', 'Sempre lo Stesso, pur scendesti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('387', '3', '4', 'In condizion d\'umanità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('387', '4', '1', 'L\'anime nostre sono mosse');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('387', '4', '2', 'Le glorie Tue nel contemplar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('387', '4', '3', 'Adorazione, omaggio, lode');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('387', '4', '4', 'A Te con gioia amiamo dar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('388', '8.7.8.7.4.7.', '50', '196');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('388', '1', '1', 'ATTENDIAMO il Tuo ritorno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('388', '1', '2', 'E gridiam: Vieni, Gesù!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('388', '1', '3', 'Noi bramiam che sorga il giorno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('388', '1', '4', 'Che vedremo Te lassù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('388', '1', '5', 'Quando il pianto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('388', '1', '6', 'E il dolor non saran più.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('388', '2', '1', 'E\' pur vano il desiderio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('388', '2', '2', 'Pace in terra di goder:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('388', '2', '3', 'Solo nella Tua presenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('388', '2', '4', 'Noi potrem riposo aver');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('388', '2', '5', 'E il nemico');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('388', '2', '6', 'Non dovremo più temer.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('388', '3', '1', 'Fa\' che intanto a Te fedeli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('388', '3', '2', 'Le Tue orme noi seguiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('388', '3', '3', 'Attendendo che Tu venga');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('388', '3', '4', 'E che il volto Tuo vediam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('388', '3', '5', 'Ed in gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('388', '3', '6', 'Lodi eterne a Te cantiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('389', '11.10.11.10.', '52', '142');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('389', '1', '1', 'O PADRE, T\'invochiam ché Tu ci tenga');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('389', '1', '2', 'Vicini a Te, protetti dal Tuo amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('389', '1', '3', 'Fa\' che la gioia della Tua salvezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('389', '1', '4', 'A tutti i Tuoi figlioli inondi il cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('389', '2', '1', 'Gesù, divino nostro Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('389', '2', '2', 'Sii nostra luce e guida nel sentier,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('389', '2', '3', 'Tienci a Te accanto, e fa\' che Ti serviamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('389', '2', '4', 'T\'amiam e Ti lodiam con cuor sincer.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('389', '3', '1', 'O Santo Spirto, possa Tua influenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('389', '3', '2', 'La nostra vita ognor santificar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('389', '3', '3', 'E fa\' che nella lotta d\'ogni giorno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('389', '3', '4', 'La grazia Tua ci dia di trionfar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('389', '4', '1', 'O Dio, Padre, Figlio e Spirto Santo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('389', '4', '2', 'Tu che sei Dio per tutta eternità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('389', '4', '3', 'Ci guida, ci proteggi e benedici,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('389', '4', '4', 'Ci tieni presso Te nell\'umiltà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('390', '11.10.11.10.', '52', '18');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('390', '1', '1', 'DAL ciel discende una divina pace');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('390', '1', '2', 'Fondata su Gesù, di Dio Figliol,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('390', '1', '3', 'Ei che, supremo Oggetto del Suo cuore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('390', '1', '4', 'Tutta la redenzion compiva sol.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('390', '2', '1', 'Pace con Dio - Gesù è risuscitato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('390', '2', '2', 'Ed or nel ciel Lo vedo per la fé;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('390', '2', '3', 'Morendo sulla croce, Egli ha acquistato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('390', '2', '4', 'Pace, giustizia e libertà per me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('390', '3', '1', 'Pace con Dio, ché Cristo è nella gloria:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('390', '3', '2', 'Il giusto Dio è pure il Dio d\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('390', '3', '3', 'Per grazia or davanti a Lui veniamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('390', '3', '4', 'Uniti a Cristo, nostro Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('390', '4', '1', 'Cristo di Dio, noi tutto a Te dobbiamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('390', '4', '2', 'Gesù, il Signore, l\'Unto, T\'adoriam!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('390', '4', '3', 'Noi frutto siamo della Tua vittoria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('390', '4', '4', 'E Te Signor di gloria confessiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('391', '8.7.8.7. Dattilico.', '80', '199');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('391', '1', '1', 'DEH, sorgi, o Spirito Santo!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('391', '1', '2', 'Muovici insieme a cantar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('391', '1', '3', 'A Te, e con gioia, umilmente,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('391', '1', '4', 'ln Tua presenza adorar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('391', '2', '1', 'Deh, sorgi, O Spirito, in noi!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('391', '2', '2', 'L\'amor ci mostra fedel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('391', '2', '3', 'Di Quei che scese a salvarci-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('391', '2', '4', 'Gesù, esaltato nel ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('391', '3', '1', 'Zampilla, O Pozzo, in Tua gloria!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('391', '3', '2', 'Aprici gli occhi del cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('391', '3', '3', 'Rendici liberi Teco,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('391', '3', '4', 'Come sarem ad ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('391', '4', '1', 'Deh, sorgi, O Spirto, e c\'insegna');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('391', '4', '2', 'Di Dio la gloria, finché');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('391', '4', '3', 'Sì come siam conosciuti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('391', '4', '4', 'Conosceremo nel ciel.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('392', '11.10.11.10.', '52', '91');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('392', '1', '1', 'O DIO, sei Capo sopra ogni cosa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('392', '1', '2', 'Glorioso è il Nome Tuo per ogni età:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('392', '1', '3', 'Supremo in maestà ed in potere,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('392', '1', '4', 'Lo Stesso sei per tutta eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('392', '2', '1', 'D\'ogni ricchezza Tu ci benedici');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('392', '2', '2', 'E quel che Tu ci dài noi T\'apportiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('392', '2', '3', 'Lieti guardando il piano Tuo sublime,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('392', '2', '4', 'Di Cristo nella vita già viviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('392', '3', '1', 'La vasta economia dell\'amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('392', '3', '2', 'Con gioia, riverenti, comprendiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('392', '3', '3', 'A Te, o Padre, Figlio e Spirto Santo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('392', '3', '4', 'Omaggio e gloria senza fin rendiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('393', '10.10.4.10.10.4.', '18', '179');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('393', '1', '1', 'PER Tua sapienza e il sommo Tuo poter');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('393', '1', '2', 'Di creazione i mondi comparîr,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('393', '1', '3', 'O Dio suprem;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('393', '1', '4', 'In essi appar la somma Tua Deità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('393', '1', '5', 'La Tua grandezza, gloria e potestà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('393', '1', '6', 'Da eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('393', '2', '1', 'Ma Tua natura benedetta or,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('393', '2', '2', 'E i movimenti del Tuo cuor d\'amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('393', '2', '3', 'Svelati son,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('393', '2', '4', 'O Padre, a noi che in Cristo parte abbiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('393', '2', '5', 'Che in libertà davanti a Te restiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('393', '2', '6', 'E in Lui gioiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('394', '11.10.11.10.', '52', '91');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '1', '1', 'E\' GIOIA ai nostri cuori raccontare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '1', '2', 'Come il Signor di gloria dal fulgor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '1', '3', 'Discese sulla terra, a dimorare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '1', '4', 'Con l\'uomo qui, nel Suo prezioso amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '2', '1', 'Toccato da profonda compassione,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '2', '2', 'Di Sicar presso il fonte un di sedè');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '2', '3', 'Per incontrar un cuore bisognoso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '2', '4', 'E tale compassione è pur per te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '3', '1', 'Pur conoscendo tutti i tuoi peccati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '3', '2', 'Su Sé li prese quale santo Agnel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '3', '3', 'Se stesso offerse sì che tu potessi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '3', '4', 'Viver per sempre insieme a Lui nel ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '4', '1', 'Vieni a Gesù! A Sé ti vuol attrarre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '4', '2', 'Con la Sua grazia e il Suo profondo amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '4', '3', 'E ti vuol dare l\'acqua della vita');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '4', '4', 'Per sodisfar la sete del tuo cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '5', '1', 'Egli lo Spirto Santo t\'offre in dono,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '5', '2', 'Che sempre nel tuo cuor zampillerà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '5', '3', 'Gioia che niuna nube può offuscare,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('394', '5', '4', 'Forza pel tuo cammino ti darà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('395', '11.10.11.10.11.10.11.10.', '183', '97');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '1', '1', 'O CAPO della nostra salvazione,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '1', '2', 'Nel cielo coronato Ti vediam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '1', '3', 'A Te con umiltà noi c\'inchiniamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '1', '4', 'Di lode i canti lieti a Te eleviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '1', '5', 'Che sei Signore nostro confessiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '1', '6', 'Con una sola voce ed un sol cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '1', '7', 'Tu crocifisso fosti per i Tuoi;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '1', '8', 'Sei degno di potenza, lode, onor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '2', '1', 'Signor, per noi la croce sopportasti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '2', '2', 'La sofferenza e tutto il disonor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '2', '3', 'La morte, l\'abbandono ed il sepolcro');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '2', '4', 'Al fin d\'avere noi per Tuo tesor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '2', '5', 'La nostra pena su di Te prendesti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '2', '6', 'Quando soffristi come santo Agnel;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '2', '7', 'Vivente sei di gloria coronato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '2', '8', 'E centro della lode là nel ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '3', '1', 'Del Padre stai sul trono in ciel assiso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '3', '2', 'Tu che sei Capo della creazion,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '3', '3', 'Ed i Tuoi santi trovan lor diletto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '3', '4', 'Nel presentar a Te l\'adorazion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '3', '5', 'Con gioia ed esultanza Te Signore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '3', '6', 'Nella Tua gloria noi riconosciam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '3', '7', 'A Te s\'inchinerà ogni cosa presto:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('395', '3', '8', 'Quell\'ora gloriosa or attendiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('396', '11.10.11.10.11.10.', '182', '14');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '1', '1', 'O TU che sei dei secoli la Rocca,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '1', '2', 'In Te, Signor, mi voglio rifugiar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '1', '3', 'Dal fianco Tuo trafitto il sangue usciva');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '1', '4', 'E pure l\'acqua per purificar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '1', '5', 'Per cancellar la macchia del peccato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '1', '6', 'E liberarmi ancor dal suo poter.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '2', '1', 'Nulla ch\'io possa fare è sufficiente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '2', '2', 'La santa legge Tua per adempir:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '2', '3', 'Pur se il mio zelo fosse illimitato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '2', '4', 'Se il pianto mio potesse non finir-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '2', '5', 'Sol il Tuo sangue l\'alma mia poteva');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '2', '6', 'Dal peso dei peccati liberar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '3', '1', 'Nelle mie man non porto offerta alcuna;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '3', '2', 'Debol e ignudo, mi rivolgo a Te,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '3', '3', 'Fonte di vita, sol Tu puoi lavarmi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '3', '4', 'Solo dipendo dalla Tua mercé.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '3', '5', 'Di viver qui per Dio Tu m\'hai dato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '3', '6', 'E tutta la mia forza trovo in Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '4', '1', 'Pria ancora ch\'io pensassi di cercarti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '4', '2', 'Tu m\'hai trovato e m\'hai condotto a Te');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '4', '3', 'E della Tua giustizia m\'hai vestito,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '4', '4', 'Grazia su grazia or mi dài per fé.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '4', '5', 'La gioia mia Tu sempre in ciel sarai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('396', '4', '6', 'Tu che col sangue m\'hai lavato appien.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('397', '11.10.11.10.', '52', '196');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '1', '1', 'IL capo Tuo, Signore, che una volta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '1', '2', 'Di spine cinto fu nel disonor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '1', '3', 'Or da regal diadema è coronato;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '1', '4', 'Di gloria adorno sei, o Vincitor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '2', '1', 'O Tu che di Tua luce inondi il cielo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '2', '2', 'Che gioia sei ai santi Tuoi quaggiù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '2', '3', 'Ci dona di conoscer il Tuo amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '2', '4', 'Rivela sue profondità ognor più.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '3', '1', 'La croce di vergogna a noi sia dato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '3', '2', 'Con la Tua grazia di poter portar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '3', '3', 'Il Nome Tuo, quaggiù disonorato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '3', '4', 'Dio Si compiace in cielo d\'onorar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '4', '1', 'Con Te, Signor, chi soffre sulla terra');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '4', '2', 'Presto nel cielo regnerà con Te:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '4', '3', 'Fin d\'or sia nostra gioia di seguire');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '4', '4', 'La via d\'amore e pace, per la fé.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '5', '1', 'Per noi Tua croce è vita ed è salvezza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '5', '2', 'A Te diè morte, duolo e disonor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '5', '3', 'In Te troviamo gloria, gioia, pace,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('397', '5', '4', 'Ora ed eternamente, Salvator.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('398', '9.8.9.8. Giambico.', '161', '108');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '1', '1', 'TUA morte e Tua risurrezione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '1', '2', '(Oh, quale gioia per la fé!)');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '1', '3', 'Nostra condanna han tolto appieno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '1', '4', 'Di morte il dardo più non è.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '2', '1', 'Ben presto i santi addormentati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '2', '2', 'In Te, all\'incontro Tuo saran,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '2', '3', 'Quando dal trono del Tuo Padre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '2', '4', 'Verrai, i Tuoi per reclamar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '3', '1', 'Di morte il regno spezzerai,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '3', '2', 'I morti in Cristo sorgeran;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '3', '3', 'Noi, i viventi, in un momento');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '3', '4', 'Lo Spirto allor trasformerà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '4', '1', 'Completa in una vasta schiera,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '4', '2', 'Sarà la chiesa insieme allor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '4', '3', 'Rapita, ad incontrarti dove');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '4', '4', 'Sempre adorato sei, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '5', '1', 'Ed or in fede, speme e amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '5', '2', 'Noi T\'attendiam, Signor, dal ciel;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '5', '3', 'Potenza e grazia ci sostengon');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('398', '5', '4', 'Finché il Tuo volto noi vedrem.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('399', '11.10.11.10.11.10.11.10.', '183', '97');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('399', '1', '1', 'NOSTRO Maestro, fa\' che qui nel mondo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('399', '1', '2', 'Che Ti respinse, più non ricerchiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('399', '1', '3', 'Una dimora, ma con fermo passo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('399', '1', '4', 'Giorno per giorno l\'orme Tue seguiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('399', '1', '5', 'Ci dona di conoscer le Tue gioie');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('399', '1', '6', 'E di partecipare al Tuo soffrir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('399', '1', '7', 'Con umil cuor in mezzo al vituperio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('399', '1', '8', 'Memori ognor del sommo Tuo martir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('399', '2', '1', 'Signor, per chi conosce il Tuo dolore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('399', '2', '2', 'Di gloria una corona serbi Tu.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('399', '2', '3', 'Presto avran fin la lotta, l\'onta, il pianto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('399', '2', '4', 'E con Te sempre noi sarem, Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('399', '2', '5', 'Oh fa\', Signor, che per il Tuo piacere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('399', '2', '6', 'Nel Tuo servizio sempre più cresciam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('399', '2', '7', 'Si che, la nostra corsa completata,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('399', '2', '8', 'La Tua parola "Bene sta" sentiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('400', '14.13.14.13.', '203', '110');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('400', '1', '1', 'DIO manifestato in carne: oh meraviglia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('400', '1', '2', 'Dell\'universo Suo! Sapienza che operò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('400', '1', '3', 'In sante vie per compier i Suoi consigli eccelsi-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('400', '1', '4', 'Or trova Dio risposta in piena adorazion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('400', '2', '1', 'Oh, qual mutuale gloria tra il Padre e il Figlio è vista!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('400', '2', '2', 'La sfera di segreti rapporti in santo amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('400', '2', '3', 'E\' il sen del Padre, dove dimora Quei che appieno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('400', '2', '4', 'A quell\'amor perfetto risponderà ad ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('400', '3', '1', 'Ma per lo Spirto Santo l\'amor del Padre è sparso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('400', '3', '2', 'Nei nostri cuori e sempre, col Figlio, in noi sarà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('400', '3', '3', 'E le affezion dei santi s\'esprimon senza fine');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('400', '3', '4', 'Immerse in quell\'amore che mai decrescerà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('401', '11.11.11.11.(c)', '193', '171');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('401', '1', '1', 'SPIRTO di grazia, Tu che ci sostieni');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('401', '1', '2', 'Di giorno in giorno lungo tutto il viaggio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('401', '1', '3', 'Per le Tue cure che non vengon meno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('401', '1', '4', 'Ti ringraziam e Ti rendiamo omaggio.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('401', '2', '1', 'Spirto di verità, Tu ci conduci');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('401', '2', '2', 'Nel piano da Dio stesso preparato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('401', '2', '3', 'E ci riveli il volto pien di luce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('401', '2', '4', 'Del Figlio, ch\'è supremo sul creato.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('401', '3', '1', 'Colmi dei ben di cui ci fai gioire,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('401', '3', '2', 'Possiamo insiem, con santa riverenza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('401', '3', '3', 'Spirto di vita, apprender a servire');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('401', '3', '4', 'Meglio, fidando solo in Tua potenza.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('401', '4', '1', 'Nel nostro cuor fa\' splender Tu la face,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('401', '4', '2', 'Spirto di Dio, del giorno del riposo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('401', '4', '3', 'Dell\'umiltà rivestici verace');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('401', '4', '4', 'Che brilla nel servizio Tuo prezioso.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('402', '8.8.8.8.7.', '155', '43');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '1', '1', 'PADRE, Figlio e Spirto Santo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '1', '2', 'Sommo Dio che conosciamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '1', '3', 'Nome in cui per fé apprendiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '1', '4', 'La pienezza e la potenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '1', '5', 'Della rivelaïon.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '2', '1', 'Padre, è nostro desiderio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '2', '2', 'Che da Te santificati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '2', '3', 'Nel Tuo Nome siam serbati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '2', '4', 'Nella Trinità esultanti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '2', '5', 'Fermi nella verità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '3', '1', 'Veglia sulle nostre case,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '3', '2', 'O Gesù, Signore nostro:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '3', '3', 'Al Tuo Nome battezzate');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '3', '4', 'Fa\' che siano mantenute');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '3', '5', 'Nei diritti Tuoi d\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '4', '1', 'Santo Spirto, in Tua potenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '4', '2', 'Allontanaci dal mondo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '4', '3', 'Nell\'amore Tuo profondo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '4', '4', 'Guida sempre i nostri passi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('402', '4', '5', 'Nella vita che Tu dài.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('403', '11.10.11.10.', '52', '68');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '1', '1', 'A TE davanti, Padre, noi veniamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '1', '2', 'Umilemente il volto Tuo a cercar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '1', '3', 'Mentre con grati cuori T\'adoriamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '1', '4', 'Per il Tuo amor che mai non può mutar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '2', '1', 'Nessuna nube offusca il Tuo favore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '2', '2', 'Nel qual gioiosi in Tua presenza stiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '2', '3', 'Condotti a Te da Cristo Salvatore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '2', '4', 'Noi da Tua mano sostenuti siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '3', '1', 'Vano è il temer poiché Tu sei per noi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '3', '2', 'Tu ci sorreggi, ed ogni dì che vien');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '3', '3', 'Tu lo coroni con i doni Tuoi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '3', '4', 'Ed ogni istante è di Tua grazia pien.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '4', '1', 'Deh, fa\' che al Tuo voler devoti siamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '4', '2', 'Al Tuo servizio dedicati appien,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '4', '3', 'Giorno per giorno mentre proseguiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '4', '4', 'Con quell\'aiuto che da Te ci vien;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '5', '1', 'Che circondati da celeste luce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '5', '2', 'Seguiam con gioia il resto del cammin');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '5', '3', 'Lungo la via che in cielo ci conduce,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('403', '5', '4', 'Al giorno Tuo che non avrà mai fin.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('404', '9.8.9.8.8.8.', '104', '140');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('404', '1', '1', 'SUL tron del Padre Suo seduto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('404', '1', '2', 'Cristo, il Vivente, sta, il Signor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('404', '1', '3', 'In terra è il Suo lavor compiuto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('404', '1', '4', 'E l\'opra Sua pei peccator;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('404', '1', '5', 'Ed or in gloria eccelsa là');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('404', '1', '6', 'Di Dio il Figliol vediamo già.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('404', '2', '1', 'In terra l\'uom Lo rifiutava,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('404', '2', '2', 'L\'uom crocifisse il Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('404', '2', '3', 'La croce il mondo condannava,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('404', '2', '4', 'Glorificando di Dio il cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('404', '2', '5', 'E nella gloria accolto fu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('404', '2', '6', 'Quegli che un dì morì quaggiù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('404', '3', '1', 'Ogni ginocchio a Lui s\'inchini,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('404', '3', '2', 'Ognun confessi Lui Signor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('404', '3', '3', 'E le redente schiere adorin');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('404', '3', '4', 'Ei che soffrì pel peccator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('404', '3', '5', 'E dalla gloria Dio tuttor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('404', '3', '6', 'Proclama all\'uomo il Suo valor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('405', '8.8.8.8.8.8.8.8. (b)', '158', '183');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('405', '1', '1', 'A DIO, supremo in poter,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('405', '1', '2', 'A Dio, eccelso in saper,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('405', '1', '3', 'A Dio, ch\'è sommo in onor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('405', '1', '4', 'A Dio, di tutto il Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('405', '1', '5', 'Dal nostro grato cuore sal');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('405', '1', '6', 'La voce dell\'adorazion,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('405', '1', '7', 'La gloria Sua per celebrar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('405', '1', '8', 'E le Sue lodi per cantar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('405', '2', '1', 'O Dio, il Tuo Figlio desti Tu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('405', '2', '2', 'Ed il Tuo amor svelato fu:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('405', '2', '3', 'Il canto dell\'adorazion');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('405', '2', '4', 'Al Tuo cospetto sale ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('405', '2', '5', 'Qual gioia hai nel veder quaggiù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('405', '2', '6', 'I santi, simili a Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('405', '2', '7', 'Che già rispondon al Tuo cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('405', '2', '8', 'Ed a Te rendon lode e amor!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('406', '11.10.11.10.', '52', '69');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('406', '1', '1', 'DIO benedetto, l\'alme nostre insieme');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('406', '1', '2', 'Son mosse a render lode e gloria a Te;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('406', '1', '3', 'Ciò che Tu hai fatto colma nostra mente,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('406', '1', '4', 'Nel contemplar il pian del Tuo voler.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('406', '2', '1', 'Noi T\'adoriam, poi che sappiam che prima');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('406', '2', '2', 'Che fosse il mondo, avevi nel Tuo cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('406', '2', '3', 'D\'empir la scena ov\'è perenne lode,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('406', '2', '4', 'E aver con l\'uomo il Tuo riposo ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('406', '3', '1', 'Già per lo Spirto entriam in quel riposo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('406', '3', '2', 'O Dio, lo scopo di Tue vie vediam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('406', '3', '3', 'In Cristo, benedetti dal Tuo amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('406', '3', '4', 'Or Ti serviam e un canto a Te leviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('406', '4', '1', 'A Tua divina gloria c\'inchiniamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('406', '4', '2', 'Cosi esaltando il Nome Tuo suprem');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('406', '4', '3', 'Ed adoriam, sclamando di cuor lieto:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('406', '4', '4', '"Nessuno può impedire i Tuoi pensier!"');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('407', '9.8.9.8.8.8.', '104', '68');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '1', '1', 'O DIO, Tua grazia è illimitata,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '1', '2', 'Puro e insondabil è il Tuo amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '1', '3', 'Scorre la Tua mercé infinita,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '1', '4', 'Poiché dal ciel Gesù, il Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '1', '5', 'Scese, e quaggiù per noi Si diè,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '1', '6', 'Quando eravam lontan da Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '2', '1', 'Gesù il Signor pagò il riscatto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '2', '2', 'In grazia immensa, senza par!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '2', '3', 'Venne nel mondo ch\'Egli ha fatto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '2', '4', 'Dell\'empio il posto ad occupar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '2', '5', 'Il Giusto per gli ingiusti qui');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '2', '6', 'Per i diritti Tuoi morì.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '3', '1', 'Pure risorto, in ciel, per sempre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '3', '2', 'Vive il possente Salvator;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '3', '3', 'A chi confida in Lui, concede');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '3', '4', 'Benedizion dai Tuoi tesor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '3', '5', 'Per Lui il Tuo amor divin sappiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '3', '6', 'In Lui la gloria Tua vediam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '4', '1', 'Nei nostri cuor lo Spirto Santo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '4', '2', 'Effonde il Tuo prezioso amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '4', '3', 'Che il nostro posto in ciel con Cristo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '4', '4', 'Ci fa conoscer già fin d\'or.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '4', '5', 'Redenti e perdonati siam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('407', '4', '6', 'O Dio, e il Nome Tuo lodiam!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('408', '13.12.13.12.', '128', '184');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('408', '1', '1', 'SANTO Consolator, in Te ci rallegriamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('408', '1', '2', 'La Tua venuta fu richiesta dal Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('408', '1', '3', 'I sentimenti Tuoi profondi contempliamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('408', '1', '4', 'Quando venisti al fin di star con noi ognor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('408', '2', '1', 'Spirto di verità, in Te troviam riposo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('408', '2', '2', 'Mentre una scena ostil e oscura traversiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('408', '2', '3', 'Con noi Tu sempre sei: oh quant\'è prezïoso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('408', '2', '4', 'Conoscerti così, benché non Ti vediam!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('408', '3', '1', 'Occhio non vide mai, né orecchio potè udire,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('408', '3', '2', 'Né in cuore d\'uomo entrar poteron mai quaggiù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('408', '3', '3', 'Le cose eccelse che Dio preparò in amore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('408', '3', '4', 'E che riveli a noi, O Santo Spirto, Tu!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('408', '4', '1', 'E ancora Tu per noi sei l\'Arra di superna');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('408', '4', '2', 'Felicità a venir, e pur ci dài quaggiù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('408', '4', '3', 'D\'entrar nella porzion celeste nostra, eterna,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('408', '4', '4', 'E di gustar fin d\'or le gioie di lassù!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('409', '11.11.11.10.', '189', '68');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '1', '1', 'VIENI! ché il Padre parla a te dal cielo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '1', '2', 'La morte di Gesù il Suo amore espresse;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '1', '3', 'Ei diè per te il Suo unico Figliolo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '1', '4', 'E nulla la Sua man ti negherà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '2', '1', 'Vieni, ché in grazia parla il Salvatore:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '2', '2', 'Purificarti e perdonarti vuole;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '2', '3', 'Soltanto il sangue Suo ti può guarire');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '2', '4', 'E dai peccati tuoi lavarti appien.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '3', '1', 'Vieni! Lo Spirto parla a te di Cristo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '3', '2', 'In gloria, che in pazienza ancor t\'attende;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '3', '3', 'Ascolta alfin Sua voce, accetta il dono');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '3', '4', 'D\'illimitata e piena salvazion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '4', '1', 'Vieni con fé: Dio stesso, sì, t\'invita,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '4', '2', 'Ei vuol empirti il cuor d\'eccelse gioie;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '4', '3', 'Pur se la Sua bontà hai trascurata,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '4', '4', 'Egli con grazia e amor ti cerca ancor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '5', '1', 'Vieni a Gesù, e Lui qual Salvatore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '5', '2', 'Accetta, confessandogli i tuoi falli;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '5', '3', 'Ei sia per te il Sovrano ed il Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('409', '5', '4', 'E vita eterna, pace e gioia avrai.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('410', '10.9.10.9.', '114', '87');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '1', '1', 'SULL\'Agnel l\'alma nostra riposa:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '1', '2', 'Niuna lingua può dire il Suo amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '1', '3', 'Quale don! - tutti i nostri peccati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '1', '4', 'Nel Suo sangue son tolti ad ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '2', '1', 'Dolce pace e riposo ci colman,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '2', '2', 'E dolcissima lode eleviam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '2', '3', 'Dio fu appieno in Gesù sodisfatto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '2', '4', 'E noi pur sodisfatti in Lui siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '3', '1', 'La coscienza non più ci condanna');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '3', '2', 'Ché il Suo sangue, che tanto apprezziam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '3', '3', 'Ci ha lavati una volta per sempre:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '3', '4', 'Nel cospetto di Dio puri siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '4', '1', 'D\'una pace si dolce ricolmi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '4', '2', 'Procediam, nella lotta e il timor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '4', '3', 'Finché siam, dell\'Agnel nella gloria,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '4', '4', 'Da tal pace attorniati ad ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '5', '1', 'Nel Signore vivente credendo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '5', '2', 'La giustizia e la pace gustiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '5', '3', 'E lo Spirito Santo ci dona');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('410', '5', '4', 'Sante gioie che ognor dureran.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('411', '10.9.10.9.', '114', '107');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '1', '1', 'O SIGNORE, Te attender vogliamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '1', '2', 'Fa\' che sia nostro solo piacer');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '1', '3', 'Il servirti qui in terra, ignorati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '1', '4', 'Nell\'attesa del gaudio del ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '2', '1', 'T\'attendiamo, per Te lavorando');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '2', '2', 'E servendoti nell\'umiltà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '2', '3', 'Quel che Tu da compire ci desti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '2', '4', 'Ci rallegra, e la Tua volontà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '3', '1', 'Ben possiamo aspettare! Tu attendi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '3', '2', 'O Signor, finché il giorno verrà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '3', '3', 'Quando a Te la potenza nemica');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '3', '4', 'In eterno soggetta sarà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '4', '1', 'Sarà allor pienamente compìto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '4', '2', 'O Signore, il Tuo santo voler,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '4', '3', 'E qual gioia sarà pei Tuoi santi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '4', '4', 'Nella gloria Te stesso veder!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '5', '1', 'Vieni presto, Signore! I cuor nostri');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '5', '2', 'Qui riposo non posson trovar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '5', '3', 'Sol avranno la gioia e il riposo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('411', '5', '4', 'Quando Teco potrem dimorar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('412', '11.10.11.10.', '52', '166');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '1', '1', 'DA Te, Signore Spirto, siam guidati:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '1', '2', 'In noi dimori e pur per Te apprendiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '1', '3', 'La verità che tutta Tu confidi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '1', '4', 'Ai nostri cuor se a Te soggetti siam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '2', '1', 'La Tua presenza dimorante in noi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '2', '2', 'I nostri cuori muove ad adorar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '2', '3', 'Spirto divino, e con riconoscenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '2', '4', 'Pel santo Tuo servizio Te lodar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '3', '1', 'Tutte le cose di Gesù conosci,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '3', '2', 'La lor grandezza noi per Te vediam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '3', '3', 'Mediante Te, o Spirto benedetto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '3', '4', 'Cristo, Signore nostro, contempliam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '4', '1', 'Signore Spirto, dove Tu Ti trovi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '4', '2', 'Dolce e completa libertà godiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '4', '3', 'E, nel Suo volto senza vel, la gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '4', '4', 'Di Cristo in cielo già fin d\'or vediam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '5', '1', 'Di gloria in gloria per il Tuo potere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '5', '2', 'E l\'opra Tua noi trasformati siam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '5', '3', 'E l\'infinita gloria che risplende');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('412', '5', '4', 'Nel volto Suo divino contempliam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('413', '10.10.10.10.10.10.', '165', '97');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '1', '1', '"UN po\' di tempo" ed il Signor verrà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '1', '2', 'Il nostro viaggio in terra finirà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '1', '3', 'E nella casa del Suo Padre in ciel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '1', '4', 'Ci porterà, dov\'Ei ci precedè.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '1', '5', 'Là noi sarem con Lui, cantando ognor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '1', '6', 'Le glorie di Sua grazia e del Suo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '2', '1', '"Un po\' di tempo" ed Egli tornerà:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '2', '2', 'Di riscattare l\'ore noi cerchiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '2', '3', 'Sia nostra gioia nel seguirlo ognor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '2', '4', 'Non più causar tristezza pel Suo cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '2', '5', 'D\'essere pronti, in veglia, noi bramiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '2', '6', 'Poi che il Signore nostro qui attendiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '3', '1', '"Un po\' di tempo"-presto finirà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '3', '2', 'Perché evitar la croce ch\'Ei ci dà?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '3', '3', 'Nelle Sue orme in terra ci affrettiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '3', '4', 'E tutto qui qual perdita stimiam!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '3', '5', 'Oh, come Sua presenza sarà ognor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '3', '6', 'La ricompensa all\'ansia ed al dolor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '4', '1', '"Un po\' di tempo"-vieni, Salvator!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '4', '2', 'Il popol Tuo quaggiù T\'attende ancor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '4', '3', 'Deh, prendi i pellegrini a casa, in ciel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '4', '4', 'Ove vedran Tua gloria senza vel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '4', '5', 'Il nuovo canto eterno canteran');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('413', '4', '6', 'E conformati in tutto a Te saran!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('414', '9.8.9.8.8.8.', '104', '9');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '1', '1', 'UN dì dall\'alta gloria in cielo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '1', '2', 'Volle Gesù, il Signor, venir');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '1', '3', 'Il Padre per glorificare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '1', '4', 'E sulla croce per morir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '1', '5', 'Umìle e santo Salvator!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '1', '6', 'Di grazia pieno, pien d\'amor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '2', '1', 'Fino alla croce del Calvario,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '2', '2', 'Nella Sua grazia, Egli avanzò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '2', '3', 'E là Si offerse pel peccato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '2', '4', 'E il sangue Suo per noi versò:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '2', '5', 'Meraviglioso Salvator!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '2', '6', 'Se stesso diè pel peccator!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '3', '1', 'Compìta l\'opra, Egli risorse,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '3', '2', 'Il Vincitore trionfò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '3', '3', 'Or alla destra di Dio siede:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '3', '4', 'Anche il più vil salvare può.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '3', '5', 'Glorioso e santo Salvator!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '3', '6', 'Ei diede tutto nel Suo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '4', '1', 'Là Egli attende che tu venga,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '4', '2', 'Da molto tempo atteso ha già:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '4', '3', 'Vuol darti parte nelle gioie,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '4', '4', 'Nei canti dell\'eternità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '4', '5', 'Oh, benedetto Salvator!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('414', '4', '6', 'Dei riscattati è tema ognor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('415', '9.8.9.8.9.8. Giambico.', '162', '152');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '1', '1', 'SIGNOR, qual carico portasti!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '1', '2', 'Il nostro peso fu su Te;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '1', '3', 'Pei peccator là Ti tenesti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '1', '4', 'Portando tutto il mal per me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '1', '5', 'Vittima, il sangue Tuo spargesti:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '1', '6', 'Non v\'è più peso ormai per me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '2', '1', 'La nostra coppa ricevesti-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '2', '2', 'Fu piena di dolor per Te!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '2', '3', 'Tu solo appieno la bevesti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '2', '4', 'E vuota or è, Signor, per me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '2', '5', 'Tu l\'amarezza ne subisti:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '2', '6', 'Solo il Tuo amor riman per me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '3', '1', 'Della tempesta là fu inteso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '3', '2', 'Signore, il rombo su di Te;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '3', '3', 'Tu fosti là per mia difesa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '3', '4', 'Subendo l\'uragan per me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '3', '5', 'Allor disfatto fu il Tuo viso:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '3', '6', 'Serena pace or v\'è per me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '4', '1', 'Per me moristi Tu, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '4', '2', 'Ed io pur morto son con Te;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '4', '3', 'Sorgendo, i miei legami ognora');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '4', '4', 'Sciogliesti, ed ora vivi in me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '4', '5', 'Del Padre il volto in grazia ora');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('415', '4', '6', 'Risplende in luce su di me.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('416', '8.7.8.7.8.7.8.7.', '25', '44');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '1', '1', 'PADRE nostro, riverenti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '1', '2', 'T\'adoriam dal nostro cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '1', '3', 'Te supremo discerniamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '1', '4', 'Nell\'economia d\'amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '1', '5', 'Tu maggior di tutto sei,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '1', '6', 'Gloria hai Tu in rivelazion;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '1', '7', 'Dai Tuoi figli a Te si leva');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '1', '8', 'Un\'eterna adorazion.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '2', '1', 'Tu oprasti per compire');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '2', '2', 'I consigli del Tuo cuor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '2', '3', 'Nel Diletto benedetti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '2', '4', 'A Te diamo lode e onor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '2', '5', 'Da Te ha nome ogni famiglia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '2', '6', 'E la Tua benedizion');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '2', '7', 'Da per tutto si diffonde;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '2', '8', 'Tu sei Fonte d\'ogni don.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '3', '1', 'Per lo Spirto T\'adoriamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '3', '2', 'Il Figliol Ti rivelò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '3', '3', 'E l\'amore Tuo divino');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '3', '4', 'Nella Sua bontà mostrò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '3', '5', 'Benedetti in Tua presenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '3', '6', 'Quali santi in luce siam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '3', '7', 'A Te sempre sia la gloria!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('416', '3', '8', 'Padre nostro, T\'adoriam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('417', '9.8.9.8.9.8.9.8. Giambico.', '137', '182');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '1', '1', 'OH, chi ascoltare vuol la storia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '1', '2', 'Gloriosa del divino amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '1', '3', 'Ch\'è ripetuta in sua pienezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '1', '4', 'D\'Adamo ai figli, in grazia, or?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '1', '5', 'Chiunque crede - oh, qual messaggio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '1', '6', 'Che vien dal tron di Dio lassù-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '1', '7', 'In Quei che qui morì per lui,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '1', '8', 'Godrà l\'amor di Dio in Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '2', '1', 'Oh, chi ascoltare il Salvatore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '2', '2', 'Vuol, mentre in grazia chiama ancor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '2', '3', 'Ed, il perdon di Dio accettando,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '2', '4', 'Lui confessare qual Signor?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '2', '5', 'Chi, in obbedienza piena, al Figlio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '2', '6', 'Di Dio esaltato, si darà?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '2', '7', 'Ei donerà lo Spirto Santo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '2', '8', 'Di pace il cuore colmerà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '3', '1', 'Oh, chi ascoltare vuol lo Spirto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '3', '2', 'Ritrarsi dall\'iniquità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '3', '3', 'Essendo un vaso pel Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '3', '4', 'Di cuore puro, in santità?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '3', '5', 'Quaggiù vincendo in mezzo al male,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '3', '6', 'E fermo nella verità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '3', '7', 'Fin d\'or a Cristo rispondendo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('417', '3', '8', 'A Lui la gloria renderà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('418', '7,6.7.6.7.6.7.6.', '141', '47');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '1', '1', 'GESU\', Signore nostro,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '1', '2', 'Prezioso Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '1', '3', 'Noi T\'adoriam per tutto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '1', '4', 'Quel che in Te brilla ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '1', '5', 'Signore, Tu sei degno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '1', '6', 'Del nostro eterno amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '1', '7', 'Sei degno che la lode');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '1', '8', 'A Te s\'elevi ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '2', '1', 'Tu per lo Spirto eterno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '2', '2', 'A Dio Te stesso offrir');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '2', '3', 'Volesti, in obbedienza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '2', '4', 'Perfetta al Suo voler.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '2', '5', 'Il Padre T\'ama: il Figlio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '2', '6', 'Del Suo amor sei Tu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '2', '7', 'E pure sei amato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '2', '8', 'Dai santi Tuoi quaggiù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '3', '1', 'T\'onorin senza fine');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '3', '2', 'Gli eserciti del ciel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '3', '3', 'E tutto quel che ha vita');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '3', '4', 'In terra lodi Te!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '3', '5', 'Poiché, Signor, sei degno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '3', '6', 'Di nostra lode ognor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '3', '7', 'Sei degno eternamente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('418', '3', '8', 'Di tutto il nostro amor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('419', '6.6.6.6.6.6.6.6.', '90', '130');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '1', '1', 'SIGNOR, Tu sei con me!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '1', '2', 'Che cosa temerò?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '1', '3', 'Se Tu mi sei vicin,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '1', '4', 'Chi nuocermi ancor può?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '1', '5', 'Sicuro, all\'ombra Tua,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '1', '6', 'Rifugio troverò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '1', '7', 'E\' dolce là per me');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '1', '8', 'Il frutto Tuo, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '2', '1', 'Signor, Tu sei con me:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '2', '2', 'La grazia Tua mi dà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '2', '3', 'Nel viaggio giornalier');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '2', '4', 'Vigor per continuar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '2', '5', 'Rinnovi ogni mattin');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '2', '6', 'Le grazie Tue per me;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '2', '7', 'Il Tuo riposo è già');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '2', '8', 'In vista per la fé.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '3', '1', 'Signor, Tu sei con me,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '3', '2', 'Ed ogni dì maggior');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '3', '3', 'La prova Tu mi dài');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '3', '4', 'Del Tuo profondo amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '3', '5', 'Ed ora Tu m\'attrai');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '3', '6', 'Ed operi, affinché');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '3', '7', 'Nulla m\'abbia a impedir');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('419', '3', '8', 'Di dimorar con Te.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('420', '12.13.12.10.', '48', '191');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('420', '1', '1', 'GLORIA, gloria, gloria, lode e adorazione!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('420', '1', '2', 'Odi i canti che s\'elevan per l\'eternità!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('420', '1', '3', 'Padre, Figlio e Spirto - Dio in rivelazione -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('420', '1', '4', 'Prostrisi ognuno alla Deità!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('420', '2', '1', 'Padre in cui (oh, gloria!) le famiglie han nome,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('420', '2', '2', 'Figlio che sostiene tutto con il Suo poter,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('420', '2', '3', 'Spirto Santo ch\'empie la gloriosa scena:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('420', '2', '4', 'Santa Pienezza, sempre adorerem!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('420', '3', '1', 'In splendore santo, Dio, T\'adoriamo!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('420', '3', '2', 'Tua maestà, grandezza, lode, gloria e poter');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('420', '3', '3', 'O supremo Capo, noi riconosciamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('420', '3', '4', 'Eterna Fonte d\'ogni bene ver!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('421', '11.10.11.11.6.', '186', '130');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '1', '1', 'CHE mai sarà allorché, la via finita,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '1', '2', 'Entrati nel riposo noi sarem;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '1', '3', 'La notte delle lacrime passata,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '1', '4', 'Con Te, Signor, per sempre benedetti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '1', '5', 'La nostra parte avrem!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '2', '1', 'Che mai sarà, allora che la lotta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '2', '2', 'Sarà finita, e i santi Tuoi che or');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '2', '3', 'Dispersi son, saranno uniti tutti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '2', '4', 'A Te simìli, senza variazione,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '2', '5', 'Al fianco Tuo, Signor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '3', '1', 'Là, terminato il giorno delle pene,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '3', '2', 'Dolori e prove non saranno più;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '3', '3', 'Nel fulgido futuro parte avremo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '3', '4', 'Nel dì perfetto, in perfetta pace');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '3', '5', 'Con Te, Signor Gesù!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '4', '1', 'Che mai sarà? - Or mentre T\'attendiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '4', '2', 'La lode sgorga a Te dal nostro cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '4', '3', 'Ma quando faccia a faccia Ti vedremo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '4', '4', 'Signor, sarà più limpida e più dolce');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('421', '4', '5', 'La nostra lode allor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('422', '9.8.9.8. Giambico.', '161', '84');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '1', '1', 'GESU\', Signor, con Te gioiamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '1', '2', 'Passò la notte del dolor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '1', '3', 'Vinti i nemici, Te per sempre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '1', '4', 'Riconosciamo Vincitor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '2', '1', 'Tutto il cammino che il Tuo amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '2', '2', 'Tracciò, con gioia vogliam far,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '2', '3', 'L\'immensa fedeltà, la grazia,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '2', '4', 'La mansuetudine imitar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '3', '1', 'Del Padre Tu il voler compiendo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '3', '2', 'Volesti fino a morte andar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '3', '3', 'Giustizia e pace in Te, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '3', '4', 'Là sulla croce s\'abbracciâr.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '4', '1', 'Come risorto Te, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '4', '2', 'Noi salutiam, ché l\'ombra andò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '4', '3', 'L\'amor divin nel suo trionfo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '4', '4', 'Tuoi, con Te sempre, ci chiamò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '5', '1', 'Così gioiamo in Te, Signore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '5', '2', 'E lietamente Ti lodiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '5', '3', 'Il Tuo trionfo e la Tua gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('422', '5', '4', 'Per sempre noi magnifichiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('423', '10.10.10.2.', '87', '83');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '1', '1', 'DA Te, Signor, pei peccatori fu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '1', '2', 'L\'amor mostrato col supremo don');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '1', '3', 'Della Tua vita, data un dì quaggiù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '1', '4', 'Per me?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '2', '1', 'Per noi soffristi e pur moristi qui,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '2', '2', 'Per peccatori tali come me?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '2', '3', 'Ed offri la Tua grazia tuttodì');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '2', '4', 'Per me?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '3', '1', 'Per me che fui lontano dal Tuo amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '3', '2', 'Lasciato Dio di propria volontà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '3', '3', 'Proprio per me la grazia scorre ancor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '3', '4', 'Per me?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '4', '1', 'S\'è il peccator perduto che incontrar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '4', '2', 'Vuoi Tu, per dargli piena libertà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '4', '3', 'Così ai Tuoi piedi è dato d\'adorar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '4', '4', 'Per me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '5', '1', 'A dar perdono, casa, pace e amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '5', '2', 'Per me sei sceso in grazia, O Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '5', '3', 'E posto v\'è, Signore, nel Tuo cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('423', '5', '4', 'Per me.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('424', '11.10.11.10.', '52', '144');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '1', '1', 'QUANDO, o Signor, potremo alfin vedere');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '1', '2', 'Fuggir la notte innanzi al Tuo splendor?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '1', '3', 'Con cuor soggetti qui attendiamo l\'alba');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '1', '4', 'Del giorno eterno, senza più dolor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '2', '1', 'L\'ora attendiam in cui siam liberati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '2', '2', 'Da schiavitù e d\'ogni mal terren');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '2', '3', 'E con gloriosi corpi, al Tuo simìli,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '2', '4', 'Insieme intorno al trono ognor sarem.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '3', '1', 'Più non sarà la morte, né il peccato-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '3', '2', 'Tutti i nemici nostri vinti ognor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '3', '3', 'La speme eleva i nostri cuori, e toglie');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '3', '4', 'Il dardo della morte già fin d\'or.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '4', '1', 'I servitori Tuoi, Signore, muoion:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '4', '2', 'Il lor servizio noi goduto abbiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '4', '3', 'Deh, Tu ci accorda che ora, con celeste');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '4', '4', 'Valore, il posto loro noi prendiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '5', '1', 'Accorda a noi, che ancora rimaniamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '5', '2', 'Di camminare puri innanzi a Te,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '5', '3', 'Servendo la Tua chiesa fedelmente');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('424', '5', '4', 'Finché anche noi sarem chiamati al ciel.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('425', '10.10.10.10.10.10.', '165', '167');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('425', '1', '1', 'O BENEDETTO Spirto, a Te leviam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('425', '1', '2', 'Il nostro canto in santa lode or,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('425', '1', '3', 'Mentre l\'umìle posto discerniam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('425', '1', '4', 'Che Tu prendesti in grazia ed in amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('425', '1', '5', 'Il Padre ed il Figliolo Ti mandâr,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('425', '1', '6', 'Con noi e in noi, O Santo, a dimorar!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('425', '2', '1', 'Pur brillan in divina maestà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('425', '2', '2', 'Le glorie della Tua Persona appien;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('425', '2', '3', 'Tu hai un posto nella Deità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('425', '2', '4', 'Il cui suprem diritto T\'appartien.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('425', '2', '5', 'Signore Spirto! Insieme T\'adoriam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('425', '2', '6', 'Con cuori uniti a Te noi c\'inchiniam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('426', '7.7.7.8.', '88', '175');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '1', '1', 'O FIGLIOL di Dio, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '1', '2', 'Fosti l\'Uomo dei dolor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '1', '3', 'Per salvare i peccator-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '1', '4', 'Ti lodiamo, Salvatore!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '2', '1', 'L\'uomo vil Ti condannò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '2', '2', 'D\'ignominia Ti colmò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '2', '3', 'Ma il Tuo sangue ci acquistò-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '2', '4', 'Ti lodiamo, Salvatore!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '3', '1', 'Santo Agnel di Dio sei Tu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '3', '2', 'Senza speme noi quaggiù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '3', '3', 'Ma redenti ci hai, Gesù-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '3', '4', 'Ti lodiamo, Salvatore!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '4', '1', '"E\' compiuto!" il grido fu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '4', '2', 'Allorché moristi Tu:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '4', '3', 'Esaltato or sei lassù-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '4', '4', 'Ti lodiamo, Salvatore!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '5', '1', 'Te Signor riconosciam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '5', '2', 'E sul trono Ti vediam-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '5', '3', 'Giubilanti a Te cantiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('426', '5', '4', 'Ti lodiamo, Salvatore!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('427', '8.8.8.8.', '30', '146');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '1', '1', 'CHI se non Te, Signore, può');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '1', '2', 'L\'alma assetata sodisfar?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '1', '3', 'Sorgente inesauribil Tu!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '1', '4', 'Niun\'altra ne possiam trovar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '2', '1', 'Già ver\' le cose di lassù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '2', '2', 'Da Te è portato il nostro cuor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '2', '3', 'Potremmo mai dimenticar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '2', '4', 'Il Tuo fedel, prezioso amor?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '3', '1', 'La nostra parte non vien men,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '3', '2', 'Ché come Dio Tu dàì, Signor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '3', '3', 'Felice è nostra sorte in Te');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '3', '4', 'Del sangue Tuo nel valor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '4', '1', 'Sol dei redenti il vasto stuol');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '4', '2', 'Quel sangue appieno può apprezzar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '4', '3', 'Al trono, per la redenzion,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '4', '4', 'Or ci possiamo avvicinar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '5', '1', 'Più in alto e più vicini ognor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '5', '2', 'Portati in Te, pel sangue, siam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '5', '3', 'Gustiam l\'amor che non ha fin');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('427', '5', '4', 'Ed "Abba, Padre!" noi gridiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('428', '11.10.11.10.', '52', '54');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('428', '1', '1', 'ETERNO Dio, supremo ad ogni cosa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('428', '1', '2', 'L\'amore Tuo per sempre noi lodiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('428', '1', '3', 'L\'amore Tuo che caccia ogni timore-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('428', '1', '4', 'Udendo la Tua voce T\'adoriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('428', '2', '1', 'Noi siam Tuoi figli, eternamente Tuoi,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('428', '2', '2', 'Frutto dell\'opra del Tuo sommo amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('428', '2', '3', 'E T\'apportiam la nostra adorazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('428', '2', '4', 'Perché cercasti veri adorator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('428', '3', '1', 'Piena risposta all\'amor Tuo Tu trovi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('428', '3', '2', 'In cuori che or a Te devoti son');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('428', '3', '3', 'E che, gioiosi nella Tua presenza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('428', '3', '4', 'Ti danno lode e eterna adorazion.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('429', '11.10.11.6.', '187', '12');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '1', '1', 'GESU\', Signor, al posto mio Tu fosti:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '1', '2', 'Di Dio il furore santo fu su Te;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '1', '3', 'Annoverato Tu per me coi morti-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '1', '4', 'Per me, Signor, per me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '2', '1', 'Gesù, Signor, io sono avvicinato');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '2', '2', 'Pel sangue Tuo, che puro a ognor mi fe\',');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '2', '3', 'Per me al Calvario il sangue Tuo fu sparso-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '2', '4', 'Per me, Signor, per me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '3', '1', 'Gesù, Signor, l\'amore Tuo è immutato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '3', '2', 'Per me di Dio alla destra vivi in ciel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '3', '3', 'Di giorno in giorno gusto le Tue cure');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '3', '4', 'Per me, Signor, per me.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '4', '1', 'Per me, Signore, tutto Tu compisti;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '4', '2', 'In lode piena la mia voce a Te');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '4', '3', 'S\'eleverà, allorché sarò per sempre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '4', '4', 'Con Te, Signor, con Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '5', '1', 'Gesù, Signor, fa\' sì che in Te confidi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '5', '2', 'E se il dolor ola tempesta vien');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '5', '3', 'In Te ch\'io trovi piena protezione-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('429', '5', '4', 'In Te, Signor, in Te.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('430', '11.10.11.10.', '52', '110');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('430', '1', '1', 'L\'AMORE Tuo che in morte rivelasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('430', '1', '2', 'Avvinto ha i nostri cuori a Te, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('430', '1', '3', 'Ed all\'eterna lode che a Te ascende');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('430', '1', '4', 'Noi pur partecipiam con grato cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('430', '2', '1', 'Il pane che un sol corpo rappresenta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('430', '2', '2', 'A ognun rammenta che noi uno siam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('430', '2', '3', 'La forza dello Spirto ci congiunge');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('430', '2', '4', 'Ove sì disuniti un dì eravam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('430', '3', '1', 'Ai Tuoi parlasti del Tuo corpo dato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('430', '3', '2', 'Del sangue sparso nel Tuo santo amor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('430', '3', '3', 'E noi, gli emblemi insieme contemplando,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('430', '3', '4', 'Pur oggi udiam la voce Tua, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('430', '4', '1', 'E mentre qui così Ti ricordiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('430', '4', '2', 'Tu stesso vieni a noi, Signor Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('430', '4', '3', 'E in terra, dove asil Ti fu negato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('430', '4', '4', 'In seno all\'assemblea riposo hai Tu.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('431', '10.10.10.9.10.10.10.9.', '170', '29');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '1', '1', 'NESSUN atto possente espiare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '1', '2', 'I peccati poteva, o parola');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '1', '3', 'Prodigiosa qui far risuonare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '1', '4', 'Dalla gloria la voce d\'amor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '1', '5', 'Per mostrare quaggiù al peccatore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '1', '6', 'La grandezza d\'amore divino,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '1', '7', 'Del Calvario l\'obbrobrio e il dolore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '1', '8', 'Tu prendesti su Te, Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '2', '1', 'Là di Dio la giustizia è mostrata,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '2', '2', 'E\' veduta la grazia Sua immensa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '2', '3', 'Mentre Tu hai appien mantenuta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '2', '4', 'Del Suo trono la gloria, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '2', '5', 'Dio in Te or è glorificato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '2', '6', 'Tu che sei l\'unigenito Figlio;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '2', '7', 'Poi che qui il Tuo lavor fu compiuto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '2', '8', 'Ei ci aprì la Sua casa e il Suo cuor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '3', '1', 'E poiché Gli rendesti, Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '3', '2', 'Più di quello che l\'uomo Gli tolse,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '3', '3', 'Or, dov\'era il peccato, brillare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '3', '4', 'Più fulgente Sua gloria vediam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '3', '5', 'A Te attratti noi siam in amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '3', '6', 'Ed un canto di gioia eleviamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '3', '7', 'Un diadema di lode e d\'onore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('431', '3', '8', 'In concento col cielo, Ti diam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('432', '9.8.9.8.9.8.9.8. Giambico.', '137', '22');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('432', '1', '1', 'UDITE! E\' un libero messaggio');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('432', '1', '2', 'Di pace e gioia, di perdon,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('432', '1', '3', 'Di giubileo la tromba, buone');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('432', '1', '4', 'Novelle di liberazion!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('432', '1', '5', 'I prigionieri del nemico');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('432', '1', '6', 'Ascoltin questo lieto suon:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('432', '1', '7', 'Dove peccato e morte abbondan');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('432', '1', '8', 'La grazia regna - quale don!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('432', '2', '1', 'E\' offerta piena salvazione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('432', '2', '2', 'Nel Nome di Gesù tuttor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('432', '2', '3', 'Da messaggeri giubilanti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('432', '2', '4', 'E\' sparsa la Sua fama ancor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('432', '2', '5', '"Chiunque vuole" è la parola:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('432', '2', '6', 'Non vuoi la grazia Sua accettar?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('432', '2', '7', 'Il sangue Suo ti può redimer,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('432', '2', '8', 'Purificare e riscattar!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('433', '11.10.11.10.', '52', '63');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '1', '1', 'CONSOLATORE santo e benedetto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '1', '2', 'Sceso dal Padre per Suo sommo amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '1', '3', 'In noi quaggiù Ti degni dimorare:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '1', '4', 'Qual gioia è questa per i nostri cuor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '2', '1', 'Tu sei con noi e in noi, che il Figlio amiamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '2', '2', 'Ei stesso al Padre Suo domandò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '2', '3', 'Che Tu venissi a dimorar coi santi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '2', '4', 'Quand\'Ei, tornando al cielo, li lasciò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '3', '1', 'Egli è la Via, la Verità, la Vita,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '3', '2', 'Tu sei lo Spirto della verità:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '3', '3', 'Felici siamo ché quaggiù ci guidi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '3', '4', 'Ver\' la celeste nostra eredità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '4', '1', 'Dalla potenza Tua sostenuti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '4', '2', 'La Tua presenza santa noi godiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '4', '3', 'E in quest\'oscuro mondo che T\'ignora,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '4', '4', 'O Spirto Santo, noi Ti conosciam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '5', '1', 'Tu, nella Tua Persona glorïosa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '5', '2', 'Operi al fine di glorificar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '5', '3', 'Gesù, il Signore, e noi con cuori grati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('433', '5', '4', 'L\'aiuto Tuo veniamo ad invocar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('434', '6.6.6.6.6.6.6.6.', '90', '165');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '1', '1', 'IL mondo ancor non è');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '1', '2', 'Soggetto a Te, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '1', '3', 'E il trono Tuo quaggiù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '1', '4', 'Non stabilito ancor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '1', '5', 'Ma, santo Salvator');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '1', '6', 'Cui tutto noi dobbiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '1', '7', 'Te coronato in ciel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '1', '8', 'Per fede già vediam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '2', '1', 'Noi attendiamo il dì');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '2', '2', 'Che Ti vediam, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '2', '3', 'Ed il creato inter');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '2', '4', 'A Te dia lode e onor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '2', '5', 'Ma al Nome Tuo, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '2', '6', 'Noi qui fedeli siam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '2', '7', 'Ed al Tuo amor divin');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '2', '8', 'Devoti rispondiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '3', '1', 'Pur, mentre qui attendiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '3', '2', 'Che venga Tu dal ciel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '3', '3', 'Deh, tienci fidi a Te');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '3', '4', 'Che sempre sei il Fedel;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '3', '5', 'Aiutaci, Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '3', '6', 'Cosi qui a camminar;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '3', '7', 'Che in noi si veda ognor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('434', '3', '8', 'La gloria Tua brillar.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('435', '7.6.7.6.7.6.7.6.', '34', '73');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '1', '1', 'IN quella stessa notte');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '1', '2', 'In cui tutto, quaggiù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '1', '3', 'S\'unì per dar la morte');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '1', '4', 'A Te, Signor Gesù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '1', '5', 'Sentiamo la Tua voce-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '1', '6', '"In memoria di Me",');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '1', '7', 'E noi, con cuori grati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '1', '8', 'Ci ricordiam di Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '2', '1', 'La grazia Tua vediamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '2', '2', 'E il Tuo perfetto amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '2', '3', 'Pensando ai flutti, l\'onde');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '2', '4', 'Che fûr su Te, Signor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '2', '5', 'Le tenebre opprimenti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '2', '6', 'Che sceser su di Te:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '2', '7', 'Con cuor riconoscenti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '2', '8', 'Ci ricordiam di Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '3', '1', 'Finché verrai in gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '3', '2', 'Chiamando i Tuoi, allor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '3', '3', 'Ad esser nel riposo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '3', '4', 'Con Te, nel Tuo splendor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '3', '5', 'La morte Tua annunciamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '3', '6', 'Ed esser qui bramiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '3', '7', 'Ad essa conformati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('435', '3', '8', 'Mentre Ti ricordiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('436', '8.7.8.7.8.7.8.7. Giambico.', '66', '69');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '1', '1', 'QUANT\'è prezioso al nostro cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '1', '2', 'Il Nome Tuo, Signore!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '1', '3', 'Pur s\'è negletto in terra ancor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '1', '4', 'Riman lo Stesso ognora.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '1', '5', 'Il fondamento fermo sta,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '1', '6', 'Lo Spirto con potenza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '1', '7', 'Sostien l\'intera verità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '1', '8', 'Quaggiù nell\'assemblea.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '2', '1', 'Deh, sorgi in forza e maestà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '2', '2', 'E fa\' che il Tuo splendore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '2', '3', 'Possiam veder, nel confessar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '2', '4', 'Il Nome Tuo, Signore.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '2', '5', 'Così ai Tuoi piè, Signor, cadiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '2', '6', 'E grazia Ti chiediamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '2', '7', 'Per oppugnar con umiltà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '2', '8', 'Qualunque sfida al trono.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '3', '1', 'Tu degli eserciti il Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '3', '2', 'Possente Uom di guerra!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '3', '3', 'Ben presto regnerai ognor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '3', '4', 'Sovrano sulla terra.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '3', '5', 'Or di tra i cherubini Tu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '3', '6', 'Per mantenere i santi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '3', '7', 'Diritti del Tuo Dio quaggiù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '3', '8', 'Pastore, deh, risplendi!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '4', '1', 'Pur, tienci sempre a Te vicin,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '4', '2', 'Soggetti, Ti preghiamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '4', '3', 'Sia lieto o triste a noi il cammin,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '4', '4', 'In Te vittoria abbiamo.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '4', '5', 'E ad ogni lotta che finì');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '4', '6', 'Ritorna, o Vittorioso,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '4', '7', 'Tra le mirïadi di cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('436', '4', '8', 'Che T\'aman, al riposo.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('437', '10.10.10.10.', '21', '48');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('437', '1', '1', 'GRAZIA divina! il Salvator versò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('437', '1', '2', 'Sul legno il sangue di Sua vita un dì;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('437', '1', '3', 'Sopra la croce il capo Suo chinò:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('437', '1', '4', 'Per affrancare il popol Suo morì.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('437', '2', '1', 'Soffrendo sulla croce, il distruttor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('437', '2', '2', 'Sotto i Suoi piè, vincendo, calpestò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('437', '2', '3', 'Là, forza e debolezza s\'incontrâr -');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('437', '2', '4', 'Di spine il serto le rappresentò.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('437', '3', '1', 'Fu la potenza del Tuo immenso amor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('437', '3', '2', 'O Salvator, che a morte Ti portò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('437', '3', '3', 'Oh, quale amor, nell\'ora di dolor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('437', '3', '4', 'Nel grande grido Tuo trionfò!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('437', '4', '1', 'Sì, fu per noi, e noi dobbiamo ognor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('437', '4', '2', 'La nostra vita, speme e gioia, a Te-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('437', '4', '3', 'La sofferenza Tua per noi allor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('437', '4', '4', 'La Tua vittoria, libertà ci diè!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('438', '8.7.8.7.', '24', '140');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '1', '1', 'DIO mandò il Suo Figlio in grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '1', '2', 'Ad un mondo di dolor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '1', '3', 'Là Gesù fu crocifisso:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '1', '4', 'Ei morì pei peccator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '2', '1', 'Oh, la gloria della grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '2', '2', 'Ch\'è sul volto del Signor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '2', '3', 'Essa annuncia ai peccatori:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '2', '4', '"Dio è luce" e "Dio è amor".');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '3', '1', 'Il peccato più non regna:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '3', '2', 'Ei morì e risuscitò;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '3', '3', 'Or, di Dio suprem diletto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '3', '4', 'Sta nel fulgido splendor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '4', '1', 'A chi crede nel Suo Nome');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '4', '2', 'Vita eterna in dono dà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '4', '3', 'A Lui pieghi ogni ginocchio,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '4', '4', 'Ei Signor di tutti è già.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '5', '1', 'Il Signor Gesù ritorna:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '5', '2', 'Ei sofferse e regnerà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '5', '3', 'Al celeste Re un tributo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('438', '5', '4', 'Ogni lingua renderà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('439', '10.7.10.7, Coro 11.7.11.7.', '174', '209');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '1', '1', 'GESU\' indugia ancor, Egli aspetta te,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '1', '2', 'Già da lungo atteso Egli ha:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '1', '3', 'Ei del ciel le gioie ti vuole dar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '1', '4', 'E la pace e sicurtà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '1', '5', 'Vieni, vieni, benvenuto tu sarai,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '1', '6', 'E\' l\'appello del Signor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '1', '7', 'Ei Se stesso ha dato te per riscattar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '1', '8', 'Vieni adesso al Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '2', '1', 'Se per vie tortuose di colpe e error');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '2', '2', 'Hai voluto camminar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '2', '3', 'Pure in grazia attende il Salvator');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '2', '4', 'Il tuo cuor per conquistar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '3', '1', 'Pur se vano è stato il Suo dolce appel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '3', '2', 'E negletto il Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '3', '3', 'Immutato ognor è il Suo amor fedel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '3', '4', 'Che ti cerca in grazia ancor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '4', '1', 'Più non indugiar, ché il tuo Salvator');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '4', '2', 'Con pazienza attende ancor;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '4', '3', 'Mentre in grazia dice: "Venite a Me"');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('439', '4', '4', 'Vengo\' di\' con tutto il cuor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('440', '11.10.11.10.10.6.', '181', '73');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('440', '1', '1', 'SIGNOR Gesù, di gioia e meraviglia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('440', '1', '2', 'Sarem ricolmi quando Ti vedrem;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('440', '1', '3', 'Tua voce udrem: allora uniti insieme');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('440', '1', '4', 'Nell\'aria ad incontrarti noi verrem,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('440', '1', '5', 'E nella gloria del Tuo santo amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('440', '1', '6', 'Avremo parte ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('440', '2', '1', 'La nostra speme alfine coronata,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('440', '2', '2', 'Trofei di grazia, Teco noi sarem;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('440', '2', '3', 'Non più traverso un vetro oscuramente,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('440', '2', '4', 'Ma faccia a faccia appieno allor vedrem.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('440', '2', '5', 'In Te, che non veduto noi amiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('440', '2', '6', 'Dimora in ciel abbiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('440', '3', '1', 'O Salvatore, mentre T\'attendiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('440', '3', '2', 'Al nostro spirto dà nuovo vigor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('440', '3', '3', 'La Tua parola "Ecco, vengo presto"');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('440', '3', '4', 'Ed in risposta s\'apre il nostro cuor:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('440', '3', '5', '"Amen-diciamo mentre siam quaggiù-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('440', '3', '6', 'Vieni, Signor Gesù!"');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('441', '9.8.9.8. Giambico.', '161', '91');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '1', '1', 'PADRE di tutte le famiglie,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '1', '2', 'Il nostro canto a Te eleviam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '1', '3', 'Tu sei supremo nella gloria:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '1', '4', 'L\'amor Tuo santo noi lodiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '2', '1', 'Fortificati dal Tuo Spirto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '2', '2', 'Ricolmi di poter divin,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '2', '3', 'Noi comprendiamo la grandezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '2', '4', 'Dei Tuoi consigli senza fin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '3', '1', 'Là Cristo e l\'assemblea veduti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '3', '2', 'Son in un fulgido splendor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '3', '3', 'L\'Uomo a Tua propria somiglianza,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '3', '4', 'Che forma Tue delizie ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '4', '1', 'L\'amore Suo per la Sua sposa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '4', '2', 'Di conoscenza è al di là,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '4', '3', 'Pur è compreso nell\'unione');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '4', '4', 'Con Lui in gloria che gustiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '5', '1', 'Così in libertà di figli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '5', '2', 'I nostri cuori a Te chiniam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '5', '3', 'E nelle lodi a Te, o Padre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('441', '5', '4', 'Da Cristo noi guidati siam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('442', '8.8.8.7.8.8.8.7.', '153', '214');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('442', '1', '1', 'SANTO Spirto d\'adozione,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('442', '1', '2', 'Ora al grido di figlioli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('442', '1', '3', 'Possiam dar per Te espressione,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('442', '1', '4', 'Di Dio il cuor a rallegrar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('442', '1', '5', 'Noi mediante Cristo abbiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('442', '1', '6', 'Per Te accesso innanzi al Padre;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('442', '1', '7', 'Presso il trono Lo serviamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('442', '1', '8', 'E il Suo Nome celebriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('442', '2', '1', 'Santo Spirito del Padre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('442', '2', '2', 'Tu ci dài, nell\'uomo interno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('442', '2', '3', 'Il poter di penetrare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('442', '2', '4', 'In quel regno di splendor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('442', '2', '5', 'Là di Cristo conosciamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('442', '2', '6', 'L\'amor santo, e alla pienezza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('442', '2', '7', 'Di Dio pur ripieni siamo:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('442', '2', '8', 'Qual benedizion per l\'uom!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('443', '11.10.11.10.', '52', '86');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '1', '1', 'GESU\', quant\'è gloriosa la Tua grazia!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '1', '2', 'Allor che nel Tuo Nome confidiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '1', '3', 'Per fede nel Tuo sangue, una giustizia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '1', '4', 'Che dalle colpe lava, riceviam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '2', '1', 'Son vane le speranze che sull\'opre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '2', '2', 'Dell\'uom fondate sono: nel suo cuor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '2', '3', 'Regna il peccato, e tutti gli atti suoi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '2', '4', 'Attestan ch\'egli è invero peccator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '3', '1', 'Giudeo e Greco restino silenti-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '3', '2', 'L\'uomo non pensi di gloriarsi ancor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '3', '3', 'Ma in umiltà confessi la sua colpa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '3', '4', 'Davanti a la giustizia del Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '4', '1', 'Per quanto giusta sia la legge, niuna');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '4', '2', 'Speranza in essa non possiam fondar:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '4', '3', 'La legge non potrà giustificare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '4', '4', 'Nessuno, ma soltanto condannar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '5', '1', 'Con Cristo siamo morti, e pur con Lui');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '5', '2', 'Ad una nuova vita risorgiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '5', '3', 'Vita di cui godremo sempre in cielo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('443', '5', '4', 'Ma che per fede in terra già gustiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('444', '8.8.6.6.8.', '149', '112');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '1', '1', 'SIGNORE, in Te ci dilettiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '1', '2', 'Dalle Tue cure dipendiam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '1', '3', 'A Te, nostro Amico,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '1', '4', 'Che mai non vien meno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '1', '5', 'In ogni pena ricorriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '2', '1', 'Se intorno aridità troviam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '2', '2', 'La Tua pienezza ognor gustiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '2', '3', 'Oh, questo ci basti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '2', '4', 'Nel nostro sentiero,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '2', '5', 'Sì che nel Nome Tuo esultiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '3', '1', 'Se nelle creature v\'è');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '3', '2', 'Valore alcuno, vien da Te;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '3', '3', 'Abbiam ogni cosa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '3', '4', 'Signor, e abbondiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '3', '5', 'Per Tua ricchezza e Tua mercé.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '4', '1', 'La nostra speme compirai,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '4', '2', 'Ed ogni ben ci donerai;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '4', '3', 'Di nulla manchiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '4', '4', 'Ché tutto ci accordi:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '4', '5', 'Te stesso desti pur per noi!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '5', '1', 'Le nostre cure a Te portiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '5', '2', 'E trionfanti T\'adoriam;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '5', '3', 'Oh, il nostro più grande');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '5', '4', 'Desir sia che sempre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('444', '5', '5', 'Di più T\'amiamo e Ti lodiam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('445', '6.6.6.6.8.8.', '51', '195');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '1', '1', 'GESU\' risuscitò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '1', '2', 'Glorioso dall\'avel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '1', '3', 'La morte Ei debellò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '1', '4', 'Vive per sempre in ciel!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '1', '5', 'Prigione è la cattività:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '1', '6', 'Vive Gesù ed ognor vivrà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '2', '1', 'Chi contro a noi sarà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '2', '2', 'Se il sangue ch\'Ei versò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '2', '3', 'Noi dall\'iniquità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '2', '4', 'Per sempre liberò?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '2', '5', 'Prigione è la cattività:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '2', '6', 'Vive Gesù ed ogrior vivrà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '3', '1', 'Chi mai ci può accusar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '3', '2', 'Se Dio giustificò?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '3', '3', 'Chi ci può condannar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '3', '4', 'Se Cristo riscattò?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '3', '5', 'Prigione è la cattività:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '3', '6', 'Vive Gesù ed ognor vivrà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '4', '1', 'Della redenzïon');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '4', '2', 'Ei l\'opra completò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '4', '3', 'In Lui vittoria abbiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '4', '4', 'Ei sostenerci può.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '4', '5', 'Prigione è la cattività:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('445', '4', '6', 'Vive Gesù ed ognor vivrà.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('446', '11.10.11.8.', '188', '133');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '1', '1', 'COSI\' qual sono - senza alcun diritto');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '1', '2', 'Se non nel sangue Tuo, che per me');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '1', '3', 'Fu sparso, e per la Tua chiamata in grazia');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '1', '4', 'Agnel di Dio, io vengo a Te!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '2', '1', 'Così qual sono - cieco, miserabil,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '2', '2', 'Ma tutto quel che aspiro trovo in Te:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '2', '3', 'Vista, ricchezza, piena guarigione,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '2', '4', 'Agnel di Dio, io vengo a Te!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '3', '1', 'Così qual sono - senza più cercare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '3', '2', 'Di toglier una sola macchia in me;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '3', '3', 'Poi che il Tuo sangue appien mi può lavare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '3', '4', 'Agnel di Dio, io vengo a Te!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '4', '1', 'Così qual sono - so che l\'amor Tuo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '4', '2', 'Ogni barriera e ostacolo abbattè;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '4', '3', 'Per esser Tuo, mia gioia e mia corona,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '4', '4', 'Agnel di Dio, io vengo a Te!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '5', '1', 'Così qual sono-per gustar l\'amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '5', '2', 'Tuo così vasto, sì profondo e pien,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '5', '3', 'Qui per un tempo, e poi nel ciel per sempre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('446', '5', '4', 'Agnel di Dio, io vengo a Te!');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('447', '9.8.9.8. Dattilico.', '112', '146');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '1', '1', 'DI Te mai vogliamo stancarci:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '1', '2', 'Il Pane vivente sei Tu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '1', '3', 'Che il cuore appieno sodisfa');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '1', '4', 'Di quei che hai redenti, Gesù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '2', '1', 'Se in mezzo alla notte ed al duolo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '2', '2', 'Un inno possiam elevar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '2', '3', 'Oh, quali saranno le gioie');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '2', '4', 'Che, in ciel, ci daran di cantar?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '3', '1', 'Non più circondati dal male,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '3', '2', 'Là puri di cuor noi sarem,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '3', '3', 'Da pene e timor liberati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '3', '4', 'E Te faccia a faccia vedrem.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '4', '1', 'Compiuta ogni Tua promessa,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '4', '2', 'Raggiunto il desìo d\'ogni cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '4', '3', 'Alfine sarem trasformati');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '4', '4', 'A Tua somiglianza, Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '5', '1', 'Oh, possa il Tuo Spirto aiutarci');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '5', '2', 'A compier del Padre il voler');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '5', '3', 'E, da questa speme sorretti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('447', '5', '4', 'A viver pel Tuo piacer.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('448', '10.9.10.9.(b)', '175', '196');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('448', '1', '1', 'CANTIAMO a Dio ch\'è nostra forza:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('448', '1', '2', 'Ei ci ha condotti già fino ad or;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('448', '1', '3', 'Con forte braccio sino alla méta');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('448', '1', '4', 'Egli condurre ci vuole ancor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('448', '2', '1', 'Cantiamo a Dio, nostro Sostegno.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('448', '2', '2', 'Chi l\'amor Suo può misurar?');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('448', '2', '3', 'Esso è un tesoro che non ha fine,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('448', '2', '4', 'Vasto e profondo più d\'ogni mar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('448', '3', '1', 'Cantiamo a Dio, nostra difesa:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('448', '3', '2', 'Pur se il nemico ci assalirà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('448', '3', '3', 'Dalla Sua forte mano protetti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('448', '3', '4', 'Nulla i Suoi santi toccar potrà.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('448', '4', '1', 'Cantiam, cantiamo al nostro Dio!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('448', '4', '2', 'Benché sia lungo, aspro il cammin,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('448', '4', '3', 'Dal Suo costante amor sorretti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('448', '4', '4', 'Noi giungeremo freschi alla fin.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('449', '6.6.8.4.6.6.8.4.', '23', '71');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '1', '1', 'SIA gloria a Dio! cantiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '1', '2', 'Tributo Gli rendiam,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '1', '3', 'Con tutti i Suoi la voce alziam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '1', '4', 'D\'un coro sol!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '1', '5', 'Il Figlio Suo mandò');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '1', '6', 'Gli uomini a salvar-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '1', '7', 'Da morte Lo risuscitò,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '1', '8', 'Gesù, il Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '2', '1', 'Sia gloria a Dio! cantiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '2', '2', 'I santi e il cielo insiem');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '2', '3', 'Sua lode faccian risuonar!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '2', '4', 'Qual Uomo in ciel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '2', '5', 'Glorioso sta Gesù-');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '2', '6', 'La morte Sua ci diè');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '2', '7', 'Accesso al Dio Suo, ch\'è pur');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '2', '8', 'Dio nostro or.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '3', '1', 'Sia gloria a Dio! gridiam:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '3', '2', 'Le nostre voci alziam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '3', '3', 'E insieme noi magnifichiam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '3', '4', 'Gesù, il Signor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '3', '5', 'Tua grazia, o Dio, vediam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '3', '6', 'Ch\'Ei rivelò in amor!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '3', '7', 'Con cuor toccati celebriam');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('449', '3', '8', 'Gesù, il Signor.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('450', '10.10.10.9.10.10.10.9.', '170', '73');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '1', '1', 'BENEDETTO sia Dio, il Padre');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '1', '2', 'Del Figliolo, di Cristo Signore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '1', '3', 'Che propose d\'averci per figli');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '1', '4', 'Pria che fosser la terra od il ciel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '1', '5', 'Sì che noi, Suoi redenti e diletti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '1', '6', 'Con Lui sempre possiam dimorare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '1', '7', 'E del santo Suo amore gustare');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '1', '8', 'La pienezza e la profondità.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '2', '1', 'Dove tutti gli affetti profondi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '2', '2', 'Che del Padre rïempiono il cuore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '2', '3', 'Troveranno la sodisfazione,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '2', '4', 'Dando gioia e diletto a noi pur,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '2', '5', 'Là con Lui "Abba, Padre" diremo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '2', '6', 'Radunati intorno al Signore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '2', '7', 'Nelle molte celesti dimore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '2', '8', 'Che per noi preparate già son.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '3', '1', 'Di godere con Lui il riposo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '3', '2', 'Mentre ancora qui in terra attendiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '3', '3', 'Già la gioia noi ben conosciamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '3', '4', 'D\'esser figli con Cristo, il Figliol;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '3', '5', 'Dal Suo Spirito Santo guidati,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '3', '6', '"Abba, Padre" quaggiù già gridiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '3', '7', 'E con cuori anelanti bramiamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('450', '3', '8', 'Di trovarci per sempre lassù.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('451', '11.10.11.10.', '52', '196');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '1', '1', 'O SANTO Agnello, Tu sei coronato:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '1', '2', 'A Te la gloria, a Te tutt\'il poter!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '1', '3', 'Luogo non v\'è per Te troppo elevato:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '1', '4', 'Tu siedi nel più eccelso posto in ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '2', '1', 'Tu riempi il trono - il trono della gloria');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '2', '2', 'Pel Tuo diritto T\'appartien lassù;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '2', '3', 'Tu sei l\'oggetto dell\'amor del Padre,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '2', '4', 'Tu che compisti il Suo piacer quaggiù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '3', '1', 'Il tema sei di tutti i Tuoi redenti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '3', '2', 'A Te la lode sal, divin Signor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '3', '3', 'E benché debol sia talvolta il canto,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '3', '4', 'L\'orecchio Tuo raggiunge, Salvator.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '4', '1', 'Ed or con cuor unito celebriamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '4', '2', 'Il Tuo prezioso Nome, santo Agnel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '4', '3', 'Dal Padre Tu sei or glorificato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '4', '4', 'Ma fino a morte fosti qui fedel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '5', '1', 'A Te, dal mondo ancora rigettato,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '5', '2', 'Dan grata lode i Tuoi, Signor Gesù:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '5', '3', 'Tue sono le corone, a Te appartiene');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('451', '5', '4', 'Il trono nella gloria di lassù.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('452', '10.10.10.10.', '21', '26');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '1', '1', 'QUAL gioia inesprimibile sarà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '1', '2', 'Restar eternamente a Te vicin');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '1', '3', 'E presto, in quella sfera, tributar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '1', '4', 'Le lodi a Te, Signore, senza fin!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '2', '1', 'Così qual sei ogni occhio Ti vedrà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '2', '2', 'Il volto Tuo mirando senza vel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '2', '3', 'Ed ogni cuor d\'amore vibrerà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '2', '4', 'Nella benedizione eterna in ciel.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '3', '1', 'Ed ogni orecchio la Tua voce udrà');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '3', '2', 'Che sempre fu conforto a noi quaggiù;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '3', '3', 'Alla Tua lode ognuno s\'unirà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '3', '4', 'Felice appien, Signor, con Te lassù.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '4', '1', 'Qual gioia allor, fedele Salvator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '4', '2', 'Quale rapita estasi sarà,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '4', '3', 'Là, liberati alfin d\'ogni dolor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '4', '4', 'A Te un\'eterna lode tributar!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '5', '1', 'Sì, nello Spirto noi gustiam fin d\'or,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '5', '2', 'Signor, le cose che il Tuo amor ci dà;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '5', '3', 'Gioiosi siam nel Tuo immenso amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('452', '5', '4', 'Ed, ai Tuoi piè prostrati, T\'adoriam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('453', '8.8.8.8.6.', '58', '212');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '1', '1', 'O SANTO Spirto, che dal ciel');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '1', '2', 'Mandato fosti un dì quaggiù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '1', '3', 'Con noi dimori, e insiem con noi');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '1', '4', 'Straniero sei nel mondo Tu,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '1', '5', 'Ma pur Ti conosciam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '2', '1', 'Uniti siam nel Tuo poter;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '2', '2', 'Per noi Tu sei il Consolator,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '2', '3', 'Ci guidi in ogni verità:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '2', '4', 'Ti ringraziam con grato cuor,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '2', '5', 'E Ti magnifichiam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '3', '1', 'Di Dio le profondità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '3', '2', 'Mediante Te svelate son;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '3', '3', 'Sei l\'Arra dell\'eredità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '3', '4', 'E noi rendiam le nostre azion');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '3', '5', 'Di grazie ognor a Te.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '4', '1', 'L\'unzione e la potenza ancor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '4', '2', 'Che in Cristo viste fûr quaggiù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '4', '3', 'Sei Tu, o Santo Spirto, ed or');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '4', '4', 'Con il sostegno che dài Tu');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('453', '4', '5', 'Per Dio qui ci teniam.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('454', '8.8.8.7.', '151', '123');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('454', '1', '1', 'PADRE, quali Tuoi figlioli,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('454', '1', '2', 'Di cuor lieto T\'adoriamo;');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('454', '1', '3', 'In presenza Tua noi siamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('454', '1', '4', 'Resi accetti nel Figliol.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('454', '2', '1', 'Noi qual figli in Gesù Cristo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('454', '2', '2', 'Nel passato designasti:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('454', '2', '3', 'Quale grazia a noi mostrasti!');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('454', '2', '4', 'Ti lodiamo e T\'adoriam.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('454', '3', '1', 'Come Tu lo vuoi, veniamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('454', '3', '2', 'A Te senza più timore,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('454', '3', '3', 'Conosciam l\'immenso amore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('454', '3', '4', 'Che su noi riposa ognor.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('454', '4', '1', 'Padre nostro, T\'adoriamo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('454', '4', '2', 'E lodiam di lieto cuore:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('454', '4', '3', 'A Te lode sia ed onore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('454', '4', '4', 'Ora e per l\'eternità.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('455', '11.10.11.10.', '52', '62');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '1', '1', 'FRA tutti i nomi non ve n\'è che uno');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '1', '2', 'Che possa il nostro orecchio dilettar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '1', '3', 'Nessuno in terra può apprezzarlo appieno,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '1', '4', 'Nessuno può la gloria sua cantar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '2', '1', 'Ci parla dell\'amor del Salvatore');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '2', '2', 'Che diè Se stesso noi per liberar,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '2', '3', 'Ci parla di quel sangue prezïoso');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '2', '4', 'Che il peccatore può purificar.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '3', '1', 'E\' il Nome di Gesù che tanto amiamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '3', '2', 'Che più d\'ogni altro amiamo di sentir,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '3', '3', 'Sì caro ad ogni sento sulla terra:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '3', '4', 'Nessuno il suo valor può concepir.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '4', '1', 'Di questo santo Nome la fragranza');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '4', '2', 'Con noi rimane nel terren cammin');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '4', '3', 'E men scabrosa renderà la via');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '4', '4', 'Che presso Dio ci conduce alfin.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '5', '1', 'E quando al grande coro trionfante');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '5', '2', 'Dei riscattati in cielo ci unirem,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '5', '3', 'Il nuovo canto eterno eleveremo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('455', '5', '4', 'E con Gesù per sempre noi sarem.');
INSERT INTO `hymn_in` (`hymn_no`, `meter`, meter_id, `author_id`) VALUES ('456', '8.7.8.7. Giambico.', '94', '198');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '1', '1', 'TE, Dio, lodiamo per l\'amor');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '1', '2', 'Che in Cristo rivelasti');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '1', '3', 'E i santi Tuoi da schiavitù');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '1', '4', 'Per sempre liberasti.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '2', '1', 'Non più distanza, oscurità,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '2', '2', 'Timore né tristezza:');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '2', '3', 'In Tua presenza i santi son');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '2', '4', 'Ripieni d\'allegrezza.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '3', '1', 'In Cristo or coronato in ciel,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '3', '2', 'O Dio, Ti conosciamo,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '3', '3', 'Ed al cospetto Tuo con Lui');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '3', '4', 'Noi, lieti, T\'adoriamo.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '4', '1', 'Tu d\'ogni lingua, ogni tribù,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '4', '2', 'Formasti un popol santo');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '4', '3', 'Che, unito intorno al Tuo Figliol,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '4', '4', 'T\'innalza un grato canto.');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '5', '1', 'A Te niun mai potrà strappar');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '5', '2', 'Il popol dei redenti,');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '5', '3', 'Che ora e per l\'eternità');
INSERT INTO `hymn_line_in` (`hymn_no`, `vers_no`, `line_no`, `line_text`) VALUES ('456', '5', '4', 'Ti loda in lieti accenti.');
